def _provider_preflight_targets(snapshot: dict) -> list:
    from provider_retry import _checkpoint_base_url

    if not isinstance(snapshot, dict):
        return []
    targets = [(
        "Ana ceviri",
        str(snapshot.get("main_api_key") or ""),
        str(snapshot.get("main_api_base_url") or ""),
        str(snapshot.get("main_model_name") or ""),
    )]
    if not snapshot.get("auto_retry_repair_only"):
        enabled_roles = set()
        if snapshot.get("hybrid_mode"):
            enabled_roles.add("analysis")
        if any(snapshot.get(key) for key in (
                "critic", "native", "semantic_reconcile", "review")):
            enabled_roles.add("critic")
        if snapshot.get("polish") or snapshot.get("condense"):
            enabled_roles.add("polish")
        if snapshot.get("qc") or snapshot.get("backtrans"):
            enabled_roles.add("qc")
        helper_keys = snapshot.get("helper_keys") or {}
        helper_urls = snapshot.get("helper_urls") or {}
        helper_models = snapshot.get("helper_models") or {}
        for role in sorted(enabled_roles):
            targets.append((
                API_PROFILE_ROLE_LABELS.get(role, role),
                str(helper_keys.get(role) or ""),
                str(helper_urls.get(role) or ""),
                str(helper_models.get(role) or ""),
            ))
    seen = set()
    result = []
    for label, key, base_url, model in targets:
        identity = (key, _checkpoint_base_url(base_url), model.casefold())
        if not key or not base_url or not model or identity in seen:
            continue
        seen.add(identity)
        result.append((label, key, base_url, model))
    return result


def _visible_model_ids(response) -> set:
    data = getattr(response, "data", None)
    if data is None and isinstance(response, dict):
        data = response.get("data")
    result = set()
    for item in data or ():
        model_id = item.get("id") if isinstance(item, dict) else getattr(item, "id", None)
        if model_id:
            result.add(str(model_id))
    return result


_SENSITIVE_URL_QUERY_KEY_RE = re.compile(
    r"(?:api[_-]?key|access[_-]?token|auth(?:orization)?|secret|token|"
    r"credential|subscription[_-]?key|sig|key)\Z", re.I)


def _api_base_url_has_embedded_secret(value: str) -> bool:
    try:
        parsed = urlparse(str(value or "").strip())
        if parsed.username is not None or parsed.password is not None:
            return True
        return any(_SENSITIVE_URL_QUERY_KEY_RE.fullmatch(str(key or ""))
                   for key, _value in parse_qsl(parsed.query,
                                                keep_blank_values=True))
    except Exception:
        return False


def _sanitize_api_key_profiles(value) -> dict:
    profiles = {}
    if not isinstance(value, dict):
        return profiles
    for profile_id, raw in value.items():
        if not re.fullmatch(r"[0-9a-f]{32}", str(profile_id)) or not isinstance(raw, dict):
            continue
        provider = str(raw.get("provider") or "").strip()
        name = str(raw.get("name") or "").strip()[:80]
        model = str(raw.get("model") or "").strip()[:160]
        base_url = str(raw.get("base_url") or "").strip()[:500]
        if _api_base_url_has_embedded_secret(base_url):
            base_url = ""
        if provider not in API_PROFILE_PROVIDERS or not name or not model:
            continue
        profiles[str(profile_id)] = {
            "name": name,
            "provider": provider,
            "model": model,
            "base_url": base_url,
        }
    return profiles


def _sanitize_api_key_assignments(value, profiles: dict) -> dict:
    if not isinstance(value, dict):
        return {}
    return {
        role: profile_id for role, profile_id in value.items()
        if role in API_PROFILE_ROLE_LABELS and profile_id in profiles
    }


def _desktop_directory() -> Path:
    if os.name == "nt":
        try:
            import winreg
            key_path = (
                r"Software\Microsoft\Windows\CurrentVersion"
                r"\Explorer\User Shell Folders"
            )
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path) as key:
                value, _ = winreg.QueryValueEx(key, "Desktop")
            path = Path(os.path.expandvars(str(value))).expanduser()
            if path:
                return path
        except Exception:
            pass
    home = Path.home()
    for name in ("Desktop", "Masaüstü"):
        candidate = home / name
        if candidate.exists():
            return candidate
    return home / "Desktop"


def _file_list_page(files, page: int, page_size: int = FILE_LIST_PAGE_SIZE):
    items = list(files or [])
    size = max(1, int(page_size))
    pages = max(1, math.ceil(len(items) / size))
    current = min(max(0, int(page)), pages - 1)
    start = current * size
    return items[start:start + size], current, pages


def _nested_output_exclusions(roots, output_path="", same_folder=False):
    if same_folder or not str(output_path or "").strip():
        return []
    output_abs = os.path.abspath(str(output_path))
    output_key = os.path.normcase(output_abs)
    excluded = []
    for root in roots or ():
        if not str(root or "").strip():
            continue
        root_abs = os.path.abspath(str(root))
        root_key = os.path.normcase(root_abs)
        try:
            nested = os.path.commonpath([root_key, output_key]) == root_key
        except (OSError, ValueError):
            nested = False
        if nested and output_key != root_key:
            excluded.append(output_abs)
    return list(dict.fromkeys(excluded))


def _scan_subtitle_folders(paths, cancel_check=None, exclude_paths=()):
    files = []
    empty = []
    for path in paths:
        if cancel_check is not None and cancel_check():
            break
        found = get_subtitle_files(
            path, recursive=True, cancel_check=cancel_check,
            exclude_paths=exclude_paths)
        if cancel_check is not None and cancel_check():
            break
        if found:
            files.extend(found)
        else:
            empty.append(path)
    return files, empty


def _safe_chat_create(client, cancel_context=None, **kwargs):
    checkpoint_label = str(kwargs.pop("_checkpoint_label", "") or "")
    model = kwargs.get("model", "")
    requested_format = kwargs.get("response_format")
    model_lower = (model or "").lower()
    base_url = str(getattr(client, "base_url", "")).rstrip("/")
    base_url_lower = base_url.lower()
    if cancel_context is not None:
        cancel_context.raise_if_cancelled()

    # Bedrock and Anthropic provider check
    is_bedrock = False
    is_anthropic = False
    explicit_openai = False
    try:
        from helper_models import normalize_helper_model_label, resolve_helper_model, _CONFIGS, _ALIASES
        norm_label = normalize_helper_model_label(model)
        is_known_model = (model in _CONFIGS) or (model.lower() in _ALIASES)
        cfg = resolve_helper_model(norm_label)
        if cfg.provider == "bedrock":
            is_bedrock = True
        elif cfg.provider == "anthropic":
            is_anthropic = True
        elif cfg.provider == "openai" and is_known_model:
            explicit_openai = True
    except Exception:
        pass

    # Fallback/dynamic detection based on URL or model name
    if not is_bedrock and not is_anthropic and not explicit_openai:
        if "bedrock" in base_url_lower or "bedrock" in model_lower:
            is_bedrock = True
        elif ("anthropic" in base_url_lower or base_url_lower.endswith("/messages")
              or ("claude" in model_lower and "/messages" in base_url_lower)):
            if "bedrock" not in base_url_lower and "bedrock" not in model_lower:
                is_anthropic = True

    if is_bedrock:
        api_key = getattr(client, "api_key", None)
        from helper_models import call_bedrock_converse
        from provider_retry import provider_call_with_retry
        from request_cancellation import run_cancellable_call
        return provider_call_with_retry(
            lambda: run_cancellable_call(
                lambda: call_bedrock_converse(
                    model_id=model,
                    messages=kwargs.get("messages", []),
                    temperature=kwargs.get("temperature"),
                    max_tokens=kwargs.get("max_tokens") or kwargs.get("max_completion_tokens"),
                    api_key_str=api_key,
                    base_url=base_url,
                    cancel_context=cancel_context,
                    timeout_seconds=kwargs.get("timeout") or API_REQUEST_TIMEOUT_SECONDS,
                ),
                cancel_context,
            ),
            client, model,
            {"operation": checkpoint_label or "bedrock_direct"},
        )

    if is_anthropic:
        api_key = getattr(client, "api_key", None)
        from helper_models import call_anthropic_messages
        from provider_retry import provider_call_with_retry
        from request_cancellation import run_cancellable_call
        return provider_call_with_retry(
            lambda: run_cancellable_call(
                lambda: call_anthropic_messages(
                    model_id=model,
                    messages=kwargs.get("messages", []),
                    temperature=kwargs.get("temperature"),
                    max_tokens=kwargs.get("max_tokens") or kwargs.get("max_completion_tokens"),
                    api_key_str=api_key,
                    base_url=base_url,
                    cancel_context=cancel_context,
                    timeout_seconds=kwargs.get("timeout") or API_REQUEST_TIMEOUT_SECONDS,
                ),
                cancel_context,
            ),
            client, model,
            {"operation": checkpoint_label or "anthropic_direct"},
        )

    try:
        import hybrid_translate as ht
        kwargs = ht._normalize_chat_create_kwargs(model, kwargs)
    except Exception:
        pass

    kwargs.setdefault("timeout", API_REQUEST_TIMEOUT_SECONDS)
    from provider_retry import chat_create_with_compat
    if cancel_context is None:
        return chat_create_with_compat(
            client, model, kwargs, requested_format=requested_format,
            checkpoint_label=checkpoint_label)
    cancel_context.register(client)
    try:
        result = chat_create_with_compat(
            client, model, kwargs, requested_format=requested_format,
            checkpoint_label=checkpoint_label)
        cancel_context.raise_if_cancelled()
        return result
    except Exception as exc:
        if cancel_context.is_cancelled():
            raise RequestCancelled("request cancelled") from exc
        raise
    finally:
        cancel_context.unregister(client)


_CLEAN_CHAT_FINISH_REASONS = {"", "stop", "end_turn", "completed"}


def _validated_chat_content(response) -> str:
    choices = response.get("choices") if isinstance(response, dict) else getattr(response, "choices", None)
    if not choices:
        raise RuntimeError("API returned empty choices")
    choice = choices[0]
    finish_reason = (
        choice.get("finish_reason") if isinstance(choice, dict)
        else getattr(choice, "finish_reason", None)
    )
    normalized_reason = str(finish_reason or "").strip().lower()
    if normalized_reason not in _CLEAN_CHAT_FINISH_REASONS:
        raise RuntimeError(f"API response incomplete (finish_reason={normalized_reason})")
    message = choice.get("message") if isinstance(choice, dict) else getattr(choice, "message", None)
    content = message.get("content") if isinstance(message, dict) else getattr(message, "content", None)
    text = str(content or "").strip()
    if not text:
        raise RuntimeError("API returned empty content")
    return text


_SETTINGS_SECRET_KEY_RE = re.compile(
    r'("(?:[^"]*(?:api[_-]?key|secret|token|_key)[^"]*)"\s*:\s*")([^"]*)(")',
    re.I,
)
_SETTINGS_TOKEN_RE = re.compile(
    r"\b(?:(?:sk|mk)-[A-Za-z0-9._\-]+|AIza[0-9A-Za-z_-]{20,}|AKIA[0-9A-Z]{16})\b")
_URL_EMBEDDED_SECRET_RE = re.compile(
    r"(?i)(\b[a-z][a-z0-9+.-]*://)(?:[^/\s:@]+(?::[^@/\s]+)?@|"
    r"[^/\s:@]*:[^@/\s]+@)")
_URL_QUERY_SECRET_RE = re.compile(
    r"(?i)([?&](?:api[_-]?key|access[_-]?token|auth(?:orization)?|secret|"
    r"token|credential|subscription[_-]?key|sig|key)=)([^&#\s\"\\]+)")
_SECRET_HEADER_RE = re.compile(
    r"(?i)(\b(?:authorization|x-api-key)\s*[:=]\s*(?:bearer\s+)?)([^\s,;]+)")


def _sanitize_settings_backup_text(text: str) -> str:
    text = str(text or "")
    text = _SETTINGS_SECRET_KEY_RE.sub(r"\1[REDACTED]\3", text)
    text = _SETTINGS_TOKEN_RE.sub("[REDACTED]", text)
    text = _URL_EMBEDDED_SECRET_RE.sub(r"\1[REDACTED]@", text)
    text = _URL_QUERY_SECRET_RE.sub(r"\1[REDACTED]", text)
    text = _SECRET_HEADER_RE.sub(r"\1[REDACTED]", text)
    return text


def _settings_backup_suffix(path: Path) -> int:
    """`.gui_settings.json.bak.<suffix>` adındaki sayısal kısmı döner, yoksa -1.
    Yeni/eski sıralaması için dosyanın kendi st_mtime'ı YERİNE bu kullanılmalı:
    art arda birden fazla yedek aynı saniye içinde yazılırsa (ör. testte 5 sahte
    + 1 gerçek yedek üst üste oluşturuluyor) bazı dosya sistemlerinde mtime
    çözünürlüğü bunları ayırt edemeyip aralarında rastgele bir dosyayı "en yeni"
    seçtiriyordu — dosya adındaki sayı (epoch saniye) zaten kesin ve çakışmasız
    bir sıralama sağlıyor."""
    try:
        return int(path.name.rsplit(".", 1)[-1])
    except (ValueError, IndexError):
        return -1


def _write_sanitized_settings_backup(src_path: Path, keep_last: int = 3) -> Path | None:
    if not src_path.exists():
        return None
    bak = src_path.with_name(f".gui_settings.json.bak.{time.time_ns()}")
    raw = src_path.read_text(encoding="utf-8", errors="replace")
    atomic_write_text(bak, _sanitize_settings_backup_text(raw), encoding="utf-8")
    backups = sorted(src_path.parent.glob(".gui_settings.json.bak.*"), key=_settings_backup_suffix, reverse=True)
    for stale in backups[keep_last:]:
        try:
            stale.unlink()
        except Exception:
            pass
    return bak


_SHUAI_API_HOSTS = frozenset({
    "api.shuaiapi.com", "oai.sb", "api.oai.sb", "cdn.shuaiapi.com",
})


def _is_shuai_api_route(value: str) -> bool:
    try:
        return (urlparse(str(value or "")).hostname or "").casefold() in _SHUAI_API_HOSTS
    except Exception:
        return False


def _normalize_api_base_url(value: str) -> str:
    """Normalize the optional main API base URL field."""
    url = (value or "").strip().rstrip("/")
    if url.lower() in {"", "none", "null", "default", "openai"}:
        return ""
    if _api_base_url_has_embedded_secret(url):
        return ""
    try:
        parsed = urlparse(url)
        if (parsed.hostname or "").casefold() in _SHUAI_API_HOSTS:
            return parsed._replace(
                path="/v1", params="", query="", fragment="").geturl()
    except Exception:
        pass
    return url


def _get_usage_details(usage):
    if not usage:
        return 0, 0
    if isinstance(usage, dict):
        total = usage.get("total_tokens", 0) or 0
        prompt_details = usage.get("prompt_tokens_details") or {}
        cached = prompt_details.get("cached_tokens", 0) or 0
        return total, cached
    
    total = getattr(usage, "total_tokens", 0) or 0
    cached = 0
    try:
        p_details = getattr(usage, "prompt_tokens_details", None)
        if p_details:
            cached = getattr(p_details, "cached_tokens", 0) or 0
    except Exception:
        pass
    return total, cached


def _report_response_usage(token_callback, response, *, log_fn=None,
                           pass_name: str = "", filepath: str = "") -> bool:
    """Forward real usage, or explicitly record when a provider omitted it."""
    usage = getattr(response, "usage", None)
    usage_available = getattr(response, "usage_available", None) is not False
    if not token_callback:
        return bool(usage) and usage_available
    if usage and usage_available:
        total, cached = _get_usage_details(usage)
        try:
            token_callback(total, cached=cached)
        except TypeError:
            try:
                token_callback(total)
            except Exception:
                return False
        except Exception:
            return False
        return True
    reporter = getattr(token_callback, "report_missing_usage", None)
    if callable(reporter):
        try:
            reporter()
        except Exception:
            return False
    else:
        try:
            token_callback(0, usage_available=False)
        except Exception:
            return False
    if log_fn:
        label = pass_name or "API isteği"
        suffix = f" [{Path(filepath).name}]" if filepath else ""
        log_fn(
            f"{label}{suffix}: sağlayıcı kullanım bilgisini döndürmedi; "
            "token/maliyet sağlayıcı panelinden doğrulanmalı.", "warn")
    return False


