def _batch_error_file_entries(content: str, limit: int = 5) -> tuple[list, int]:
    entries = []
    malformed = 0
    for line in str(content or "").splitlines()[:100]:
        if not line.strip():
            continue
        try:
            row = json.loads(line)
            error = row.get("error") or {}
            message = error.get("message", "") if isinstance(error, dict) else str(error)
            entries.append((str(row.get("custom_id", "?")), str(message)))
        except Exception:
            malformed += 1
        if len(entries) >= max(0, int(limit)):
            break
    return entries, malformed


# CustomTkinter ZeroDivisionError patch (scaling 0 olduğunda çöküyor)
# Bilinen bug: https://github.com/TomSchimansky/CustomTkinter/issues/2295
# Pencere boyutlandırma sırasında __window_scaling veya __widget_scaling
# bazen 0 oluyor ve _reverse_window_scaling / _reverse_widget_scaling
# bölme hatası veriyor. Aşağıdaki monkey-patch o iki metoda fallback ekler.
# ─────────────────────────────────────────────────────────────────────
try:
    from customtkinter.windows.widgets.scaling.scaling_base_class import ScalingBaseClass as _SBC

    def _safe_reverse_widget_scaling(self, value):
        s = getattr(self, "_ScalingBaseClass__widget_scaling", 1.0) or 1.0
        try:
            return value / s
        except ZeroDivisionError:
            return value

    def _safe_reverse_window_scaling(self, scaled_value):
        s = getattr(self, "_ScalingBaseClass__window_scaling", 1.0) or 1.0
        try:
            return int(scaled_value / s)
        except ZeroDivisionError:
            return int(scaled_value)

    _SBC._reverse_widget_scaling = _safe_reverse_widget_scaling
    _SBC._reverse_window_scaling = _safe_reverse_window_scaling
except Exception:
    pass


def _install_customtkinter_dpi_guard(root_cls=None, toplevel_cls=None):
    """CustomTkinter 5.2.2'nin monitör geçişindeki boyut kilidi hatasını düzelt."""
    if root_cls is None or toplevel_cls is None:
        try:
            from customtkinter.windows.ctk_tk import CTk as root_cls
            from customtkinter.windows.ctk_toplevel import CTkToplevel as toplevel_cls
        except Exception:
            return False

    def _block_dimensions(self):
        self._block_update_dimensions_event = True

    def _unblock_dimensions(self):
        self._block_update_dimensions_event = False
        callback = getattr(self, "_after_dpi_scaling", None)
        if callable(callback):
            try:
                self.after_idle(callback)
            except Exception:
                pass

    for cls in (root_cls, toplevel_cls):
        if getattr(cls, "_subtitle_dpi_guard_installed", False):
            continue
        cls.block_update_dimensions_event = _block_dimensions
        cls.unblock_update_dimensions_event = _unblock_dimensions
        cls._subtitle_dpi_guard_installed = True
    return True


def _refresh_scrollable_frame_after_dpi(frame):
    canvas = getattr(frame, "_parent_canvas", None)
    if canvas is None:
        return False
    try:
        old_view = canvas.yview()
        bounds = canvas.bbox("all")
        if bounds:
            canvas.configure(scrollregion=bounds)
        if old_view:
            canvas.yview_moveto(max(0.0, min(1.0, float(old_view[0]))))
        return True
    except Exception:
        return False


def _log_view_at_bottom(yview, tolerance: float = 0.002) -> bool:
    try:
        _top, bottom = yview
        return float(bottom) >= 1.0 - tolerance
    except (TypeError, ValueError):
        return False


def _dashboard_stat_columns(content_width: int) -> int:
    """Dar ana panelde istatistik kartlarını iki satıra böler."""
    try:
        return 6 if int(content_width) >= 900 else 3
    except (TypeError, ValueError):
        return 3


PIPELINE_STAGE_LABELS = ("Hazırlık", "Çeviri", "Kalite", "Teslim")


def _pipeline_stage_index(phase: str) -> int:
    """Görünür faz adını dört kullanıcı aşamasından birine indirger."""
    value = str(phase or "").strip().casefold()
    if any(token in value for token in (
            "tamam", "teslim", "çıktı", "yazıyor", "hata")):
        return 3
    if any(token in value for token in (
            "critic", "polish", "native", "qc", "nihai", "mutabakat",
            "tutarlılık", "terim", "sdh", "post-işlem", "kalite")):
        return 2
    if any(token in value for token in (
            "çeviri", "translation", "onarım", "repair")):
        return 1
    return 0


def _phase_detail_text(phase: str, detail: str) -> str:
    if detail:
        return str(detail)
    if str(phase or "").strip().casefold().startswith("hazır"):
        return "Dosya veya klasör ekleyerek başlayın."
    return ""


def _job_board_counts(rows) -> dict:
    counts = {"waiting": 0, "running": 0, "done": 0,
              "skip": 0, "error": 0}
    for row in (rows or {}).values():
        state = str(row.get("state", "waiting") or "waiting").casefold()
        if state not in counts:
            state = "waiting"
        counts[state] += 1
    return counts


def _job_board_summary_text(rows) -> str:
    counts = _job_board_counts(rows)
    finished = counts["done"] + counts["skip"]
    return (
        f"○ {counts['waiting']}   ● {counts['running']}   "
        f"✓ {finished}   ! {counts['error']}")


def _readiness_view(file_count: int, target: str, profile: str,
                    running: bool = False) -> tuple[str, str, str]:
    count = max(0, int(file_count or 0))
    target = str(target or "Hedef dil seçilmedi").strip()
    profile = str(profile or "Özel").strip()
    detail = (
        f"{count} dosya  ·  {target}  ·  {profile}"
        if count else "Dosya veya klasör ekleyin")
    if running:
        return "ÇALIŞIYOR", detail, "active"
    if count:
        return "ÇEVİRİYE HAZIR", detail, "ready"
    return "DOSYA BEKLENİYOR", detail, "waiting"


APP_WINDOW_TITLE = "Subtitle Translator"


def _progress_window_title(phase: str, detail: str = "",
                           progress: float = 0.0,
                           running: bool = False) -> str:
    phase = re.sub(r"\s+", " ", str(phase or "")).strip()
    phase_key = phase.casefold()
    if not phase or phase_key.startswith("hazır"):
        return APP_WINDOW_TITLE
    if any(token in phase_key for token in (
            "tamam", "kısmen", "hata", "durduruldu", "iptal")):
        return f"{phase} — {APP_WINDOW_TITLE}"
    if not running:
        return APP_WINDOW_TITLE
    try:
        pct = max(0, min(100, int(round(float(progress) * 100))))
    except (TypeError, ValueError):
        pct = 0
    focus = re.sub(r"\s+", " ", str(detail or "")).strip()
    if "—" in focus:
        focus = focus.split("—", 1)[0].strip()
    if len(focus) > 42:
        focus = focus[:39].rstrip() + "…"
    parts = [phase, f"%{pct}"]
    if focus:
        parts.append(focus)
    return " · ".join(parts) + f" — {APP_WINDOW_TITLE}"


def _phase_activity_indicator(activity: str, age_seconds: float,
                              pulse_step: int = 0) -> str:
    label = re.sub(r"\s+", " ", str(activity or "ÇALIŞIYOR")).strip()
    try:
        elapsed = max(0, int(float(age_seconds)))
    except (TypeError, ValueError):
        elapsed = 0
    if elapsed >= 8:
        minutes, seconds = divmod(elapsed, 60)
        return f"BEKLİYOR · {minutes}:{seconds:02d}"
    dots = "·" * (1 + (max(0, int(pulse_step or 0)) // 3) % 3)
    return f"{label} {dots}"


