LANGUAGES = [
    "Turkish","English","German","French","Spanish","Italian",
    "Portuguese","Russian","Japanese","Korean","Chinese","Arabic",
    "Dutch","Polish","Swedish","Norwegian","Danish","Finnish",
]
AUTO_LANGUAGE = "Otomatik"
UNRESOLVED_LANGUAGE = "Dil seçin"
SOURCE_LANGUAGES = [AUTO_LANGUAGE] + LANGUAGES
CONFIRM_SOURCE_LANGUAGES = [UNRESOLVED_LANGUAGE] + LANGUAGES
# Naive `name.lower()[:2]` guesses the ISO 639-1 code from the English language
# name — wrong for over half of LANGUAGES (Turkish->"tu" not "tr", German->"ge"
# not "de", Spanish->"sp" not "es", Portuguese/Polish collide on "po", Chinese
# ->"ch" not "zh", Dutch->"du" not "nl", Swedish->"sw" not "sv"). Since
# sanitize_glossary_for_turkish's target-language guard only recognizes "tr"/
# "tur"/"turkish", the "tu" produced for Turkish silently disabled every
# glossary-poisoning guard (wqx/gloss-marker/verbose-meta-commentary) in
# production — the language name never matched, so the sanitizer always took
# its "unrecognized target, return unmodified" early exit.
_LANGUAGE_ISO639_1 = {
    "turkish": "tr", "türkçe": "tr", "turkce": "tr",
    "english": "en", "german": "de", "french": "fr",
    "spanish": "es", "italian": "it", "portuguese": "pt", "russian": "ru",
    "japanese": "ja", "korean": "ko", "chinese": "zh", "arabic": "ar",
    "dutch": "nl", "polish": "pl", "swedish": "sv", "norwegian": "no",
    "danish": "da", "finnish": "fi",
}


def _lang_iso639_1(name: str) -> str:
    """LANGUAGES display name -> correct ISO 639-1 code (falls back to a naive
    2-letter slice for anything not in the table above)."""
    key = str(name or "").strip().lower()
    return _LANGUAGE_ISO639_1.get(key) or key[:2]


def normalize_language_name(name: str, allow_auto: bool = True) -> str:
    raw = str(name or "").strip()
    if allow_auto and raw.lower() in {"auto", "automatic", "otomatik", "dil seçin", "dil secin"}:
        return AUTO_LANGUAGE
    for language in LANGUAGES:
        if language.lower() == raw.lower():
            return language
    code = raw.lower()
    for language in LANGUAGES:
        if _lang_iso639_1(language) == code:
            return language
    return AUTO_LANGUAGE if allow_auto else ""


def _video_track_language(tag: str) -> str:
    """FFmpeg stream tag -> a supported per-file source language."""
    raw = str(tag or "").strip()
    if not raw:
        return AUTO_LANGUAGE
    token = raw.casefold().replace("_", "-").split("-", 1)[0]
    return _FILENAME_LANGUAGE_TOKENS.get(token, normalize_language_name(token))


_FILENAME_LANGUAGE_TOKENS = {
    "tur": "Turkish", "turkish": "Turkish",
    "eng": "English", "english": "English",
    "deu": "German", "ger": "German", "german": "German",
    "fra": "French", "fre": "French", "french": "French",
    "spa": "Spanish", "spanish": "Spanish",
    "ita": "Italian", "italian": "Italian",
    "por": "Portuguese", "portuguese": "Portuguese",
    "rus": "Russian", "russian": "Russian",
    "jpn": "Japanese", "japanese": "Japanese",
    "kor": "Korean", "korean": "Korean",
    "zho": "Chinese", "chi": "Chinese", "chinese": "Chinese",
    "ara": "Arabic", "arabic": "Arabic",
    "nld": "Dutch", "dut": "Dutch", "dutch": "Dutch",
    "pol": "Polish", "polish": "Polish",
    "swe": "Swedish", "swedish": "Swedish",
    "nor": "Norwegian", "norwegian": "Norwegian",
    "dan": "Danish", "danish": "Danish",
    "fin": "Finnish", "finnish": "Finnish",
}


def infer_source_language_from_filename(filename: str) -> str:
    """Yalnız açık release etiketi olan dosya adlarında muhafazakâr dil fallback'i."""
    stem = Path(str(filename or "")).stem.casefold()
    tokens = re.findall(r"[a-z]+|\d+", stem)
    if not tokens:
        return AUTO_LANGUAGE
    has_prior_release_number = False
    candidates = set()
    for pos, token in enumerate(tokens):
        if token.isdigit() and len(token) >= 3:
            has_prior_release_number = True
            continue
        language = _FILENAME_LANGUAGE_TOKENS.get(token)
        if not language:
            continue
        is_code = len(token) == 3
        is_last_token = pos == len(tokens) - 1
        if is_last_token or has_prior_release_number or (is_code and pos >= len(tokens) - 2):
            candidates.add(language)
    return next(iter(candidates)) if len(candidates) == 1 else AUTO_LANGUAGE


def prepare_source_language_confirm_items(detected: dict) -> dict:
    """Prepares items for the source language preflight confirmation dialog.
    Returns: {fp: {"initial": str, "is_failed": bool}}
    Failed detections (AUTO_LANGUAGE or invalid) get initial UNRESOLVED_LANGUAGE ("Dil seçin")
    and is_failed True.
    """
    items = {}
    for fp, raw_lang in detected.items():
        norm = normalize_language_name(raw_lang, allow_auto=False)
        if norm:
            items[fp] = {"initial": norm, "is_failed": False}
        else:
            items[fp] = {"initial": UNRESOLVED_LANGUAGE, "is_failed": True}
    return items


def validate_source_language_selections(selections: dict) -> tuple[bool, list]:
    """Validates user selections from the preflight confirmation dialog.
    Returns (is_valid, unresolved_filepaths).
    is_valid is True only if every file has a valid supported language selected.
    """
    unresolved = []
    for fp, val in selections.items():
        norm = normalize_language_name(val, allow_auto=False)
        if not norm:
            unresolved.append(fp)
    return (len(unresolved) == 0, unresolved)


def resolve_source_language_preflight(detected_input: dict, user_selections: dict, action: str) -> tuple[bool, dict]:
    """Resolves the final preflight state and map to apply.
    Returns: (should_continue: bool, final_applied_map: dict)

    Rules:
    - If action != 'continue': should_continue is False.
    - If action == 'continue':
        - If any file in user_selections is unresolved: should_continue is False.
        - If all files resolved: should_continue is True.
    - final_applied_map contains resolved language names for resolved files,
      and AUTO_LANGUAGE ("Otomatik") for unresolved files (NEVER "English").
    """
    is_valid, unresolved = validate_source_language_selections(user_selections)
    should_continue = (action == "continue") and is_valid

    final_map = {}
    for fp in detected_input:
        user_val = user_selections.get(fp, "")
        norm = normalize_language_name(user_val, allow_auto=False)
        if norm:
            final_map[fp] = norm
        else:
            final_map[fp] = AUTO_LANGUAGE

    return (should_continue, final_map)


def centered_dialog_geometry(parent_x: int, parent_y: int, parent_width: int,
                             parent_height: int, dialog_width: int,
                             dialog_height: int) -> str:
    """Dialogu, negatif koordinatlı ikinci monitörlerde de ebeveynin içinde ortalar."""
    x = int(parent_x) + max((int(parent_width) - int(dialog_width)) // 2, 0)
    y = int(parent_y) + max((int(parent_height) - int(dialog_height)) // 2, 0)
    return f"{int(dialog_width)}x{int(dialog_height)}{x:+d}{y:+d}"


