def _apply_boundary_quality_values(snapshot: dict, values: dict) -> dict:
    if not isinstance(snapshot, dict) or not isinstance(values, dict):
        return {}
    changed = {}
    for key in _BOUNDARY_QUALITY_VARS:
        if key not in values:
            continue
        new_value = bool(values[key])
        old_value = bool(snapshot.get(key))
        snapshot[key] = new_value
        if old_value != new_value:
            changed[key] = (old_value, new_value)
    if changed:
        snapshot["quality_snapshot_revision"] = int(
            snapshot.get("quality_snapshot_revision", 0) or 0) + 1
    return changed


def _content_detection_detail(value) -> dict:
    if isinstance(value, dict):
        category = normalize_schema_name(value.get("category", "Otomatik"))
        raw_confidence = value.get("confidence")
    else:
        category = normalize_schema_name(value or "Otomatik")
        raw_confidence = None
    try:
        confidence = float(raw_confidence)
        if 1.0 < confidence <= 100.0 and confidence.is_integer():
            confidence /= 100.0
        confidence = max(0.0, min(1.0, confidence))
    except (TypeError, ValueError):
        confidence = None
    return {"category": category, "confidence": confidence}


def _set_windows_sleep_prevention(enabled: bool) -> bool:
    if os.name != "nt":
        return False
    try:
        import ctypes
        es_continuous = 0x80000000
        es_system_required = 0x00000001
        flags = es_continuous | (es_system_required if enabled else 0)
        return bool(ctypes.windll.kernel32.SetThreadExecutionState(flags))
    except Exception:
        return False


def _apply_quality_profile_defaults(settings: dict) -> bool:
    if settings.get("quality_profile_version") == QUALITY_PROFILE_VERSION:
        return False
    previous_version = settings.get("quality_profile_version")
    if previous_version == 5:
        settings.update(RESELLER_ROUTING_DEFAULTS)
    if previous_version in {5, 6}:
        settings.update({
            "hybrid": True,
            "analysis_depth": "Gelişmiş",
            "critic": True,
            "polish": False,
            "native": False,
            "qc": False,
            "backtrans": False,
            "semantic_reconcile": False,
            "review_pass": False,
            "term_normalize": True,
            "quality_report_only": True,
            "chain_ctx": True,
            "clean_sdh": True,
            "backup_raw": True,
            "season_canon": False,
        })
        settings["series_memory"] = settings.get("media_mode", "Dizi") == "Dizi"
        settings["quality_profile_version"] = QUALITY_PROFILE_VERSION
        return True
    if "analysis_depth" not in settings or "chunk_size" not in settings:
        return False
    settings.update(QUALITY_PROFILE_DEFAULTS)
    settings["quality_profile_version"] = QUALITY_PROFILE_VERSION
    return True

