def _api_operation_label(checkpoint_label: str) -> str:
    return _API_OPERATION_LABELS.get(
        str(checkpoint_label or ""), "API İşlemi")


def _api_context_text(details: dict | None, include_attempt: bool = True) -> str:
    info = dict(details or {})
    parts = []
    model = str(info.get("model") or "").strip()
    provider = str(info.get("provider") or "").strip()
    if model:
        parts.append(model)
    if provider:
        parts.append(provider)
    attempt = int(info.get("attempt") or info.get("next_attempt") or 0)
    maximum = int(info.get("max_attempts") or 0)
    if include_attempt and attempt and maximum:
        parts.append(f"deneme {attempt}/{maximum}")
    return " · ".join(parts)


def _api_stall_thresholds(elapsed: float) -> tuple[int, ...]:
    elapsed = max(0.0, float(elapsed or 0.0))
    return tuple(threshold for threshold in (120, 240) if elapsed >= threshold)


def _run_summary_data(record: dict) -> dict:
    statuses = {"done": [], "error": [], "skip": [], "pending": []}
    for path, state in dict(record.get("files") or {}).items():
        status = str((state or {}).get("status") or "pending")
        statuses[status if status in statuses else "pending"].append(path)
    return {
        "run_id": record.get("run_id", ""),
        "started_at": record.get("started_at", ""),
        "ended_at": record.get("ended_at", ""),
        "duration_seconds": float(record.get("duration_seconds", 0) or 0),
        "status": record.get("status", ""),
        "counts": {key: len(value) for key, value in statuses.items()},
        "files": statuses,
        "fixes_applied": int(record.get("fixes_applied", 0) or 0),
        "suggestions_rejected": int(record.get("suggestions_rejected", 0) or 0),
        "warnings": int(record.get("warnings", 0) or 0),
        "errors": int(record.get("errors", 0) or 0),
        "api": copy.deepcopy(record.get("api") or {}),
        "settings_fingerprint": record.get("settings_fingerprint", ""),
        "checkpoint_origin_run_id": record.get("checkpoint_origin_run_id", ""),
        "outputs": list(dict.fromkeys(record.get("outputs") or [])),
        "reports": list(dict.fromkeys(record.get("reports") or [])),
        "completion_markers": list(dict.fromkeys(
            record.get("completion_markers") or [])),
        "log_path": record.get("log_path", ""),
    }


def build_run_summary_text(record: dict) -> str:
    data = _run_summary_data(record)
    counts = data["counts"]
    lines = [
        "SON ÇALIŞTIRMA ÖZETİ",
        f"Çalışma kimliği : {data['run_id']}",
        f"Başlangıç        : {data['started_at']}",
        f"Bitiş            : {data['ended_at'] or 'devam ediyor'}",
        f"Toplam süre      : {_format_elapsed(data['duration_seconds'])}",
        f"Durum            : {data['status'] or 'çalışıyor'}",
        f"Ayar parmak izi  : {data.get('settings_fingerprint') or '-'}",
        f"Checkpoint kökeni: {data.get('checkpoint_origin_run_id') or '-'}",
        "",
        f"Toplam dosya     : {sum(counts.values())}",
        f"Tamamlanan       : {counts['done']}",
        f"Başarısız        : {counts['error']}",
        f"Atlanan          : {counts['skip']}",
        f"Bekleyen         : {counts['pending']}",
        f"Düzeltme         : {data['fixes_applied']}",
        f"Reddedilen öneri : {data['suggestions_rejected']}",
        f"Uyarı / hata     : {data['warnings']} / {data['errors']}",
    ]
    api = data["api"]
    if api:
        lines.extend([
            "",
            "API SÜRECİ:",
            f"  Gerçek istek   : {int(api.get('attempts', 0) or 0)}",
            f"  Başarılı       : {int(api.get('successes', 0) or 0)}",
            f"  Başarısız      : {int(api.get('failures', 0) or 0)}",
            f"  Kalıcı hata    : {int(api.get('terminal_failures', 0) or 0)}",
            f"  Yeniden deneme : {int(api.get('retries', 0) or 0)}",
            f"  Sağlayıcı mola : {int(api.get('provider_pauses', 0) or 0)}",
            f"  API yanıt süresi: {_format_elapsed(api.get('duration_seconds'))}",
        ])
        operations = dict(api.get("operations") or {})
        if operations:
            lines.append("  İşlem dağılımı :")
            for name, counts_by_operation in operations.items():
                lines.append(f"    - {name}: {_format_api_operation(counts_by_operation)}")
                fingerprints = list(counts_by_operation.get("request_fingerprints") or [])
                if fingerprints:
                    lines.append(
                        "      İstek/prompt parmak izi: " + ", ".join(fingerprints))
        usage_by_pass = dict(api.get("usage_by_pass") or {})
        if usage_by_pass:
            lines.append("  Pass bazlı API harcaması:")
            for name, usage in usage_by_pass.items():
                lines.append(f"    - {name}: {_format_api_usage(usage)}")
        checkpoint_hits = dict(api.get("checkpoint_hits_by_pass") or {})
        if checkpoint_hits:
            lines.append("  Checkpoint'ten karşılanan istekler:")
            checkpoint_fingerprints = dict(
                api.get("checkpoint_fingerprints_by_pass") or {})
            for name, count in checkpoint_hits.items():
                detail = f"    - {name}: {int(count or 0)} istek"
                fingerprints = checkpoint_fingerprints.get(name) or []
                if fingerprints:
                    detail += " | parmak izi " + ", ".join(fingerprints)
                lines.append(detail)
        diagnostics = list(api.get("diagnostics") or _api_diagnostic_findings(api))
        if diagnostics:
            lines.extend(["", "API / PASS TEŞHİS BULGULARI:"])
            lines.extend(f"  - {_format_api_diagnostic(item)}" for item in diagnostics)
    for title, values in (
        ("Başarısız dosyalar", data["files"]["error"]),
        ("Üretilen çıktılar", data["outputs"]),
        ("Üretilen raporlar", data["reports"]),
        ("ÇEVRİLDİ işaretleri", data["completion_markers"]),
    ):
        if values:
            lines.extend(["", f"{title}:"])
            lines.extend(f"  - {value}" for value in values)
    file_items = dict(record.get("files") or {})
    if file_items:
        lines.extend(["", "DOSYA BAZLI SÜRELER:"])
        for path, item in file_items.items():
            status = str(item.get("status") or "pending")
            lines.append(f"  - {Path(path).name} [{status}]")
            lines.append(f"    Kuyruğa giriş : {item.get('queued_at') or '-'}")
            lines.append(f"    Başlangıç     : {item.get('started_at') or '-'}")
            lines.append(f"    Bitiş         : {item.get('ended_at') or '-'}")
            lines.append(
                f"    Toplam süre   : {_format_elapsed(item.get('duration_seconds'))}")
            totals = _timing_stage_totals(item)
            if totals:
                lines.append("    Aşamalar      : " + ", ".join(
                    f"{name}={_format_elapsed(seconds)}"
                    for name, seconds in totals))
    if data["log_path"]:
        lines.extend(["", f"Log: {data['log_path']}"])
    return "\n".join(lines) + "\n"


_COMPLETION_MARKER_NAME = "ÇEVRİLDİ.txt"


def _completion_marker_root(source: Path, roots: list[Path]) -> Path | None:
    matches = []
    for root in roots:
        try:
            source.resolve(strict=False).relative_to(root.resolve(strict=False))
            matches.append(root)
        except (OSError, ValueError):
            continue
    if matches:
        return max(matches, key=lambda value: len(value.parts))
    if source.parent.is_dir():
        return source.parent
    return None


def _completion_marker_groups(record: dict) -> list[tuple[Path, list[str]]]:
    files = dict(record.get("files") or {})
    settings = dict(record.get("settings") or {})
    roots = [Path(value) for value in settings.get("selected_folder_roots") or ()
             if str(value or "").strip()]
    groups = {}
    for filepath, state in files.items():
        source = Path(filepath)
        group_root = _completion_marker_root(source, roots)
        if group_root is None:
            continue
        groups.setdefault(group_root, []).append((str(source), state or {}))
    completed = []
    for root, members in groups.items():
        if not members or not all(
                str(state.get("status")) == "done"
                for _path, state in members):
            continue
        if not all(
                str(state.get("output_path") or "").strip()
                and Path(str(state.get("output_path"))).is_file()
                for _path, state in members):
            continue
        tracked = {
            os.path.normcase(os.path.abspath(path))
            for path, _state in members
        }
        output_dir = str(settings.get("output_dir") or "")
        excluded = _nested_output_exclusions(
            [root], output_dir,
            same_folder=bool(settings.get("same_folder")))
        discovered = {
            os.path.normcase(os.path.abspath(path))
            for path in get_subtitle_files(
                str(root), recursive=True, exclude_paths=excluded)
        }
        if not discovered or discovered != tracked:
            continue
        completed.append((root, [path for path, _state in members]))
    return completed


def _completion_marker_text(record: dict, source_files: list[str]) -> str:
    settings = dict(record.get("settings") or {})
    lines = [
        "ÇEVRİLDİ",
        f"Çalıştırma kimliği: {record.get('run_id') or '-'}",
        f"Tamamlanma: {record.get('ended_at') or '-'}",
        f"Çevrilen altyazı sayısı: {len(source_files)}",
    ]
    output_dir = str(settings.get("output_dir") or "").strip()
    if output_dir:
        lines.append(f"Çıktı klasörü: {output_dir}")
    lines.extend(["", "Kaynak altyazılar:"])
    lines.extend(f"- {Path(path).name}" for path in source_files)
    return "\n".join(lines) + "\n"


def _write_completion_markers(record: dict, errors: list[str] | None = None) -> list[str]:
    local_errors = errors if errors is not None else []
    written = []
    completed = _completion_marker_groups(record)
    completed_roots = {root for root, _source_files in completed}
    settings = dict(record.get("settings") or {})
    roots = [Path(value) for value in settings.get("selected_folder_roots") or ()
             if str(value or "").strip()]
    candidate_roots = {
        group_root
        for source_path in (record.get("files") or {})
        for group_root in [_completion_marker_root(Path(source_path), roots)]
        if group_root is not None
    }
    for root in candidate_roots - completed_roots:
        marker = root / _COMPLETION_MARKER_NAME
        try:
            marker.unlink(missing_ok=True)
        except Exception as exc:
            local_errors.append(f"{marker}: eski işaret kaldırılamadı ({exc})")
    for root, source_files in completed:
        if not root.is_dir():
            continue
        marker = root / _COMPLETION_MARKER_NAME
        try:
            atomic_write_text(
                marker, _completion_marker_text(record, source_files),
                encoding="utf-8")
            written.append(str(marker))
        except Exception as exc:
            local_errors.append(f"{marker}: işaret yazılamadı ({exc})")
    if errors is None and local_errors:
        raise OSError("; ".join(local_errors))
    return written


def _post_ui(self, fn, *args, **kwargs):
    """Worker thread'lerden veya ana thread'den UI callback'lerini güvenli şekilde kuyruğa ekler.
    Worker thread'deyse Tcl/Tk çağrısı YAPMAZ; sadece Python queue.Queue'ya koyar.
    """
    if getattr(self, "_is_shutting_down", False):
        return
    if threading.current_thread() is threading.main_thread():
        try:
            fn(*args, **kwargs)
        except Exception as e:
            print(f"[UI Dispatcher Direct Error] {fn}: {e}")
        return
    ui_q = getattr(self, "_ui_queue", None)
    if ui_q is not None:
        ui_q.put((fn, args, kwargs))

def _count_hata_cps(blocks) -> tuple:
    """(idx, ts, text) bloklarında eksik çeviri ve CPS aşımı sayısını döner."""
    hata = cps_n = 0
    for _idx, _ts, _txt in blocks:
        if str(_txt).startswith("[HATA") or str(_txt).strip() == "[ÇEVİRİ EKSİK]":
            hata += 1
            continue
        try:
            dur = max(_ts_end_sec_gui(_ts) - _ts_to_sec_gui(_ts), 0.1)
            if len(str(_txt).replace("\n", "")) / dur > CPS_WARN_LIMIT:
                cps_n += 1
        except Exception:
            pass
    return hata, cps_n


def _blocks_have_translation_failures(blocks) -> bool:
    return any(
        str(text or "").startswith("[HATA")
        or "[ÇEVİRİ EKSİK]" in str(text or "")
        for _idx, _ts, text in (blocks or [])
    )


def _partition_quality_blocks(blocks):
    order = [str(idx) for idx, _ts, _text in (blocks or [])]
    failed = {
        str(idx): (idx, ts, text)
        for idx, ts, text in (blocks or [])
        if _blocks_have_translation_failures([(idx, ts, text)])
    }
    healthy = [
        block for block in (blocks or []) if str(block[0]) not in failed
    ]
    return healthy, failed, order


def _restore_quality_failure_blocks(blocks, failed: dict, order: list):
    if not failed:
        return list(blocks or [])
    processed = {
        str(idx): (idx, ts, text) for idx, ts, text in (blocks or [])
    }
    restored = []
    used = set()
    for idx in order or []:
        block = failed.get(str(idx), processed.get(str(idx)))
        if block is not None:
            restored.append(block)
            used.add(str(idx))
    restored.extend(
        block for block in (blocks or []) if str(block[0]) not in used
    )
    return restored


_UNTRANSLATED_ENGLISH_SIGNAL_RE = re.compile(
    r"\b(?:the|and|are|is|was|were|this|that|these|those|with|from|"
    r"what|where|when|why|how|you|your|have|has|not|don't|can't)\b",
    re.IGNORECASE,
)


def _looks_like_untranslated_output(source_text: str, output_text: str) -> bool:
    """Only reject an exact source echo when it is clearly English dialogue.

    Proper names, formulae and screen labels can legitimately remain identical;
    a structural-completeness check must not turn those into retranslation
    loops.  Function-word evidence makes this a deliberately narrow guard.
    """
    source = _align_visible(str(source_text or "")).strip()
    output = _align_visible(str(output_text or "")).strip()
    if len(source) < 8 or source.casefold() != output.casefold():
        return False
    return bool(_UNTRANSLATED_ENGLISH_SIGNAL_RE.search(source))


def _partial_missing_translation_ids(blocks, raw_src_map, source_cues=(), *,
                                     locked_terms=None,
                                     source_language: str | None = None) -> list[str]:
    existing = {str(idx): str(text or "") for idx, _ts, text in (blocks or [])}
    source_ids = []
    for cue in source_cues or []:
        try:
            if hasattr(cue, "text"):
                idx, text = str(cue.index), str(cue.text or "")
            else:
                idx, text = str(cue[0]), str(cue[2] or "")
        except (TypeError, ValueError, IndexError):
            continue
        if text.strip() and not _source_cue_is_delivery_removable(text):
            source_ids.append(idx)
    if not source_ids:
        source_ids = [
            str(idx) for idx, text in (raw_src_map or {}).items()
            if str(text or "").strip()
            and not _source_cue_is_delivery_removable(text)
        ]
    missing = []
    for idx in source_ids:
        src = str((raw_src_map or {}).get(idx, "") or "")
        text = existing.get(idx, "")
        if (not text.strip()
                or text.startswith("[HATA")
                or "[ÇEVİRİ EKSİK]" in text
                or _is_untranslated(
                    src, text, locked_terms=locked_terms,
                    source_language=source_language)):
            missing.append(idx)
    return missing


def _polish_chunk_ranges(blocks, fragment_group_ids, chunk_size):
    ranges = []
    start = 0
    total = len(blocks or [])
    size = max(1, int(chunk_size or 1))

    def _group_id(idx):
        return fragment_group_ids.get(idx, fragment_group_ids.get(str(idx)))

    while start < total:
        end = min(total, start + size)
        while end < total:
            previous_gid = _group_id(blocks[end - 1][0])
            next_gid = _group_id(blocks[end][0])
            if previous_gid is None or previous_gid != next_gid:
                break
            end += 1
        ranges.append((start, end))
        start = end
    return ranges


def _partial_output_path(out_path) -> Path:
    path = Path(out_path)
    return (
        path.parent / "Raporlar" / "Kurtarma"
        / f"{path.stem}.partial{path.suffix}"
    )


def _legacy_partial_output_path(out_path) -> Path:
    path = Path(out_path)
    return path.with_name(f"{path.stem}.partial{path.suffix}")


def _partial_output_candidates(out_path) -> tuple[Path, ...]:
    current = _partial_output_path(out_path)
    legacy = _legacy_partial_output_path(out_path)
    return (current, legacy) if current != legacy else (current,)


def _move_stage_to_partial(stage_path, out_path, report_dir=None,
                           source_hash: str = "") -> Path:
    partial = _partial_output_path(out_path)
    partial.parent.mkdir(parents=True, exist_ok=True)
    if partial.is_file():
        archive = partial.with_name(f"{partial.stem}.superseded.bak{partial.suffix}")
        serial = 2
        while archive.exists():
            archive = partial.with_name(
                f"{partial.stem}.superseded.{serial}.bak{partial.suffix}")
            serial += 1
        atomic_write_bytes(archive, partial.read_bytes())
    Path(stage_path).replace(partial)
    if report_dir is not None and source_hash:
        _write_output_source_fingerprint(report_dir, partial, source_hash)
    return partial


def _archive_completed_partial_output(partial_path, out_path) -> Path | None:
    partial = Path(partial_path)
    if not partial.is_file():
        return None
    archive_dir = Path(out_path).parent / "Raporlar" / "Kurtarma"
    archive_dir.mkdir(parents=True, exist_ok=True)
    target = archive_dir / f"{Path(out_path).stem}.pre-repair.bak{partial.suffix}"
    serial = 2
    while target.exists():
        target = archive_dir / (
            f"{Path(out_path).stem}.pre-repair.{serial}.bak{partial.suffix}")
        serial += 1
    partial.replace(target)
    return target


def _partial_retry_raw_map(partial_blocks, file_map: dict, source_cues) -> tuple:
    source_map = {}
    for cue in source_cues or []:
        try:
            if hasattr(cue, "text"):
                idx = str(cue.index)
                ts = f"{cue.start} --> {cue.end}"
                text = str(cue.text or "")
            else:
                idx, ts, text = str(cue[0]), str(cue[1]), str(cue[2] or "")
            source_map[idx] = (ts.replace(".", ","), text)
        except Exception:
            continue
    partial_map = {
        str(idx): (str(ts).replace(".", ","), str(text or ""))
        for idx, ts, text in (partial_blocks or [])
        if not _DELIVERY_SIGNATURE_RE.fullmatch(str(text or "").strip())
    }
    raw_map = {}
    recovered = missing = 0
    for cid, chunk_info in (file_map or {}).items():
        items = []
        for idx, start, end in chunk_info:
            cue_id = str(idx)
            expected_ts = f"{start} --> {end}".replace(".", ",")
            existing = partial_map.get(cue_id)
            if existing and existing[0] == expected_ts and existing[1].strip():
                text = existing[1]
                if _blocks_have_translation_failures(
                        [(cue_id, expected_ts, text)]):
                    text = "[HATA]"
                    missing += 1
                else:
                    recovered += 1
            else:
                source_ts, source_text = source_map.get(cue_id, ("", ""))
                if (source_ts == expected_ts
                        and (_src_is_sdh_only(source_text)
                             or _is_delivery_credit(source_text))):
                    text = "[MÜZİK]"
                else:
                    text = "[HATA]"
                    missing += 1
            items.append({"i": cue_id, "t": text})
        raw_map[str(cid)] = json.dumps(items, ensure_ascii=False)
    return raw_map, recovered, missing


def _quarantine_incomplete_final(out_path) -> Path | None:
    path = Path(out_path)
    if not path.is_file():
        return None
    if path.parent.name == "Kurtarma" and path.parent.parent.name == "Raporlar":
        return path
    archive_dir = path.parent / "Raporlar" / "Kurtarma"
    archive_dir.mkdir(parents=True, exist_ok=True)
    target = archive_dir / f"{path.stem}.incomplete.bak"
    serial = 2
    while target.exists():
        target = archive_dir / f"{path.stem}.incomplete.{serial}.bak"
        serial += 1
    path.replace(target)
    return target


def _existing_output_is_complete(out_blocks, source_cues) -> bool:
    if not out_blocks or _blocks_have_translation_failures(out_blocks):
        return False
    source_rows = []
    required_positions = set()
    for cue in source_cues or []:
        if hasattr(cue, "index") and not callable(getattr(cue, "index")):
            idx = cue.index
            text = cue.text
            if hasattr(cue, "start") and hasattr(cue, "end"):
                ts = f"{cue.start} --> {cue.end}"
            else:
                ts = None
        else:
            try:
                idx, ts, text = cue
            except (TypeError, ValueError):
                continue
        value = str(text or "")
        bounds = None
        if ts:
            try:
                bounds = _srt_timestamp_bounds(ts)
            except Exception:
                pass
        source_rows.append((str(idx), str(ts or ""), value, bounds))
        if (_has_wordlike_text(_align_visible(value))
                and not _src_is_sdh_only(value)):
            required_positions.add(len(source_rows) - 1)
    if not required_positions:
        return False
    used = set()
    untranslated_echo = False
    for out_idx, ts, text in out_blocks:
        if (not str(text or "").strip()
                or _DELIVERY_SIGNATURE_RE.fullmatch(str(text or "").strip())):
            continue
        try:
            bounds = _srt_timestamp_bounds(ts)
        except Exception:
            bounds = None
        positions = (
            _source_positions_for_delivery_span(source_rows, bounds, used)
            if bounds else [])
        if positions:
            used.update(positions)
            if any(_looks_like_untranslated_output(
                    source_rows[pos][2], text) for pos in positions):
                untranslated_echo = True
            continue
        id_pos = next((
            pos for pos, (source_idx, _source_ts, _source_text, source_bounds)
            in enumerate(source_rows)
            if pos not in used and source_idx == str(out_idx)
            and source_bounds is None
        ), None)
        if id_pos is not None:
            used.add(id_pos)
            if _looks_like_untranslated_output(source_rows[id_pos][2], text):
                untranslated_echo = True
    return required_positions <= used and not untranslated_echo


def _should_skip_existing_output(filepath, out_blocks, source_cues,
                                 force_retranslate_paths=()) -> bool:
    key = os.path.normcase(os.path.abspath(str(filepath)))
    forced = {
        os.path.normcase(os.path.abspath(str(path)))
        for path in (force_retranslate_paths or ())
    }
    return key not in forced and _existing_output_is_complete(
        out_blocks, source_cues)


def _output_source_fingerprint_path(report_dir, output_path) -> Path:
    resolved = os.path.normcase(os.path.abspath(str(output_path)))
    token = hashlib.sha256(resolved.encode("utf-8", "replace")).hexdigest()[:16]
    return Path(report_dir) / f"{Path(output_path).stem}.{token}.source.sha256"


def _output_matches_source_fingerprint(report_dir, output_path, source_path) -> bool:
    sidecar = _output_source_fingerprint_path(report_dir, output_path)
    try:
        expected = sidecar.read_text(encoding="utf-8").strip()
    except Exception:
        return False
    return bool(expected) and expected == _file_content_sha256(source_path)


def _archive_delivery_source(source_path, output_path, source_hash="") -> Path:
    source = Path(source_path)
    if not source.is_file():
        raise FileNotFoundError(source)
    payload = source.read_bytes()
    actual_hash = hashlib.sha256(payload).hexdigest()
    if source_hash and actual_hash != str(source_hash).strip():
        raise OSError("source_changed")
    delivery_parent = Path(output_path).parent
    if (delivery_parent.name.casefold() == "kurtarma"
            and delivery_parent.parent.name.casefold() == "raporlar"):
        delivery_parent = delivery_parent.parent.parent
    archive_dir = delivery_parent / "Raporlar" / "Kaynak"
    archive_dir.mkdir(parents=True, exist_ok=True)
    candidate = archive_dir / source.name
    if candidate.is_file():
        if _file_content_sha256(candidate) == actual_hash:
            return candidate
        candidate = archive_dir / (
            f"{source.stem}.{actual_hash[:12]}{source.suffix}")
        if candidate.is_file() and _file_content_sha256(candidate) == actual_hash:
            return candidate
    atomic_write_bytes(candidate, payload)
    if _file_content_sha256(candidate) != actual_hash:
        candidate.unlink(missing_ok=True)
        raise OSError("source_archive_verification_failed")
    return candidate


def _write_output_source_fingerprint(report_dir, output_path, source_hash,
                                     source_path=None) -> bool:
    if not source_hash:
        return False
    try:
        if source_path is not None:
            _archive_delivery_source(source_path, output_path, source_hash)
        path = _output_source_fingerprint_path(report_dir, output_path)
        path.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_text(path, str(source_hash).strip(), encoding="utf-8")
        return True
    except Exception:
        return False


def _partial_output_recovery_allowed(report_dir, partial_path, source_path,
                                     force_retranslate_paths=()) -> bool:
    normalized = os.path.normcase(os.path.abspath(str(source_path)))
    forced = {
        os.path.normcase(os.path.abspath(str(path)))
        for path in (force_retranslate_paths or ())
    }
    return (
        normalized not in forced
        and Path(partial_path).is_file()
        and _output_matches_source_fingerprint(
            report_dir, partial_path, source_path)
    )


def _recoverable_partial_output_path(report_dir, out_path, source_path,
                                     force_retranslate_paths=()) -> Path | None:
    for candidate in _partial_output_candidates(out_path):
        if _partial_output_recovery_allowed(
                report_dir, candidate, source_path, force_retranslate_paths):
            return candidate
    return None


def _cps_stats(blocks) -> tuple:
    """(cps_avg, cps_max) — CPS dağılım istatistiklerini döndürür."""
    values = []
    for _idx, _ts, _txt in blocks:
        txt = str(_txt or "").replace("\n", "")
        if not txt or txt.startswith("[HATA"):
            continue
        try:
            dur = max(_ts_end_sec_gui(_ts) - _ts_to_sec_gui(_ts), 0.1)
            values.append(len(txt) / dur)
        except Exception:
            pass
    if not values:
        return 0.0, 0.0
    return round(sum(values) / len(values), 1), round(max(values), 1)


def _iter_text_changes(before_blocks, after_blocks):
    """Yield text changes by subtitle id, ignoring restored formatting tags."""
    before = {str(idx): _clean_src(text) for idx, _ts, text in (before_blocks or [])}
    for idx, _ts, text in (after_blocks or []):
        sid = str(idx)
        old = before.get(sid)
        new = _clean_src(text)
        if old is not None and old != new:
            yield sid, old, new


def _count_text_changes(before_blocks, after_blocks) -> int:
    """Count text changes by subtitle id, ignoring restored formatting tags."""
    return sum(1 for _ in _iter_text_changes(before_blocks, after_blocks))


_STRUCTURE_GUARDED_PASSES = frozenset({
    "Review", "Critic", "Polish", "Native", "Condense", "QC auto", "QC",
    "Term-Normalize", "Final-Semantic",
})


def _pass_structure_signature(blocks) -> dict:
    rows = [(str(idx), str(ts), str(text)) for idx, ts, text in (blocks or [])]
    ids = [row[0] for row in rows]
    timestamps = [row[1] for row in rows]
    unresolved = sum(
        1 for _idx, _ts, text in rows
        if str(text).startswith("[HATA") or str(text).strip() == "[ÇEVİRİ EKSİK]")
    return {
        "cue_count": len(rows),
        "duplicate_ids": len(ids) - len(set(ids)),
        "empty_texts": sum(1 for _idx, _ts, text in rows if not text.strip()),
        "unresolved_markers": unresolved,
        "ids_sha256": hashlib.sha256(
            "\n".join(ids).encode("utf-8", "replace")).hexdigest(),
        "timestamps_sha256": hashlib.sha256(
            "\n".join(timestamps).encode("utf-8", "replace")).hexdigest(),
        "text_sha256": hashlib.sha256(
            "\n".join(row[2] for row in rows).encode(
                "utf-8", "replace")).hexdigest(),
    }


def _pass_structure_guard_reason(label: str, before_blocks, after_blocks) -> str:
    if str(label) not in _STRUCTURE_GUARDED_PASSES:
        return ""
    before = _pass_structure_signature(before_blocks)
    after = _pass_structure_signature(after_blocks)
    reasons = []
    if after["cue_count"] != before["cue_count"]:
        reasons.append("cue_count_changed")
    if after["duplicate_ids"]:
        reasons.append("duplicate_cue_id")
    if after["ids_sha256"] != before["ids_sha256"]:
        reasons.append("cue_ids_changed")
    if after["timestamps_sha256"] != before["timestamps_sha256"]:
        reasons.append("timestamps_changed")
    if after["empty_texts"] > before["empty_texts"]:
        reasons.append("new_empty_translation")
    if after["unresolved_markers"] > before["unresolved_markers"]:
        reasons.append("new_unresolved_marker")
    return ",".join(reasons)


def _record_pass_change(trace: dict, label: str, before_blocks, after_blocks,
                         history: dict = None) -> int:
    """Record how many lines a quality pass changed and return that count."""
    before_signature = _pass_structure_signature(before_blocks)
    proposed_changes = list(_iter_text_changes(before_blocks, after_blocks))
    guard_reason = _pass_structure_guard_reason(label, before_blocks, after_blocks)
    if guard_reason:
        event = {
            "pass": str(label), "reason": guard_reason,
            "proposed_changes": len(proposed_changes),
            "sample_ids": [sid for sid, _old, _new in proposed_changes[:10]],
            "before": before_signature,
            "rejected": _pass_structure_signature(after_blocks),
        }
        trace.setdefault("__guard_events__", []).append(event)
        if isinstance(after_blocks, list):
            after_blocks[:] = copy.deepcopy(list(before_blocks or []))
        trace.setdefault(label, 0)
        trace.setdefault("__pass_snapshots__", []).append({
            "pass": str(label), "changed": 0, "rolled_back": True,
            "reason": guard_reason, "before": before_signature,
            "after": _pass_structure_signature(after_blocks),
        })
        return 0
    changes = list(_iter_text_changes(before_blocks, after_blocks))
    n = len(changes)
    trace.setdefault(label, 0)
    if n:
        trace[label] = trace.get(label, 0) + n
        if history is not None:
            for sid, old, new in changes:
                history.setdefault(sid, []).append({
                    "pass": label,
                    "before": old,
                    "after": new,
                })
    trace.setdefault("__pass_snapshots__", []).append({
        "pass": str(label), "changed": n, "rolled_back": False,
        "reason": "", "before": before_signature,
        "after": _pass_structure_signature(after_blocks),
    })
    return n


def _log_exception_or_warning(owner, message: str, exc: Exception) -> None:
    """Keep pass recovery diagnosable even in small test/headless callers."""
    log_exc = getattr(owner, "_log_exc", None)
    if callable(log_exc):
        log_exc(message, exc)
        return
    log = getattr(owner, "_log", None)
    if callable(log):
        log(f"{message}: {exc}", "warn")


def _log_persistence_failure(owner, message: str, exc: Exception) -> None:
    log = getattr(owner, "_log", None)
    if callable(log):
        log(f"{message} ({type(exc).__name__})", "err")


def _record_file_stage_if_available(owner, filepath: str, phase: str,
                                    status: str) -> None:
    """Record timing only when a real run record exists.

    Lightweight/headless pass callers intentionally construct ``App`` without
    Tk or a run record; accessing ordinary attributes on those instances can
    recurse through Tk's ``__getattr__``.
    """
    try:
        state = object.__getattribute__(owner, "__dict__")
    except (AttributeError, TypeError):
        return
    lock = state.get("_run_record_lock") if isinstance(state, dict) else None
    if not hasattr(lock, "__enter__"):
        return
    recorder = state.get("_record_file_status")
    if callable(recorder):
        recorder(filepath, phase, status)
    else:
        App._record_file_status(owner, filepath, phase, status)


def _format_pass_trace(trace: dict) -> str:
    if not trace:
        return ""
    return ", ".join(
        f"{name}: {count}" for name, count in trace.items()
        if not str(name).startswith("__") and count)


_PASS_USAGE_ALIASES = {
    "Review": "Bağlam İncelemesi",
    "Critic": "Critic Pass",
    "Polish": "Polish Pass",
    "Native": "Native Okuyucu",
    "Condense": "Okuma Hızı Kısaltma",
    "QC auto": "QC",
    "QC": "QC",
    "Term-Normalize": "Terim Normalizasyonu",
    "Final-Semantic": "Nihai Anlam Mutabakatı",
}


def _pass_efficiency_rows(row: dict) -> list[dict]:
    trace = dict(row.get("pass_trace") or {})
    pass_status = dict(row.get("pass_status") or {})
    timing = dict(row.get("timing") or {})
    usage_map = dict(timing.get("api_usage") or {})
    result = []
    used_stages = set()
    for label, changed in trace.items():
        if str(label).startswith("__") or not isinstance(changed, (int, float)):
            continue
        stage = _PASS_USAGE_ALIASES.get(str(label), str(label))
        usage = dict(usage_map.get(stage) or {})
        if stage in used_stages and stage == "QC":
            usage = {}
        used_stages.add(stage)
        tokens = int(usage.get("total_tokens", 0) or 0)
        cost = float(usage.get("cost_usd", 0.0) or 0.0)
        changed = int(changed or 0)
        status = pass_status.get(str(label)) or {}
        report_only = bool(
            isinstance(status, dict) and status.get("report_only"))
        suggested = int(status.get("suggested", 0) or 0) if report_only else 0
        result.append({
            "pass": str(label), "stage": stage, "changed": changed,
            "suggested": suggested, "report_only": report_only,
            "tokens": tokens, "cost_usd": cost,
            "tokens_per_change": round(tokens / changed, 2) if changed else None,
            "cost_per_change": round(cost / changed, 8) if changed else None,
            "tokens_per_suggestion": (
                round(tokens / suggested, 2) if suggested else None),
        })
    return result


_REQUIRED_QUALITY_PASS_KEYS = frozenset({
    "Consistency", "Review", "Critic", "Polish", "Native", "Condense",
    "QC", "Term-Normalize", "Final-Semantic", "Backtranslation",
    "Post-processing", "Final-Delivery",
})


def _quality_pass_has_hard_failure(pass_status: dict | None) -> bool:
    for name, detail in dict(pass_status or {}).items():
        if name not in _REQUIRED_QUALITY_PASS_KEYS or not isinstance(detail, dict):
            continue
        state = str(detail.get("status", "")).casefold()
        if state in {"failed", "cancelled"}:
            return True
        if name == "Post-processing" and state == "partial":
            return True
    return False


def _quality_feature_audit(row: dict, snapshot: dict = None) -> list[str]:
    snapshot = snapshot or {}
    trace = row.get("pass_trace") or {}
    pass_status = row.get("pass_status") or {}
    status = str(row.get("run_status") or "done")
    lines = []

    if row.get("repair_only"):
        before = int(row.get("repair_missing_before", 0) or 0)
        after = int(row.get("repair_missing_after", 0) or 0)
        repaired = int(trace.get("Repair", 0) or 0)
        lines.append(
            f"Yalnız Eksik Cue Onarımı: çalıştı, {before} eksikten "
            f"{repaired} cue onarıldı, {after} eksik kaldı")
        lines.append("Yardımcı Analiz: kısmi onarım gereği atlandı")
        lines.append("Zincirleme Bağlam: kısmi onarım gereği atlandı")
        for title in (
                "Tutarlılık taraması", "Bağlam İncelemesi", "Critic Pass", "Polish Pass",
                "Native Okuyucu", "QC", "Nihai Anlam Mutabakatı",
                "Geri Çeviri", "Terim Normalizasyonu", "Okuma Hızı Kısaltma",
                "Auto-Glossary", "Dizi Hafızası", "SDH temizleme",
                "Satır düzenleme"):
            lines.append(f"{title}: kısmi onarım gereği atlandı")
        return lines

    helper_on = bool(row.get("helper_analysis", snapshot.get("hybrid_mode")))
    if helper_on:
        analysis_status = str(row.get("analysis_status") or "etkin")
        lines.append(f"Yardımcı Analiz: {analysis_status}")
        metrics = dict(row.get("analysis_metrics") or {})
        if metrics:
            depth_label = {
                "standard": "Standart", "advanced": "Gelişmiş",
                "maximum": "Maksimum",
            }.get(str(metrics.get("depth") or ""), "Bilinmiyor")
            lines.append(
                f"Analiz kapsam ölçümü [{depth_label}]: "
                f"{int(metrics.get('analysis_chunks', 0) or 0)} analiz chunk, "
                f"{int(metrics.get('terms', 0) or 0)} terim, "
                f"{int(metrics.get('characters', 0) or 0)} karakter, "
                f"{int(metrics.get('pronoun_pairs', 0) or 0)} hitap çifti, "
                f"{int(metrics.get('scenes', 0) or 0)} sahne, "
                f"cue kapsamı %{float(metrics.get('scene_coverage_pct', 0.0) or 0.0):.1f}, "
                f"{int(metrics.get('referent_scenes', 0) or 0)} gönderge, "
                f"{int(metrics.get('goal_scenes', 0) or 0)} konuşmacı hedefi, "
                f"{int(metrics.get('idioms', 0) or 0)} deyim, "
                f"{int(metrics.get('cultural_refs', 0) or 0)} kültürel referans")
            uncovered = int(metrics.get("scene_uncovered_cues", 0) or 0)
            if uncovered:
                ranges = list(metrics.get("scene_uncovered_ranges") or [])
                detail = ",".join(str(value) for value in ranges[:30])
                if len(ranges) > 30:
                    detail += f",+{len(ranges) - 30} aralık"
                lines.append(
                    f"Sahne planı kapsam boşluğu: {uncovered} cue "
                    f"[{detail or '-'}] — bu cue'larda genel/canlı bağlam kullanıldı")
            term_conflicts = list(metrics.get("term_conflicts") or [])
            character_conflicts = list(metrics.get("character_style_conflicts") or [])
            if term_conflicts or character_conflicts:
                def _conflict_text(values):
                    text = ",".join(str(value) for value in values[:20])
                    if len(values) > 20:
                        text += f",+{len(values) - 20}"
                    return text or "-"
                lines.append(
                    "Analiz çatışmaları (prompt/cache dışında bırakıldı): "
                    f"terim [{_conflict_text(term_conflicts)}]; "
                    f"karakter üslubu [{_conflict_text(character_conflicts)}]")
            lines.append(
                "Analiz sonrası karşılaştırma ölçümü: "
                f"Critic {int(trace.get('Critic', 0) or 0)} düzeltme, "
                f"tüm pass'ler {int(row.get('pass_fix', 0) or 0)} değişik cue, "
                f"{int(row.get('warn', 0) or 0)} nihai uyarı, "
                f"{int(row.get('hata', 0) or 0)} eksik/hata")
            lines.append(
                "Analiz derinliği kararı: tek koşu nedensel kanıt değildir; "
                "aynı kaynakta diğer derinliğin raporuyla karşılaştırılmalı")
    else:
        lines.append("Yardımcı Analiz: kapalı")

    chain_on = bool(row.get("chain_ctx", snapshot.get("chain_ctx")))
    chunk_count = int(row.get("translation_chunks", 0) or 0)
    run_mode = str(row.get("mode", snapshot.get("mode", "")) or "").strip().lower()
    twowave_on = bool(row.get("twowave", snapshot.get("twowave")))
    context_metrics = dict(row.get("context_payload_metrics") or {})
    measured_chunks = int(context_metrics.get("chunks", 0) or 0)
    measured_prev_tr = int(context_metrics.get("prev_tr_chunks", 0) or 0)
    if chain_on and run_mode == "batch" and not twowave_on:
        lines.append(
            "Zincirleme Bağlam: açık ama normal Batch'te uygulanmadı "
            "(chunk'lar paralel gönderildi)")
    elif chain_on and measured_prev_tr:
        lines.append(
            f"Zincirleme Bağlam: çalıştı, {measured_prev_tr}/{measured_chunks} "
            "chunk önceki çeviriyi aldı")
    elif chain_on and measured_chunks == 1:
        lines.append(
            "Zincirleme Bağlam: açık; dosya tek chunk olduğu için önceki "
            "çeviri enjeksiyonu gerekmedi")
    elif chain_on and measured_chunks:
        lines.append(
            f"Zincirleme Bağlam: açık ama {measured_chunks} chunk'ın hiçbirine "
            "önceki çeviri enjekte edilmedi")
    elif chain_on and chunk_count:
        lines.append(
            "Zincirleme Bağlam: açık; gerçek enjeksiyon ölçümü bulunamadı")
    elif chain_on:
        lines.append("Zincirleme Bağlam: açık, çalışma kaydı yok")
    else:
        lines.append("Zincirleme Bağlam: kapalı")

    if context_metrics.get("chunks"):
        lines.append(
            "Bağlam taşıma kanıtı: "
            f"{int(context_metrics.get('ctx_chunks', 0))}/{int(context_metrics['chunks'])} chunk önceki kaynak, "
            f"{int(context_metrics.get('next_ctx_chunks', 0))}/{int(context_metrics['chunks'])} chunk sonraki kaynak, "
            f"{int(context_metrics.get('prev_tr_chunks', 0))}/{int(context_metrics['chunks'])} chunk önceki çeviri; "
            f"{int(context_metrics.get('scene_plan_chunks', 0))} chunk sahne planı")
        lines.append(
            "Cümle zinciri kanıtı: "
            f"{int(context_metrics.get('sentence_groups', 0))} çok-cue cümle grubu, "
            f"{int(context_metrics.get('fragment_cues', 0))} parçalı cue, "
            f"{int(context_metrics.get('prev_scene_chunks', 0))} sahne köprüsü")
        def _chunk_context_label(item):
            cue_start = str(item.get("cue_start") or "?")
            cue_end = str(item.get("cue_end") or "?")
            cue_range = (
                f"#{cue_start}-{cue_end}"
                if cue_start != "?" or cue_end != "?" else "")
            return f"{item.get('chunk', '?')}{cue_range}"
        chain_breaks = list(context_metrics.get("chain_breaks") or [])
        if chain_breaks:
            detail = ", ".join(
                f"{_chunk_context_label(item)}[{item.get('reason', '?')}]"
                for item in chain_breaks[:20])
            if len(chain_breaks) > 20:
                detail += f", +{len(chain_breaks) - 20}"
            lines.append(
                f"Zincirleme bağlam kopması: {len(chain_breaks)} chunk — {detail}")
        elif row.get("chain_ctx", snapshot.get("chain_ctx")):
            lines.append("Zincirleme bağlam kopması: yok")
        context_gaps = list(context_metrics.get("context_gap_chunks") or [])
        if context_gaps:
            detail = ", ".join(
                f"{_chunk_context_label(item)}"
                f"[{'|'.join(item.get('reasons') or ['?'])}]"
                for item in context_gaps[:20])
            if len(context_gaps) > 20:
                detail += f", +{len(context_gaps) - 20}"
            lines.append(
                f"Bağlam kaynak boşluğu (inceleme): {len(context_gaps)} chunk — {detail}")

    critic_status = pass_status.get("Critic")
    if isinstance(critic_status, dict):
        reviewed_groups = int(critic_status.get("reviewed_sentence_groups", 0) or 0)
        reviewed_cues = int(critic_status.get("reviewed_sentence_cues", 0) or 0)
        rejected = int(critic_status.get("rejected_count", 0) or 0)
        if reviewed_groups or rejected:
            reasons = dict(critic_status.get("rejected_reasons") or {})
            rejected_ids = []
            for candidate in list(critic_status.get("rejected_candidates") or []):
                cue_id = str(candidate.get("id") or "")
                if cue_id and cue_id not in rejected_ids:
                    rejected_ids.append(cue_id)
                reason = str(candidate.get("reason") or "").strip()
                if reason and reason not in reasons:
                    reasons[reason] = sum(
                        1 for item in critic_status.get("rejected_candidates") or []
                        if str(item.get("reason") or "").strip() == reason)
            reason_text = ", ".join(
                f"{key}:{value}" for key, value in sorted(reasons.items(), key=lambda row: -row[1])
            )
            detail = f"; korunup raporlanan {rejected} öneri"
            if rejected_ids:
                cue_text = ",".join(rejected_ids[:30])
                if len(rejected_ids) > 30:
                    cue_text += f",+{len(rejected_ids) - 30}"
                detail += f"; cue [{cue_text}]"
            if reason_text:
                detail += f" ({reason_text})"
            lines.append(
                f"Critic cümle-zinciri kapsamı: {reviewed_groups} grup/{reviewed_cues} cue{detail}")
        validator_candidates = list(critic_status.get("validator_candidates") or [])
        if validator_candidates:
            reason_counts = {}
            cue_ids = []
            for candidate in validator_candidates:
                cue_id = str(candidate.get("id") or "")
                if cue_id and cue_id not in cue_ids:
                    cue_ids.append(cue_id)
                for reason in str(candidate.get("reason") or "").split("|"):
                    reason = reason.strip()
                    if reason and reason != "CROSS_CUE_SENTENCE_REVIEW":
                        reason_counts[reason] = reason_counts.get(reason, 0) + 1
            reason_text = ", ".join(
                f"{key}:{value}" for key, value in sorted(
                    reason_counts.items(), key=lambda row: -row[1]))
            cue_text = ",".join(cue_ids[:30])
            if len(cue_ids) > 30:
                cue_text += f",+{len(cue_ids) - 30}"
            lines.append(
                f"Critic deterministik inceleme adayları: {len(cue_ids)} cue "
                f"[{cue_text or '-'}]" + (f" ({reason_text})" if reason_text else ""))

    term_status = pass_status.get("Term-Normalize")
    if isinstance(term_status, dict):
        safe_ids = [str(value) for value in term_status.get("safe_candidate_ids") or []]
        rejected_candidates = list(term_status.get("rejected_candidates") or [])
        rejected_ids = []
        for candidate in rejected_candidates:
            cue_id = str(candidate.get("id") or "")
            if cue_id and cue_id not in rejected_ids:
                rejected_ids.append(cue_id)
        response_issues = list(term_status.get("response_issues") or [])
        issue_ids = []
        issue_reasons = {}
        for issue in response_issues:
            cue_id = str(issue.get("id") or "")
            if cue_id and cue_id not in issue_ids:
                issue_ids.append(cue_id)
            reason = str(issue.get("reason") or "unknown")
            issue_reasons[reason] = issue_reasons.get(reason, 0) + 1
        if safe_ids or rejected_ids or issue_ids:
            def _cue_list(values):
                text = ",".join(values[:30])
                if len(values) > 30:
                    text += f",+{len(values) - 30}"
                return text or "-"
            parts = [f"güvenli {len(safe_ids)} cue [{_cue_list(safe_ids)}]"]
            if rejected_ids:
                reasons = dict(term_status.get("rejected_reasons") or {})
                reason_text = ", ".join(
                    f"{key}:{value}" for key, value in sorted(
                        reasons.items(), key=lambda row: -row[1]))
                parts.append(
                    f"korunan {len(rejected_ids)} cue [{_cue_list(rejected_ids)}]"
                    + (f" ({reason_text})" if reason_text else ""))
            if issue_ids:
                reason_text = ", ".join(
                    f"{key}:{value}" for key, value in sorted(
                        issue_reasons.items(), key=lambda row: -row[1]))
                parts.append(
                    f"JSON/kimlik sorunu {len(issue_ids)} cue [{_cue_list(issue_ids)}]"
                    + (f" ({reason_text})" if reason_text else ""))
            lines.append("Terim Normalizasyonu tanısı: " + "; ".join(parts))
            detail_records = []
            for candidate in list(term_status.get("safe_candidates") or []):
                detail_records.append((
                    "yalnız öneri" if term_status.get("report_only") else "uygulandı",
                    candidate,
                ))
            detail_records.extend(
                ("korundu", candidate) for candidate in rejected_candidates)
            def _term_detail_text(value):
                text = " ".join(str(value or "").split())
                return text if len(text) <= 240 else text[:237] + "..."
            for disposition, candidate in detail_records[:30]:
                lines.append(
                    f"Terim kararı #{candidate.get('id', '?')} [{disposition}"
                    + (f":{candidate.get('reason')}" if candidate.get("reason") else "")
                    + f"] kaynak='{_term_detail_text(candidate.get('source'))}' | "
                    f"mevcut='{_term_detail_text(candidate.get('before'))}' | "
                    f"öneri='{_term_detail_text(candidate.get('candidate'))}'")
            if len(detail_records) > 30:
                lines.append(
                    f"Terim kararı ayrıntısı: +{len(detail_records) - 30} kayıt raporda kısaltıldı")

    auto_enabled = bool(snapshot.get("auto_glossary"))
    auto_status = pass_status.get("Auto-Glossary")
    if isinstance(auto_status, dict):
        auto_state = str(auto_status.get("status") or "")
        if auto_state == "completed":
            lines.append(
                f"Auto-Glossary: çalıştı, "
                f"{int(auto_status.get('suggested', 0) or 0)} öneri, "
                f"{int(auto_status.get('written', 0) or 0)} terim eklendi")
        elif auto_state == "skipped":
            lines.append("Auto-Glossary: incelenecek çift olmadığı için atlandı")
        elif auto_state in {"failed", "partial", "cancelled"}:
            auto_text = {
                "failed": "başarısız", "partial": "kısmi tamamlandı",
                "cancelled": "durduruldu",
            }[auto_state]
            lines.append(f"Auto-Glossary: {auto_text}")
        elif auto_enabled:
            lines.append("Auto-Glossary: açık, çalışma kaydı yok")
        else:
            lines.append("Auto-Glossary: kapalı")
    elif auto_enabled:
        lines.append("Auto-Glossary: açık, çalışma kaydı yok")
    else:
        lines.append("Auto-Glossary: kapalı")

    series_enabled = bool(snapshot.get("series_memory"))
    series_status = pass_status.get("Series-Memory")
    if not series_enabled:
        lines.append("Dizi Hafızası: kapalı")
    elif isinstance(series_status, dict):
        series_state = str(series_status.get("status") or "")
        if series_state == "completed":
            lines.append("Dizi Hafızası: çalıştı, bölüm kanonu kaydedildi")
        elif series_state == "failed":
            lines.append("Dizi Hafızası: başarısız")
        elif series_state == "skipped":
            reason = str(series_status.get("reason") or "")
            detail = {
                "not_series": "dizi bölümü algılanmadı",
                "analysis_incomplete": "analiz veya çeviri tamamlanmadı",
            }.get(reason, "uygulanmadı")
            lines.append(f"Dizi Hafızası: atlandı, {detail}")
        else:
            lines.append("Dizi Hafızası: açık, çalışma kaydı yok")
    else:
        lines.append("Dizi Hafızası: açık, çalışma kaydı yok")

    features = (
        ("Tutarlılık taraması", True, ("Consistency", "Final-Consistency")),
        ("Bağlam İncelemesi", bool(row.get("review_expected")), ("Review",)),
        ("Critic Pass", bool(snapshot.get("critic")), ("Critic",)),
        ("Polish Pass", bool(snapshot.get("polish")), ("Polish",)),
        ("Native Okuyucu", bool(snapshot.get("native")), ("Native",)),
        ("QC", bool(snapshot.get("qc")), ("QC auto", "QC")),
        ("Nihai Anlam Mutabakatı", bool(snapshot.get("semantic_reconcile")),
         ("Final-Semantic",)),
        ("Geri Çeviri", bool(snapshot.get("backtrans")),
         ("Backtranslation",)),
        ("Terim Normalizasyonu", bool(snapshot.get("term_normalize")),
         ("Term-Normalize",)),
        ("Eksik Cue API Onarımı", bool(snapshot.get("repair_missing")),
         ("Repair", "Eksik Çeviri Onarımı", "Yalnız Eksik Cue Onarımı")),
        ("Okuma Hızı Kısaltma", bool(snapshot.get("condense")),
         ("Condense",)),
        ("SDH temizleme", bool(snapshot.get("clean_sdh")), ("SDH",)),
        ("Satır düzenleme", bool(snapshot.get("linebreak")), ("Line-break",)),
    )
    for title, enabled, labels in features:
        if title == "Eksik Cue API Onarımı" and not enabled:
            lines.append(f"{title}: kapalı")
            continue
        status_info = next(
            (pass_status.get(label) for label in labels
             if isinstance(pass_status.get(label), dict)), None)
        trace_changed = any(
            int(trace.get(label, 0) or 0) > 0 for label in labels)
        if not enabled and not status_info and not trace_changed:
            lines.append(f"{title}: kapalı")
            continue
        if status_info and status_info.get("status") in {
                "failed", "partial", "cancelled"}:
            state = status_info["status"]
            successful = int(status_info.get("successful_chunks", 0) or 0)
            total = int(status_info.get("total_chunks", 0) or 0)
            changed = max(
                int(status_info.get("changed", 0) or 0),
                sum(int(trace.get(label, 0) or 0) for label in labels),
            )
            detail = f", {successful}/{total} paket başarılı" if total else ""
            if changed:
                detail += f", {changed} cue değiştirdi"
            state_text = {
                "failed": "başarısız",
                "partial": "kısmi tamamlandı",
                "cancelled": "durduruldu",
            }[state]
            lines.append(f"{title}: {state_text}{detail}")
            continue
        ran = [label for label in labels if label in trace]
        if (status_info and status_info.get("status") == "completed"
                and status_info.get("report_only")):
            suggested = int(status_info.get("suggested", 0) or 0)
            lines.append(
                f"{title}: yalnız rapor modunda çalıştı, {suggested} öneri; "
                "altyazı değiştirilmedi")
        elif ran:
            changed = sum(int(trace.get(label, 0) or 0) for label in ran)
            lines.append(f"{title}: çalıştı, {changed} cue değiştirdi")
        elif status_info and status_info.get("status") == "completed":
            changed = int(status_info.get("changed", 0) or 0)
            lines.append(f"{title}: çalıştı, {changed} cue değiştirdi")
        elif enabled:
            reason = "dosya tamamlanamadığı için atlandı" if status == "error" else "açık, çalışma kaydı yok"
            lines.append(f"{title}: {reason}")
        else:
            lines.append(f"{title}: kapalı")
    return lines


def _delivery_visible_line(text: str) -> str:
    value = re.sub(r"\{\\[^}]*\}", "", str(text or ""))
    value = re.sub(r"</?(?:i|b|u)>", "", value, flags=re.IGNORECASE)
    return re.sub(r"\s+", " ", value).strip()


def _delivery_untranslated_fragment_ids(blocks: list, source_map: dict,
                                        target_language="Turkish",
                                        source_language=None) -> list[str]:
    if normalize_language_name(target_language, allow_auto=False) != "Turkish":
        return []
    flagged = []
    for idx, _timestamp, target_text in blocks or []:
        source_text = str((source_map or {}).get(str(idx), "") or "")
        if not source_text:
            continue
        target_visible_lines = [
            _delivery_visible_line(line)
            for line in str(target_text or "").splitlines()
            if _delivery_visible_line(line)
        ]
        target_lines = {line.casefold() for line in target_visible_lines}
        source_lines = source_text.splitlines()
        for source_line_no, source_line in enumerate(source_lines):
            visible = _delivery_visible_line(source_line)
            if (not visible or visible.casefold() not in target_lines
                    or _source_cue_is_delivery_removable(visible)):
                continue
            reason = _untranslated_reason(
                visible, visible, source_language=source_language)
            source_is_english = (
                source_language is None
                or _lang_iso639_1(source_language) == "en")
            foreign_name_line = (
                source_is_english and reason == "identical_source"
                and bool(re.search(r"[^\x00-\x7f]", visible))
                and not bool(re.search(r"[.!?…]\s*$", visible))
            )
            matching_targets = [
                line for line in target_visible_lines
                if line.casefold() == visible.casefold()
            ]
            list_tail_proper_name = (
                source_is_english and reason == "identical_source"
                and source_line_no > 0 and "," in source_text
                and bool(re.fullmatch(
                    r"[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ'’.-]*"
                    r"(?:\s+(?:(?:d|de|del|van|von)['’]?)?"
                    r"[A-ZÀ-ÖØ-Þ][A-Za-zÀ-ÖØ-öø-ÿ'’.-]*){0,5}"
                    r"[.!?…]*",
                    visible))
                and any(line[:1].isupper() for line in matching_targets)
                and any(
                    _delivery_visible_line(sibling).casefold() not in target_lines
                    for sibling in source_lines if _delivery_visible_line(sibling)
                )
            )
            if reason and not foreign_name_line and not list_tail_proper_name:
                flagged.append(str(idx))
                break
    return flagged


def _subtitle_delivery_audit(source_path: str, output_path: str,
                             target_language="Turkish", source_language=None) -> dict:
    audit = {
        "source_path": str(source_path or ""),
        "output_path": str(output_path or ""),
        "status": "unavailable",
    }
    try:
        source = list(parse_subtitle(str(source_path), source_language))
        output = list(parse_subtitle(str(output_path)))
    except Exception as exc:
        audit["error"] = str(exc)
        return audit
    source_rows = [
        (str(idx), str(ts), str(text or "")) for idx, ts, text in source]
    output_dialogue = [
        (str(idx), str(ts), str(text or "")) for idx, ts, text in output
        if not _DELIVERY_SIGNATURE_RE.fullmatch(str(text or "").strip())
    ]
    invalid_timestamp_ids = []
    reversed_timestamp_ids = []
    signature_overlap_ids = []
    duplicate_cue_ids, unnumbered_cue_lines = _srt_raw_cue_id_issues(output_path)
    timed_output = []
    for output_idx, output_ts, output_text in output:
        try:
            start, end = _srt_timestamp_bounds(output_ts)
        except ValueError:
            invalid_timestamp_ids.append(str(output_idx))
            continue
        if end <= start:
            reversed_timestamp_ids.append(str(output_idx))
            continue
        timed_output.append((str(output_idx), start, end, str(output_text or "")))
    for output_idx, start, end, output_text in timed_output:
        if not _DELIVERY_SIGNATURE_RE.fullmatch(output_text.strip()):
            continue
        if any(
                other_idx != output_idx
                and not _DELIVERY_SIGNATURE_RE.fullmatch(other_text.strip())
                and start < other_end and other_start < end
                for other_idx, other_start, other_end, other_text in timed_output):
            signature_overlap_ids.append(output_idx)
    source_with_bounds = []
    for source_idx, source_ts, source_text in source_rows:
        try:
            bounds = _srt_timestamp_bounds(source_ts)
        except ValueError:
            bounds = None
        source_with_bounds.append((source_idx, source_ts, source_text, bounds))
    used_source = set()
    missing_dialogue = []
    expected_removed = []
    timestamp_mismatches = []
    extras = []
    source_to_output_ids = {}
    for output_idx, output_ts, _output_text in output_dialogue:
        try:
            output_bounds = _srt_timestamp_bounds(output_ts)
        except ValueError:
            output_bounds = None
        positions = (
            _source_positions_for_delivery_span(
                source_with_bounds, output_bounds, used_source)
            if output_bounds else [])
        if positions:
            used_source.update(positions)
            for pos in positions:
                source_to_output_ids[source_with_bounds[pos][0]] = output_idx
            continue
        id_pos = next((
            pos for pos, (source_idx, _ts, _text, _bounds)
            in enumerate(source_with_bounds)
            if pos not in used_source and source_idx == output_idx
        ), None)
        if id_pos is not None:
            used_source.add(id_pos)
            source_to_output_ids[source_with_bounds[id_pos][0]] = output_idx
            timestamp_mismatches.append(source_with_bounds[id_pos][0])
        else:
            extras.append(output_idx)
    for pos, (source_idx, _source_ts, source_text, _bounds) in enumerate(
            source_with_bounds):
        if pos in used_source:
            continue
        if _source_cue_is_delivery_removable(source_text):
            expected_removed.append(source_idx)
        else:
            missing_dialogue.append(source_idx)
    extras.sort()
    output_texts = [text for _idx, _ts, text in output_dialogue]
    output_source_map = _delivery_source_map(output_dialogue, source_rows)
    owner_source_map = _delivery_owner_source_map(
        source_rows, source_to_output_ids)
    delivery_owner_mismatch_ids = sorted(
        _chunk_content_owner_mismatch_ids(
            [{"i": idx, "t": text} for idx, _ts, text in output_dialogue],
            owner_source_map),
        key=lambda value: (0, int(value))
        if str(value).isdigit() else (1, str(value)),
    )
    untranslated_fragment_ids = _delivery_untranslated_fragment_ids(
        output_dialogue, output_source_map, target_language, source_language)
    unresolved_markers = sum(
        text.startswith("[HATA") or "[ÇEVİRİ EKSİK]" in text
        for text in output_texts)
    residual_credit_cues = sum(_is_delivery_credit(text) for text in output_texts)
    residual_sdh_cues = sum(_is_delivery_sdh_only(text) for text in output_texts)
    residual_speaker_label_ids = [
        str(idx) for idx, _ts, text in output_dialogue
        if sdh_cleaner._src_has_plain_speaker_label(
            output_source_map.get(str(idx), ""))
        and sdh_cleaner._TR_PLAIN_SPEAKER_LABEL_RE.search(str(text or ""))
    ]
    residual_literal_newline_cues = sum(
        "\\n" in text and "\\n" not in output_source_map.get(str(idx), "")
        for idx, _ts, text in output_dialogue)
    residual_position_tags = sum(
        len(_DELIVERY_ASS_POSITION_RE.findall(text)) for text in output_texts)
    residual_format_tags = sum(
        _delivery_ass_command_count(text) for text in output_texts)
    residual_control_chars = sum(
        sum(ord(char) < 32 and char not in "\n\r\t" for char in text)
        for text in output_texts)
    serialized_json_residue_ids = [
        str(idx) for idx, _ts, text in output_dialogue
        if re.search(r"\}\s*,\s*\{", str(text or ""))
    ]
    hatted_letters = sum(
        sum(text.count(char) for char in "âîûÂÎÛ") for text in output_texts)
    delivery_signatures = sum(
        bool(_DELIVERY_SIGNATURE_RE.fullmatch(str(text or "").strip()))
        for _idx, _ts, text in output)
    expected_signatures = 0
    if (output_dialogue and normalize_language_name(
            target_language, allow_auto=False) == "Turkish"):
        try:
            first_dialogue_start, _ = _srt_timestamp_bounds(output_dialogue[0][1])
        except ValueError:
            first_dialogue_start = 0
        expected_signatures = (
            1 + bool(first_dialogue_start > 0)
            + bool(_delivery_middle_signature_slot(output_dialogue)))
    signature_mismatch = delivery_signatures != expected_signatures
    source_text_by_id = {
        str(idx): str(text or "") for idx, _ts, text in source_rows}
    output_text_by_id = {
        str(idx): str(text or "") for idx, _ts, text in output_dialogue}
    review_details = []

    def _add_review_detail(reason, source_id="", output_id=""):
        source_id = str(source_id or "")
        output_id = str(output_id or "")
        source_text = source_text_by_id.get(source_id, "")
        if not source_text and output_id:
            source_text = output_source_map.get(output_id, "")
        review_details.append({
            "reason": str(reason),
            "source_id": source_id,
            "output_id": output_id,
            "source": source_text,
            "target": output_text_by_id.get(output_id, ""),
        })

    for source_id in missing_dialogue:
        _add_review_detail("missing_dialogue", source_id)
    for output_id in extras:
        _add_review_detail("extra_dialogue", output_id=output_id)
    for source_id in timestamp_mismatches:
        _add_review_detail(
            "timestamp_mismatch", source_id,
            source_to_output_ids.get(str(source_id), str(source_id)))
    for output_id in delivery_owner_mismatch_ids:
        _add_review_detail("cue_owner_mismatch", output_id=output_id)
    for output_id in untranslated_fragment_ids:
        _add_review_detail("untranslated_fragment", output_id=output_id)
    for output_id, _ts, text in output_dialogue:
        if str(text or "").startswith("[HATA") or "[ÇEVİRİ EKSİK]" in str(text or ""):
            _add_review_detail("unresolved_marker", output_id=output_id)
    for output_id in invalid_timestamp_ids:
        _add_review_detail("invalid_timestamp", output_id=output_id)
    for output_id in reversed_timestamp_ids:
        _add_review_detail("reversed_timestamp", output_id=output_id)
    for output_id in signature_overlap_ids:
        _add_review_detail("signature_overlap", output_id=output_id)
    for output_id in serialized_json_residue_ids:
        _add_review_detail("serialized_json_residue", output_id=output_id)
    for output_id in residual_speaker_label_ids:
        _add_review_detail("residual_speaker_label", output_id=output_id)
    needs_review = any((
        missing_dialogue, extras, timestamp_mismatches, unresolved_markers,
        delivery_owner_mismatch_ids, untranslated_fragment_ids,
        residual_credit_cues, residual_sdh_cues, residual_position_tags,
        residual_speaker_label_ids,
        residual_format_tags, residual_literal_newline_cues, hatted_letters,
        residual_control_chars,
        serialized_json_residue_ids,
        signature_mismatch, duplicate_cue_ids, unnumbered_cue_lines,
        invalid_timestamp_ids,
        reversed_timestamp_ids, signature_overlap_ids,
    ))
    audit.update({
        "status": "review" if needs_review else "ok",
        "source_cues": len(source_rows),
        "output_cues": len(output),
        "dialogue_output_cues": len(output_dialogue),
        "missing_dialogue_ids": missing_dialogue,
        "expected_removed_ids": expected_removed,
        "extra_dialogue_ids": extras,
        "timestamp_mismatch_ids": timestamp_mismatches,
        "source_to_output_ids": source_to_output_ids,
        "delivery_owner_mismatch_ids": delivery_owner_mismatch_ids,
        "untranslated_fragment_ids": untranslated_fragment_ids,
        "unresolved_markers": unresolved_markers,
        "residual_credit_cues": residual_credit_cues,
        "residual_sdh_cues": residual_sdh_cues,
        "residual_speaker_label_ids": residual_speaker_label_ids,
        "residual_literal_newline_cues": residual_literal_newline_cues,
        "residual_position_tags": residual_position_tags,
        "residual_format_tags": residual_format_tags,
        "residual_control_chars": residual_control_chars,
        "serialized_json_residue_ids": serialized_json_residue_ids,
        "hatted_letters": hatted_letters,
        "delivery_signatures": delivery_signatures,
        "expected_delivery_signatures": expected_signatures,
        "signature_mismatch": signature_mismatch,
        "invalid_timestamp_ids": invalid_timestamp_ids,
        "reversed_timestamp_ids": reversed_timestamp_ids,
        "signature_overlap_ids": signature_overlap_ids,
        "duplicate_cue_ids": duplicate_cue_ids,
        "unnumbered_cue_lines": unnumbered_cue_lines,
        "review_details": review_details,
        "source_sha256": _file_content_sha256(source_path),
        "output_sha256": _file_content_sha256(output_path),
    })
    return audit


def _delivery_audit_has_hard_error(audit: dict) -> bool:
    """Return whether the final file is unsafe to call upload-ready.

    Cosmetic report warnings may remain review-only; a missing dialogue,
    unresolved marker, invalid interval, or an injected signature covering a
    dialogue must never receive a completion marker or be skipped next run.
    """
    if not isinstance(audit, dict):
        return True
    if audit.get("status") == "unavailable":
        return True
    return any((
        audit.get("missing_dialogue_ids"),
        audit.get("extra_dialogue_ids"),
        audit.get("timestamp_mismatch_ids"),
        audit.get("untranslated_fragment_ids"),
        audit.get("unresolved_markers"),
        audit.get("residual_credit_cues"),
        audit.get("residual_sdh_cues"),
        audit.get("residual_speaker_label_ids"),
        audit.get("residual_literal_newline_cues"),
        audit.get("residual_position_tags"),
        audit.get("residual_format_tags"),
        audit.get("residual_control_chars"),
        audit.get("serialized_json_residue_ids"),
        audit.get("hatted_letters"),
        audit.get("signature_mismatch"),
        audit.get("invalid_timestamp_ids"),
        audit.get("reversed_timestamp_ids"),
        audit.get("signature_overlap_ids"),
        audit.get("duplicate_cue_ids"),
        audit.get("unnumbered_cue_lines"),
    ))


def _file_process_report_text(row: dict, run_id: str = "") -> str:
    audit = row.get("delivery_audit") or {}
    lines = [
        "ALTYAZI İŞLEM VE TESLİM DÖKÜMÜ",
        f"Çalışma kimliği: {run_id or '-'}",
        f"Dosya: {row.get('name', '-')}",
        f"Kaynak: {row.get('source_path', '-')}",
        f"Çıktı: {row.get('output_path', '-')}",
        "=" * 72,
        "İŞLEM GEÇİŞLERİ",
    ]
    lines.extend(f"- {item}" for item in row.get("feature_audit") or ["Kayıt yok"])
    timing = row.get("timing") or {}
    lines.extend([
        "",
        "SÜRE ZAMAN ÇİZELGESİ",
        f"- Kuyruğa giriş: {timing.get('queued_at') or '-'}",
        f"- Başlangıç: {timing.get('started_at') or '-'}",
        f"- Bitiş: {timing.get('ended_at') or '-'}",
        f"- Toplam süre: {_format_elapsed(timing.get('duration_seconds'))}",
    ])
    for stage in timing.get("stage_timings") or []:
        stage_line = (
            f"- {stage.get('name', 'İşleniyor')}: "
            f"{stage.get('started_at', '-')} → {stage.get('ended_at', '-')} "
            f"({_format_elapsed(stage.get('duration_seconds'))})")
        usage_by_pass = stage.get("api_usage_by_pass") or {}
        if usage_by_pass:
            stage_line += " | API: " + "; ".join(
                f"{name}: {_format_api_usage(usage)}"
                for name, usage in usage_by_pass.items())
        operations = stage.get("api_operations") or {}
        if operations:
            stage_line += " | İstekler: " + "; ".join(
                f"{name}: {_format_api_operation(metrics)}"
                for name, metrics in operations.items())
        lines.append(stage_line)
    lines.extend(["", "YAPISAL TESLİM DENETİMİ"])
    for key, label in (
        ("status", "Durum"),
        ("source_cues", "Kaynak cue"),
        ("output_cues", "Çıktı cue"),
        ("dialogue_output_cues", "İmza dışı çıktı cue"),
        ("missing_dialogue_ids", "Eksik diyalog kimlikleri"),
        ("expected_removed_ids", "Beklenen temizlenmiş kimlikler"),
        ("extra_dialogue_ids", "Fazladan diyalog kimlikleri"),
        ("timestamp_mismatch_ids", "Zaman damgası uyuşmazlıkları"),
        ("delivery_owner_mismatch_ids", "Kaynak-cue sahiplik inceleme kimlikleri"),
        ("untranslated_fragment_ids", "Satır içinde çevrilmeden kalan kaynak kimlikleri"),
        ("unresolved_markers", "Eksik çeviri işaretleri"),
        ("residual_credit_cues", "Kalan eski kredi cue'ları"),
        ("residual_sdh_cues", "Kalan SDH cue'ları"),
        ("residual_literal_newline_cues", "Düz metin \\n kalıntısı olan cue'lar"),
        ("residual_position_tags", "Kalan konum kodları"),
        ("hatted_letters", "Şapkalı harfler"),
        ("delivery_signatures", "discord: ceviri2 imzaları"),
        ("expected_delivery_signatures", "Beklenen discord imzası"),
        ("signature_mismatch", "discord imza sayısı hatası"),
        ("invalid_timestamp_ids", "Geçersiz zaman damgası kimlikleri"),
        ("reversed_timestamp_ids", "Ters/geçersiz zaman aralığı kimlikleri"),
        ("signature_overlap_ids", "Diyalogla çakışan discord imzaları"),
        ("source_sha256", "Kaynak SHA-256"),
        ("output_sha256", "Çıktı SHA-256"),
    ):
        if key in audit:
            value = audit[key]
            if isinstance(value, list):
                value = ", ".join(value) if value else "yok"
            lines.append(f"- {label}: {value}")
    lines.extend(["", "CUE BAZLI PASS DEĞİŞİKLİKLERİ"])
    history = row.get("pass_history") or {}
    if not history:
        lines.append("- Değişiklik yok.")
    else:
        for cue_id, steps in history.items():
            lines.append(f"\n#{cue_id}")
            lines.append(
                "  Zincir: " + " -> ".join(
                    str(step.get("pass", "?")) for step in steps))
            for step in steps:
                lines.append(f"  [{step.get('pass', '?')}]")
                lines.append(f"  Önce: {step.get('before', '')}")
                lines.append(f"  Sonra: {step.get('after', '')}")
    guard_events = (row.get("pass_trace") or {}).get("__guard_events__") or []
    lines.extend(["", "PASS GUARD / OTOMATİK GERİ ALMA"])
    if not guard_events:
        lines.append("- Yapısal guard ihlali yok.")
    else:
        for event in guard_events:
            lines.append(
                f"- {event.get('pass')}: geri alındı | {event.get('reason')} | "
                f"önerilen değişiklik={event.get('proposed_changes', 0)} | "
                f"örnek cue={','.join(event.get('sample_ids') or []) or 'yok'}")
    lines.extend(["", "PASS VERİMİ"])
    efficiency = _pass_efficiency_rows(row)
    if not efficiency:
        lines.append("- Ölçülebilir pass kaydı yok.")
    else:
        for item in efficiency:
            if item["changed"]:
                lines.append(
                    f"- {item['pass']}: {item['changed']} cue | {item['tokens']:,} token | "
                    f"${item['cost_usd']:.6f} | {item['tokens_per_change']:.2f} "
                    "token/düzeltme")
            elif item.get("report_only") and item.get("suggested"):
                lines.append(
                    f"- {item['pass']}: {item['suggested']} öneri "
                    f"(uygulanmadı) | {item['tokens']:,} token | "
                    f"${item['cost_usd']:.6f} | "
                    f"{item['tokens_per_suggestion']:.2f} token/öneri")
            else:
                lines.append(
                    f"- {item['pass']}: düzeltme yok | {item['tokens']:,} token | "
                    f"${item['cost_usd']:.6f}")
    return "\n".join(lines).rstrip() + "\n"


def _multi_pass_history(history: dict, max_items: int = 5) -> tuple[int, str]:
    multi = [(sid, steps) for sid, steps in (history or {}).items() if len(steps) > 1]
    if not multi:
        return 0, ""
    samples = []
    for sid, steps in multi[:max_items]:
        chain = " -> ".join(str(step.get("pass", "?")) for step in steps)
        samples.append(f"#{sid}: {chain}")
    more = f" (+{len(multi) - max_items})" if len(multi) > max_items else ""
    return len(multi), "; ".join(samples) + more


def _is_refinement_change(before: str, after: str) -> bool:
    """Best-effort marker for small polish changes, not suspicious overrides."""
    if before == after:
        return False
    before_terminal = before.rstrip()[-1:] if before.rstrip() else ""
    after_terminal = after.rstrip()[-1:] if after.rstrip() else ""
    expressive_punct = {"?", "!"}
    terminal_punct = {".", "?", "!", "…"}
    if before_terminal and after_terminal and before_terminal != after_terminal:
        if before_terminal in terminal_punct and (
                before_terminal in expressive_punct or after_terminal in expressive_punct):
            return False
    compact_before = re.sub(r"[\s\W_]+", "", before, flags=re.UNICODE).casefold()
    compact_after = re.sub(r"[\s\W_]+", "", after, flags=re.UNICODE).casefold()
    if compact_before and compact_before == compact_after:
        return True
    if before and after.startswith(before) and len(after) <= max(len(before) + 3, int(len(before) * 1.15)):
        suffix = after[len(before):].strip()
        return bool(suffix) and all(ch in ".,;:!?…" for ch in suffix)
    return False


def _pass_interaction_events(history: dict) -> list:
    """Return adjacent pass interactions as (sid, prev_step, cur_step, kind)."""
    events = []
    for sid, steps in (history or {}).items():
        if len(steps) < 2:
            continue
        for i in range(1, len(steps)):
            prev = steps[i - 1]
            cur = steps[i]
            prev_before = str(prev.get("before", ""))
            prev_after = str(prev.get("after", ""))
            cur_after = str(cur.get("after", ""))
            if not prev_after or not cur_after or prev_after == cur_after:
                continue
            if cur_after == prev_before:
                kind = "revert"
            elif _is_refinement_change(prev_after, cur_after):
                kind = "refinement"
            else:
                kind = "override"
            events.append((sid, prev, cur, kind))
    return events


def _pass_interaction_counts(history: dict) -> dict:
    counts = {}
    for _sid, _prev, _cur, kind in _pass_interaction_events(history):
        counts[kind] = counts.get(kind, 0) + 1
    return counts


def _format_interaction_counts(counts: dict) -> str:
    order = ("override", "revert", "refinement")
    return ", ".join(f"{name}: {counts[name]}" for name in order if counts.get(name))


def _detect_pass_overrides(history: dict, max_items: int = 5) -> tuple[int, str]:
    """Summarize adjacent pass changes: refinement, override, or revert."""
    events = _pass_interaction_events(history)
    if not events:
        return 0, ""
    samples = []
    for sid, prev, cur, kind in events[:max_items]:
        chain = f"{prev.get('pass', '?')} -> {cur.get('pass', '?')}"
        samples.append(f"#{sid}: {chain} ({kind})")
    more = f" (+{len(events) - max_items})" if len(events) > max_items else ""
    return len(events), "; ".join(samples) + more


def build_quality_report_text(rows: list, model_name: str, tgt: str, mode: str,
                              total_tokens: int, actual_cost: float = None,
                              unknown_cost_tokens: int = 0,
                              run_id: str = "") -> str:
    """ceviri_raporu.txt içeriğini üretir. Satırlardaki alanlar opsiyoneldir —
    yalnızca mevcut olanlar yazılır (düz mod 'rev', hybrid 'pass_fix'/'qc' taşır)."""
    import datetime as _dt
    fields = [
        ("hata",     "Eksik çeviri satırı"),
        ("cps",      f"CPS aşımı (>{CPS_WARN_LIMIT} k/sn)"),
        ("cps_avg",  "Ortalama CPS"),
        ("cps_max",  "Maksimum CPS"),
        ("tm_hits",  "TM önbellek kullanımı"),
        ("cons",     "Tutarlılık düzeltmesi"),
        ("rev",      "İnceleme düzeltmesi"),
        ("pass_fix", "Kalite geçişi düzeltmesi"),
        ("qc_auto",  "QC otomatik düzeltmesi"),
        ("qc",       "QC düzeltmesi"),
        ("warn",     "Kalite uyarısı (tarama)"),
    ]
    price = MODEL_PRICE.get(model_name)
    lines = [
        "ÇEVİRİ KALİTE RAPORU",
        f"Çalışma kimliği: {run_id or '-'}",
        f"Tarih  : {_dt.datetime.now().strftime('%Y-%m-%d %H:%M')}",
        f"Model  : {model_name}  |  Hedef dil: {tgt}  |  Mod: {mode}",
        "=" * 72,
    ]
    hata_files = [r.get("name", "?") for r in rows if r.get("hata_indices")]
    if hata_files:
        lines.insert(0, "")
        lines.insert(0, "!!! UYARI: [ÇEVİRİ EKSİK] kalan satırlar var - aşağıdaki dosyalarda indeks listesini kontrol edin!")
        lines.insert(0, "=" * 72)
    width = max(len(lbl) for _, lbl in fields)
    for r in rows:
        lines.append(f"\n• {r['name']}  ({r.get('total', 0)} satır)")
        for key, lbl in fields:
            if key in r:
                shown_label = lbl
                if key == "cons" and _report_only_consistency_suggestions(r):
                    shown_label = "Tutarlılık önerisi (uygulanmadı)"
                lines.append(f"   {shown_label.ljust(width)} : {r[key]}")
        hata_idxs = r.get("hata_indices")
        if hata_idxs:
            idx_str = ", ".join(str(i) for i in sorted(hata_idxs))
            lines.append(f"   >>> [ÇEVİRİ EKSİK] kalan satır indeksleri: {idx_str}")
        passes = r.get("pass_coverage", "")
        if passes:
            lines.append(f"   {'Uygulanan geçişler'.ljust(width)} : {passes}")
        feature_audit = r.get("feature_audit") or []
        if feature_audit:
            lines.append("   İşlem dökümü:")
            lines.extend(f"      - {item}" for item in feature_audit)
        delivery_audit = r.get("delivery_audit") or {}
        if r.get("run_status") == "review":
            lines.append(
                "   >>> TESLİM DURUMU: İNCELEME GEREKLİ — çıktı yerinde "
                "bırakıldı; yüklemeye hazır/tamamlanmış sayılmadı.")
        if delivery_audit.get("status"):
            lines.append(
                f"   Yapısal teslim denetimi : {delivery_audit.get('status')} | "
                f"eksik diyalog={len(delivery_audit.get('missing_dialogue_ids') or [])}, "
                f"zaman uyuşmazlığı={len(delivery_audit.get('timestamp_mismatch_ids') or [])}, "
                f"satır içi kaynak kalıntısı={len(delivery_audit.get('untranslated_fragment_ids') or [])}, "
                f"kalan kredi={delivery_audit.get('residual_credit_cues', 0)}, "
                f"kalan SDH={delivery_audit.get('residual_sdh_cues', 0)}, "
                f"eksik işareti={delivery_audit.get('unresolved_markers', 0)}")
            owner_ids = delivery_audit.get("delivery_owner_mismatch_ids") or []
            if owner_ids:
                lines.append(
                    "   >>> Kaynak-cue sahiplik incelemesi (rapor): "
                    f"{len(owner_ids)} cue ({', '.join(map(str, owner_ids))})")
            fragment_ids = delivery_audit.get("untranslated_fragment_ids") or []
            if fragment_ids:
                lines.append(
                    "   >>> Satır içinde çevrilmeden kalan kaynak: "
                    f"{len(fragment_ids)} cue ({', '.join(map(str, fragment_ids))})")
            review_details = delivery_audit.get("review_details") or []
            if review_details:
                lines.append("   >>> Elle inceleme ayrıntıları:")
                for detail in review_details:
                    cue_label = "/".join(filter(None, (
                        str(detail.get("source_id") or ""),
                        str(detail.get("output_id") or "")))) or "-"
                    lines.append(
                        f"      - [{detail.get('reason', 'review')}] #{cue_label} | "
                        f"kaynak={detail.get('source', '')!r} | "
                        f"çıktı={detail.get('target', '')!r}")
        trace_txt = _format_pass_trace(r.get("pass_trace") or {})
        if trace_txt:
            lines.append(f"   {'Kalite geçişi kırılımı'.ljust(width)} : {trace_txt}")
        repair_advisories = (
            (r.get("pass_trace") or {}).get("__repair_advisories__") or [])
        if repair_advisories:
            lines.append(
                f"   Onarım sonrası elle incelenecek : {len(repair_advisories)} cue")
            for item in repair_advisories:
                status = "ONARILAMADI" if item.get("unresolved") else "UYARI"
                lines.append(
                    f"      - [{status}] #{item.get('id')}: {item.get('reason')} | "
                    f"kaynak={item.get('source')!r} | aday={item.get('candidate')!r}")
        multi_count, multi_txt = _multi_pass_history(r.get("pass_history") or {})
        if multi_count:
            lines.append(f"   {'Çoklu-pass satırı'.ljust(width)} : {multi_count} ({multi_txt})")
        override_count, override_txt = _detect_pass_overrides(r.get("pass_history") or {})
        if override_count:
            lines.append(f"   {'Pass etkileşimi'.ljust(width)} : {override_count} ({override_txt})")
    sums = {}
    for key, _lbl in fields:
        if key in {"cps_avg", "cps_max"}:
            continue
        vals = [r[key] for r in rows
                if key in r and not (
                    key == "cons" and
                    _report_only_consistency_suggestions(r))]
        if vals:
            sums[key] = sum(vals)
    cps_rows = [
        r for r in rows
        if "cps_avg" in r and int(r.get("total", 0) or 0) > 0
    ]
    if cps_rows:
        weights = [max(int(r.get("total", 0) or 0), 1) for r in cps_rows]
        sums["cps_avg"] = round(
            sum(float(r["cps_avg"]) * weight
                for r, weight in zip(cps_rows, weights)) / sum(weights), 1)
        sums["cps_max"] = round(
            max(float(r.get("cps_max", 0.0) or 0.0) for r in cps_rows), 1)
    total_lines = sum(r.get("total", 0) for r in rows)
    parts = [
        f"{lbl}: {sums[key]:.1f}" if key in {"cps_avg", "cps_max"}
        else f"{lbl}: {sums[key]}"
        for key, lbl in fields if key in sums
    ]
    report_only_consistency = sum(
        _report_only_consistency_suggestions(r) for r in rows)
    if report_only_consistency:
        parts.append(
            "Tutarlılık önerisi (uygulanmadı): "
            f"{report_only_consistency}")
    trace_sums = {}
    for r in rows:
        for name, count in (r.get("pass_trace") or {}).items():
            if str(name).startswith("__"):
                continue
            trace_sums[name] = trace_sums.get(name, 0) + count
    trace_total = _format_pass_trace(trace_sums)
    lines += [
        "\n" + "=" * 72,
        f"TOPLAM: {len(rows)} dosya, {total_lines} satır",
        "  |  ".join(parts),
    ]
    if trace_total:
        lines.append(f"Pass breakdown total: {trace_total}")
    total_multi = 0
    multi_samples = []
    total_overrides = 0
    override_samples = []
    interaction_counts = {}
    for r in rows:
        count, sample = _multi_pass_history(r.get("pass_history") or {}, max_items=2)
        total_multi += count
        if sample:
            multi_samples.append(f"{r.get('name', '?')}: {sample}")
        for name, count_value in _pass_interaction_counts(r.get("pass_history") or {}).items():
            interaction_counts[name] = interaction_counts.get(name, 0) + count_value
        override_count, override_sample = _detect_pass_overrides(
            r.get("pass_history") or {}, max_items=2)
        total_overrides += override_count
        if override_sample:
            override_samples.append(f"{r.get('name', '?')}: {override_sample}")
    if total_multi:
        joined = " | ".join(multi_samples[:5])
        if len(multi_samples) > 5:
            joined += f" | +{len(multi_samples) - 5} dosya"
        lines.append(f"Çoklu-pass değişen satırlar: {total_multi} ({joined})")
    if total_overrides:
        joined = " | ".join(override_samples[:5])
        if len(override_samples) > 5:
            joined += f" | +{len(override_samples) - 5} dosya"
        counts_txt = _format_interaction_counts(interaction_counts)
        suffix = f"; {counts_txt}" if counts_txt else ""
        lines.append(f"Pass etkileşimleri: {total_overrides}{suffix} ({joined})")
    if actual_cost is None:
        if price is None:
            actual_cost = 0.0
            unknown_cost_tokens = max(int(unknown_cost_tokens or 0), int(total_tokens or 0))
        else:
            actual_cost = total_tokens / 1e6 * price
    unknown_note = (f" + {unknown_cost_tokens:,} token maliyeti sağlayıcı panelinden doğrulanmalı"
                    if unknown_cost_tokens else "")
    lines.append(
        f"Oturum token toplamı: {total_tokens:,}  (~${actual_cost:.4f}{unknown_note})")
    return "\n".join(lines)


def _report_only_consistency_suggestions(row: dict) -> int:
    status = (row.get("pass_status") or {}).get("Consistency") or {}
    if not isinstance(status, dict) or not status.get("report_only"):
        return 0
    return int(status.get("suggested", row.get("cons", 0)) or 0)


def _quality_report_applied_fix_count(rows: list) -> int:
    total = 0
    for row in rows or []:
        total += sum(int(row.get(key, 0) or 0)
                     for key in ("rev", "pass_fix"))
        if not _report_only_consistency_suggestions(row):
            total += int(row.get("cons", 0) or 0)
    return total


_LOG_PID_RE = re.compile(r"\.pid(\d+)\.log$")


def rotate_logs(log_dir: Path, keep: int = 100) -> int:
    """En yeni `keep` log dosyasını tutar, eskileri siler. Silinen sayısını döner.

    CANLI bir sürecin log dosyası SAYIYA BAKILMAKSIZIN asla silinmez (bkz. dosya adına
    gömülü pid + _pid_alive). NEDEN (2026-07-16 gerçek olay): kullanıcı bir batch'i
    saatlerce beklerken (log dosyası sessiz — yeni satır yazılmıyor, mtime bayatlıyor)
    art arda çalıştırılan test App() örnekleri onlarca YENİ (küçük, taze mtime'lı) log
    oluşturdu; sayı-bazlı 'en yeni N' kuralı kullanıcının SESSİZ ama CANLI oturum logunu
    rotasyondan düşürüp SİLDİ — geri getirilemedi. pid kontrolü bunu artık imkânsız
    kılar: log ne kadar sessiz kalırsa kalsın, sahibi yaşadığı sürece silinmez."""
    try:
        logs = list(log_dir.glob("*.log"))
    except Exception:
        return 0

    protected, candidates = [], []
    for p in logs:
        m = _LOG_PID_RE.search(p.name)
        if m and _pid_alive(int(m.group(1))):
            protected.append(p)
        else:
            candidates.append(p)

    candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    removed = 0
    for p in candidates[keep:]:
        try:
            p.unlink()
            removed += 1
        except Exception:
            pass
    return removed





# ── Canlı batch sahipliği (yarım-batch penceresi için) ────────────────────────
# SORUN (2026-07-16 gerçek olay): `batch_id.txt` gönderim anında yazılır ve iş bitince
# temizlenir — yani UÇUŞTAKİ bir batch ile ÇÖKMÜŞ/sahipsiz kalmış bir batch dosyada
# BİREBİR aynı görünür. Bu yüzden bir batch beklenirken uygulamanın İKİNCİ bir örneği
# açılırsa (ya da kapatılıp yeniden açılırsa), açılış kontrolü canlı batch'leri "yarım
# kalmış" diye listeler. Oradaki "Seçilenleri Sil" düğmesi, parası ödenmiş ve hâlâ
# işlenen bir batch'in kurtarma verisini (fmap + id) siler.
# ÇÖZÜM: batch'leri işleyen süreç sahipliğini `batch_owner_<pid>.json`'a yazar; açılış
# kontrolü, sahibi HÂLÂ YAŞAYAN süreç olan id'leri pencerede göstermez. Süreç gerçekten
# çöktüyse pid ölüdür → kilit yok sayılır → pencere amaçlandığı gibi çıkar (kurtarma
# yine çalışır).
# NEDEN SÜREÇ-BAŞINA DOSYA (tek ortak dosya DEĞİL): tek dosya tek sahipli olurdu —
# ikinci bir süreç (ya da App kuran bir test) kendi kilidini yazarken canlı sahibin
# kaydını EZER, aktif batch'i kalmayınca da dosyayı SİLERDİ; yani korumanın kendisi
# çözmeye çalıştığı kirlenmeyi yeniden üretirdi. Her süreç yalnızca KENDİ dosyasını
# yazar/siler; okuyucu hepsini tarayıp ölü pid'lerinkini yok sayar.
_BATCH_OWNER_PREFIX = "batch_owner_"
_BATCH_OWNER_GLOB = "batch_owner_*.json"


def _batch_id_path() -> Path:
    """batch_id.txt'nin yolu. Tek nokta olması testlerin GERÇEK dosyaya dokunmadan
    (patch'leyerek) çalışabilmesi içindir — canlı bir batch sürerken testin gerçek
    kurtarma dosyasını geçici de olsa ezmesi kabul edilemez."""
    return state_path(__file__, "batch_id.txt")


def _pid_alive(pid: int) -> bool:
    """PID canlı mı?

    DİKKAT: Windows'ta `os.kill(pid, 0)` KULLANILMAZ — POSIX'te sinyal 0 zararsız bir
    varlık sorgusudur, ama Windows'ta os.kill TerminateProcess çağırır ve süreci
    GERÇEKTEN ÖLDÜRÜR. Bu yüzden Windows'ta ctypes/OpenProcess ile salt-okuma sorgu.

    BELİRSİZLİK YÖNÜ KASITLI: sorgulanamayan durumlarda True (canlı) döner. Yanlışlıkla
    "canlı" demek pencereyi bastırır (kullanıcıda '↺ Batch'i Devam Ettir' düğmesi zaten
    var — zararsız); yanlışlıkla "ölü" demek ise canlı bir batch için tehlikeli Sil/Devam
    penceresini açar. Şüphede güvenli taraf: bastırmak."""
    try:
        pid = int(pid)
    except Exception:
        return False
    if pid <= 0:
        return False
    import sys as _sys
    if _sys.platform == "win32":
        try:
            import ctypes
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            STILL_ACTIVE = 259
            k32 = ctypes.windll.kernel32
            h = k32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
            if not h:
                err = k32.GetLastError()
                if err == 87:  # ERROR_INVALID_PARAMETER: PID yok
                    return False
                return True    # ACCESS_DENIED/belirsiz: güvenli yönde canlı say
            try:
                code = ctypes.c_ulong()
                if not k32.GetExitCodeProcess(h, ctypes.byref(code)):
                    return True   # sorgulanamadı → canlı say (güvenli yön)
                return code.value == STILL_ACTIVE
            finally:
                k32.CloseHandle(h)
        except Exception:
            return True   # belirsiz → canlı say (güvenli yön)
    import os as _os
    try:
        _os.kill(pid, 0)   # POSIX: sinyal 0 = varlık sorgusu, öldürmez
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True   # süreç var, bize ait değil
    except Exception:
        return True


def _pending_recovery_batch_ids() -> list[str]:
    try:
        values = _batch_id_path().read_text(encoding="utf-8").splitlines()
    except Exception:
        return []
    return [value.strip() for value in values if is_safe_batch_id(value.strip())]


def _translation_run_owner_path() -> Path:
    return state_path(__file__, "translation_run_owner.json")


def _claim_translation_run_owner() -> bool:
    path = _translation_run_owner_path()
    with _interprocess_lock(path):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            data = {}
        owner_pid = int(data.get("pid") or 0)
        if owner_pid and owner_pid != os.getpid() and _pid_alive(owner_pid):
            stored_marker = str(data.get("process_start") or "")
            current_marker = _process_start_marker(owner_pid)
            if not stored_marker or not current_marker or stored_marker == current_marker:
                return False
        atomic_write_json(path, {
            "pid": os.getpid(),
            "started_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
            "process_start": _process_start_marker(os.getpid()),
        })
    return True


def _release_translation_run_owner() -> None:
    path = _translation_run_owner_path()
    with _interprocess_lock(path):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            data = {}
        if int(data.get("pid") or 0) != os.getpid():
            return
        try:
            path.unlink(missing_ok=True)
        except Exception:
            pass


def _translation_run_owned_by_other_process() -> bool:
    """Başka canlı bir çeviri süreci varsa batch silme ekranını kapalı tut."""
    path = _translation_run_owner_path()
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        owner_pid = int(data.get("pid") or 0)
    except Exception:
        return False
    if not owner_pid or owner_pid == os.getpid() or not _pid_alive(owner_pid):
        return False
    stored_marker = str(data.get("process_start") or "")
    current_marker = _process_start_marker(owner_pid)
    return not stored_marker or not current_marker or stored_marker == current_marker


def _process_start_marker(pid: int) -> str:
    """PID yeniden kullanÄ±mÄ±nÄ± ayÄ±rt etmek iÃ§in sÃ¼reÃ§ baÅŸlangÄ±Ã§ imzasÄ±."""
    try:
        pid = int(pid)
    except Exception:
        return ""
    if pid <= 0:
        return ""
    import sys as _sys
    if _sys.platform == "win32":
        try:
            import ctypes
            query_limited = 0x1000
            k32 = ctypes.windll.kernel32
            handle = k32.OpenProcess(query_limited, False, pid)
            if not handle:
                return ""
            try:
                creation = ctypes.c_ulonglong()
                exit_time = ctypes.c_ulonglong()
                kernel = ctypes.c_ulonglong()
                user = ctypes.c_ulonglong()
                if not k32.GetProcessTimes(
                        handle, ctypes.byref(creation), ctypes.byref(exit_time),
                        ctypes.byref(kernel), ctypes.byref(user)):
                    return ""
                return f"win:{creation.value}"
            finally:
                k32.CloseHandle(handle)
        except Exception:
            return ""
    try:
        stat = Path(f"/proc/{pid}/stat").read_text(encoding="utf-8")
        tail = stat[stat.rfind(")") + 2:].split()
        return f"proc:{tail[19]}" if len(tail) > 19 else ""
    except Exception:
        return ""


def _live_owned_batch_ids() -> set:
    """BAŞKA canlı süreçlerin şu an üzerinde çalıştığı batch id'leri.

    Tüm `batch_owner_<pid>.json` dosyaları taranır; ölü pid'lerinki yok sayılır (ve
    fırsat buldukça temizlenir). Okuma başarısızsa boş küme döner = eski davranış."""
    import os as _os
    owned: set = set()
    try:
        base = state_dir(__file__)
        my_pid = _os.getpid()
        for p in base.glob(_BATCH_OWNER_GLOB):
            try:
                d = json.loads(p.read_text(encoding="utf-8"))
                pid = int(d.get("pid", 0) or 0)
                ids = {str(b).strip() for b in (d.get("batch_ids") or []) if str(b).strip()}
                if pid <= 0 or pid == my_pid:
                    continue
                saved_marker = str(d.get("process_start") or "")
                current_marker = _process_start_marker(pid) if saved_marker else ""
                if saved_marker and current_marker and saved_marker != current_marker:
                    p.unlink(missing_ok=True)
                    continue
                if _pid_alive(pid):
                    owned |= ids
                else:
                    p.unlink(missing_ok=True)   # ölü sürecin kalıntısı — temizle
            except Exception:
                continue   # bozuk/okunamayan kilit dosyası: yok say, diğerlerine bak
    except Exception:
        return set()
    return owned


# ── Yarım-kalan-batch penceresi: OpenAI durumu ────────────────────────────────
# NEDEN: kilit (batch_owner) yanlış pencereyi bastırıyor ama pencere HAKLI olarak
# çıktığında kullanıcı yine kördü — hangi batch'in gerçekten bitmiş/hâlâ işlendiğini
# bilmeden "Seçilenleri Sil" tıklıyordu. Bu, işlenmekte olan (parası ödenmiş) bir
# batch'in kurtarma verisini silme riskini taşır. Çözüm: pencere açılırken OpenAI'den
# gerçek durumu çek, göster; hâlâ işlenen bir batch seçiliyse Sil'de ekstra onay iste.
_BATCH_LIVE_STATUSES = frozenset({"validating", "in_progress", "finalizing", "cancelling"})
_BATCH_DONE_STATUSES = frozenset({"completed"})
_BATCH_DEAD_STATUSES = frozenset({"failed", "expired", "cancelled"})


def _fetch_batch_statuses(api_key: str, batch_ids: list, log_fn=None, base_url: str = "") -> dict:
    """Verilen batch id'lerin OpenAI'deki GÜNCEL durumunu çeker.

    Döner: {batch_id: status_str}. status_str bilinen OpenAI değerlerinden biri
    ('validating'/'in_progress'/'finalizing'/'completed'/'failed'/'expired'/
    'cancelling'/'cancelled') ya da sorgulanamazsa 'unknown'. Ağ/anahtar hatası TÜM
    fonksiyonu düşürmez — her id bağımsız denenir, tek tek 'unknown'a düşer (fail-safe:
    bilinmeyen durum çağıran tarafından CANLI OLABİLİR sayılmalı, silme onayını atlamaz)."""
    result = {bid: "unknown" for bid in batch_ids}
    if not api_key or not batch_ids:
        return result
    try:
        from openai import OpenAI as _OAI
        kwargs = {"api_key": api_key}
        if base_url:
            kwargs["base_url"] = base_url
        client = _OAI(**kwargs)
    except Exception as e:
        if log_fn:
            log_fn("Batch durumu sorgulanamadı.", "warn")
        return result
    for bid in batch_ids:
        try:
            b = _batch_api_call_with_retry(
                client, lambda: client.batches.retrieve(bid), "batch_retrieve")
            result[bid] = getattr(b, "status", "unknown") or "unknown"
        except Exception:
            result[bid] = "unknown"
    return result


def _batch_status_label(status: str) -> tuple:
    """Durum kodunu (görünen_metin, renk_sınıfı) çiftine çevirir.
    renk_sınıfı: 'live' | 'done' | 'dead' | 'unknown' — çağıran gerçek renge eşler."""
    if status in _BATCH_LIVE_STATUSES:
        return f"● {status} — İŞLENİYOR", "live"
    if status in _BATCH_DONE_STATUSES:
        return "✓ completed — indirilebilir", "done"
    if status in _BATCH_DEAD_STATUSES:
        return f"✗ {status}", "dead"
    return "? durum bilinmiyor", "unknown"


# ── Sync checkpoint store module-level helpers ────────────────────────────────
SYNC_CKPT_STORE_VER = 2
SYNC_STAGE_STORE_VER = 2


def load_sync_ckpt_store(path: Path) -> dict:
    """Sync checkpoint deposunu okur (v2 JSON veya legacy JSONL dönüşümü).
    Döndürür: {'version': 2, 'entries': {key: {'cid': ..., 'h': ..., 't': ..., 'updated_at': ...}}}
    Boş/bozuk dosyada güvenli boş depo yapısı döndürür.
    """
    path = Path(path)
    store = {"version": SYNC_CKPT_STORE_VER, "entries": {}}
    target_path = path
    if not target_path.exists() and target_path.suffix == ".json":
        legacy_jsonl = target_path.with_suffix(".jsonl")
        if legacy_jsonl.exists():
            target_path = legacy_jsonl

    if not target_path.exists():
        return store

    try:
        content = target_path.read_text(encoding="utf-8")
        if not content.strip():
            return store
        try:
            d = json.loads(content)
            if isinstance(d, dict) and d.get("version") == SYNC_CKPT_STORE_VER and isinstance(d.get("entries"), dict):
                store["entries"] = d["entries"]
                return store
        except Exception:
            pass

        # Legacy JSONL format migration
        entries = {}
        for line in content.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                o = json.loads(line)
                cid = o.get("cid")
                h = o.get("h", "")
                t = o.get("t", "")
                if cid:
                    key = f"{cid}:{h}"
                    entries[key] = {"cid": cid, "h": h, "t": t, "updated_at": 0.0}
            except Exception:
                continue
        store["entries"] = entries
    except Exception:
        pass
    return store


def _sync_ckpt_store_mutation_safe(path: Path) -> bool:
    path = Path(path)
    target = path
    if not target.exists() and target.suffix == ".json":
        legacy = target.with_suffix(".jsonl")
        if legacy.exists():
            target = legacy
    if not target.exists():
        return True
    try:
        content = target.read_text(encoding="utf-8")
    except Exception:
        return False
    if not content.strip():
        return True
    try:
        data = json.loads(content)
    except Exception:
        data = None
    if (isinstance(data, dict)
            and data.get("version") == SYNC_CKPT_STORE_VER
            and isinstance(data.get("entries"), dict)):
        return True
    valid_legacy = 0
    for line in content.splitlines():
        if not line.strip():
            continue
        try:
            row = json.loads(line)
        except Exception:
            continue
        if isinstance(row, dict) and row.get("cid"):
            valid_legacy += 1
    return valid_legacy > 0


def save_sync_ckpt_entry_to_store(path: Path, cid: str, text: str, src_hash: str, log_fn=None) -> bool:
    """Süreçler arası kilit altında sync checkpoint deposuna tek kaydı atomik günceller/ekler."""
    path = Path(path)
    key = f"{cid}:{src_hash}"
    try:
        with _interprocess_lock(path):
            if not _sync_ckpt_store_mutation_safe(path):
                raise ValueError(
                    "mevcut checkpoint deposu bozuk; veri kaybını önlemek için "
                    "üzerine yazılmadı")
            store = load_sync_ckpt_store(path)
            entries = store.get("entries", {})
            entries[key] = {
                "cid": cid,
                "h": src_hash,
                "t": text,
                "updated_at": time.time(),
            }
            store["entries"] = entries
            atomic_write_json(path, store)
            return True
    except Exception as e:
        if log_fn:
            log_fn(f"Checkpoint kaydı yazılamadı: {e}", "warn")
        return False


def clear_sync_ckpt_entries_from_store(path: Path, keys_to_remove: set = None, log_fn=None) -> bool:
    """Temizlenecek (cid:hash) anahtarlarını depodan çıkarır.
    - keys_to_remove is None: Tüm depoyu (ve dosyaları) siler.
    - keys_to_remove == set() (boş): İşlem yapmaz (no-op).
    - Dolu set: Yalnızca verilen anahtarları siler.
    """
    path = Path(path)
    if keys_to_remove is not None and not keys_to_remove:
        return True

    target_path = path
    legacy_jsonl = path.with_suffix(".jsonl") if path.suffix == ".json" else None

    if not target_path.exists() and legacy_jsonl and legacy_jsonl.exists():
        target_path = legacy_jsonl

    if not target_path.exists():
        return True

    try:
        with _interprocess_lock(path):
            if keys_to_remove is None:
                path.unlink(missing_ok=True)
                if legacy_jsonl:
                    legacy_jsonl.unlink(missing_ok=True)
                return True
            if not _sync_ckpt_store_mutation_safe(path):
                raise ValueError(
                    "mevcut checkpoint deposu bozuk; kısmi temizlik yapılmadı")
            store = load_sync_ckpt_store(path)
            entries = store.get("entries", {})
            for k in set(keys_to_remove):
                entries.pop(k, None)
            if not entries:
                path.unlink(missing_ok=True)
                if legacy_jsonl:
                    legacy_jsonl.unlink(missing_ok=True)
            else:
                store["entries"] = entries
                atomic_write_json(path, store)
            return True
    except Exception as e:
        if log_fn:
            log_fn(f"Checkpoint temizlenemedi: {e}", "warn")
        return False


def load_sync_stage_store(path: Path) -> dict:
    store = {"version": SYNC_STAGE_STORE_VER, "entries": {}}
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        if (isinstance(data, dict)
                and data.get("version") == SYNC_STAGE_STORE_VER
                and isinstance(data.get("entries"), dict)):
            return data
    except Exception:
        pass
    return store


def _sync_stage_store_mutation_safe(path: Path) -> bool:
    path = Path(path)
    if not path.exists():
        return True
    try:
        content = path.read_text(encoding="utf-8")
        if not content.strip():
            return True
        data = json.loads(content)
    except Exception:
        return False
    return (isinstance(data, dict)
            and data.get("version") == SYNC_STAGE_STORE_VER
            and isinstance(data.get("entries"), dict))


def _sync_stage_request_hash(requests) -> str:
    normalized = []
    for request in (requests or ()):
        if not isinstance(request, dict):
            continue
        body = copy.deepcopy(request.get("body", {}))
        if isinstance(body, dict):
            for message in body.get("messages") or []:
                if not isinstance(message, dict) or message.get("role") != "user":
                    continue
                try:
                    payload = json.loads(message.get("content", ""))
                except (TypeError, ValueError):
                    continue
                if isinstance(payload, dict):
                    payload.pop("prev_tr", None)
                    message["content"] = json.dumps(
                        payload, ensure_ascii=False, sort_keys=True,
                        separators=(",", ":"))
        normalized.append({
            "custom_id": str(request.get("custom_id", "")),
            "body": body,
        })
    encoded = json.dumps(
        normalized, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), default=str)
    return hashlib.sha256(encoded.encode("utf-8", "replace")).hexdigest()


def matching_sync_stage_run_id(path: Path, source_path: str,
                               source_hash: str, fingerprint: str,
                               request_hash: str = "") -> str:
    entry = load_sync_stage_store(path).get("entries", {}).get(
        _sync_stage_key(source_path))
    if not isinstance(entry, dict):
        return ""
    if (entry.get("source_hash") != str(source_hash)
            or entry.get("fingerprint") != str(fingerprint)
            or (request_hash and entry.get("request_hash") != str(request_hash))
            or not isinstance(entry.get("raw_map"), dict)
            or not entry.get("raw_map")):
        return ""
    return str(entry.get("run_id") or "")


def _sync_stage_key(source_path: str) -> str:
    normalized = os.path.normcase(os.path.abspath(str(source_path)))
    return hashlib.sha256(normalized.encode("utf-8", "replace")).hexdigest()


def save_sync_stage_entry_to_store(path: Path, source_path: str,
                                   source_hash: str, fingerprint: str,
                                   run_id: str, raw_map: dict,
                                   request_hash: str = "",
                                   log_fn=None) -> bool:
    try:
        with _interprocess_lock(path):
            if not _sync_stage_store_mutation_safe(path):
                raise ValueError(
                    "mevcut aşama checkpoint'i bozuk; veri kaybını önlemek için "
                    "üzerine yazılmadı")
            store = load_sync_stage_store(path)
            store["entries"][_sync_stage_key(source_path)] = {
                "source_path": os.path.abspath(str(source_path)),
                "source_hash": str(source_hash),
                "fingerprint": str(fingerprint),
                "request_hash": str(request_hash),
                "run_id": str(run_id),
                "raw_map": {str(k): str(v) for k, v in raw_map.items()},
                "updated_at": time.time(),
            }
            atomic_write_json(path, store)
        return True
    except Exception as exc:
        if log_fn:
            log_fn(f"Aşama checkpoint'i yazılamadı: {exc}", "warn")
        return False


def clear_sync_stage_entry_from_store(path: Path, source_path: str,
                                      log_fn=None) -> bool:
    try:
        with _interprocess_lock(path):
            if not _sync_stage_store_mutation_safe(path):
                raise ValueError(
                    "mevcut aşama checkpoint'i bozuk; temizlenmedi")
            store = load_sync_stage_store(path)
            store["entries"].pop(_sync_stage_key(source_path), None)
            if store["entries"]:
                atomic_write_json(path, store)
            else:
                Path(path).unlink(missing_ok=True)
        return True
    except Exception as exc:
        if log_fn:
            log_fn(f"Aşama checkpoint'i temizlenemedi: {exc}", "warn")
        return False


def should_clear_sync_ckpt(is_stop_flag: bool, is_full_success: bool) -> bool:
    """Yalnızca durdurulmamış VE tam başarılı koşuda checkpoint temizleme kararı verir."""
    return not is_stop_flag and is_full_success


def _sync_stage_is_complete(raw_map: dict, requests: list) -> bool:
    return bool(requests) and all(
        raw_map.get(req.get("custom_id", ""))
        and not _chunk_response_retry_reason(
            raw_map.get(req.get("custom_id", "")), req)
        for req in requests
    )


# ── Ana uygulama ──────────────────────────────────────────────────────────────
def _json_glossary_store_is_valid(path) -> bool:
    path = Path(path)
    if path.suffix.casefold() != ".json" or not path.exists():
        return True
    try:
        data = json.loads(read_subtitle_text(path))
    except Exception:
        return False
    return isinstance(data, dict)


