    def _after_dpi_scaling(self):
        if getattr(self, "_is_shutting_down", False):
            return
        pending = getattr(self, "_dpi_refresh_after_id", None)
        if pending is not None:
            try:
                self.after_cancel(pending)
            except Exception:
                pass
        try:
            self._dpi_refresh_after_id = self.after(120, self._refresh_after_dpi_scaling)
        except Exception:
            self._dpi_refresh_after_id = None

    def _schedule_dashboard_layout(self):
        if getattr(self, "_is_shutting_down", False):
            return
        pending = getattr(self, "_dashboard_layout_after_id", None)
        if pending is not None:
            try:
                self.after_cancel(pending)
            except Exception:
                pass
        try:
            self._dashboard_layout_after_id = self.after(
                180, self._refresh_dashboard_layout)
        except Exception:
            self._dashboard_layout_after_id = None

    def _refresh_dashboard_layout(self):
        self._dashboard_layout_after_id = None
        main = getattr(self, "_main_frame", None)
        stats_frame = getattr(self, "_stats_frame", None)
        cards = list(getattr(self, "_stat_cards", ()) or ())
        if main is None or stats_frame is None or not cards:
            return
        try:
            columns = _dashboard_stat_columns(main.winfo_width())
        except Exception:
            return
        if columns == getattr(self, "_dashboard_stat_layout_cols", None):
            return
        self._dashboard_stat_layout_cols = columns
        try:
            for column in range(6):
                stats_frame.grid_columnconfigure(
                    column, weight=1 if column < columns else 0)
            for index, card in enumerate(cards):
                row, column = divmod(index, columns)
                card.grid_configure(
                    row=row, column=column,
                    padx=(8 if column == 0 else 4,
                          8 if column == columns - 1 else 4),
                    pady=(12 if row == 0 else 4, 12))
        except Exception:
            pass

    def _refresh_after_dpi_scaling(self):
        self._dpi_refresh_after_id = None
        if getattr(self, "_is_shutting_down", False):
            return
        try:
            self.update_idletasks()
        except Exception:
            return
        main = getattr(self, "_main_frame", None)
        if main is not None:
            try:
                main.grid_rowconfigure(4, weight=1)
                main.grid_columnconfigure(0, weight=1)
            except Exception:
                pass
        self._refresh_dashboard_layout()
        for frame in (
            getattr(self, "_main_frame", None),
            getattr(self, "_sb", None),
            getattr(self, "_job_rows_frame", None),
            getattr(self, "_file_rows_frame", None),
        ):
            if frame is not None:
                _refresh_scrollable_frame_after_dpi(frame)
        try:
            self.update_idletasks()
            if getattr(self, "_log_pinned", False):
                self.log_box.see("end")
        except Exception:
            pass

    # ── Per-file şema ─────────────────────────────────────────────────────────
    def _populate_file_list(self, files: list, reset_page: bool = True):
        """Dosya ayarlarını korur; yalnızca görünür sayfanın widget'larını oluşturur."""
        files = sorted(self._dedupe_paths(files), key=lambda p: Path(p).name.lower())
        file_set = set(files)
        self._file_schema_vars = {
            fp: var for fp, var in getattr(self, "_file_schema_vars", {}).items()
            if fp in file_set
        }
        self._file_language_vars = {
            fp: var for fp, var in getattr(self, "_file_language_vars", {}).items()
            if fp in file_set
        }
        self._file_analysis_depth_vars = {
            fp: var for fp, var in getattr(
                self, "_file_analysis_depth_vars", {}).items()
            if fp in file_set
        }
        self._file_list_files = files
        if reset_page:
            self._file_list_page = 0
        page_files, page, pages = _file_list_page(
            files, getattr(self, "_file_list_page", 0))
        self._file_list_page = page

        for w in self._file_rows_frame.winfo_children():
            w.destroy()
        schema_names = [v["name"] for v in CONTENT_SCHEMAS.values()]
        default = normalize_schema_name(self.content_type_var.get())
        default_language = normalize_language_name(self.src_var.get())
        for fp in page_files:
            row_fr = ctk.CTkFrame(
                self._file_rows_frame, fg_color=CARD, corner_radius=6,
                border_width=1, border_color=BORDER_SOFT)
            row_fr.pack(fill="x", padx=2, pady=(0, 3))
            row_fr.grid_columnconfigure(0, weight=1)
            name = Path(fp).name
            if len(name) > 40:
                name = "…" + name[-37:]
            ctk.CTkLabel(row_fr, text=name,
                         font=ctk.CTkFont("Segoe UI", 11),
                         text_color=FG, anchor="w").grid(
                         row=0, column=0, sticky="ew", padx=(10,4), pady=5)
            lang_var = self._file_language_vars.get(fp)
            if lang_var is None:
                lang_var = ctk.StringVar(value=default_language)
                self._file_language_vars[fp] = lang_var
            ctk.CTkOptionMenu(row_fr, variable=lang_var, values=SOURCE_LANGUAGES,
                              width=105, height=26,
                              font=ctk.CTkFont("Segoe UI", 10),
                              fg_color=BORDER, button_color=BORDER,
                              button_hover_color=ACCENT,
                              dropdown_fg_color=CARD, text_color=FG,
                              ).grid(row=0, column=1, padx=(4, 2), pady=4)
            var = self._file_schema_vars.get(fp)
            if var is None:
                var = ctk.StringVar(value=default)
                self._file_schema_vars[fp] = var
            ctk.CTkOptionMenu(row_fr, variable=var, values=schema_names,
                              width=155, height=26,
                              font=ctk.CTkFont("Segoe UI", 10),
                              fg_color=BORDER, button_color=BORDER,
                              button_hover_color=ACCENT,
                              dropdown_fg_color=CARD, text_color=FG,
                              ).grid(row=0, column=2, padx=(4, 2), pady=4)
            depth_var = self._file_analysis_depth_vars.get(fp)
            if depth_var is None:
                depth_var = ctk.StringVar(value="Varsayılan")
                self._file_analysis_depth_vars[fp] = depth_var
            ctk.CTkOptionMenu(
                row_fr, variable=depth_var,
                values=["Varsayılan", "Standart", "Gelişmiş", "Maksimum"],
                width=105, height=26,
                font=ctk.CTkFont("Segoe UI", 10),
                fg_color=BORDER, button_color=BORDER,
                button_hover_color=ACCENT,
                dropdown_fg_color=CARD, text_color=FG,
            ).grid(row=0, column=3, padx=(4, 2), pady=4)
            # Dosya silme butonu
            ctk.CTkButton(row_fr, text="X", width=26, height=26,
                          font=ctk.CTkFont("Segoe UI", 11, "bold"),
                          fg_color="transparent", hover_color=BORDER,
                          text_color=WARN,
                          command=lambda p=fp: self._remove_file_from_list(p)
                          ).grid(row=0, column=4, padx=(0, 6), pady=4)
        self._file_list_lbl.configure(text=f"DOSYALAR ({len(files)})")
        if pages > 1:
            self._file_page_lbl.configure(text=f"{page + 1}/{pages}")
            self._file_prev_btn.configure(state="normal" if page > 0 else "disabled")
            self._file_next_btn.configure(
                state="normal" if page + 1 < pages else "disabled")
            self._file_prev_btn.grid()
            self._file_page_lbl.grid()
            self._file_next_btn.grid()
        else:
            self._file_prev_btn.grid_remove()
            self._file_page_lbl.grid_remove()
            self._file_next_btn.grid_remove()
        self._job_board.grid_remove()   # iş panosu varsa gizle
        self._file_list_outer.grid()

    def _change_file_list_page(self, delta: int):
        files = list(getattr(self, "_file_list_files", ()) or ())
        if not files:
            return
        _visible, current, pages = _file_list_page(
            files, getattr(self, "_file_list_page", 0))
        target = min(max(0, current + int(delta)), pages - 1)
        if target == current:
            return
        self._file_list_page = target
        self._populate_file_list(files, reset_page=False)

    def _remove_file_from_list(self, filepath: str):
        """Seçili dosyayı listeden kaldır."""
        if filepath in self._selected_files:
            self._selected_files.remove(filepath)
        self._file_schema_vars.pop(filepath, None)
        getattr(self, "_file_language_vars", {}).pop(filepath, None)
        getattr(self, "_file_analysis_depth_vars", {}).pop(filepath, None)
        remaining = list(self._selected_files)
        if remaining:
            self._refresh_selected_files_ui(f"Dosya listeden çıkarıldı: {Path(filepath).name}")
        else:
            self._clear_selected_files()

    def _dedupe_paths(self, paths: list) -> list:
        import os
        seen = set()
        out = []
        for p in paths:
            key = os.path.normcase(os.path.abspath(str(p)))
            if key in seen:
                continue
            seen.add(key)
            out.append(str(p))
        return out

    def _refresh_selected_files_ui(self, log_msg: str = ""):
        import os
        self._content_type_preflight_done = False
        self._language_preflight_done = False
        files = self._dedupe_paths(self._selected_files)
        self._selected_files = files
        if not files:
            self._clear_selected_files()
            return
        try:
            common = os.path.commonpath(files)
            if not os.path.isdir(common):
                common = str(Path(common).parent)
            self.input_var.set(common)
        except Exception:
            self.input_var.set(str(Path(files[0]).parent))
        n = len(files)
        self._estimate_async(
            files,
            lambda tb, ek, n=n: f"📄  {n} dosya seçildi  •  {tb} satır  •  ~{ek} token")
        if log_msg:
            self._log(log_msg, "ok")
        self._populate_file_list(files)
        self.clear_files_btn.grid(row=0, column=1, padx=(6, 0))
        self.clear_info_btn.grid(row=0, column=1, sticky="e", padx=(4, 0))
        App._update_readiness_card(self)

    def _apply_schema_to_all(self):
        """Tüm dosyaları global şemaya sıfırla."""
        name = normalize_schema_name(self.content_type_var.get())
        self.content_type_var.set(name)
        for var in self._file_schema_vars.values():
            var.set(name)

    def _apply_source_language_to_all(self):
        language = normalize_language_name(self.src_var.get())
        for var in getattr(self, "_file_language_vars", {}).values():
            var.set(language)

    def _get_file_glossary(self, filepath: str) -> str:
        """Dosyanın şemasına göre glossary yolunu döndür.
        Glossary alanı klasör ise: <klasör>/<schema_key>.{json,txt,tsv,csv}
        Glossary alanı dosya ise: doğrudan o dosyayı kullan (tüm şemalar için)."""
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            fg = self._active_snapshot.get("file_glossaries", {}).get(filepath)
            if fg is not None:
                return fg
            return self._active_snapshot.get("global_glossary_path", "")
        glossary_path = self.glossary_var.get().strip()
        if not glossary_path:
            return ""
        p = Path(glossary_path)
        if p.is_dir():
            schema_name = self._get_file_schema(filepath)["name"]
            schema_key  = next((k for k, v in CONTENT_SCHEMAS.items()
                                if v["name"] == schema_name), None)
            if schema_key:
                for ext in (".json", ".txt", ".tsv", ".csv"):
                    candidate = p / (schema_key + ext)
                    if candidate.exists():
                        return str(candidate)
            # Fallback: default glossary in the folder
            for fname in ("default.json", "default.txt", "glossary.json", "glossary.txt"):
                candidate = p / fname
                if candidate.exists():
                    return str(candidate)
            return ""
        return glossary_path  # regular single file — used for all schemas

    def _schema_by_name(self, name: str) -> dict:
        name = normalize_schema_name(name)
        for schema in CONTENT_SCHEMAS.values():
            if schema["name"] == name:
                return schema
        return CONTENT_SCHEMAS["auto"]

    def _merge_schema_glossary(self, glossary: dict, schema_dict: dict) -> dict:
        """Şemaya gömülü sözlüğü (ör. Warhammer terimleri) aktif sözlükle birleştirir.
        Dosya/kullanıcı sözlüğü öncelikli (şema değerini ezer). Hybrid akışlarda
        build_batch_requests şema almadığı için merge burada yapılır."""
        sg = (schema_dict or {}).get("glossary") or {}
        if not sg:
            return glossary or {}
        return {**sg, **(glossary or {})}

    def _get_file_schema(self, filepath: str) -> dict:
        """Dosyaya özgü şema varsa onu, yoksa global şemayı döndür."""
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            fs = self._active_snapshot.get("file_schemas", {}).get(filepath)
            if fs:
                return fs
            return self._active_snapshot.get("schema") or self._schema_by_name("Otomatik")
        var = self._file_schema_vars.get(filepath)
        name = normalize_schema_name(var.get() if var else self.content_type_var.get())
        return self._schema_by_name(name)

    def _get_file_analysis_depth(self, filepath: str) -> str:
        snapshot = getattr(self, "_active_snapshot", None) or {}
        if threading.current_thread() is not threading.main_thread() and snapshot:
            per_file = snapshot.get("file_analysis_depths") or {}
            return _resolve_analysis_depth_choice(
                per_file.get(filepath), snapshot.get("analysis_depth", "Standart"))
        var = getattr(self, "_file_analysis_depth_vars", {}).get(filepath)
        value = var.get() if var is not None else "Varsayılan"
        global_var = getattr(self, "analysis_depth_var", None)
        default_value = global_var.get() if global_var is not None else "Standart"
        return _resolve_analysis_depth_choice(value, default_value)

    def _load_context_cache_for_file(self, ht, filepath: str, target_language: str,
                                     source_language: str, schema_dict: dict = None,
                                     glossary: dict = None):
        schema_dict = schema_dict or self._get_file_schema(filepath)
        if glossary is None:
            glossary = ht.load_glossary(
                self._get_file_glossary(filepath), strict=True)
            glossary = self._merge_schema_glossary(glossary, schema_dict)
        return ht.load_context_cache(
            filepath,
            expected_target=target_language,
            expected_analysis_depth=App._get_file_analysis_depth(self, filepath),
            expected_source=_lang_iso639_1(source_language),
            helper_model=self._helper_api_model("analysis"),
            helper_url=self._helper_api_base_url("analysis"),
            style=App._run_setting(self, "style", "style_var", "natural"),
            schema=schema_dict,
            glossary=glossary,
            expected_scene_gap_sec=float(
                self._snap_get("scene_gap_seconds", self._scene_gap_seconds)),
        )

    def _get_file_source_language(self, filepath: str) -> str:
        if (threading.current_thread() is not threading.main_thread()
                and getattr(self, "_active_snapshot", None)):
            value = self._active_snapshot.get("file_source_languages", {}).get(filepath)
            if value:
                return normalize_language_name(value)
            return normalize_language_name(self._active_snapshot.get("src_lang", "English"))
        var = getattr(self, "_file_language_vars", {}).get(filepath)
        value = var.get() if var else self.src_var.get()
        return normalize_language_name(value)

    def _effective_file_source_language(self, filepath: str, fallback: str = "English") -> str:
        language = self._get_file_source_language(filepath)
        if language != AUTO_LANGUAGE:
            return language
        fallback = normalize_language_name(fallback)
        return fallback if fallback != AUTO_LANGUAGE else "English"

    # ── UI Dispatcher & Thread Safety ─────────────────────────────────────────
    _post_ui = _post_ui

    def _drain_ui_queue(self):
        """Ana thread'de çalışır ve UI kuyruğundaki callback'leri FIFO sırasıyla tüketir.
        Kapanış durumunu kontrol eder, bir turda sınırlı sayıda callback çalıştırır.
        """
        if getattr(self, "_is_shutting_down", False):
            return

        max_per_tick = 50
        count = 0
        started = time.monotonic()
        while count < max_per_tick:
            try:
                item = self._ui_queue.get_nowait()
            except queue.Empty:
                break
            count += 1
            fn, args, kwargs = item
            try:
                if not getattr(self, "_is_shutting_down", False):
                    fn(*args, **kwargs)
            except Exception as e:
                try:
                    print(f"[UI Dispatcher Error] {fn}: {e}")
                except Exception:
                    pass
            if time.monotonic() - started >= UI_DISPATCH_BUDGET_SECONDS:
                break

        if not getattr(self, "_is_shutting_down", False):
            try:
                delay = 1 if not self._ui_queue.empty() else 20
                self._drain_ui_queue_id = self.after(delay, self._drain_ui_queue)
            except Exception:
                pass

    def _snap_get(self, key: str, default=None):
        """Snapshot'tan ayar değerini güvenli şekilde döndürür."""
        if hasattr(self, "_active_snapshot") and isinstance(self._active_snapshot, dict) and key in self._active_snapshot:
            return self._active_snapshot[key]
        return default

    def _run_scene_gap(self) -> float:
        try:
            snapshot = self.__dict__.get("_active_snapshot")
            value = (snapshot.get("scene_gap_seconds", 3.0)
                     if isinstance(snapshot, dict)
                     else self.__dict__.get("_scene_gap_seconds", 3.0))
            return float(value)
        except (TypeError, ValueError):
            return 3.0

    def _run_setting(self, key: str, var_name: str, default=None):
        snapshot = getattr(self, "_active_snapshot", None)
        if (threading.current_thread() is not threading.main_thread()
                and isinstance(snapshot, dict) and key in snapshot):
            return snapshot[key]
        var = getattr(self, var_name, None)
        try:
            return var.get()
        except Exception:
            return default

    def _delivery_report_only_enabled(self) -> bool:
        snapshot = self.__dict__.get("_active_snapshot")
        if isinstance(snapshot, dict) and "quality_report_only" in snapshot:
            return bool(snapshot["quality_report_only"])
        var = self.__dict__.get("quality_report_only_var")
        try:
            return bool(var.get())
        except Exception:
            return True

    def _maybe_quarantine_incomplete_final(self, out_path) -> Path | None:
        if self._delivery_report_only_enabled():
            return None
        return _quarantine_incomplete_final(out_path)

    def _take_run_snapshot(self) -> dict:
        """Ana thread'de çalışarak çeviri oturumu için gereken tüm UI ayarlarının
        saf Python nesnesi olarak kopyasını oluşturur. Worker thread'ler Tk variable .get()
        veya widget okumaları yapmak yerine bu snapshot'ı kullanır.
        """
        srt_files = self._get_srt_files()
        file_schemas = {}
        file_glossaries = {}
        file_source_languages = {}
        file_analysis_depths = {}
        for fp in srt_files:
            try:
                var_s = getattr(self, "_file_schema_vars", {}).get(fp)
                name_s = normalize_schema_name(var_s.get() if var_s else self.content_type_var.get())
                file_schemas[fp] = self._schema_by_name(name_s)
            except Exception:
                pass
            try:
                file_glossaries[fp] = self._get_file_glossary(fp)
            except Exception:
                pass
            try:
                file_source_languages[fp] = self._get_file_source_language(fp)
            except Exception:
                pass
            try:
                file_analysis_depths[fp] = self._get_file_analysis_depth(fp)
            except Exception:
                pass

        helper_keys = {}
        helper_urls = {}
        helper_models = {}
        for role in ["analysis", "critic", "polish", "qc", "native", "condense", "review"]:
            try:
                helper_keys[role] = self._helper_api_key(role)
                helper_urls[role] = self._helper_api_base_url(role)
                helper_models[role] = self._helper_api_model(role)
            except Exception:
                pass

        return {
            "input_dir": self.input_var.get(),
            "output_dir": self.output_var.get(),
            "src_lang": self.src_var.get(),
            "file_source_languages": file_source_languages,
            "file_analysis_depths": file_analysis_depths,
            "tgt_lang": self.tgt_var.get(),
            "profanity": self.profanity_var.get(),
            "same_folder": self.same_folder_var.get(),
            "mode": self.mode_var.get(),
            "hybrid_mode": self.hybrid_var.get(),
            "auto_glossary": self.auto_glossary_var.get(),
            "analysis_depth": self.analysis_depth_var.get(),
            "style": getattr(self, "style_var", None).get()
            if getattr(self, "style_var", None) else "natural",
            "content_type": getattr(self, "content_type_var", None).get()
            if getattr(self, "content_type_var", None) else "Otomatik",
            "backup_raw": bool(getattr(self, "backup_raw_var", None)
                               and self.backup_raw_var.get()),
            "ext_project_path": self.ext_project_path_var.get().strip(),
            "notify_desktop": self.notify_var.get(),
            "shutdown_when_done": self.shutdown_when_done_var.get(),
            "prevent_sleep": bool(getattr(self, "prevent_sleep_var", None)
                                  and self.prevent_sleep_var.get()),
            "auto_retry_files": bool(getattr(self, "auto_retry_files_var", None)
                                     and self.auto_retry_files_var.get()),
            "auto_resume_crash": bool(getattr(self, "auto_resume_crash_var", None)
                                     and self.auto_resume_crash_var.get()),
            "workflow_profile": (
                self.workflow_profile_var.get()
                if getattr(self, "workflow_profile_var", None) else "Özel"),
            "term_normalize": getattr(self, "term_normalize_var", None).get() if getattr(self, "term_normalize_var", None) else False,
            "quality_report_only": bool(
                getattr(self, "quality_report_only_var", None) is None
                or self.quality_report_only_var.get()),
            "repair_missing": bool(getattr(self, "repair_missing_var", None)
                                   and self.repair_missing_var.get()),
            "critic": self.critic_var.get(),
            "polish": self.polish_var.get(),
            "native": self.native_var.get(),
            "qc": self.qc_var.get(),
            "condense": self.condense_var.get(),
            "backtrans": bool(getattr(self, "backtrans_var", None)
                              and self.backtrans_var.get()),
            "semantic_reconcile": (self.semantic_reconcile_var.get()
                                   if getattr(self, "semantic_reconcile_var", None)
                                   else True),
            "review": self.review_pass_var.get(),
            "twowave": self.twowave_var.get(),
            "clean_sdh": self.clean_sdh_var.get(),
            "linebreak": self.linebreak_var.get(),
            "ai_segment": bool(getattr(self, "ai_segment_var", None) and self.ai_segment_var.get()),
            "merge_cues": bool(getattr(self, "merge_cues_var", None) and self.merge_cues_var.get()),
            "chain_ctx": bool(getattr(self, "chain_ctx_var", None) and self.chain_ctx_var.get()),
            "precontext": bool(getattr(self, "precontext_var", None) and self.precontext_var.get()),
            "series_memory": bool(getattr(self, "series_memory_var", None) and self.series_memory_var.get()),
            "season_canon": bool(getattr(self, "season_canon_var", None) and self.season_canon_var.get()),
            "media_mode": (self.media_mode_var.get()
                           if getattr(self, "media_mode_var", None) else "Dizi"),
            "main_api_key": self._main_api_key(),
            "main_api_base_url": self._main_api_base_url(),
            "main_model_name": self._main_model_name(),
            "schema": self._get_schema(),
            "global_glossary_path": self.glossary_var.get().strip(),
            "helper_keys": helper_keys,
            "helper_urls": helper_urls,
            "helper_models": helper_models,
            "file_schemas": file_schemas,
            "file_glossaries": file_glossaries,
            "chunk_size": self._chunk_size,
            "context_lines": self._context_lines,
            "lookahead_lines": self._lookahead_lines,
            "max_workers": self._max_workers,
            "temperature": self._temperature,
            "max_retry": self._max_retry,
            "scene_gap_seconds": self._scene_gap_seconds,
            "selected_files": tuple(getattr(self, "_selected_files", ()) or ()),
            "selected_folder_roots": tuple(
                getattr(self, "_selected_folder_roots", ()) or ()),
        }

    def _freeze_run_variable_reads(self):
        if getattr(self, "_frozen_run_var_getters", None):
            return
        self._frozen_run_var_getters = []
        mapping = {
            "input_var": "input_dir", "output_var": "output_dir",
            "src_var": "src_lang", "tgt_var": "tgt_lang",
            "profanity_var": "profanity", "same_folder_var": "same_folder",
            "mode_var": "mode", "hybrid_var": "hybrid_mode",
            "auto_glossary_var": "auto_glossary",
            "analysis_depth_var": "analysis_depth",
            "ext_project_path_var": "ext_project_path",
            "notify_var": "notify_desktop", "term_normalize_var": "term_normalize",
            "quality_report_only_var": "quality_report_only",
            "repair_missing_var": "repair_missing",
            "prevent_sleep_var": "prevent_sleep",
            "auto_retry_files_var": "auto_retry_files",
            "auto_resume_crash_var": "auto_resume_crash",
            "workflow_profile_var": "workflow_profile",
            "critic_var": "critic", "polish_var": "polish",
            "native_var": "native", "qc_var": "qc",
            "condense_var": "condense", "backtrans_var": "backtrans",
            "semantic_reconcile_var": "semantic_reconcile",
            "review_pass_var": "review", "twowave_var": "twowave",
            "clean_sdh_var": "clean_sdh", "linebreak_var": "linebreak",
            "ai_segment_var": "ai_segment", "merge_cues_var": "merge_cues",
            "chain_ctx_var": "chain_ctx", "precontext_var": "precontext",
            "series_memory_var": "series_memory", "style_var": "style",
            "season_canon_var": "season_canon", "media_mode_var": "media_mode",
            "content_type_var": "content_type", "backup_raw_var": "backup_raw",
            "glossary_var": "global_glossary_path",
        }
        snapshot = getattr(self, "_active_snapshot", {}) or {}
        for attr, key in mapping.items():
            var = getattr(self, attr, None)
            if var is None or key not in snapshot:
                continue
            try:
                original = var.get
                value = snapshot[key]
                var.get = lambda _value=value: _value
                self._frozen_run_var_getters.append((var, original))
            except Exception:
                continue

    def _unfreeze_run_variable_reads(self):
        for var, original in getattr(self, "_frozen_run_var_getters", []):
            try:
                var.get = original
            except Exception:
                pass
        self._frozen_run_var_getters = []

    # ── Log yardımcıları ──────────────────────────────────────────────────────
    def _diagnostic_run_settings(self, snapshot: dict) -> dict:
        scalar_keys = (
            "input_dir", "output_dir", "src_lang", "tgt_lang", "mode",
            "hybrid_mode", "analysis_depth", "style", "content_type",
            "profanity", "same_folder", "auto_glossary", "term_normalize",
            "repair_missing",
            "critic", "polish", "native", "qc", "condense", "backtrans",
            "semantic_reconcile", "review", "twowave", "clean_sdh",
            "linebreak", "ai_segment", "merge_cues", "chain_ctx",
            "precontext", "series_memory", "season_canon", "media_mode",
            "main_model_name",
            "main_api_base_url", "shutdown_when_done",
            "prevent_sleep", "auto_retry_files", "auto_resume_crash",
            "workflow_profile", "backup_raw", "ext_project_path",
            "notify_desktop", "global_glossary_path",
            "chunk_size", "context_lines", "lookahead_lines", "max_workers",
            "temperature", "max_retry", "scene_gap_seconds",
            "crash_resume", "resume_origin_run_id", "auto_retry_repair_only",
            "resume_state_path",
        )
        result = {key: snapshot.get(key) for key in scalar_keys if key in snapshot}
        result["helper_models"] = dict(snapshot.get("helper_models") or {})
        result["helper_urls"] = dict(snapshot.get("helper_urls") or {})
        result["file_source_languages"] = dict(
            snapshot.get("file_source_languages") or {})
        result["file_analysis_depths"] = dict(
            snapshot.get("file_analysis_depths") or {})
        result["file_schema_names"] = {
            path: str((schema or {}).get("name") or "Otomatik")
            for path, schema in dict(snapshot.get("file_schemas") or {}).items()
        }
        result["file_glossaries"] = dict(snapshot.get("file_glossaries") or {})
        result["selected_folder_roots"] = list(
            snapshot.get("selected_folder_roots") or ())
        return json.loads(_sanitize_settings_backup_text(
            json.dumps(result, ensure_ascii=False, default=str)))

    def _begin_run_record(self, files: list, resume: bool = False):
        import datetime as _dt
        run_id = _new_run_id()
        queued_epoch = time.time()
        queued_at = _timing_iso(queued_epoch)
        snapshot = dict(getattr(self, "_active_snapshot", {}) or {})
        origin_run_id = str(snapshot.get("resume_origin_run_id") or run_id)
        snapshot["resume_origin_run_id"] = origin_run_id
        if isinstance(getattr(self, "_active_snapshot", None), dict):
            self._active_snapshot["resume_origin_run_id"] = origin_run_id
        diagnostic_settings = self._diagnostic_run_settings(snapshot)
        diagnostic_settings["resume_origin_run_id"] = origin_run_id
        settings_fingerprint = _stable_fingerprint(diagnostic_settings)
        token_lock = getattr(self, "_token_lock", threading.Lock())
        with token_lock:
            token_baseline = {
                "total_tokens": int(getattr(self, "_token_total", 0) or 0),
                "cached_tokens": int(getattr(self, "_token_cached", 0) or 0),
                "unknown_cost_tokens": int(
                    getattr(self, "_unknown_cost_tokens", 0) or 0),
                "cost_usd": float(getattr(self, "_cost_total", 0.0) or 0.0),
            }
        log_path = (
            state_path(__file__, "logs")
            / f"run_{run_id}.pid{os.getpid()}.log"
        )
        log_path.parent.mkdir(parents=True, exist_ok=True)
        if not getattr(self, "_auto_retry_continuation", False):
            self._run_log_paths = []
            self._auto_retry_attempts = {}
        self._auto_retry_continuation = False
        self._run_log_paths = list(getattr(self, "_run_log_paths", ()) or ())
        self._run_log_paths.append(str(log_path))
        with self._log_lock:
            old_log = getattr(self, "_log_file", None)
            try:
                if old_log is not None:
                    old_log.flush()
                    old_log.close()
            except Exception:
                pass
            self._log_file = open(log_path, "w", encoding="utf-8")
        record = {
            "run_id": run_id,
            "pid": os.getpid(),
            "process_start": _process_start_marker(os.getpid()),
            "started_at": _dt.datetime.now().isoformat(timespec="seconds"),
            "started_epoch": queued_epoch,
            "ended_at": "",
            "status": "çalışıyor",
            "resume": bool(resume),
            "settings": diagnostic_settings,
            "settings_fingerprint": settings_fingerprint,
            "checkpoint_origin_run_id": origin_run_id,
            "files": {
                str(path): {
                    "status": "pending", "phase": "Bekliyor",
                    "queued_at": queued_at, "queued_epoch": queued_epoch,
                    "stage_timings": [],
                }
                for path in files
            },
            "fixes_applied": 0,
            "suggestions_rejected": 0,
            "warnings": 0,
            "errors": 0,
            "api": {
                "attempts": 0, "successes": 0, "failures": 0,
                "terminal_failures": 0, "retries": 0,
                "provider_pauses": 0, "duration_seconds": 0.0,
                "operations": {}, "events": [], "usage_by_pass": {},
                "token_baseline": token_baseline,
            },
            "outputs": [],
            "reports": [],
            "completion_markers": [],
            "log_path": str(log_path),
            "last_traceback": "",
        }
        with self._run_record_lock:
            self._active_run_record = record
            self._quality_issues = {}
            self._quality_issue_seq = 0
            self._quality_checkpoint_stages_seen = set()
            self._api_stall_notices = set()
        persisted, persist_message = _persist_active_run_record(self, record)
        if persist_message:
            self._log(persist_message, "warn" if not persisted else "ok")
        if persisted:
            resumed_path = str(snapshot.get("resume_state_path") or "").strip()
            if resumed_path:
                try:
                    previous = Path(resumed_path)
                    if (os.path.normcase(os.path.abspath(str(previous)))
                            != os.path.normcase(os.path.abspath(
                                str(_active_run_state_path())))):
                        previous.unlink(missing_ok=True)
                except Exception as exc:
                    self._log(
                        f"Eski çökme kurtarma kaydı temizlenemedi: {exc}",
                        "warn")
            self._crash_resume_record_path = ""
        try:
            from provider_retry import configure_response_checkpoint
            configure_response_checkpoint(
                state_path(__file__, ".quality_response_checkpoint"),
                origin_run_id,
                allow_reads=bool(resume or snapshot.get("crash_resume")),
                hit_callback=self._quality_checkpoint_hit,
                error_callback=self._quality_checkpoint_error,
            )
        except Exception as exc:
            self._log(f"Kalite checkpoint'i başlatılamadı: {exc}", "warn")
        self._log(f"Çalıştırma kimliği: {run_id}", "info")
        return run_id

    def _quality_checkpoint_hit(self, count: int, checkpoint_label: str = "",
                                request_fingerprint: str = ""):
        stage = _api_operation_label(checkpoint_label)
        with self._run_record_lock:
            record = self._active_run_record
            if record is not None:
                api = record.setdefault("api", {})
                hits = api.setdefault("checkpoint_hits_by_pass", {})
                hits[stage] = int(hits.get(stage, 0) or 0) + 1
                if request_fingerprint:
                    fingerprints = api.setdefault(
                        "checkpoint_fingerprints_by_pass", {}).setdefault(stage, [])
                    if request_fingerprint not in fingerprints:
                        fingerprints.append(request_fingerprint)
                        del fingerprints[:-20]
        if int(count) == 1:
            self._log(
                "Çökme kurtarma: tamamlanmış API istekleri "
                "checkpoint'ten alınıyor.", "ok")
        seen = self.__dict__.setdefault("_quality_checkpoint_stages_seen", set())
        if checkpoint_label and checkpoint_label not in seen:
            seen.add(checkpoint_label)
            self._log(
                f"Çökme kurtarma: {stage} tamamlanmış checkpoint'ten sürdürüldü.",
                "ok",
            )
        self._set_status(
            f"Çökme kurtarma: {stage}; toplam {int(count)} istek yeniden gönderilmedi")

    def _quality_checkpoint_error(self, operation: str, exc) -> None:
        with self._run_record_lock:
            record = self._active_run_record
            if record is not None:
                api = record.setdefault("api", {})
                api["checkpoint_write_failures"] = int(
                    api.get("checkpoint_write_failures", 0) or 0) + 1
        self._log(
            "Kalite API yanıt checkpoint'i yazılamadı; mevcut yanıt "
            f"kullanılacak ancak çökme sonrası yeniden istenebilir: {exc}", "warn")

    def _record_file_status(self, filepath: str, phase: str, status: str):
        timing_log = None
        stage_log = None
        persist_message = ""
        persisted = True
        with self._run_record_lock:
            record = self._active_run_record
            if not record:
                return
            item = record["files"].setdefault(
                str(filepath), {"status": "pending", "phase": ""})
            stage_count = len(item.get("stage_timings") or [])
            previous_active_stage = item.get("active_stage")
            operation_exclusive = bool(
                item.get("active_stage_api_exclusive", True))
            operation_baseline = copy.deepcopy(
                item.get("active_stage_api_operations_start") or {})
            newly_finished = _advance_file_timing(item, phase, status)
            if len(item.get("stage_timings") or []) > stage_count:
                stage = item["stage_timings"][-1]
                active_count = sum(
                    1 for state in (record.get("files") or {}).values()
                    if state.get("active_stage"))
                if operation_exclusive and active_count <= 1:
                    operation_delta = _api_operation_map_delta(
                        (record.get("api") or {}).get("operations") or {},
                        operation_baseline)
                    if operation_delta:
                        stage["api_operations"] = operation_delta
                stage_log = (
                    f"⏱ Aşama tamamlandı: {Path(filepath).name} | "
                    f"{stage.get('name')} | "
                    f"{_format_elapsed(stage.get('duration_seconds'))} | "
                    f"{stage.get('started_at')} → {stage.get('ended_at')}")
                usage_by_pass = stage.get("api_usage_by_pass") or {}
                if usage_by_pass:
                    stage_log += " | API: " + "; ".join(
                        f"{name}: {_format_api_usage(usage)}"
                        for name, usage in usage_by_pass.items())
                operations = stage.get("api_operations") or {}
                if operations:
                    stage_log += " | İstekler: " + "; ".join(
                        f"{name}: {_format_api_operation(metrics)}"
                        for name, metrics in operations.items())
            if (item.get("active_stage")
                    and item.get("active_stage") != previous_active_stage):
                item["active_stage_api_operations_start"] = copy.deepcopy(
                    (record.get("api") or {}).get("operations") or {})
                item["active_stage_api_exclusive"] = True
            elif not item.get("active_stage"):
                item.pop("active_stage_api_operations_start", None)
                item.pop("active_stage_api_exclusive", None)
            active_items = [
                state for state in (record.get("files") or {}).values()
                if state.get("active_stage")
            ]
            if len(active_items) > 1:
                for state in active_items:
                    state["active_stage_api_exclusive"] = False
            item["phase"] = str(phase)
            if status in {"done", "error", "skip"}:
                item["status"] = status
            elif status == "running" and item.get("status") == "pending":
                item["status"] = "running"
            if newly_finished and not item.get("timing_logged"):
                item["timing_logged"] = True
                totals = _timing_stage_totals(item)
                stages = ", ".join(
                    f"{name} {_format_elapsed(seconds)}"
                    for name, seconds in totals) or "aşama kaydı yok"
                timing_log = (
                    f"⏱ {Path(filepath).name}: başlangıç "
                    f"{item.get('started_at') or '-'}, bitiş "
                    f"{item.get('ended_at') or '-'}, toplam "
                    f"{_format_elapsed(item.get('duration_seconds'))} | {stages}")
            persisted, persist_message = _persist_active_run_record(self, record)
        logger = getattr(self, "_log", None)
        if callable(logger):
            if persist_message:
                logger(persist_message, "warn" if not persisted else "ok")
            if stage_log:
                logger(stage_log, "info")
            if timing_log:
                logger(timing_log, "err" if status == "error" else "ok")

    def _block_automatic_recovery_for_permanent_provider(self):
        self._auto_retry_blocked_by_permanent_provider = True
        lock = self.__dict__.get("_run_record_lock")
        if lock is None:
            return
        persist_message = ""
        persisted = True
        with lock:
            record = self.__dict__.get("_active_run_record")
            if record is None:
                return
            record["recovery_blocked_reason"] = "permanent_provider"
            persisted, persist_message = _persist_active_run_record(self, record)
        logger = getattr(self, "_log", None)
        if persist_message and callable(logger):
            logger(persist_message, "warn" if not persisted else "ok")

    def _file_timing_snapshot(self, filepath: str) -> dict:
        with self._run_record_lock:
            record = (
                getattr(self, "_active_run_record", None)
                or getattr(self, "_last_run_record", None)
                or {})
            item = dict((record.get("files") or {}).get(str(filepath)) or {})
        item.pop("active_stage_epoch", None)
        return copy.deepcopy(item)

    def _record_log_metadata(self, msg: str, tag: str):
        with self._run_record_lock:
            record = self._active_run_record
            if not record:
                return
            if tag == "warn":
                record["warnings"] += 1
            elif tag == "err":
                record["errors"] += 1
            folded = str(msg).casefold()
            if "redded" in folded or "filtresinden döndü" in folded:
                match = re.search(r"(\d+)\s+(?:öneri|küme)", folded)
                if match:
                    record["suggestions_rejected"] += int(match.group(1))
            saved = re.search(
                r"(?:Kaydedildi|Çıktı)\s*:\s*(.+?\.srt)(?:\s|$)", str(msg))
            if saved:
                record["outputs"].append(saved.group(1).strip())
            report = re.search(
                r"(?:rapor(?:u)?|Rapor)\s*:\s*(.+?\.txt)(?:\s|$)", str(msg))
            if report:
                record["reports"].append(report.group(1).strip())

    def _record_quality_report(self, rows: list, report_paths: list):
        fixes = _quality_report_applied_fix_count(rows)
        rows_by_name = {
            str(row.get("name", "")): row
            for row in (rows or []) if row.get("name")
        }
        rows_by_source = {
            os.path.normcase(os.path.abspath(str(row["source_path"]))): row
            for row in (rows or []) if row.get("source_path")
        }
        persist_message = ""
        persisted = True
        with self._run_record_lock:
            record = self._active_run_record
            if not record:
                return
            record["fixes_applied"] = max(record["fixes_applied"], fixes)
            record["reports"].extend(str(path) for path in report_paths if path)
            name_counts = {}
            for path in record["files"]:
                name = Path(path).name
                name_counts[name] = name_counts.get(name, 0) + 1
            for path, item in record["files"].items():
                source_key = os.path.normcase(os.path.abspath(str(path)))
                row = rows_by_source.get(source_key)
                if row is None and name_counts.get(Path(path).name) == 1:
                    row = rows_by_name.get(Path(path).name)
                if not row:
                    continue
                if row.get("run_status") in {"error", "review"}:
                    item["status"] = "error"
                elif item.get("status") != "error":
                    item["status"] = "done"
                if row.get("output_path"):
                    item["output_path"] = str(row["output_path"])
            persisted, persist_message = _persist_active_run_record(self, record)
        logger = getattr(self, "_log", None)
        if persist_message and callable(logger):
            logger(persist_message, "warn" if not persisted else "ok")

    def _finalize_run_record(self):
        import datetime as _dt
        with self._run_record_lock:
            record = self._active_run_record
            if not record:
                return None
            ended_epoch = time.time()
            record["ended_at"] = _dt.datetime.fromtimestamp(
                ended_epoch).isoformat(timespec="seconds")
            record["ended_epoch"] = ended_epoch
            record["duration_seconds"] = round(max(
                0.0, ended_epoch - float(record.get("started_epoch") or ended_epoch)), 3)
            for item in record["files"].values():
                if item.get("status") == "running" and not item.get("ended_at"):
                    _advance_file_timing(
                        item, "Durduruldu" if self._stop_flag else "Kesildi",
                        "error", now=ended_epoch)
                    item["status"] = "running"
            states = [item.get("status", "pending") for item in record["files"].values()]
            if getattr(self, "_stop_flag", False):
                record["status"] = "durduruldu"
            elif states and all(state == "done" for state in states):
                record["status"] = "tamamlandı"
            elif any(state == "done" for state in states):
                record["status"] = "kısmen tamamlandı"
            elif any(state == "error" for state in states):
                record["status"] = "başarısız"
            elif any(state in {"pending", "running"} for state in states):
                record["status"] = "eksik"
            else:
                record["status"] = "tamamlandı"
            api = record.setdefault("api", {})
            baseline = dict(api.get("token_baseline") or {})
            token_lock = getattr(self, "_token_lock", threading.Lock())
            with token_lock:
                current_usage = {
                    "total_tokens": int(getattr(self, "_token_total", 0) or 0),
                    "cached_tokens": int(getattr(self, "_token_cached", 0) or 0),
                    "unknown_cost_tokens": int(
                        getattr(self, "_unknown_cost_tokens", 0) or 0),
                    "cost_usd": float(getattr(self, "_cost_total", 0.0) or 0.0),
                }
            api["session_usage_delta"] = {
                key: round(current_usage[key] - float(baseline.get(key, 0) or 0), 10)
                if key == "cost_usd" else
                int(current_usage[key]) - int(baseline.get(key, 0) or 0)
                for key in current_usage
            }
            api["diagnostics"] = _api_diagnostic_findings(api)
            snapshot = copy.deepcopy(record)
        resume_files = _interrupted_run_pending_files(snapshot)
        snapshot["resume_pending"] = list(resume_files)

        for finding in (snapshot.get("api") or {}).get("diagnostics") or []:
            tag = "err" if finding.get("severity") == "error" else "warn"
            if finding.get("severity") == "info":
                tag = "info"
            self._log(f"API teşhisi: {_format_api_diagnostic(finding)}", tag)

        try:
            marker_errors = []
            snapshot["completion_markers"] = _write_completion_markers(
                snapshot, marker_errors)
            for marker in snapshot["completion_markers"]:
                self._log(f"Çeviri tamamlandı işareti: {marker}", "ok")
            if marker_errors:
                snapshot["completion_marker_errors"] = marker_errors
                for marker_error in marker_errors:
                    self._log(f"ÇEVRİLDİ işareti hatası: {marker_error}", "warn")
        except Exception as exc:
            snapshot["completion_marker_error"] = str(exc)
            self._log(f"ÇEVRİLDİ işareti yazılamadı: {exc}", "warn")

        settings = snapshot.get("settings") or {}
        try:
            report_dir = _resolve_report_dir(
                settings.get("input_dir", ""), settings.get("output_dir", ""))
            report_dir.mkdir(parents=True, exist_ok=True)
            base = report_dir / f"calistirma_{snapshot['run_id']}_ozet"
            txt_path = base.with_suffix(".txt")
            json_path = base.with_suffix(".json")
            snapshot["reports"] = list(dict.fromkeys(
                list(snapshot.get("reports") or []) +
                [str(txt_path), str(json_path)]))
            diagnostics = list((snapshot.get("api") or {}).get("diagnostics") or [])
            if diagnostics:
                evidence_path = report_dir / f"api_teshis_{snapshot['run_id']}.json"
                evidence = {
                    "run_id": snapshot.get("run_id"),
                    "settings_fingerprint": snapshot.get("settings_fingerprint"),
                    "checkpoint_origin_run_id": snapshot.get("checkpoint_origin_run_id"),
                    "diagnostics": diagnostics,
                    "operations": (snapshot.get("api") or {}).get("operations") or {},
                    "usage_by_pass": (snapshot.get("api") or {}).get("usage_by_pass") or {},
                    "session_usage_delta": (
                        snapshot.get("api") or {}).get("session_usage_delta") or {},
                    "events": list((snapshot.get("api") or {}).get("events") or [])[-100:],
                    "files": snapshot.get("files") or {},
                }
                atomic_write_json(evidence_path, evidence)
                snapshot["reports"].append(str(evidence_path))
                self._log(f"API hata kanıt paketi: {evidence_path}", "info")
            atomic_write_text(
                txt_path, build_run_summary_text(snapshot), encoding="utf-8")
            atomic_write_json(json_path, snapshot)
            atomic_write_json(
                state_path(__file__, "last_run_summary.json"), snapshot)
        except Exception as exc:
            self._log(f"Çalıştırma özeti yazılamadı: {exc}", "warn")

        with self._run_record_lock:
            self._last_run_record = snapshot
            self._active_run_record = None
        persisted, persist_message = _persist_active_run_record(self, snapshot)
        if persist_message:
            self._log(persist_message, "warn" if not persisted else "ok")
        if not resume_files and persisted:
            try:
                _active_run_state_path().unlink(missing_ok=True)
            except Exception as exc:
                self._log(
                    "Tamamlanan çalışmanın kurtarma kaydı temizlenemedi; "
                    f"kayıt tamamlanmış durumda bırakıldı: {exc}", "warn")
        try:
            from provider_retry import (clear_response_checkpoint_namespace,
                                        configure_response_checkpoint)
            configure_response_checkpoint()
            origin_run_id = str(
                ((snapshot.get("settings") or {}).get("resume_origin_run_id"))
                or snapshot.get("run_id") or "")
            if not resume_files and origin_run_id:
                clear_response_checkpoint_namespace(
                    state_path(__file__, ".quality_response_checkpoint"),
                    origin_run_id)
        except Exception:
            pass
        return snapshot

    def _log(self, msg, tag="", issue_id=None):
        import datetime
        icons = {"ok": "✓", "err": "✗", "warn": "⚠", "info": "›"}
        icon  = icons.get(tag, " ")
        disk_msg = _sanitize_settings_backup_text(str(msg))
        disk_msg = "".join(
            char if ord(char) >= 32 or char in "\n\r\t"
            else f"\\x{ord(char):02x}"
            for char in disk_msg)
        recorder = getattr(self, "_record_log_metadata", None)
        if callable(recorder):
            recorder(disk_msg, tag)
        ui_msg = disk_msg
        if len(ui_msg) > 500:
            ui_msg = ui_msg[:497] + "…"
        ts   = datetime.datetime.now().strftime("%H:%M:%S")
        line = f"{icon}  {ui_msg}\n"

        # Log dosyasına yaz (zaman damgası ile) — lock: concurrent worker thread'ler
        disk_warning = ""
        try:
            with self._log_lock:
                self._log_file.write(f"[{ts}] {icon}  {disk_msg}\n")
                self._log_file.flush()
        except Exception as exc:
            if not self.__dict__.get("_disk_log_failure_reported", False):
                self._disk_log_failure_reported = True
                disk_warning = (
                    f"⚠  Oturum logu dosyasına yazılamıyor "
                    f"({type(exc).__name__}); arayüz logu devam ediyor.\n")
                if callable(recorder):
                    try:
                        recorder(
                            "Oturum logu dosyasına yazılamıyor; arayüz logu "
                            "devam ediyor.", "warn")
                    except Exception:
                        pass
        if disk_warning:
            line = disk_warning + line

        def _write():
            try:
                try:
                    view_before = self.log_box.yview()
                except Exception:
                    view_before = None
                follow_bottom = bool(self._log_pinned)
                if view_before is not None:
                    follow_bottom = (
                        follow_bottom and _log_view_at_bottom(view_before))
                self._log_pinned = follow_bottom
                self.log_box.configure(state="normal")
                tags = (f"quality_issue_{issue_id}",) if issue_id else ()
                if tags:
                    self.log_box.insert("end", line, tags)
                else:
                    self.log_box.insert("end", line)
                if issue_id:
                    tag_name = tags[0]
                    self.log_box.tag_config(
                        tag_name, foreground=INFO_BLUE, underline=True)
                    self.log_box.tag_bind(
                        tag_name, "<Button-1>",
                        lambda _event, iid=issue_id: self._open_quality_issue(iid))
                    self.log_box.tag_bind(
                        tag_name, "<Enter>",
                        lambda _event: self.log_box.configure(cursor="hand2"))
                    self.log_box.tag_bind(
                        tag_name, "<Leave>",
                        lambda _event: self.log_box.configure(cursor=""))
                if follow_bottom:
                    self.log_box.see("end")
                elif view_before is not None:
                    self.log_box.yview_moveto(float(view_before[0]))
                self.log_box.configure(state="disabled")
            except Exception:
                pass

        _post_ui(self, _write)

    def _record_api_event(self, event: str, remaining: int, waiting: int,
                          details: dict | None = None):
        info = dict(details or {})
        operation = _api_operation_label(info.get("checkpoint_label", ""))
        significant = (
            event in {"request_start", "request_success", "request_failure",
                      "circuit_open", "circuit_reopen", "circuit_recovered",
                      "request_stalled"}
            or event.startswith("retry_start_")
            or event.startswith("retry_success_")
            or event in {"repair_retry_start", "repair_retry_end"}
        )
        with self._run_record_lock:
            record = self._active_run_record
            if not record:
                return None
            api = record.setdefault("api", {})
            for key in ("attempts", "successes", "failures", "terminal_failures",
                        "retries", "provider_pauses"):
                api.setdefault(key, 0)
            api.setdefault("duration_seconds", 0.0)
            api.setdefault("operations", {})
            api.setdefault("events", [])
            per_operation = api["operations"].setdefault(operation, {
                "attempts": 0, "successes": 0, "failures": 0, "retries": 0,
                "terminal_failures": 0, "provider_pauses": 0,
                "duration_seconds": 0.0,
                "latencies": [], "models": [], "providers": [],
                "request_fingerprints": [],
            })
            for key in ("attempts", "successes", "failures", "retries",
                        "terminal_failures", "provider_pauses"):
                per_operation.setdefault(key, 0)
            per_operation.setdefault("duration_seconds", 0.0)
            for key in ("latencies", "models", "providers", "request_fingerprints"):
                per_operation.setdefault(key, [])
            for key, value in (
                    ("models", info.get("model")),
                    ("providers", info.get("provider")),
                    ("request_fingerprints", info.get("request_fingerprint"))):
                if value and str(value) not in per_operation[key]:
                    per_operation[key].append(str(value))
                    del per_operation[key][:-20]
            if event == "request_start":
                api["attempts"] += 1
                per_operation["attempts"] += 1
            elif event == "request_success":
                api["successes"] += 1
                per_operation["successes"] += 1
                per_operation["duration_seconds"] = round(
                    float(per_operation.get("duration_seconds") or 0.0)
                    + float(info.get("duration_seconds") or 0.0), 3)
                per_operation["latencies"].append(
                    float(info.get("duration_seconds") or 0.0))
                del per_operation["latencies"][:-500]
                api["duration_seconds"] = round(
                    float(api.get("duration_seconds") or 0.0)
                    + float(info.get("duration_seconds") or 0.0), 3)
            elif event == "request_failure":
                api["failures"] += 1
                per_operation["failures"] += 1
                per_operation["duration_seconds"] = round(
                    float(per_operation.get("duration_seconds") or 0.0)
                    + float(info.get("duration_seconds") or 0.0), 3)
                per_operation["latencies"].append(
                    float(info.get("duration_seconds") or 0.0))
                del per_operation["latencies"][:-500]
                api["duration_seconds"] = round(
                    float(api.get("duration_seconds") or 0.0)
                    + float(info.get("duration_seconds") or 0.0), 3)
                if not info.get("will_retry"):
                    api["terminal_failures"] += 1
                    per_operation["terminal_failures"] += 1
            elif event.startswith("retry_start_") or event == "repair_retry_start":
                api["retries"] += 1
                per_operation["retries"] += 1
            elif event in {"circuit_open", "circuit_reopen"}:
                api["provider_pauses"] += 1
                per_operation["provider_pauses"] += 1
            if significant:
                api["events"].append({
                    "at": _timing_iso(time.time()), "event": event,
                    "operation": operation, "remaining_seconds": int(remaining),
                    "active_requests": int(waiting),
                    "model": str(info.get("model") or ""),
                    "provider": str(info.get("provider") or ""),
                    "attempt": int(info.get("attempt") or info.get("next_attempt") or 0),
                    "max_attempts": int(info.get("max_attempts") or 0),
                    "will_retry": bool(info.get("will_retry", False)),
                    "status_code": info.get("status_code"),
                    "reason": str(info.get("reason") or ""),
                    "request_id": str(info.get("request_id") or ""),
                    "request_fingerprint": str(
                        info.get("request_fingerprint") or ""),
                    "duration_seconds": float(
                        info.get("duration_seconds") or 0.0),
                })
                del api["events"][:-500]
            return copy.deepcopy(api)

    def _repair_retry_wait(self, delay: float, cancelled) -> bool:
        total = max(0.0, float(delay))
        details = {
            "checkpoint_label": "translation_repair",
            "reason": "önceki eksik cue adayı doğrulamadan geçmedi",
        }
        recorder = getattr(self, "_record_api_event", None)
        if callable(recorder):
            recorder("repair_retry_start", math.ceil(total), 0, details)
        self._set_phase(
            "Eksik Çeviri Onarımı",
            f"Yalnız eksik cue'lar {math.ceil(total)} sn sonra yeniden denenecek")
        deadline = time.monotonic() + total
        last_second = None
        while True:
            if cancelled():
                self._set_status("Eksik cue yeniden denemesi durduruldu")
                return False
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            second = max(1, math.ceil(remaining))
            if second != last_second:
                last_second = second
                self._motion_activity_text = "YENİDEN"
                self._set_status(
                    f"Eksik çeviri onarımı: {second} sn sonra yalnız eksik cue'lar "
                    "yeniden gönderilecek")
            time.sleep(min(0.25, remaining))
        if callable(recorder):
            recorder("repair_retry_end", 0, 0, details)
        self._set_status("Eksik cue yeniden denemesi gönderiliyor...")
        return True

    def _provider_wait_callback(self, event: str, remaining: int, waiting: int,
                                details: dict | None = None):
        info = dict(details or {})
        operation = _api_operation_label(info.get("checkpoint_label", ""))
        context = _api_context_text(info)
        recorder = getattr(self, "_record_api_event", None)
        api_stats = None
        if callable(recorder):
            api_stats = recorder(event, remaining, waiting, info)
        live_counts = ""
        if api_stats:
            live_counts = (
                f"API {int(api_stats.get('successes', 0))}/"
                f"{int(api_stats.get('attempts', 0))} başarılı · "
                f"{int(api_stats.get('retries', 0))} tekrar · "
                f"{int(api_stats.get('terminal_failures', 0))} kalıcı hata")
        if (info.get("checkpoint_label") and (
                event in {"request_start", "request_success", "request_failure",
                          "circuit_probe"}
                or event.startswith("retry_start_"))):
            phase_setter = getattr(self, "_set_phase", None)
            if callable(phase_setter):
                phase_setter(
                    operation, " · ".join(
                        value for value in (context, live_counts) if value))
        if event in {
                "circuit_open", "circuit_reopen", "circuit_start",
                "circuit_tick", "start", "tick"}:
            self._motion_activity_text = "BEKLİYOR"
        elif event in {"circuit_probe", "request_start", "request_tick"}:
            self._motion_activity_text = "API"
        elif event.startswith("retry_"):
            self._motion_activity_text = (
                "API" if "_end_" in event or "_success_" in event
                else "YENİDEN")
        elif event in {"request_success", "circuit_recovered"}:
            self._motion_activity_text = "ÇALIŞIYOR"
        if event == "circuit_open":
            self._log(
                f"{operation}: sağlayıcı art arda hata verdi; yeni istekler {remaining} sn "
                "duraklatıldı. Süre sonunda tek kontrol isteği gönderilecek.",
                "warn",
            )
            self._set_status(
                f"{operation}: sağlayıcı kullanılamıyor; güvenli bekleme {remaining} sn")
            return
        if event == "circuit_reopen":
            self._log(
                f"{operation}: sağlayıcı kontrol isteği de başarısız; {remaining} sn sonra "
                "yeniden kontrol edilecek.",
                "warn",
            )
            self._set_status(
                f"{operation}: sağlayıcı hâlâ kullanılamıyor; yeni kontrol {remaining} sn")
            return
        if event in {"circuit_start", "circuit_tick"}:
            self._set_status(
                f"{operation}: sağlayıcı kullanılamıyor; kontrol isteğine {remaining} sn")
            return
        if event == "circuit_probe":
            self._log(
                "Sağlayıcı kontrol ediliyor; yalnız bir deneme isteği gönderildi...",
                "info",
            )
            self._set_status("Sağlayıcı kontrol isteğine yanıt bekleniyor")
            return
        if event == "circuit_recovered":
            self._log(
                "Sağlayıcı yeniden yanıt veriyor; bekleyen işlemler devam ediyor.",
                "ok",
            )
            self._set_status("API bağlantısı düzeldi; işlem devam ediyor")
            return
        if event == "request_start":
            self._set_status(
                f"{operation}: API isteği gönderildi"
                f"{f' ({context})' if context else ''}; {waiting} aktif")
            return
        if event == "request_tick":
            fingerprint = str(info.get("request_fingerprint") or "")
            stall_key = fingerprint or "|".join((
                operation, str(info.get("model") or ""),
                str(info.get("attempt") or "")))
            seen = self.__dict__.setdefault("_api_stall_notices", set())
            for threshold in _api_stall_thresholds(remaining):
                marker = (stall_key, threshold)
                if marker in seen:
                    continue
                seen.add(marker)
                stall_info = dict(info)
                stall_info["duration_seconds"] = float(remaining or 0.0)
                if callable(recorder):
                    recorder("request_stalled", remaining, waiting, stall_info)
                self._log(
                    f"{operation}: API isteği {_format_elapsed(remaining)} yanıt bekledi; "
                    "istek otomatik iptal edilmedi, izleme sürüyor.",
                    "warn" if threshold >= 240 else "info")
            self._set_status(
                f"{operation}: API yanıtı {remaining} sn bekleniyor"
                f"{f' ({context})' if context else ''}; {waiting} aktif istek")
            return
        if event == "request_success":
            if waiting:
                self._set_status(
                    f"{operation}: API yanıtı alındı; {waiting} istek hâlâ bekleniyor"
                    f"{f' · {live_counts}' if live_counts else ''}")
            else:
                self._set_status(
                    f"{operation}: API yanıtı alındı"
                    f"{f' · {live_counts}' if live_counts else ''}")
            return
        if event == "request_failure":
            request_id = str(info.get("request_id") or "")
            if request_id:
                self._log(f"{operation}: sağlayıcı istek kimliği: {request_id}", "info")
            reason = str(info.get("reason") or "API hatası")
            status = info.get("status_code")
            suffix = f" (HTTP {status})" if status else ""
            retry_note = "yeniden denenecek" if info.get("will_retry") else "kalıcı hata"
            self._log(
                f"{operation}: API isteği başarısız — {reason}{suffix}; {retry_note}"
                f"{f' · {context}' if context else ''}",
                "warn" if info.get("will_retry") else "err")
            self._set_status(
                f"{operation}: {reason}{suffix}; {retry_note}")
            return
        if event == "circuit_end":
            return
        retry_match = re.fullmatch(
            r"retry_(start|tick|end|success)_(\d+)_(\d+)", event)
        if retry_match:
            phase, attempt, total = retry_match.groups()
            next_attempt = int(
                info.get("next_attempt") or attempt)
            max_attempts = int(
                info.get("max_attempts") or total)
            reason = str(info.get("reason") or "geçici API hatası")
            if phase == "start":
                self._log(
                    f"{operation}: {reason}; {remaining} sn sonra deneme "
                    f"{next_attempt}/{max_attempts} gönderilecek"
                    f"{f' · {_api_context_text(info, include_attempt=False)}' if context else ''}",
                    "warn")
            if phase in {"start", "tick"}:
                self._set_status(
                    f"{operation}: {reason}; {remaining} sn sonra yeniden deneme "
                    f"{next_attempt}/{max_attempts}")
            elif phase == "end" and waiting == 0:
                if self._stop_flag:
                    self._set_status("Durduruluyor...")
                else:
                    self._log(
                        f"{operation}: API denemesi {next_attempt}/{max_attempts} "
                        "gönderiliyor...",
                        "info")
                    self._set_status(
                        f"{operation}: API denemesi {next_attempt}/{max_attempts} "
                        "gönderildi; yanıt bekleniyor")
            elif phase == "success":
                succeeded_attempt = int(info.get("attempt") or next_attempt)
                self._log(
                    f"{operation}: API denemesi {succeeded_attempt}/{max_attempts} "
                    "başarılı; işlem devam ediyor.", "ok")
                self._set_status(
                    f"{operation}: API yanıtı alındı; deneme "
                    f"{succeeded_attempt}/{max_attempts} başarılı, işlem devam ediyor")
            return
        if event == "start" and waiting == 1:
            self._log(
                f"{operation}: reseller kota beklemesi {remaining} sn "
                f"({waiting} istek sırada)", "warn")
        if event in {"start", "tick"}:
            self._set_status(
                f"{operation}: reseller kota beklemesi {remaining} sn "
                f"({waiting} istek sırada)")
        elif event == "end" and waiting == 0:
            self._set_status(
                "Durduruluyor..." if self._stop_flag else "API beklemesi bitti, devam ediliyor...")

    def _log_exc(self, label: str, exc: Exception):
        """Hata mesajını + kısa traceback'i loga yazar."""
        tb_lines = traceback.format_exception(type(exc), exc, exc.__traceback__)
        # Son 2 frame'i al (çok uzun olmasın)
        compact = "".join(tb_lines[-3:]).strip().replace("\n", " | ")
        lock = getattr(self, "_run_record_lock", None)
        if lock is not None:
            with lock:
                record = getattr(self, "_active_run_record", None)
                if record is not None:
                    record["last_traceback"] = "".join(tb_lines)
        self._log(f"{label}: {exc}", "err")
        self._log(f"  ↳ {compact}", "err")

    def _notify(self, title: str, msg: str):
        """Windows masaüstü bildirimi (ek bağımlılık gerektirmez)."""
        enabled = False
        if threading.current_thread() is threading.main_thread():
            try:
                enabled = bool(self.notify_var.get())
            except Exception:
                enabled = False
        elif hasattr(self, "_active_snapshot") and self._active_snapshot:
            enabled = bool(self._active_snapshot.get("notify_desktop"))
        if not enabled:
            return
        try:
            import subprocess
            safe_title = title.replace("'", "").replace('"', '')
            safe_msg   = msg.replace("'", "").replace('"', '')
            ps = (
                "Add-Type -AssemblyName System.Windows.Forms; "
                "$n = [System.Windows.Forms.NotifyIcon]::new(); "
                "$n.Icon = [System.Drawing.SystemIcons]::Application; "
                "$n.Visible = $true; "
                f"$n.ShowBalloonTip(5000,'{safe_title}','{safe_msg}',"
                "[System.Windows.Forms.ToolTipIcon]::Info); "
                "Start-Sleep 6; $n.Dispose()"
            )
            subprocess.Popen(
                ["powershell", "-WindowStyle", "Hidden", "-Command", ps],
                creationflags=subprocess.CREATE_NO_WINDOW,
            )
        except Exception:
            pass

    def _test_translate(self):
        """İlk dosyanın ilk 3 chunk'ını sync çevirip önizleme dialog'u açar."""
        if getattr(self, "_is_running", False) or getattr(self, "_folder_scan_busy", False):
            self._log("Test çevirisi çalışan çeviri sırasında başlatılamaz.", "warn")
            return
        api_key = self._main_api_key()
        if not api_key:
            messagebox.showerror("API Key", "OpenAI API key girilmemiş!")
            return
        files = self._get_srt_files()
        if not files:
            messagebox.showwarning("Test", "Önce dosya veya klasör seç.")
            return

        fp   = files[0]
        src  = self._effective_file_source_language(fp, self.src_var.get())
        tgt  = self.tgt_var.get()
        model = self._main_model_name()
        base_url = self._main_api_base_url()
        schema = self._get_file_schema(fp)
        profanity = self.profanity_var.get()
        glossary_path = self._get_file_glossary(fp)
        chain_context = App._run_setting(
            self, "chain_ctx", "chain_ctx_var", True)
        build_options = {
            "chunk_size": self._chunk_size,
            "project_memory": self._project_memory_for(fp, src),
            "context_lines": self._context_lines,
            "lookahead_lines": self._lookahead_lines,
            "scene_gap_sec": self._scene_gap_seconds,
            "temperature": self._temperature,
        }

        self._log(f"🧪 Test çevirisi: {Path(fp).name} (ilk 3 chunk)", "info")
        self._set_running(True)

        def _run():
            try:
                import hybrid_translate as ht
                from openai import OpenAI as _OAI
                client = _OAI(api_key=api_key, base_url=base_url if base_url else None)
                if not list(parse_subtitle(fp)):
                    try:
                        _post_ui(self, messagebox.showwarning, "Test", "Dosyada geçerli SRT bloğu yok.")
                    except Exception:
                        pass
                    return

                # Gerçek çeviriyle birebir aynı istek hattını kullan:
                # ctx/next_ctx, süre, frag etiketleri, glossary, proje hafızası dahil.
                gloss = ht.load_glossary(glossary_path, strict=True)
                reqs, fmap = build_requests([fp], src, tgt, model,
                                            schema=schema,
                                            profanity=profanity,
                                            glossary=gloss,
                                            **build_options)
                reqs = reqs[:2]   # ilk ~2 chunk (≈100 satır) yeterli önizleme

                results, prev_pairs = [], []
                for req in reqs:
                    if self._stop_flag:
                        break
                    cid      = req["custom_id"]
                    user_msg = req["body"]["messages"][1]
                    if chain_context:
                        user_msg["content"] = _inject_prev_tr(
                            user_msg["content"], prev_pairs,
                            max_pairs=build_options["context_lines"])
                    payload = json.loads(user_msg["content"])
                    try:
                        resp = _safe_chat_create(
                            client,
                            cancel_context=self.__dict__.get(
                                "_helper_request_canceller"),
                            _checkpoint_label="translation_preview",
                            **req["body"],
                        )
                        _report_response_usage(
                            _app_token_callback(
                                self, model,
                                "Çeviri Önizleme",
                                base_url=base_url),
                            resp, log_fn=self._log,
                            pass_name="Çeviri Önizleme")
                        raw  = (resp.choices[0].message.content or "").strip()
                        tmap = parse_response(raw, fmap.get(cid, []))
                        pairs = _chain_pairs_from_result(user_msg["content"], tmap)
                        if pairs:
                            prev_pairs = pairs
                        for it in payload.get("tr", []):
                            results.append((it.get("t", ""),
                                            tmap.get(str(it["i"]), "[HATA]")))
                    except Exception as e:
                        for it in payload.get("tr", []):
                            results.append((it.get("t", ""), f"[HATA: {e}]"))

                try:
                    _post_ui(self, self._show_test_dialog, results, Path(fp).name)
                except Exception:
                    pass
            except Exception as e:
                self._log_exc("Test çevirisi hatası", e)
            finally:
                self._set_running(False)

        App._start_worker(self, _run)

    def _show_test_dialog(self, results: list, fname: str):
        """Kaynak / Çeviri yan yana önizleme dialog'u."""
        dlg = ctk.CTkToplevel(self)
        dlg.title(f"🧪 Test Çevirisi — {fname}")
        dlg.geometry("920x600")
        dlg.configure(fg_color=BG)
        dlg.grab_set()
        dlg.lift()
        dlg.focus_force()

        ctk.CTkLabel(dlg,
                     text=f"{fname} — ilk {len(results)} satır önizleme",
                     font=ctk.CTkFont("Segoe UI", 13, "bold"),
                     text_color=ACCENT).pack(pady=(14, 4))

        # İki sütunlu scrollable alan
        cols = ctk.CTkFrame(dlg, fg_color="transparent")
        cols.pack(fill="both", expand=True, padx=12, pady=4)
        cols.grid_columnconfigure((0, 1), weight=1)

        for col, header in enumerate(["KAYNAK", "ÇEVİRİ"]):
            ctk.CTkLabel(cols, text=header,
                         font=ctk.CTkFont("Segoe UI", 11, "bold"),
                         text_color=FG2).grid(row=0, column=col, sticky="w", padx=8, pady=(0, 4))

        sf = ctk.CTkScrollableFrame(cols, fg_color=PANEL, corner_radius=8)
        sf.grid(row=1, column=0, columnspan=2, sticky="nsew", padx=4)
        cols.grid_rowconfigure(1, weight=1)
        sf.grid_columnconfigure((0, 1), weight=1)

        for i, (src_t, tr_t) in enumerate(results):
            bg = CARD if i % 2 == 0 else PANEL
            for col, text in enumerate([src_t, tr_t]):
                color = FG if col == 0 else (RED if text.startswith("[HATA") else GREEN)
                ctk.CTkLabel(sf, text=text,
                             font=ctk.CTkFont("Segoe UI", 11),
                             text_color=color,
                             fg_color=bg, corner_radius=4,
                             wraplength=400, justify="left",
                             anchor="w").grid(
                    row=i, column=col, sticky="ew", padx=6, pady=2, ipady=3)

        btn_fr = ctk.CTkFrame(dlg, fg_color="transparent")
        btn_fr.pack(fill="x", padx=12, pady=(4, 14))
        btn_fr.grid_columnconfigure((0, 1), weight=1)

        ctk.CTkButton(btn_fr, text="✕  Kapat",
                      fg_color=CARD, hover_color=BORDER,
                      command=dlg.destroy).grid(row=0, column=0, padx=4, sticky="ew")
        ctk.CTkButton(btn_fr, text="▶  Tam Çeviriyi Başlat",
                      fg_color=ACCENT, hover_color=ACCENT_HOVER,
                      command=lambda: (dlg.destroy(), self._start())).grid(row=0, column=1, padx=4, sticky="ew")

    def _on_log_scrollbar_press(self, _event=None):
        self._log_pinned = False

    def _on_log_manual_scroll(self, _event=None):
        self._log_pinned = False
        try:
            self.after_idle(self._check_log_pin)
        except Exception:
            pass

    def _check_log_pin(self):
        """Kullanıcı scroll yaptıktan sonra alta yakın mı diye kontrol eder."""
        try:
            self._log_pinned = _log_view_at_bottom(self.log_box.yview())
        except Exception:
            pass

    def _pin_log_bottom(self):
        """'⬇ Alta git' butonuna basınca kilidi aç ve en alta git."""
        self._log_pinned = True
        try:
            self.log_box.see("end")
        except Exception:
            pass

    def _shortcut_copy_complete_log(self, _event=None):
        self._copy_complete_log_to_clipboard()
        return "break"

    def _shortcut_pin_log_bottom(self, _event=None):
        self._pin_log_bottom()
        return "break"

    def _shortcut_copy_diagnostic(self, _event=None):
        self._copy_diagnostic_package()
        return "break"

    def _shortcut_show_last_summary(self, _event=None):
        self._show_last_run_summary()
