    def _copy_selected_log_text(self):
        try:
            content = self.log_box.get("sel.first", "sel.last")
        except (tk.TclError, AttributeError):
            return False
        if not str(content).strip():
            return False
        try:
            self.clipboard_clear()
            self.clipboard_append(content)
            self.update_idletasks()
            return True
        except Exception as exc:
            self._log(f"Seçili log panoya kopyalanamadı: {exc}", "warn")
            return False

    def _show_log_context_menu(self, event):
        menu = self.__dict__.get("_log_context_menu")
        log_box = self.__dict__.get("log_box")
        if menu is None or log_box is None:
            return "break"
        try:
            has_selection = bool(log_box.tag_ranges("sel"))
            has_content = bool(log_box.get("1.0", "end-1c").strip())
            record_getter = getattr(self, "_current_run_record_snapshot", None)
            try:
                has_record = bool(record_getter()) if callable(record_getter) else False
            except Exception:
                has_record = False
            menu.entryconfigure(0, state="normal" if has_selection else "disabled")
            menu.entryconfigure(1, state="normal" if has_content else "disabled")
            menu.entryconfigure(4, state="normal" if has_content else "disabled")
            menu.entryconfigure(6, state="normal" if has_record else "disabled")
            menu.entryconfigure(7, state="normal" if has_record else "disabled")
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass
        return "break"

    def _complete_session_log_text(self):
        log_file = getattr(self, "_log_file", None)
        lock = getattr(self, "_log_lock", None)

        def _read_disk_log():
            if log_file is None:
                return ""
            log_file.flush()
            paths = list(getattr(self, "_run_log_paths", ()) or ())
            current = getattr(log_file, "name", None)
            if isinstance(current, (str, os.PathLike)):
                paths.append(str(current))
            chunks = []
            for raw_path in dict.fromkeys(paths):
                try:
                    text = Path(raw_path).read_text(encoding="utf-8")
                except Exception:
                    continue
                if text:
                    chunks.append(text)
            if len(chunks) == 1:
                return chunks[0]
            if chunks:
                return "\n\n".join(
                    chunk.rstrip("\r\n") for chunk in chunks) + "\n"
            return ""

        try:
            if lock is not None:
                with lock:
                    content = _read_disk_log()
            else:
                content = _read_disk_log()
            if content:
                return content
        except Exception:
            pass

        try:
            return self.log_box.get("1.0", "end-1c")
        except Exception:
            return ""

    def _copy_complete_log_to_clipboard(self):
        try:
            content = self._complete_session_log_text()
            self.clipboard_clear()
            self.clipboard_append(content)
            self.update_idletasks()
            button = getattr(self, "_copy_log_btn", None)
            if button is not None:
                button.configure(text="✓ Kopyalandı")
                self.after(1500, lambda: button.configure(text="📋 Logları Kopyala"))
            return True
        except Exception as e:
            self._log(f"Loglar panoya kopyalanamadı: {e}", "warn")
            messagebox.showwarning(
                "Pano kullanılamıyor",
                "Loglar panoya kopyalanamadı. Başka bir uygulama panoyu kilitlemiş olabilir.")
            return False

    def _export_log_and_shutdown(self, record: dict):
        run_id = re.sub(
            r"[^0-9A-Za-z_-]+", "_", str(record.get("run_id") or "son"))
        self._log(
            "Tüm çeviriler tamamlandı; oturum logu kaydedilip bilgisayar kapatılacak.",
            "info",
        )
        content = self._complete_session_log_text()
        if not content.strip():
            self._log(
                "Otomatik kapanış iptal edildi: kaydedilecek oturum logu bulunamadı.",
                "err",
            )
            return False

        try:
            desktop = _desktop_directory()
            desktop.mkdir(parents=True, exist_ok=True)
            log_path = desktop / f"ceviri_logu_{run_id}.txt"
            atomic_write_text(log_path, content, encoding="utf-8")
        except Exception as exc:
            self._log(
                f"Otomatik kapanış iptal edildi: log Masaüstüne kaydedilemedi: {exc}",
                "err",
            )
            return False

        try:
            self.clipboard_clear()
            self.clipboard_append(content)
            self.update_idletasks()
        except Exception as exc:
            self._log(
                f"Log Masaüstüne kaydedildi fakat panoya kopyalanamadı: {exc}",
                "warn",
            )

        self._log(f"Tam oturum logu Masaüstüne kaydedildi: {log_path}", "ok")
        try:
            shutdown_exe = (
                Path(os.environ.get("SystemRoot", r"C:\Windows"))
                / "System32" / "shutdown.exe"
            )
            subprocess.Popen(
                [
                    str(shutdown_exe), "/s", "/t", "30", "/c",
                    "Altyazı çevirileri tamamlandı. Bilgisayar 30 saniye içinde kapanacak.",
                ],
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            self._log(
                "Windows kapanışı başlatıldı (30 saniye; iptal için: shutdown /a).",
                "info",
            )
        except Exception as exc:
            self._log(f"Bilgisayar kapatma komutu başlatılamadı: {exc}", "err")
            return False
        countdown = getattr(self, "_show_shutdown_countdown", None)
        if callable(countdown):
            try:
                countdown(30)
            except Exception as exc:
                self._log(
                    "Windows kapanışı başlatıldı fakat geri sayım penceresi "
                    f"açılamadı: {exc}. İptal için: shutdown /a",
                    "err",
                )
        return True

    def _cancel_scheduled_shutdown(self):
        try:
            shutdown_exe = (
                Path(os.environ.get("SystemRoot", r"C:\Windows"))
                / "System32" / "shutdown.exe"
            )
            completed = subprocess.run(
                [str(shutdown_exe), "/a"],
                check=False,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
        except Exception as exc:
            self._log(f"Windows kapanışı iptal edilemedi: {exc}", "err")
            return False
        if completed.returncode != 0:
            self._log(
                f"Windows kapanışı iptal edilemedi (kod {completed.returncode}). "
                "Komut satırında shutdown /a deneyin.",
                "err",
            )
            return False
        self._log("Windows kapanışı kullanıcı tarafından iptal edildi.", "warn")
        after_id = self._shutdown_countdown_after_id
        if after_id is not None:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        self._shutdown_countdown_after_id = None
        dlg = self._shutdown_countdown_dialog
        self._shutdown_countdown_dialog = None
        try:
            if dlg is not None and dlg.winfo_exists():
                dlg.destroy()
        except Exception:
            pass
        return True

    def _show_shutdown_countdown(self, seconds: int = 30):
        if getattr(self, "_is_shutting_down", False):
            return
        dlg = ctk.CTkToplevel(self)
        self._shutdown_countdown_dialog = dlg
        dlg.title("Bilgisayar Kapanacak")
        dlg.configure(fg_color=BG)
        dlg.resizable(False, False)
        dlg.protocol("WM_DELETE_WINDOW", self._cancel_scheduled_shutdown)
        label = ctk.CTkLabel(
            dlg,
            text="",
            font=ctk.CTkFont("Segoe UI", 18, "bold"),
            text_color=YELLOW,
        )
        label.pack(fill="x", padx=30, pady=(28, 16))
        ctk.CTkLabel(
            dlg,
            text="Tam oturum logu Masaüstüne kaydedildi.",
            font=ctk.CTkFont("Segoe UI", 11),
            text_color=FG2,
        ).pack(fill="x", padx=30, pady=(0, 18))
        ctk.CTkButton(
            dlg,
            text="Kapatmayı İptal Et",
            height=40,
            fg_color=RED,
            hover_color=RED_HOVER,
            command=self._cancel_scheduled_shutdown,
        ).pack(fill="x", padx=30, pady=(0, 28))
        dlg.transient(self)
        dlg.geometry(centered_dialog_geometry(
            self.winfo_rootx(), self.winfo_rooty(),
            max(self.winfo_width(), 1), max(self.winfo_height(), 1),
            460, 220,
        ))
        dlg.lift()
        dlg.attributes("-topmost", True)

        def _tick(remaining):
            if self._shutdown_countdown_dialog is not dlg:
                return
            label.configure(text=f"{remaining} saniye sonra bilgisayar kapanacak")
            if remaining <= 0:
                self._shutdown_countdown_after_id = None
                return
            self._shutdown_countdown_after_id = self.after(
                1000, _tick, remaining - 1)

        _tick(max(0, int(seconds)))

    def _schedule_shutdown_after_success(self, record: dict | None):
        if not record or record.get("status") != "tamamlandı":
            return False
        switch = getattr(self, "shutdown_when_done_var", None)
        if switch is not None:
            enabled = bool(switch.get())
        else:
            enabled = bool(
                (getattr(self, "_active_snapshot", {}) or {}).get(
                    "shutdown_when_done"))
        if not enabled:
            return False
        run_id = str(record.get("run_id") or "")
        if not run_id or run_id == self._auto_shutdown_scheduled_run_id:
            return False
        self._auto_shutdown_scheduled_run_id = run_id
        try:
            self.shutdown_when_done_var.set(False)
        except Exception:
            pass
        self._log(
            "Otomatik kapanış etkin: son log ve rapor işlemlerinin tamamlanması bekleniyor.",
            "info",
        )
        try:
            self.after(
                2500,
                lambda _record=copy.deepcopy(record):
                    self._export_log_and_shutdown(_record),
            )
            return True
        except Exception as exc:
            self._log(f"Otomatik kapanış zamanlanamadı: {exc}", "err")
            return False

    def _on_shutdown_when_done_changed(self):
        enabled = bool(self.shutdown_when_done_var.get())
        snapshot = getattr(self, "_active_snapshot", None)
        if isinstance(snapshot, dict):
            snapshot["shutdown_when_done"] = enabled
        lock = getattr(self, "_run_record_lock", None)
        persist_message = ""
        persisted = True
        if lock is not None:
            with lock:
                record = getattr(self, "_active_run_record", None)
                if record is not None:
                    record.setdefault("settings", {})["shutdown_when_done"] = enabled
                    persisted, persist_message = _persist_active_run_record(
                        self, record)
        if persist_message:
            self._log(persist_message, "warn" if not persisted else "ok")
        if getattr(self, "_is_running", False):
            state = "açıldı" if enabled else "kapatıldı"
            self._log(
                f"Bu çalışma için 'Bitince bilgisayarı kapat' {state}.",
                "warn" if enabled else "info",
            )

    def _schedule_failed_file_retry(self, record: dict | None) -> bool:
        if not record or record.get("status") in {"tamamlandı", "durduruldu"}:
            return False
        run_settings = dict(record.get("settings") or {})
        if str(run_settings.get("mode") or "sync").casefold() != "sync":
            return False
        snapshot = getattr(self, "_active_snapshot", {}) or {}
        if not snapshot.get("auto_retry_files"):
            return False
        if getattr(self, "_auto_retry_blocked_by_permanent_provider", False):
            self._log(
                "Kalıcı API/model/anahtar hatası nedeniyle dosyalar otomatik "
                "yeniden gönderilmeyecek.", "warn")
            return False
        failed = []
        manual_missing = 0
        manual_missing_paths = {
            str(row.get("source_path") or "")
            for row in list(record.get("_quality_report_rows") or [])
            if (
                int(row.get("repair_missing_after", 0) or 0) > 0
                or int((row.get("delivery_audit") or {}).get(
                    "unresolved_markers", 0) or 0) > 0
            )
        }
        for filepath, item in dict(record.get("files") or {}).items():
            if not _file_recovery_is_retryable(item):
                continue
            phase = str((item or {}).get("phase") or "").casefold()
            if (not snapshot.get("repair_missing")
                    and ("eksik çeviri" in phase
                         or str(filepath) in manual_missing_paths)):
                manual_missing += 1
                continue
            if not Path(filepath).is_file():
                continue
            attempt = int(self._auto_retry_attempts.get(filepath, 0))
            if attempt < 2:
                self._auto_retry_attempts[filepath] = attempt + 1
                failed.append(filepath)
        if not failed:
            if manual_missing:
                self._log(
                    f"Eksik Cue API Onarımı kapalı: {manual_missing} eksik dosya "
                    "otomatik yeniden başlatılmadı; cue ayrıntıları logda bırakıldı.",
                    "warn",
                )
            return False
        self._selected_files = failed
        self._input_folder_explicitly_selected = False
        self._language_preflight_done = True
        self._content_type_preflight_done = True
        self._file_integrity_preflight_done = False
        self._auto_retry_continuation = True
        retry_settings = copy.deepcopy(
            dict(run_settings or snapshot))
        retry_settings["crash_resume"] = True
        retry_settings["auto_retry_repair_only"] = True
        retry_settings["resume_origin_run_id"] = str(
            retry_settings.get("resume_origin_run_id")
            or record.get("run_id") or "")
        self._resume_snapshot_override = retry_settings
        attempt_no = max(self._auto_retry_attempts[path] for path in failed)
        self._log(
            f"{len(failed)} başarısız/eksik dosya otomatik yeniden denenecek "
            f"(deneme {attempt_no}/2).",
            "warn",
        )
        try:
            self.after(1500, self._start)
            return True
        except Exception as exc:
            self._log(f"Otomatik dosya yeniden denemesi başlatılamadı: {exc}", "err")
            return False

    def _current_run_record_snapshot(self):
        with self._run_record_lock:
            record = self._active_run_record or self._last_run_record
            return copy.deepcopy(record) if record else None

    def _record_quality_issue(self, issue: dict):
        with self._run_record_lock:
            self._quality_issue_seq += 1
            run_id = str((self._active_run_record or {}).get("run_id") or "run")
            issue_id = f"{run_id}-{self._quality_issue_seq}"
            self._quality_issues[issue_id] = copy.deepcopy(issue)
            return issue_id

    def _open_quality_issue(self, issue_id: str):
        with self._run_record_lock:
            issue = copy.deepcopy(self._quality_issues.get(issue_id))
        if not issue:
            messagebox.showinfo(
                "Cue İnceleyici", "Bu uyarının cue ayrıntıları artık bellekte değil.")
            return
        items = list(issue.get("items") or [])
        dlg = ctk.CTkToplevel(self)
        dlg.title(f"Cue İnceleyici — {Path(issue.get('source_path', '')).name}")
        dlg.geometry("1100x650")
        dlg.minsize(760, 420)
        dlg.configure(fg_color=BG)
        dlg.grid_columnconfigure((0, 1), weight=1)
        dlg.grid_rowconfigure(2, weight=1)
        ctk.CTkLabel(
            dlg, text=issue.get("message", ""), anchor="w",
            justify="left", wraplength=1040,
            font=ctk.CTkFont("Segoe UI", 12, "bold"),
            text_color=YELLOW).grid(
                row=0, column=0, columnspan=2, sticky="ew",
                padx=16, pady=(14, 8))
        ctk.CTkLabel(
            dlg, text="KAYNAK", text_color=FG2,
            font=ctk.CTkFont("Segoe UI", 11, "bold")).grid(
                row=1, column=0, sticky="w", padx=16)
        ctk.CTkLabel(
            dlg, text="ÇEVİRİ", text_color=FG2,
            font=ctk.CTkFont("Segoe UI", 11, "bold")).grid(
                row=1, column=1, sticky="w", padx=16)
        source_box = ctk.CTkTextbox(
            dlg, font=ctk.CTkFont("Consolas", 12),
            fg_color=PANEL, text_color=FG, wrap="word")
        target_box = ctk.CTkTextbox(
            dlg, font=ctk.CTkFont("Consolas", 12),
            fg_color=PANEL, text_color=FG, wrap="word")
        source_box.grid(row=2, column=0, sticky="nsew", padx=(16, 6), pady=(6, 12))
        target_box.grid(row=2, column=1, sticky="nsew", padx=(6, 16), pady=(6, 12))
        source_text = []
        target_text = []
        for item in items:
            cue_id = item.get("id", "?")
            source_text.append(f"#{cue_id}\n{item.get('source', '')}\n{'─' * 44}")
            target_text.append(f"#{cue_id}\n{item.get('translation', '')}\n{'─' * 44}")
        source_box.insert("1.0", "\n".join(source_text) or "Cue bulunamadı.")
        target_box.insert("1.0", "\n".join(target_text) or "Cue bulunamadı.")
        source_box.configure(state="disabled")
        target_box.configure(state="disabled")
        dlg.lift()
        dlg.focus_force()

    def _diagnostic_package_text(self, record: dict) -> str:
        import platform
        import subprocess
        import sys
        try:
            commit = subprocess.check_output(
                ["git", "rev-parse", "--short", "HEAD"],
                cwd=str(Path(__file__).resolve().parent),
                text=True, encoding="utf-8", errors="replace",
                timeout=3).strip()
        except Exception:
            commit = "bilinmiyor"
        log_text = ""
        log_path = str(record.get("log_path") or "")
        active = getattr(self, "_active_run_record", None)
        if active and active.get("run_id") == record.get("run_id"):
            log_text = self._complete_session_log_text()
        else:
            try:
                if log_path:
                    log_text = Path(log_path).read_text(encoding="utf-8")
            except Exception:
                log_text = ""
        sections = [
            "SUBTITLE TRANSLATOR TANI PAKETİ",
            "=" * 72,
            build_run_summary_text(record).rstrip(),
            "",
            "SÜRÜM / ORTAM",
            f"Commit            : {commit}",
            f"Python            : {sys.version.split()[0]}",
            f"CustomTkinter     : {getattr(ctk, '__version__', 'bilinmiyor')}",
            f"Sistem            : {platform.platform()}",
            "",
            "AYARLAR (ANAHTARLAR HARİÇ)",
            json.dumps(record.get("settings") or {}, ensure_ascii=False, indent=2),
            "",
            "SON TRACEBACK",
            str(record.get("last_traceback") or "Yok"),
            "",
            "EKSİKSİZ OTURUM LOGU",
            log_text or "Log bulunamadı.",
        ]
        return _sanitize_settings_backup_text("\n".join(sections))

    def _copy_diagnostic_package(self):
        record = self._current_run_record_snapshot()
        if not record:
            messagebox.showinfo(
                "Tanı Paketi", "Henüz kaydedilmiş bir çalıştırma bulunmuyor.")
            return False
        try:
            content = self._diagnostic_package_text(record)
            self.clipboard_clear()
            self.clipboard_append(content)
            self.update_idletasks()
            button = getattr(self, "_diagnostic_btn", None)
            if button is not None:
                button.configure(text="✓ Kopyalandı")
                self.after(
                    1500, lambda: button.configure(text="🩺 Tanı Paketi"))
            return True
        except Exception as exc:
            self._log(f"Tanı paketi kopyalanamadı: {exc}", "warn")
            messagebox.showwarning(
                "Pano kullanılamıyor",
                "Tanı paketi panoya kopyalanamadı. Başka bir uygulama panoyu kilitlemiş olabilir.")
            return False

    def _show_last_run_summary(self):
        record = self._current_run_record_snapshot()
        if not record:
            messagebox.showinfo(
                "Son Çalıştırma Özeti",
                "Henüz kaydedilmiş bir çalıştırma bulunmuyor.")
            return
        self._show_report_dialog(
            build_run_summary_text(record),
            str(record.get("reports", [""])[-1] if record.get("reports") else ""))

    def _clear_log(self):
        self.log_box.configure(state="normal")
        self.log_box.delete("1.0", "end")
        self.log_box.configure(state="disabled")

