    def _motion_enabled(self) -> bool:
        var = self.__dict__.get("light_animations_var")
        try:
            return bool(var and var.get())
        except Exception:
            return False

    def _pass_progress_callback(self, filepath, label: str,
                                start_pct: float, end_pct: float):
        display_name = Path(filepath).name if filepath else "Geçerli dosya"

        def _progress(done: int, total: int, state: str = "completed"):
            total = max(1, int(total or 1))
            done = max(0, min(total, int(done or 0)))
            waiting = state == "requesting"
            visible = min(total, done + 1) if waiting else done
            activity = "yanıt bekleniyor" if waiting else "yanıt alındı"
            phase_setter = self.__dict__.get("_set_phase")
            if callable(phase_setter):
                phase_setter(
                    label,
                    f"{display_name}  —  Paket {visible}/{total} · {activity}",
                )
            else:
                App._set_phase(
                    self, label,
                    f"{display_name}  —  Paket {visible}/{total} · {activity}",
                )
            if filepath:
                span = max(0.0, float(end_pct) - float(start_pct))
                pct = float(start_pct) + span * (done / total)
                row_updater = self.__dict__.get("_update_file_progress")
                if callable(row_updater):
                    row_updater(filepath, label, pct)
                else:
                    App._update_file_progress(self, filepath, label, pct)

        return _progress

    def _on_window_motion(self, event=None):
        if event is None or getattr(event, "widget", self) is self:
            self._motion_pause_until = time.monotonic() + 0.65
            App._schedule_dashboard_layout(self)

    def _cancel_motion_animation(self, snap: bool = False):
        after_id = self.__dict__.get("_motion_after_id")
        self._motion_after_id = None
        if after_id is not None:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
        if snap:
            target = float(self.__dict__.get("_motion_progress_target", 0.0))
            self._motion_progress_value = target
            phase_color = self.__dict__.get("_motion_phase_color", ACCENT)
            try:
                self.progress.set(target)
                self.progress.configure(progress_color=phase_color)
                self._phase_dot.configure(text="●", text_color=phase_color)
                self._phase_activity_lbl.configure(
                    text=(
                        _phase_activity_indicator(
                            self.__dict__.get("_motion_activity_text"),
                            time.monotonic() - self.__dict__.get(
                                "_motion_activity_started_at", time.monotonic()),
                            self.__dict__.get("_motion_step", 0),
                        )
                        if self.__dict__.get("_is_running", False) else ""))
                self._phase_card.configure(
                    border_width=1,
                    border_color=_mix_hex_color(BORDER, phase_color, 0.38))
            except Exception:
                pass
            for row in self.__dict__.get("_job_rows", {}).values():
                value = float(row.get("target", row.get("value", 0.0)))
                row["value"] = value
                try:
                    row["pb"].set(value)
                    row["dot"].configure(text_color=row.get("color", FG2))
                    if row.get("state") != "running":
                        row["frame"].configure(
                            border_width=1, border_color=BORDER_SOFT)
                except Exception:
                    pass

    def _on_light_animations_changed(self):
        if not App._motion_enabled(self):
            App._cancel_motion_animation(self, snap=True)
        elif self.__dict__.get("_is_running", False):
            App._ensure_motion_animation(self)
        try:
            self._save_settings(save_credentials=False)
        except Exception:
            pass

    def _ensure_motion_animation(self):
        if (self.__dict__.get("_motion_after_id") is not None
                or not App._motion_enabled(self)
                or not self.__dict__.get("_is_running", False)
                or self.__dict__.get("_is_shutting_down", False)):
            return
        try:
            self._motion_after_id = self.after(
                110, lambda: App._motion_tick(self))
        except Exception:
            self._motion_after_id = None

    def _motion_tick(self):
        self._motion_after_id = None
        if (not App._motion_enabled(self)
                or not self.__dict__.get("_is_running", False)
                or self.__dict__.get("_is_shutting_down", False)):
            return
        if time.monotonic() < self.__dict__.get("_motion_pause_until", 0.0):
            App._ensure_motion_animation(self)
            return

        self._motion_step = (self.__dict__.get("_motion_step", 0) + 1) % 32
        wave = (math.sin(self._motion_step * math.pi / 16.0) + 1.0) / 2.0
        base_color = self.__dict__.get("_motion_phase_color", ACCENT)
        phase_color = _mix_hex_color(
            _mix_hex_color(PANEL, base_color, 0.52),
            _mix_hex_color(FG, base_color, 0.72), wave)
        dot_frames = ("●", "◉", "◎", "◉")
        dot_text = dot_frames[(self._motion_step // 4) % len(dot_frames)]
        activity = str(
            self.__dict__.get("_motion_activity_text") or "ÇALIŞIYOR")
        activity_age = time.monotonic() - self.__dict__.get(
            "_motion_activity_started_at", time.monotonic())
        try:
            self._phase_dot.configure(text=dot_text, text_color=phase_color)
            self._phase_activity_lbl.configure(
                text=_phase_activity_indicator(
                    activity, activity_age, self._motion_step),
                text_color=phase_color)
            self._phase_card.configure(
                border_width=1,
                border_color=_mix_hex_color(BORDER, phase_color, 0.72))
            self.progress.configure(progress_color=phase_color)
        except Exception:
            pass

        active_path = self.__dict__.get("_motion_active_filepath")
        active_row = self.__dict__.get("_job_rows", {}).get(active_path)
        if active_row and active_row.get("state") == "running":
            try:
                active_row["dot"].configure(text_color=_mix_hex_color(
                    FG2, active_row.get("color", ACCENT),
                    0.58 + wave * 0.42))
                active_row["frame"].configure(
                    border_width=1,
                    border_color=_mix_hex_color(
                        BORDER, active_row.get("color", ACCENT),
                        0.42 + wave * 0.48))
                active_row["pb"].configure(progress_color=_mix_hex_color(
                    active_row.get("color", ACCENT), FG, wave * 0.28))
            except Exception:
                pass

        current = float(self.__dict__.get("_motion_progress_value", 0.0))
        target = float(self.__dict__.get("_motion_progress_target", current))
        if abs(target - current) > 0.0005:
            current += (target - current) * 0.28
            if abs(target - current) < 0.001:
                current = target
            self._motion_progress_value = current
            try:
                self.progress.set(current)
            except Exception:
                pass

        if active_row and active_row.get("state") == "running":
            row_current = float(active_row.get("value", 0.0))
            row_target = float(active_row.get("target", row_current))
            if abs(row_target - row_current) > 0.0005:
                row_current += (row_target - row_current) * 0.32
                if abs(row_target - row_current) < 0.001:
                    row_current = row_target
                active_row["value"] = row_current
                try:
                    active_row["pb"].set(row_current)
                except Exception:
                    pass
        App._ensure_motion_animation(self)

    def _update_pipeline_rail(self, phase: str, color: str):
        widgets = list(
            self.__dict__.get("_pipeline_stage_widgets", ()) or ())
        if not widgets:
            return
        current = _pipeline_stage_index(phase)
        phase_key = str(phase or "").strip().casefold()
        fully_complete = phase_key.startswith("tamam")
        for index, item in enumerate(widgets):
            if index < current or (fully_complete and index == current):
                stage_color = GREEN
                stage_bg = _mix_hex_color(CARD, GREEN, 0.14)
                number = "✓"
            elif index == current:
                stage_color = color
                stage_bg = _mix_hex_color(CARD, color, 0.16)
                number = f"0{index + 1}"
            else:
                stage_color = FG_DIS
                stage_bg = CARD
                number = f"0{index + 1}"
            item["frame"].configure(
                fg_color=stage_bg,
                border_color=_mix_hex_color(BORDER_SOFT, stage_color, 0.55))
            item["number"].configure(text=number, text_color=stage_color)
            item["label"].configure(text_color=stage_color)

    def _refresh_progress_window_title(self):
        title = _progress_window_title(
            self.__dict__.get("_window_phase", "Hazır"),
            self.__dict__.get("_window_phase_detail", ""),
            self.__dict__.get("_motion_progress_target", 0.0),
            bool(self.__dict__.get("_is_running", False)),
        )
        if title == self.__dict__.get("_window_title_value"):
            return
        self._window_title_value = title
        title_setter = getattr(self, "title", None)
        if callable(title_setter):
            title_setter(title)

    def _set_phase(self, phase: str, detail: str = ""):
        """Büyük faz etiketini günceller. phase = 'analiz'|'çeviri'|'critic'|..."""
        key   = phase.lower().split()[0]
        color = self._PHASE_COLORS.get(key, ACCENT)
        visible_detail = _phase_detail_text(phase, detail)

        def _upd():
            try:
                self._window_phase = phase
                self._window_phase_detail = visible_detail
                self._motion_activity_started_at = time.monotonic()
                self._motion_phase_color = color
                self._motion_activity_text = (
                    "" if key in {"hazır", "tamam"} else "ÇALIŞIYOR")
                self._motion_step = 0
                self._phase_lbl.configure(text=phase, text_color=color)
                self._phase_dot.configure(text="●", text_color=color)
                self._phase_card.configure(
                    border_width=1,
                    border_color=_mix_hex_color(BORDER, color, 0.78))
                self.progress.configure(progress_color=color)
                self._phase_activity_lbl.configure(
                    text="" if key in {"hazır", "tamam"} else "ÇALIŞIYOR ·")
                self.progress_lbl.configure(text=visible_detail)
                App._update_pipeline_rail(self, phase, color)
                App._refresh_progress_window_title(self)
                App._ensure_motion_animation(self)
            except Exception:
                pass

        _post_ui(self, _upd)

    def _set_status(self, msg):
        def _upd():
            try:
                self._motion_activity_started_at = time.monotonic()
                self.progress_lbl.configure(text=msg)
            except Exception:
                pass
        _post_ui(self, _upd)

    def _set_progress(self, pct):
        val = max(0.0, min(1.0, pct / 100))
        def _upd(v=val):
            try:
                previous_target = float(
                    self.__dict__.get("_motion_progress_target", 0.0))
                self._motion_progress_target = v
                if abs(v - previous_target) > 0.0005:
                    self._motion_activity_started_at = time.monotonic()
                pct_label = self.__dict__.get("_progress_pct_lbl")
                if pct_label is not None:
                    pct_label.configure(
                        text=f"{int(round(v * 100))}%",
                        text_color=self.__dict__.get(
                            "_motion_phase_color", FG2))
                if App._motion_enabled(self) and self.__dict__.get("_is_running", False):
                    App._ensure_motion_animation(self)
                else:
                    self._motion_progress_value = v
                    self.progress.set(v)
                App._refresh_progress_window_title(self)
            except Exception:
                pass
        _post_ui(self, _upd)

    def _set_eta(self, text: str):
        """ETA etiketini thread-safe günceller."""
        def _upd(t=text):
            try:
                self.eta_lbl.configure(text=t)
            except Exception:
                pass
        _post_ui(self, _upd)

    def _set_stat(self, var, value):
        """Stat sayacı Tk değişkenini thread-safe ayarlar (worker thread'den de güvenli —
        Tcl değişken yazımı yalnız ana thread'de güvenlidir)."""
        def _upd(v=value):
            try:
                var.set(v)
            except Exception:
                pass
        _post_ui(self, _upd)

    def _season_canon_groups(self):
        snapshot = getattr(self, "_active_snapshot", {}) or {}
        record = getattr(self, "_active_run_record", None) or {}
        groups = {}
        for source_path, item in (record.get("files") or {}).items():
            if item.get("status") != "done" or not item.get("output_path"):
                continue
            key = series_memory.parse_series_key(source_path)
            output_path = Path(item["output_path"])
            if key is None or not output_path.exists():
                continue
            slug, season, episode = key
            source_language = self._effective_file_source_language(
                source_path, snapshot.get("src_lang") or "English")
            memory_root = str(series_memory.series_memory_root(source_path))
            group_key = (
                os.path.normcase(os.path.abspath(memory_root)), slug, season,
                _lang_iso639_1(source_language),
            )
            groups.setdefault(group_key, []).append(
                (episode, str(source_path), output_path))
        return {
            key: sorted(items)
            for key, items in groups.items() if len(items) >= 2
        }

    def _should_start_season_canon(self) -> bool:
        snapshot = getattr(self, "_active_snapshot", {}) or {}
        record = getattr(self, "_active_run_record", None) or {}
        if (getattr(self, "_season_canon_finalizing", False)
                or getattr(self, "_season_canon_done", False)
                or getattr(self, "_stop_flag", False)
                or snapshot.get("media_mode", "Dizi") != "Dizi"
                or not snapshot.get("series_memory", True)
                or not snapshot.get("season_canon", True)):
            return False
        states = [item.get("status", "pending")
                  for item in (record.get("files") or {}).values()]
        if not states or any(state in {"pending", "running"} for state in states):
            return False
        return bool(self._season_canon_groups())

    def _run_season_canon_audit(self):
        snapshot = getattr(self, "_active_snapshot", {}) or {}
        record = getattr(self, "_active_run_record", None) or {}
        run_id = str(record.get("run_id") or "run")
        groups = self._season_canon_groups()
        if not groups:
            return
        tgt = snapshot.get("tgt_lang") or "Turkish"
        report_lines = ["# Sezon Sonu Kanon Denetimi", ""]
        total_suspects = total_fixed = total_errors = 0
        season_report_updates = {}
        self._log(
            f"Sezon Sonu Kanon Denetimi: {len(groups)} sezon, "
            f"{sum(len(items) for items in groups.values())} bölüm inceleniyor...",
            "info",
        )
        for (_memory_root, slug, season, source_key), items in groups.items():
            report_lines.append(f"## {slug} S{season:02d}")
            for episode, source_path, output_path in items:
                failure_output_path = ""
                try:
                    expected_source_hash = _file_content_sha256(source_path)
                    output_baseline = _file_state_signature(output_path)
                    if not expected_source_hash or not output_baseline.get("exists"):
                        raise OSError("kaynak veya hedef dosya durumu okunamadı")
                    source_language = self._effective_file_source_language(
                        source_path, snapshot.get("src_lang") or "English")
                    source_blocks = list(parse_subtitle(source_path, source_language))
                    output_blocks, unmapped = _align_delivery_blocks_to_source(
                        source_blocks, parse_srt(output_path))
                    if unmapped:
                        raise ValueError(
                            f"{len(unmapped)} çıktı cue'su kaynak zamanına bağlanamadı")
                    src_map = _source_map_for_aligned_delivery(
                        source_blocks, output_blocks)
                    locked_terms = self._get_locked_terms_dict(source_path, tgt)
                    suspects = _season_canon_suspect_ids(
                        output_blocks, src_map, locked_terms)
                    sm_obj, _season, _episode = self._series_mem_for(source_path)
                    canon_hint = sm_obj.build_hint() if sm_obj else ""
                    if sm_obj and sm_obj.get_address_map():
                        suspects.update(_season_address_suspect_ids(output_blocks))
                    total_suspects += len(suspects)
                    before = {str(idx): text for idx, _ts, text in output_blocks}
                    if suspects:
                        report_dir = _resolve_report_dir(
                            snapshot.get("input_dir", ""),
                            snapshot.get("output_dir", ""))
                        artifact_stem = _season_canon_artifact_stem(
                            slug, season, episode, source_path, run_id)
                        semantic_status = {}
                        self._maybe_semantic_reconciliation(
                            output_path, src_map, output_blocks,
                            src_lang=self._effective_file_source_language(
                                source_path, snapshot.get("src_lang") or "English"),
                            changed_ids=suspects, source_path=source_path,
                            canon_hint=canon_hint, force=True,
                            target_coverage=0.0,
                            report_path=report_dir / (
                                f"{artifact_stem}.sezon-anlam-mutabakati.txt"),
                            raise_errors=True, status_out=semantic_status)
                        if semantic_status.get("status") != "completed":
                            raise RuntimeError(
                                "sezon anlam denetimi tamamlanamadı: "
                                f"{semantic_status.get('status', 'unknown')}")
                    if snapshot.get("term_normalize", True):
                        term_status = {}
                        before_term_normalize = list(output_blocks)
                        output_blocks, _ = _normalize_mixed_terms(
                            output_blocks, src_map,
                            self._helper_api_key("polish"),
                            self._helper_api_base_url("polish"),
                            self._helper_api_model("polish"),
                            log_fn=self._log, locked_terms=locked_terms,
                            cancel_context=self.__dict__.get(
                                "_helper_request_canceller"),
                            token_callback=App._token_callback_for_pass(
                                self, self._helper_api_model("polish"),
                                "Terim Normalizasyonu",
                                base_url=self._helper_api_base_url("polish"),
                                file_path=source_path),
                            status_out=term_status,
                            apply_changes=not bool(snapshot.get(
                                "quality_report_only", True)))
                        self._write_term_normalize_report(
                            output_path, term_status,
                            source_cues=source_blocks,
                            translation_blocks=before_term_normalize)
                        if term_status.get("status") not in {"completed", "skipped"}:
                            raise RuntimeError(
                                "sezon terim denetimi tamamlanamadı: "
                                f"{term_status.get('status', 'unknown')}")
                    output_blocks, _ = _finalize_translation_blocks(
                        output_blocks, _raw_src_map_from_cues(source_blocks),
                        source_cues=source_blocks, log_fn=self._log)
                    if not _existing_output_is_complete(
                            output_blocks, source_blocks):
                        raise RuntimeError(
                            "sezon denetimi sonrası cue yapısı eksik veya bozuk")
                    changes = [
                        (str(idx), before.get(str(idx), ""), text)
                        for idx, _ts, text in output_blocks
                        if before.get(str(idx), text) != text
                    ]
                    report_dir = _resolve_report_dir(
                        snapshot.get("input_dir", ""),
                        snapshot.get("output_dir", ""))
                    if changes:
                        guard_reason = _batch_write_guard_reason(
                            source_path, output_path, expected_source_hash,
                            output_baseline)
                        if guard_reason:
                            raise RuntimeError(
                                f"sezon denetimi sonucu yazılmadı ({guard_reason})")
                        report_dir.mkdir(parents=True, exist_ok=True)
                        artifact_stem = _season_canon_artifact_stem(
                            slug, season, episode, source_path, run_id)
                        backup = report_dir / f"{artifact_stem}.season-canon.bak.srt"
                        if not backup.exists():
                            atomic_write_bytes(backup, output_path.read_bytes())
                        delivery = _prepare_upload_ready_blocks(
                            output_blocks, tgt, self._log,
                            source_cues=source_blocks)
                        write_srt(output_path, delivery, tgt)
                    delivery_audit = _subtitle_delivery_audit(
                        source_path, output_path, tgt, source_language)
                    if _delivery_audit_has_hard_error(delivery_audit):
                        quarantined = self._maybe_quarantine_incomplete_final(output_path)
                        failure_output_path = str(quarantined or output_path)
                        raise RuntimeError(
                            "sezon denetimi yazımı sonrası teslim denetimi "
                            f"başarısız ({quarantined or output_path})")
                    report_dir.mkdir(parents=True, exist_ok=True)
                    if not _write_output_source_fingerprint(
                            report_dir, output_path, expected_source_hash):
                        quarantined = self._maybe_quarantine_incomplete_final(output_path)
                        failure_output_path = str(quarantined or output_path)
                        raise RuntimeError(
                            "sezon denetimi kaynak-çıktı parmak izi yazılamadı")
                    season_report_updates[str(source_path)] = {
                        "output_path": str(output_path),
                        "delivery_audit": delivery_audit,
                        "season_canon_changes": len(changes),
                        "season_canon_status": {
                            "status": "completed", "changed": len(changes),
                        },
                    }
                    self.__dict__.setdefault(
                        "_season_canon_completed_sources", set()).add(
                            str(source_path))
                    self._record_file_status(source_path, "Sezon Kanonu", "done")
                    total_fixed += len(changes)
                    report_lines.append(
                        f"- E{episode:02d}: şüpheli {len(suspects)}, "
                        f"düzeltme {len(changes)}")
                    for idx, old, new in changes:
                        report_lines.extend([
                            f"  [{idx}] önce: {old}",
                            f"       sonra: {new}",
                        ])
                except RequestCancelled:
                    raise
                except Exception as exc:
                    total_errors += 1
                    season_report_updates[str(source_path)] = {
                        "output_path": failure_output_path or str(output_path),
                        "run_status": "error",
                        "season_canon_status": {
                            "status": "failed", "error": str(exc),
                        },
                    }
                    report_lines.append(f"- E{episode:02d}: hata — {exc}")
                    recorder = getattr(self, "_record_file_status", None)
                    if callable(recorder):
                        recorder(
                            source_path, "Sezon kanon denetimi hatası", "error")
                    with self._run_record_lock:
                        active = getattr(self, "_active_run_record", None)
                        if active is not None:
                            active.setdefault("season_canon_errors", []).append({
                                "source_path": str(source_path),
                                "error": str(exc),
                            })
                    self._log(
                        f"Sezon kanon denetimi [{Path(source_path).name}]: {exc}",
                        "err",
                    )
            report_lines.append("")
        report_dir = _resolve_report_dir(
            snapshot.get("input_dir", ""), snapshot.get("output_dir", ""))
        report_dir.mkdir(parents=True, exist_ok=True)
        safe_run = re.sub(
            r"[^A-Za-z0-9._-]+", "-", run_id).strip("-") or "run"
        report_path = report_dir / f"sezon_kanon_denetimi_{safe_run}.txt"
        atomic_write_text(report_path, "\n".join(report_lines), encoding="utf-8")
        with self._run_record_lock:
            record = getattr(self, "_active_run_record", None)
            if record is not None:
                record["fixes_applied"] = int(record.get("fixes_applied", 0)) + total_fixed
                record.setdefault("reports", []).append(str(report_path))
        summary = (
            f"Sezon Sonu Kanon Denetimi tamamlandı: {total_suspects} şüpheli cue, "
            f"{total_fixed} düzeltme")
        if total_errors:
            summary += f", {total_errors} bölüm denetlenemedi"
        self._log(f"{summary} — {report_path}", "warn" if total_errors else "ok")
        refresher = getattr(self, "_refresh_quality_report_after_season_canon", None)
        if callable(refresher):
            refresher(season_report_updates)

    def _start_season_canon_finalizer(self):
        self._season_canon_finalizing = True
        self._season_canon_completed_sources = set()
        self._set_phase(
            "Sezon Kanonu", "Sezon genelinde terim ve hitap denetleniyor")
        self._set_status(
            "Sezon Sonu Kanon Denetimi çalışıyor — uygulamayı kapatmayın")

        def _work():
            expected_sources = set()
            try:
                expected_sources = {
                    str(source_path)
                    for items in self._season_canon_groups().values()
                    for _episode, source_path, _output_path in items
                }
                self._run_season_canon_audit()
            except RequestCancelled:
                pass
            except Exception as exc:
                if not expected_sources:
                    with self._run_record_lock:
                        record = getattr(self, "_active_run_record", None) or {}
                        expected_sources = {
                            str(source_path)
                            for source_path, item in (record.get("files") or {}).items()
                            if item.get("status") == "done" and item.get("output_path")
                        }
                completed_sources = set(getattr(
                    self, "_season_canon_completed_sources", set()) or set())
                pending_sources = expected_sources - completed_sources
                recorder = getattr(self, "_record_file_status", None)
                if callable(recorder):
                    for source_path in sorted(pending_sources):
                        recorder(
                            source_path, "Sezon kanon denetimi tamamlanamadı", "error")
                self._log(
                    f"Sezon Sonu Kanon Denetimi hatası: {exc}"
                    + (f"; {len(pending_sources)} bölüm hazır sayılmadı"
                       if pending_sources else ""),
                    "err" if pending_sources else "warn")
            finally:
                self._season_canon_done = True
                self._season_canon_finalizing = False
                _post_ui(self, self._set_running, False)

        self._start_worker(_work)

    def _update_readiness_card(self):
        if threading.current_thread() is not threading.main_thread():
            _post_ui(self, App._update_readiness_card, self)
            return
        state_label = self.__dict__.get("_readiness_state_lbl")
        detail_label = self.__dict__.get("_readiness_detail_lbl")
        card = self.__dict__.get("_readiness_card")
        if state_label is None or detail_label is None or card is None:
            return
        running = bool(self.__dict__.get("_is_running", False))
        if running and self.__dict__.get("_job_rows"):
            file_count = len(self._job_rows)
        else:
            files = (self.__dict__.get("_selected_files") or
                     self.__dict__.get("_file_list_files") or ())
            file_count = len(files)
        try:
            target = self.tgt_var.get()
        except Exception:
            target = ""
        try:
            profile = self.workflow_profile_var.get()
        except Exception:
            profile = "Özel"
        state, detail, tone = _readiness_view(
            file_count, target, profile, running)
        color = {"waiting": FG2, "ready": GREEN, "active": ACCENT}[tone]
        state_label.configure(
            text=state, text_color=color,
            fg_color=_mix_hex_color(CARD, color, 0.13))
        detail_label.configure(
            text=detail, text_color=FG if file_count else FG2)
        card.configure(
            border_color=_mix_hex_color(BORDER_SOFT, color, 0.5))

    def _set_running(self, running):
        # Worker thread'lerden çağrılabilir; Tk widget .configure()/after_cancel YALNIZCA
        # ana thread'de güvenli (Tcl thread-safe değil). Ana thread'de değilsek marshal et.
        if threading.current_thread() is not threading.main_thread():
            _post_ui(self, self._set_running, running)
            return
        if not running and App._should_start_season_canon(self):
            App._start_season_canon_finalizer(self)
            return
        if not running:
            _release_translation_run_owner()
        s = "disabled" if (running or getattr(self, "_folder_scan_busy", False)) else "normal"
        self.start_btn.configure(state=s)
        test_btn = getattr(self, "test_btn", None)
        if test_btn is not None:
            test_btn.configure(state=s)
        self.resume_btn.configure(state=s)
        self.jsonl_btn.configure(state=s)
        self.postprocess_btn.configure(state=s)
        self.stop_btn.configure(state="normal" if running else "disabled")
        self.pause_btn.configure(state="normal" if running else "disabled")
        adv_btn = getattr(self, "adv_settings_btn", None)
        if adv_btn is not None:
            adv_btn.configure(state=s)
        self._is_running = running
        App._refresh_progress_window_title(self)
        App._update_readiness_card(self)
        if running:
            self._motion_progress_value = 0.0
            self._motion_progress_target = 0.0
            try:
                self.progress.set(0.0)
            except Exception:
                pass
            App._ensure_motion_animation(self)
        else:
            App._cancel_motion_animation(self, snap=True)
        if running and not getattr(self, "_run_state_initialized", False):
            self._auto_retry_blocked_by_permanent_provider = False
            self._season_canon_done = False
            self._season_canon_finalizing = False
            self._run_state_initialized = True
            self._helper_request_canceller = RunRequestCanceller()
            self._run_series_memory = {}
            self._run_precontext_data = {}
            self._active_snapshot = self._take_run_snapshot()
            resume_settings = getattr(self, "_resume_snapshot_override", None)
            if isinstance(resume_settings, dict):
                scalar_keys = (
                    "input_dir", "output_dir", "src_lang", "tgt_lang", "mode",
                    "hybrid_mode", "analysis_depth", "style", "content_type",
                    "profanity", "same_folder", "auto_glossary", "term_normalize",
                    "repair_missing",
                    "critic", "polish", "native", "qc", "condense", "backtrans",
                    "semantic_reconcile", "review", "twowave", "clean_sdh",
                    "linebreak", "ai_segment", "merge_cues", "chain_ctx",
                    "precontext", "series_memory", "season_canon", "media_mode",
                    "main_model_name",
                    "main_api_base_url", "backup_raw", "ext_project_path",
                    "notify_desktop",
                    "crash_resume", "resume_origin_run_id", "auto_retry_repair_only",
                    "chunk_size", "context_lines", "lookahead_lines",
                    "max_workers", "temperature", "max_retry",
                    "scene_gap_seconds",
                )
                for key in scalar_keys:
                    if key in resume_settings:
                        self._active_snapshot[key] = resume_settings[key]
                for key in ("helper_models", "helper_urls", "file_source_languages",
                            "file_glossaries", "file_analysis_depths"):
                    if key in resume_settings:
                        self._active_snapshot[key] = dict(resume_settings.get(key) or {})
                if "global_glossary_path" in resume_settings:
                    self._active_snapshot["global_glossary_path"] = str(
                        resume_settings.get("global_glossary_path") or "")
                saved_schemas = dict(resume_settings.get("file_schema_names") or {})
                if saved_schemas:
                    self._active_snapshot["file_schemas"] = {
                        path: self._schema_by_name(name)
                        for path, name in saved_schemas.items()
                    }
                self._resume_snapshot_override = None
            App._freeze_run_variable_reads(self)
            self._start_elapsed_timer()
            if (getattr(self, "_active_snapshot", {}) or {}).get("prevent_sleep"):
                self._sleep_prevention_active = _set_windows_sleep_prevention(True)
                if self._sleep_prevention_active:
                    self._log("Çeviri boyunca Windows uyku modu engellendi.", "info")
        elif not running:
            finalizer = getattr(self, "_finalize_run_record", None)
            finalized_record = None
            if callable(finalizer):
                finalized_record = finalizer()
            retry_scheduler = getattr(self, "_schedule_failed_file_retry", None)
            retry_scheduled = (
                retry_scheduler(finalized_record)
                if callable(retry_scheduler) else False
            )
            scheduler = getattr(self, "_schedule_shutdown_after_success", None)
            if not retry_scheduled and callable(scheduler):
                scheduler(finalized_record)
            if getattr(self, "_sleep_prevention_active", False):
                _set_windows_sleep_prevention(False)
                self._sleep_prevention_active = False
            try:
                from provider_retry import configure_provider_wait_hooks
                configure_provider_wait_hooks()
            except Exception:
                pass
            self._run_state_initialized = False
            App._unfreeze_run_variable_reads(self)
            self._active_snapshot = None
            self._helper_request_canceller = None
            self._run_series_memory = {}
            self._run_precontext_data = {}
            self._stop_elapsed_timer()
            if self._job_rows:
                self._set_phase("Hazır", "")

    # ── İş panosu yardımcıları ────────────────────────────────────────────────
    def _show_progress_board(self, files: list):
        """İşlem başlarken tüm dosyaları 'Bekliyor' olarak gösteren panoyu açar."""
        def _build():
            for w in self._job_rows_frame.winfo_children():
                w.destroy()
            self._job_rows.clear()
            self._removed_queue_files.clear()

            for fp in files:
                fname = Path(fp).name
                if len(fname) > 46:
                    fname = "…" + fname[-43:]

                row_fr = ctk.CTkFrame(
                    self._job_rows_frame, fg_color=CARD, corner_radius=6,
                    border_width=1, border_color=BORDER_SOFT)
                row_fr.pack(fill="x", padx=2, pady=(0, 3))
                row_fr.grid_columnconfigure(1, weight=1)

                dot = ctk.CTkLabel(row_fr, text="○", width=22,
                                   font=ctk.CTkFont("Segoe UI", 13, "bold"),
                                   text_color=FG2)
                dot.grid(row=0, column=0, padx=(8, 2), pady=7)

                name_lbl = ctk.CTkLabel(row_fr, text=fname, anchor="w",
                                        font=ctk.CTkFont("Segoe UI", 11),
                                        text_color=FG)
                name_lbl.grid(row=0, column=1, sticky="ew", padx=(4, 8))

                phase_lbl = ctk.CTkLabel(
                    row_fr, text="Bekliyor", width=148, height=24,
                    anchor="center", corner_radius=6,
                    fg_color=_mix_hex_color(CARD, FG2, 0.08),
                    font=ctk.CTkFont("Segoe UI", 10, "bold"),
                    text_color=FG2)
                phase_lbl.grid(row=0, column=2, padx=4)

                pb = ctk.CTkProgressBar(row_fr, height=5, width=108,
                                        progress_color=FG2, fg_color=BORDER)
                pb.grid(row=0, column=3, padx=(2, 12), pady=9)
                pb.set(0)

                pct_lbl = ctk.CTkLabel(
                    row_fr, text="0%", width=38, anchor="e",
                    font=ctk.CTkFont("Consolas", 9, "bold"),
                    text_color=FG2)
                pct_lbl.grid(row=0, column=4, padx=(0, 6))

                remove_btn = ctk.CTkButton(
                    row_fr, text="×", width=26, height=26,
                    font=ctk.CTkFont("Segoe UI", 15, "bold"),
                    fg_color="transparent", hover_color=BORDER, text_color=WARN,
                    command=lambda p=fp: self._remove_queued_file(p))
                remove_btn.grid(row=0, column=5, padx=(0, 6), pady=4)

                self._job_rows[fp] = {"dot": dot, "phase": phase_lbl,
                                      "pb": pb, "frame": row_fr,
                                      "pct": pct_lbl,
                                      "remove": remove_btn, "state": "waiting",
                                      "value": 0.0, "target": 0.0,
                                      "color": FG2}

            n = len(files)
            self._jb_title.configure(text=f"DOSYALAR — 0 / {n}")
            self._jb_summary.configure(text=_job_board_summary_text(self._job_rows))
            self._file_list_outer.grid_remove()
            self._job_board.grid()

        if threading.current_thread() is threading.main_thread():
            _build()
        else:
            ready = threading.Event()
            def _build_ready():
                try:
                    _build()
                finally:
                    ready.set()
            try:
                _post_ui(self, _build_ready)
                ready.wait(timeout=5)
            except Exception:
                pass

    def _norm_path(self, filepath: str) -> str:
        import os
        return os.path.normcase(os.path.abspath(str(filepath)))

    def _is_queued_file_removed(self, filepath: str) -> bool:
        return self._norm_path(filepath) in self._removed_queue_files

    def _remove_queued_file(self, filepath: str):
        """Henüz başlamamış dosyayı iş panosundaki kuyruktan çıkar."""
        row = self._job_rows.get(filepath)
        if not row or row.get("state") != "waiting":
            return
        norm_fp = self._norm_path(filepath)
        self._removed_queue_files.add(norm_fp)
        self._selected_files = [p for p in self._selected_files if self._norm_path(p) != norm_fp]
        self._file_schema_vars.pop(filepath, None)
        getattr(self, "_file_language_vars", {}).pop(filepath, None)
        getattr(self, "_file_analysis_depth_vars", {}).pop(filepath, None)
        try:
            row["frame"].destroy()
        except Exception:
            pass
        self._job_rows.pop(filepath, None)
        self._log(f"Kuyruktan çıkarıldı: {Path(filepath).name}", "info")
        self._refresh_job_board_title()
        self._set_stat(self.stat_files_var, str(len(self._job_rows)))
        App._update_readiness_card(self)

    def _refresh_job_board_title(self):
        counts = _job_board_counts(self._job_rows)
        done_n = counts["done"] + counts["skip"] + counts["error"]
        self._jb_title.configure(text=f"DOSYALAR — {done_n} / {len(self._job_rows)}")
        summary = self.__dict__.get("_jb_summary")
        if summary is not None:
            summary.configure(text=_job_board_summary_text(self._job_rows))

    def _update_file_progress(self, filepath: str, phase: str,
                               pct: float, status: str = "running"):
        """Tek dosya satırını günceller. Thread-safe.
        status: 'running' | 'done' | 'error' | 'skip'"""
        recorder = getattr(self, "_record_file_status", None)
        if callable(recorder):
            recorder(filepath, phase, status)
        row = self._job_rows.get(filepath)
        if not row:
            return

        if status == "running":
            row["state"] = "running"

        if status == "done":
            color, dot_text = GREEN,  "✓"
        elif status == "error":
            color, dot_text = RED,    "✗"
        elif status == "skip":
            color, dot_text = FG2,    "—"
        else:
            key   = phase.lower().split()[0]
            color = self._PHASE_COLORS.get(key, ACCENT)
            dot_text = "●"

        def _upd():
            try:
                value = max(0.0, min(1.0, pct / 100))
                previous_path = self.__dict__.get("_motion_active_filepath")
                if previous_path != filepath:
                    previous = self._job_rows.get(previous_path)
                    if previous and previous.get("state") == "running":
                        previous["value"] = previous.get("target", previous.get("value", 0.0))
                        previous["pb"].set(previous["value"])
                        previous["dot"].configure(
                            text_color=previous.get("color", ACCENT))
                        previous["frame"].configure(
                            border_width=1, border_color=BORDER_SOFT)
                row["dot"].configure(text=dot_text, text_color=color)
                row["phase"].configure(
                    text=phase, text_color=color,
                    fg_color=_mix_hex_color(CARD, color, 0.13))
                row["pb"].configure(progress_color=color)
                pct_label = row.get("pct")
                if pct_label is not None:
                    pct_label.configure(
                        text=("—" if status == "skip"
                              else f"{int(round(value * 100))}%"),
                        text_color=color)
                row["color"] = color
                row["target"] = value
                if status == "running":
                    row["state"] = "running"
                    self._motion_active_filepath = filepath
                    row["remove"].configure(state="disabled")
                    row["frame"].configure(
                        fg_color=_mix_hex_color(CARD, color, 0.06),
                        border_width=1,
                        border_color=_mix_hex_color(BORDER_SOFT, color, 0.55))
                    if App._motion_enabled(self) and self.__dict__.get("_is_running", False):
                        App._ensure_motion_animation(self)
                    else:
                        row["value"] = value
                        row["pb"].set(value)
                else:
                    row["state"] = status
                    row["frame"].configure(fg_color=CARD)
                    row["value"] = value
                    row["pb"].set(value)
                    if status == "done" and App._motion_enabled(self):
                        row["frame"].configure(border_width=1, border_color=GREEN)
                        def _bright_flash(r=row):
                            try:
                                r["frame"].configure(
                                    border_color=_mix_hex_color(GREEN, FG, 0.42))
                            except Exception:
                                pass
                        def _clear_flash(r=row):
                            try:
                                r["frame"].configure(
                                    border_width=1, border_color=BORDER_SOFT)
                            except Exception:
                                pass
                        self.after(150, _bright_flash)
                        self.after(680, _clear_flash)
                self._refresh_job_board_title()
            except Exception:
                pass

        _post_ui(self, _upd)

    def _maybe_condense(self, blocks, mm_k, mm_u, mm_m, tgt, src_map=None,
                        locked_terms=None, status_out: dict | None = None,
                        file_path: str = ""):
        """condense_var açıksa CPS sınırını aşan satırları kısaltır. Aksi halde blocks aynen döner."""
        if status_out is not None:
            status_out.clear()
            status_out.update({
                "status": "not_started", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
            })
        if not getattr(self, "condense_var", None) or not self.condense_var.get():
            if status_out is not None:
                status_out["status"] = "skipped"
            return blocks
        if not blocks or not mm_k:
            if status_out is not None:
                status_out.update({
                    "status": "skipped" if not blocks else "failed",
                    "error": "missing_api_key" if blocks else "",
                })
            return blocks
        import hybrid_translate as ht
        try:
            cancel_context = self.__dict__.get("_helper_request_canceller")
            self._set_status("Okuma hızı kısaltma...")
            new_blocks, _n = ht.condense_fast_lines(
                tr_blocks=blocks,
                helper_api_key=mm_k, helper_url=mm_u, helper_model=mm_m,
                tgt_lang=tgt, cps_limit=21.0,
                log_fn=self._log,
                token_callback=_app_token_callback(
                    self, mm_m, "Okuma Hızı Kısaltma",
                    base_url=mm_u, file_path=file_path),
                src_map=src_map,
                locked_terms=locked_terms,
                cancel_context=cancel_context,
                status_out=status_out)
            if self.__dict__.get("_stop_flag", False) or (
                    cancel_context is not None and cancel_context.is_cancelled()):
                if status_out is not None:
                    status_out.update({"status": "cancelled", "changed": 0})
                return blocks
            return new_blocks
        except RequestCancelled:
            if status_out is not None:
                status_out["status"] = "cancelled"
            return blocks
        except Exception as e:
            if status_out is not None:
                status_out.update({"status": "failed", "error": str(e)})
            self._log_exc("Kısaltma pass hatası", e)
            return blocks

    def _maybe_merge_cues(self, blocks, file_path: str = ""):
        """ai_segment_var açıksa AI destekli akıllı segmentasyon, değilse merge_cues_var
        açıksa hızlı parçalı birleştirme uygular. ÇIKTI biçimlendirmesidir — TM/scan
        PRE-merge bloklarla çalıştığı için bu yalnızca write_srt'e giden son adımda uygulanır."""
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            ai_on = bool(self._active_snapshot.get("ai_segment"))
            fast_on = bool(self._active_snapshot.get("merge_cues"))
        else:
            ai_on   = bool(getattr(self, "ai_segment_var", None) and self.ai_segment_var.get())
            fast_on = bool(getattr(self, "merge_cues_var", None) and self.merge_cues_var.get())
        if not (ai_on or fast_on):
            return blocks
        try:
            if ai_on:
                key = self._helper_api_key("analysis")
                if key:
                    return ai_resegment_cues(
                        blocks, key, self._helper_api_base_url("analysis"), self._helper_api_model("analysis"),
                        log_fn=self._log, max_chars=self._merge_max_chars,
                        max_gap_ms=self._merge_max_gap_ms,
                        token_callback=_app_token_callback(
                            self, self._helper_api_model("analysis"),
                            "AI Segmentasyon",
                            base_url=self._helper_api_base_url("analysis"),
                            file_path=file_path),
                        cancel_context=self.__dict__.get(
                            "_helper_request_canceller"))
                self._log("AI segmentasyon: API anahtarı yok, hızlı birleştirmeye düşülüyor", "warn")
            source_cues = self._cached_blocks_for(file_path) if file_path else None
            out = merge_fragmented_cues(blocks,
                                        max_chars=self._merge_max_chars,
                                        max_gap_ms=self._merge_max_gap_ms,
                                        source_cues=source_cues)
            if len(out) < len(blocks):
                self._log(f"Parçalı cue birleştirme: {len(blocks)} → {len(out)} blok", "ok")
            return out
        except RequestCancelled:
            raise
        except Exception as e:
            self._log_exc("Cue birleştirme hatası", e)
            return blocks

    def _get_schema(self) -> dict:
        name = self.content_type_var.get()
        for schema in CONTENT_SCHEMAS.values():
            if schema["name"] == name:
                return schema
        return CONTENT_SCHEMAS["auto"]

    def _record_api_usage(self, added: int, cached: int, cost_added: float,
                           unknown_added: int = 0, model: str = "",
                           prompt_tokens: int = 0,
                           completion_tokens: int = 0,
                           pass_name: str = "", file_path: str = "",
                           usage_available: bool = True):
        lock = getattr(self, "_run_record_lock", None)
        if lock is None:
            return
        with lock:
            record = getattr(self, "_active_run_record", None)
            if not record:
                return
            active = [
                (path, item) for path, item in (record.get("files") or {}).items()
                if item.get("active_stage")
            ]
            labels = {str(item.get("active_stage")) for _path, item in active}
            stage = (str(pass_name).strip() or
                     (next(iter(labels)) if len(labels) == 1 else "Diğer API İşlemleri"))

            def add_usage(target):
                target["total_tokens"] = int(target.get("total_tokens", 0) or 0) + int(added or 0)
                target["prompt_tokens"] = int(target.get("prompt_tokens", 0) or 0) + int(prompt_tokens or 0)
                target["completion_tokens"] = int(target.get("completion_tokens", 0) or 0) + int(completion_tokens or 0)
                target["cached_tokens"] = int(target.get("cached_tokens", 0) or 0) + int(cached or 0)
                target["unknown_cost_tokens"] = int(target.get("unknown_cost_tokens", 0) or 0) + int(unknown_added or 0)
                target["cost_usd"] = float(target.get("cost_usd", 0.0) or 0.0) + float(cost_added or 0.0)
                if not usage_available:
                    target["usage_missing_responses"] = int(
                        target.get("usage_missing_responses", 0) or 0) + 1
                models = target.setdefault("models", [])
                if model and model not in models:
                    models.append(model)

            api = record.setdefault("api", {})
            add_usage(api.setdefault("usage_by_pass", {}).setdefault(stage, {}))
            explicit_item = (record.get("files") or {}).get(str(file_path)) if file_path else None
            if explicit_item is not None:
                add_usage(explicit_item.setdefault("api_usage", {}).setdefault(stage, {}))
            elif len(active) == 1:
                item = active[0][1]
                add_usage(item.setdefault("api_usage", {}).setdefault(stage, {}))

    def _update_tokens(self, added: int, price=_DEFAULT_TOKEN_PRICE, cached: int = 0,
                       prompt_tokens: int = 0, completion_tokens: int = 0,
                       model: str = "", pass_name: str = "", base_url: str | None = None,
                       file_path: str = "", usage_available: bool = True):
        """Token sayacını + tahmini maliyeti günceller. Maliyet AYRI birikir (kümülatif
        token × tek fiyat DEĞİL) — böylece her kaynak kendi fiyatıyla eklenir. price
        verilmezse ana model fiyatı kullanılır; Batch API çağrıları %50 indirimli geçer.
        cached verilirse OpenAI Prompt Caching indirimi (%50) hesaba katılır."""
        if price is _DEFAULT_TOKEN_PRICE:
            main_url = base_url
            if main_url is None:
                resolver = getattr(self, "_main_api_base_url", None)
                main_url = resolver() if callable(resolver) else None
            price = _verified_token_price(
                self._main_model_name(), main_url, default_is_official=True)
        with self._token_lock:
            self._token_total += added
            self._token_cached = getattr(self, "_token_cached", 0) + cached
            unknown_added = added if price is None else 0
            self._unknown_cost_tokens = (
                getattr(self, "_unknown_cost_tokens", 0) + unknown_added)
            uncached = max(0, added - cached)
            cost_added = 0.0 if price is None else (
                uncached * price + cached * price * 0.5) / 1_000_000
            self._cost_total = getattr(self, "_cost_total", 0.0) + cost_added
            
            total = self._token_total
            cached_total = self._token_cached
            cost  = self._cost_total
            unknown_total = self._unknown_cost_tokens
        App._record_api_usage(
            self, added, cached, cost_added, unknown_added, model,
            prompt_tokens, completion_tokens, pass_name, file_path,
            usage_available)
        def _upd(t=total, c=cost, ct=cached_total, ut=unknown_total):
            try:
                self.stat_tokens_var.set(f"{t:,}")
                if ut > 0:
                    self.stat_tokens_sub_var.set(
                        f"~${c:.4f} + {ut:,} token maliyeti sağlayıcı panelinden doğrulanmalı")
                elif ct > 0:
                    self.stat_tokens_sub_var.set(f"~${c:.4f} ({ct:,} önb.)")
                else:
                    self.stat_tokens_sub_var.set(f"Token  ~${c:.4f}")
                pts = self._token_sparkline_points
                if not pts or pts[-1] != t:
                    pts.append(t)
                    if len(pts) > 20:
                        del pts[:-20]
                    self._update_token_sparkline()
            except Exception:
                pass
        _post_ui(self, _upd)

    def _token_callback_for_model(self, model: str, discount: float = 1.0,
                                   pass_name: str = "", base_url: str | None = None,
                                   file_path: str = ""):
        if base_url is None:
            snapshot = self.__dict__.get("_active_snapshot", {}) or {}
            helper_models = snapshot.get("helper_models") or {}
            helper_urls = snapshot.get("helper_urls") or {}
            candidates = {
                str(helper_urls.get(role) or "").strip()
                for role, configured in helper_models.items()
                if str(configured or "").strip() == str(model or "").strip()
            }
            candidates.discard("")
            if len(candidates) == 1:
                base_url = next(iter(candidates))
            elif not candidates:
                main_model = str(snapshot.get("main_model_name") or "").strip()
                if main_model and main_model == str(model or "").strip():
                    base_url = snapshot.get("main_api_base_url")
        price = _verified_token_price(model, base_url)
        if price is not None:
            price *= discount

        def _callback(added, cached=0, prompt_tokens=0, completion_tokens=0,
                      usage_available=True):
            updater = getattr(self, "_update_tokens", None)
            if not callable(updater):
                updater = lambda *args, **kwargs: App._update_tokens(
                    self, *args, **kwargs)
            try:
                updater(
                    added, price=price, cached=cached,
                    prompt_tokens=prompt_tokens,
                    completion_tokens=completion_tokens, model=model,
                    pass_name=pass_name, base_url=base_url,
                    file_path=file_path, usage_available=usage_available)
            except TypeError:
                updater(added, price=price, cached=cached)
        def _report_missing_usage():
            _callback(0, usage_available=False)
        _callback.report_missing_usage = _report_missing_usage
        return _callback

    def _token_callback_for_pass(self, model: str, pass_name: str,
                                 base_url: str | None = None,
                                 file_path: str = ""):
        try:
            return App._token_callback_for_model(
                self, model, pass_name=pass_name, base_url=base_url,
                file_path=file_path)
        except TypeError:
            return App._token_callback_for_model(self, model)

    def _update_batch_tokens(self, added: int, cached: int = 0,
                              prompt_tokens: int = 0,
                              completion_tokens: int = 0,
                              file_path: str = ""):
        """Batch API token/maliyeti — Batch API %50 daha ucuz (gösterilen maliyet de öyle)."""
        price = _model_token_price(self._main_model_name())
        self._update_tokens(
            added, price=None if price is None else price * 0.5, cached=cached,
            prompt_tokens=prompt_tokens, completion_tokens=completion_tokens,
            model=self._main_model_name(), pass_name="Ana Çeviri",
            file_path=file_path)

    def _store_tm_pairs(self, blocks, src_clean_map, model, tgt, schema_name: str = "",
                        source_language: str = "", context_fingerprint: str = ""):
        """Kaynak↔çeviri çiftlerini TM'ye yazar; eksik işaretler ve kaynak==çeviri
        (kimlik) çiftleri hariç tutulur. DÖRT akışın ortak TM-kayıt mantığı tek yerde — birebir aynıydı,
        burada toplandı ki bir daha 'şu akışta var bu akışta yok' sürüklenmesi olmasın.
        (tr_text etiket geri yüklemeden geçmiş olmalı — TM'e temiz hâliyle yazılır.)"""
        try:
            pairs = [
                (src_clean_map[str(idx)], _clean_src(tr_text))
                for idx, ts, tr_text in blocks
                if str(idx) in src_clean_map
                and not str(tr_text).startswith("[HATA")
                and str(tr_text).strip() != "[ÇEVİRİ EKSİK]"
                and _clean_src(tr_text).strip().lower() != src_clean_map[str(idx)].strip().lower()
            ]
            if pairs:
                if (threading.current_thread() is not threading.main_thread()
                        and getattr(self, "_active_snapshot", None)):
                    profanity = self._active_snapshot.get("profanity", "")
                else:
                    profanity = self.profanity_var.get() if hasattr(self, "profanity_var") else ""
                if not self._tm.store_batch(
                        pairs, model, tgt_lang=tgt, profanity=profanity,
                        schema_name=schema_name, source_language=source_language,
                        context_fingerprint=context_fingerprint):
                    self._log("TM toplu kayıt başarısız; çeviri çıktısı korundu", "warn")
            self._update_tm_stat()
        except Exception as _tm_e:
            self._log(f"TM kayıt hatası: {_tm_e}", "warn")

    def _update_tm_stat(self):
        """TM vuruş sayacını stats panelinde günceller."""
        hits = self._tm.hit_count_session()
        def _upd():
            try:
                self.stat_tm_var.set(str(hits))
            except Exception:
                pass
        _post_ui(self, _upd)

    def _json_repair_pass(self, client, raw_map: dict, requests_list: list,
                          file_map: dict | None = None, file_path: str = ""):
        """Before full retry, try to repair malformed JSON responses.
        For chunks where JSON extraction failed, ask the model to fix its own output.
        This avoids a full re-translation (cheaper) and recovers most parse failures.
        """
        repaired = 0
        for req in requests_list:
            if getattr(self, "_stop_flag", False):
                break
            cid = req["custom_id"]
            req_file_path = file_path
            if not req_file_path:
                try:
                    req_file_path = str((file_map or {})[cid][0][2])
                except (KeyError, IndexError, TypeError):
                    req_file_path = ""
            raw = raw_map.get(cid)
            if raw is None:
                continue  # no response at all — handled by retry_hata
            from response_integrity import parse_translation_payload
            expected_ids = _expected_ids_from_req(req)
            parsed_before = parse_translation_payload(raw, expected_ids)
            missing_ids = set(parsed_before.missing_ids)
            if not missing_ids:
                continue
            if parsed_before.parse_mode in {"array", "envelope"}:
                continue
            if len(raw) > 12000:
                self._log(
                    f"  ↺ {cid}: bozuk yanıt JSON onarımı için çok uzun; "
                    "tam yeniden çeviriye bırakıldı", "warn")
                continue
            # Build repair prompt
            try:
                original_messages = req.get("body", {}).get("messages") or []
                original_payload = json.loads(original_messages[1]["content"])
            except Exception:
                original_payload = {}
            missing_items = [
                {"i": item.get("i"), "t": item.get("t", "")}
                for item in original_payload.get("tr", [])
                if isinstance(item, dict) and str(item.get("i")) in missing_ids
            ]
            repair_payload = {
                "task": "Recover only the missing items from this malformed JSON response. "
                        "Return ONLY a JSON array for the requested IDs. "
                        "No commentary, no markdown fences, no extra text.",
                "rules": [
                    "Output must be a JSON array: [{\"i\": N, \"t\": \"...\"}]",
                    "Preserve all translation content — do not change meanings",
                    "Do not return any ID outside missing_ids",
                    "Do not wrap in ```json``` or any other delimiter",
                ],
                "missing_ids": sorted(missing_ids),
                "missing_source_items": missing_items,
                "broken_response": raw,
            }
            try:
                resp = _safe_chat_create(
                    client,
                    cancel_context=self.__dict__.get("_helper_request_canceller"),
                    _checkpoint_label="translation_json_repair",
                    model=req.get("body", {}).get("model") or self._main_model_name(),
                    messages=[
                        {"role": "system", "content": "You are a JSON repair assistant. Return only valid JSON."},
                        {"role": "user",   "content": json.dumps(repair_payload, ensure_ascii=False)},
                    ],
                    max_completion_tokens=2048,
                    temperature=0.0,
                )
                fixed = (resp.choices[0].message.content or "").strip()
                _report_response_usage(
                    _app_token_callback(
                        self, self._main_model_name(), "JSON Onarımı",
                        base_url=self._main_api_base_url(),
                        file_path=req_file_path),
                    resp, log_fn=self._log, pass_name="JSON Onarımı")
                parsed_repair = parse_translation_payload(fixed, missing_ids)
                if (parsed_repair.fatal_reason
                        or parsed_repair.duplicate_ids
                        or parsed_repair.unexpected_ids
                        or parsed_repair.invalid_text_ids
                        or not parsed_repair.translations):
                    self._log(f"  ↺ {cid}: JSON onarımı id doğrulamasından geçemedi, "
                              f"tam yeniden çeviriye bırakıldı", "warn")
                    continue
                merged = dict(parsed_before.translations)
                merged.update(parsed_repair.translations)
                if not parsed_before.translations and not parsed_repair.missing_ids:
                    raw_map[cid] = fixed
                else:
                    raw_map[cid] = json.dumps(
                        [{"i": cue_id, "t": merged[cue_id]}
                         for cue_id in sorted(
                             expected_ids,
                             key=lambda value: (0, int(value))
                             if str(value).isdigit() else (1, str(value)))
                         if cue_id in merged],
                        ensure_ascii=False)
                repaired += 1
                self._log(
                    f"  🔧 {cid}: JSON onarımı birleştirildi "
                    f"({len(parsed_repair.translations)} yeni, "
                    f"{len(merged)}/{len(expected_ids)} toplam)", "ok")
            except RequestCancelled:
                raise
            except Exception as repair_error:
                # Recovery remains non-fatal, but it must be diagnosable.
                self._log(
                    f"  ↳ {cid}: JSON onarımı çalışmadı ({repair_error}); "
                    "yalnız eksik cue kurtarması denenecek",
                    "warn",
                )
        if repaired:
            self._log(f"JSON onarımı: {repaired} chunk kurtarıldı", "ok")

    def _retry_hata(self, client, raw_map: dict, requests_list: list,
                    max_rounds: int = 2, file_map: dict | None = None,
                    file_path: str = ""):
        """Retry chunks that produced [HATA] or failed to parse.
        First attempts JSON repair (cheap), then full re-translation.
        Up to `max_rounds` passes with exponential backoff on 429/5xx.
        """
        import random
        import hybrid_translate as ht
        if getattr(self, "_stop_flag", False):
            return {req.get("custom_id", "") for req in requests_list}
        req_by_id = {r["custom_id"]: r for r in requests_list}

        snapshot = self.__dict__.get("_active_snapshot")
        if isinstance(snapshot, dict) and "repair_missing" in snapshot:
            repair_enabled = bool(snapshot.get("repair_missing"))
        else:
            repair_var = self.__dict__.get("repair_missing_var")
            repair_enabled = (
                bool(repair_var.get()) if repair_var is not None else True)
        if not repair_enabled:
            unresolved = {}
            for cid, req in req_by_id.items():
                reason = _chunk_response_retry_reason(raw_map.get(cid), req)
                if not reason:
                    continue
                cue_ids = []
                try:
                    user_message = next(
                        msg["content"]
                        for msg in req.get("body", {}).get("messages", [])
                        if msg.get("role") == "user")
                    payload = json.loads(user_message)
                    missing = _missing_block_items(
                        [item for item in payload.get("tr", [])
                         if isinstance(item, dict)],
                        raw_map.get(cid, ""),
                    )
                    cue_ids = [str(item.get("i")) for item in missing]
                    if reason == "non_turkish_target":
                        response_items = json.loads(_extract_json_array(
                            raw_map.get(cid, "")))
                        leak_src_map = (
                            _chunk_leak_src_map_from_request(req)
                            or _chunk_src_map_from_request(req))
                        leaks = []
                        for item in response_items:
                            if not isinstance(item, dict):
                                continue
                            item_id = str(item.get("i", ""))
                            token = ht.non_turkish_leak_token(
                                str(item.get("t", "")),
                                source_text=_chunk_leak_source_text(
                                    leak_src_map, item_id),
                            )
                            if token:
                                leaks.append((item_id, token))
                        if leaks:
                            cue_ids = [item_id for item_id, _token in leaks]
                            reason = (
                                "non_turkish_target:"
                                + ", ".join(
                                    f"#{item_id}='{token}'"
                                    for item_id, token in leaks[:5]))
                    elif reason == "cue_content_owner_mismatch":
                        response_items = json.loads(_extract_json_array(
                            raw_map.get(cid, "")))
                        owner_src_map = (
                            _chunk_leak_src_map_from_request(req)
                            or _chunk_src_map_from_request(req))
                        cue_ids = sorted(
                            _chunk_content_owner_mismatch_ids(
                                response_items, owner_src_map),
                            key=lambda value: (0, int(value))
                            if str(value).isdigit() else (1, str(value)),
                        )
                except Exception:
                    cue_ids = []
                unresolved[cid] = (reason, cue_ids)
            report_once = self.__dict__.setdefault(
                "_repair_disabled_chunk_report_once", set())
            for cid, (reason, cue_ids) in unresolved.items():
                report_key = (id(raw_map), cid, reason, tuple(cue_ids))
                if report_key in report_once:
                    continue
                report_once.add(report_key)
                detail = f" ({_fmt_align_ranges(cue_ids)})" if cue_ids else ""
                self._log(
                    f"  ↪ {cid}: {reason}; Eksik Cue API Onarımı kapalı, API yeniden "
                    f"denenmedi{detail}. Şüpheli cue inceleme raporuna bırakıldı",
                    "warn",
                )
            return set(unresolved)
        # Step 0: try cheap JSON repair before full re-translation
        self._json_repair_pass(
            client, raw_map, requests_list, file_map, file_path)

        def _request_file_path(req):
            if file_path:
                return file_path
            try:
                return str((file_map or {})[req["custom_id"]][0][2])
            except (KeyError, IndexError, TypeError):
                return ""
        if getattr(self, "_stop_flag", False):
            return {cid for cid in req_by_id if _chunk_response_retry_reason(
                raw_map.get(cid), req_by_id.get(cid))}
        partial_only_cids = set()

        # A valid but partial JSON array is the usual provider-truncation
        # case.  Salvage it before the strict whole-chunk retry so the
        # translations that did arrive can never be replaced by [HATA].
        for cid, req in req_by_id.items():
            raw = raw_map.get(cid)
            if raw is None:
                continue
            try:
                user_message = next(
                    msg["content"] for msg in req.get("body", {}).get("messages", [])
                    if msg.get("role") == "user")
                payload = json.loads(user_message)
                all_items = [it for it in payload.get("tr", []) if isinstance(it, dict)]
                missing = _missing_block_items(all_items, raw)
                from response_integrity import parse_translation_payload
                parsed = parse_translation_payload(
                    raw, {str(it.get("i")) for it in all_items if "i" in it})
                recovered = sum(
                    1 for value in parsed.translations.values()
                    if str(value).strip() and not str(value).strip().startswith("[HATA"))
                if missing and recovered and len(missing) < len(all_items):
                    # A partially valid response must never fall back to a
                    # whole-chunk retry: that would spend the translation
                    # again and could replace the sound cues that already
                    # arrived.  Keep this chunk on the missing-cue repair path.
                    partial_only_cids.add(cid)
                    merged = self._resend_missing_blocks(
                        client, req, raw, max_sub=1,
                        file_path=_request_file_path(req))
                    if merged is not None:
                        raw_map[cid] = merged
                        self._log(
                            f"  ↳ {cid}: {len(missing)} eksik cue önce alt-grupta onarıldı; "
                            "sağlam cue'lar korunuyor",
                            "ok",
                        )
            except RequestCancelled:
                raise
            except Exception as salvage_error:
                self._log(
                    f"  ↳ {cid}: erken alt-grup kurtarması çalışmadı ({salvage_error})",
                    "warn",
                )
        upstream_failed = set()
        permanent_failure = False

        def _retry_reason(cid):
            return _chunk_response_retry_reason(raw_map.get(cid), req_by_id.get(cid))

        def _needs_retry(cid):
            return bool(_retry_reason(cid))

        def _leak_example_token(cid):
            """Log/teşhis amaçlı: bu chunk'ta hedef-dil kaçağını tetikleyen somut
            token'ı döndürür (yanlış alarm mı gerçek sızıntı mı ayırt edilebilsin)."""
            try:
                items = json.loads(_extract_json_array(raw_map.get(cid, "")))
                req = req_by_id.get(cid)
                chunk_src_map = _chunk_src_map_from_request(req) if req else {}
                for it in items:
                    tok = ht.non_turkish_leak_token(
                        str(it.get("t", "")),
                        source_text=_chunk_leak_source_text(
                            chunk_src_map, it.get("i")),
                    )
                    if tok:
                        return tok
            except Exception:
                pass
            return None

        def _retry_body_for(req, reason: str):
            body = copy.deepcopy(req["body"])
            if reason in {"adjacent_duplicate", "id_integrity", "empty_dialogue",
                          "cue_content_owner_mismatch"}:
                for msg in body.get("messages", []):
                    if msg.get("role") != "user":
                        continue
                    try:
                        payload = json.loads(msg.get("content", ""))
                        payload.pop("sentence_groups", None)
                        for it in payload.get("tr", []):
                            if isinstance(it, dict):
                                it.pop("frag", None)
                                it.pop("frag_group", None)
                        msg["content"] = json.dumps(payload, ensure_ascii=False)
                    except Exception:
                        pass
                    break
                guard_msg = (
                    "STRICT ID RETRY — ID INTEGRITY: Retry the whole chunk and output ONLY valid JSON. "
                    "Translate every tr item independently into its own id. Context may clarify meaning, "
                    "but NEVER move, borrow, merge, or redistribute words or clauses between ids. "
                    "Return every input id exactly once, in the same order. No id may be missing and no "
                    "dialogue translation may be empty."
                )
                role = "developer" if any(m.get("role") == "developer" for m in body.get("messages", [])) else "system"
                body.setdefault("messages", []).insert(1, {"role": role, "content": guard_msg})
            if reason == "non_turkish_target":
                guard_msg = (
                    "QUALITY RETRY: The previous JSON parsed, but at least one translation contained "
                    "non-Turkey-Turkish Latin/Turkic artifacts. Retry the whole chunk. Output ONLY valid "
                    "JSON. Use natural Turkey Turkish only. Do not output Turkmen/Uzbek/Azeri-looking "
                    "forms such as bäýram, holidaý, oturylyşyğı, ortadagy, geň, taksidermiya, bäseke, "
                    "qora, yuqori, pichoq, shaxs, xavf, daraj, haqli. Keep the same ids and line breaks."
                )
                role = "developer" if any(m.get("role") == "developer" for m in body.get("messages", [])) else "system"
                body.setdefault("messages", []).insert(1, {"role": role, "content": guard_msg})
            if "temperature" in body:
                body["temperature"] = min(float(body.get("temperature") or 0.2), 0.2)
            return body

        strict_reasons = {"adjacent_duplicate", "id_integrity", "empty_dialogue",
                          "cue_content_owner_mismatch"}
        report_only_reasons = {"cue_content_owner_mismatch"}
        report_only_cids = set()
        report_only_ids = set()
        recovery_report_once = self.__dict__.setdefault(
            "_recovery_report_once", set())
        for cid, req in req_by_id.items():
            reason = _retry_reason(cid)
            if reason not in strict_reasons:
                continue
            if reason in report_only_reasons:
                try:
                    response_items = json.loads(_extract_json_array(
                        raw_map.get(cid, "")))
                    owner_src_map = (
                        _chunk_leak_src_map_from_request(req)
                        or _chunk_src_map_from_request(req))
                    bad_ids = sorted(
                        _chunk_content_owner_mismatch_ids(
                            response_items, owner_src_map),
                        key=lambda value: (0, int(value))
                        if str(value).isdigit() else (1, str(value)),
                    )
                except Exception:
                    bad_ids = []
                report_only_cids.add(cid)
                report_key = (
                    id(raw_map), cid, reason,
                    tuple(str(value) for value in bad_ids),
                )
                first_report = report_key not in recovery_report_once
                recovery_report_once.add(report_key)
                if first_report:
                    report_only_ids.update(str(value) for value in bad_ids)
                detail = (
                    f" ({_fmt_align_ranges(bad_ids)})" if bad_ids else "")
                if first_report:
                    self._log(
                        f"  ↪ {cid}: {reason}; şüpheli cue yalnız inceleme raporuna "
                        f"bırakıldı{detail}. API yeniden denenmedi, mevcut çeviri korundu",
                        "warn",
                    )
                continue
            targeted = _targeted_strict_chunk_salvage(
                raw_map.get(cid, ""), req, reason)
            if targeted is None:
                continue
            raw_map[cid], bad_ids = targeted
            partial_only_cids.add(cid)
            self._log(
                f"  ↪ {cid}: {reason}; {len(bad_ids)} şüpheli cue hedefli "
                f"onarıma bırakıldı ({_fmt_align_ranges(bad_ids)}), sağlam cue'lar korundu",
                "warn",
            )

        for cid, req in req_by_id.items():
            if _retry_reason(cid) != "non_turkish_target":
                continue
            targeted = _targeted_non_turkish_chunk_salvage(
                raw_map.get(cid, ""), req)
            if targeted is None:
                continue
            original_raw = raw_map.get(cid, "")
            raw_map[cid], bad_ids = targeted
            self._log(
                f"  ↪ {cid}: {len(bad_ids)} hedef-dil kaçağı yalnız ilgili "
                f"cue için bir kez onarılacak ({_fmt_align_ranges(bad_ids)}); "
                "sağlam cue'lar korunuyor",
                "warn",
            )
            try:
                merged = self._resend_missing_blocks(
                    client, req, raw_map[cid], max_sub=1,
                    file_path=_request_file_path(req))
            except RequestCancelled:
                raise
            except Exception as repair_error:
                self._log(
                    f"  ↪ {cid}: hedefli hedef-dil onarımı çalışmadı "
                    f"({repair_error}); mevcut çeviri rapora bırakıldı",
                    "warn",
                )
                merged = None
            if (merged is not None
                    and _chunk_response_retry_reason(merged, req) != "non_turkish_target"):
                raw_map[cid] = merged
                continue
            raw_map[cid] = original_raw
            report_only_cids.add(cid)
            self._log(
                f"  ↪ {cid}: hedef-dil kaçağı tek cue denemesinde giderilemedi; "
                "pahalı tüm-chunk tekrarı yapılmadı, mevcut çeviri inceleme "
                "raporuna bırakıldı",
                "warn",
            )

        strict_reported = set()
        for round_idx in range(max_rounds):
            if self._stop_flag:
                break
            retry_reasons = {cid: _retry_reason(cid) for cid in req_by_id}
            pending = [cid for cid, reason in retry_reasons.items() if reason]
            if not pending:
                return set()
            to_retry = [
                cid for cid in pending
                if cid not in upstream_failed and cid not in partial_only_cids
                and cid not in report_only_cids
                and retry_reasons.get(cid) not in strict_reasons
            ]
            if not to_retry:
                break
            leak_cids = [cid for cid in to_retry if retry_reasons.get(cid) == "non_turkish_target"]
            leak_count = len(leak_cids)
            extra = f", {leak_count} hedef-dil kaçağı" if leak_count else ""
            if leak_cids:
                example = _leak_example_token(leak_cids[0])
                if example:
                    extra += f" (örn: '{example}')"
            dup_count = sum(1 for reason in retry_reasons.values() if reason == "adjacent_duplicate")
            if dup_count:
                extra += f", {dup_count} chunk-içi tekrar"
            self._log(f"↺  {len(to_retry)} chunk yeniden deneniyor{extra} (tur {round_idx+1}/{max_rounds})...", "warn")
            for cid in to_retry:
                if self._stop_flag:
                    break
                req = req_by_id.get(cid)
                if not req:
                    continue
                for attempt in range(3):  # up to 3 attempts per round for transient errors
                    try:
                        resp = _safe_chat_create(
                            client,
                            cancel_context=self.__dict__.get("_helper_request_canceller"),
                            _checkpoint_label="main_translation_retry",
                            **_retry_body_for(req, retry_reasons.get(cid, "")),
                        )
                        text = _validated_chat_content(resp)
                        raw_map[cid] = text
                        _report_response_usage(
                            _app_token_callback(
                                self, req.get("body", {}).get("model", ""),
                                "Ana Çeviri Yeniden Deneme",
                                base_url=(self.__dict__.get(
                                    "_active_snapshot", {}) or {}).get(
                                        "main_api_base_url", ""),
                                file_path=_request_file_path(req)),
                            resp, log_fn=self._log,
                            pass_name="Ana Çeviri Yeniden Deneme")
                        self._log(f"  ↺ {cid}: tamam", "ok")
                        break
                    except RequestCancelled:
                        raise
                    except Exception as e:
                        if _is_provider_unavailable_error(e):
                            permanent_failure = True
                            self._log(
                                "  Sağlayıcıda model kanalı yok; kalan chunk ve "
                                "kurtarma istekleri gönderilmeyecek",
                                "warn",
                            )
                            break
                        if _is_permanent_provider_error(e):
                            permanent_failure = True
                            self._log(
                                "  Kalıcı API/bakiye hatası; kalan chunk ve alt-istek "
                                "kurtarmaları gönderilmeyecek",
                                "warn",
                            )
                            break
                        if _is_upstream_provider_error(e):
                            upstream_failed.add(cid)
                            self._log(
                                f"  ↪ {cid}: sağlayıcı büyük isteği reddetti; "
                                "küçük isteklerle kurtarmaya geçilecek",
                                "warn",
                            )
                            break
                        transient = _is_transient_retry_error(e)
                        if transient and attempt < 2:
                            wait = (2 ** attempt) + random.random()
                            time.sleep(wait)
                            if getattr(self, "_stop_flag", False):
                                break
                            continue
                        self._log(f"  ↺ {cid}: başarısız — {e}", "err")
                        break
                if permanent_failure:
                    break
            if permanent_failure:
                break

        # Kurtarma adımı
        if self._stop_flag or permanent_failure:
            if permanent_failure:
                self._block_automatic_recovery_for_permanent_provider()
            return set(req_by_id)
        for cid, req in req_by_id.items():
            reason = _retry_reason(cid)
            if reason not in {"adjacent_duplicate", "id_integrity", "empty_dialogue",
                              "cue_content_owner_mismatch"}:
                continue
            if cid in report_only_cids:
                continue
            if cid not in strict_reported:
                strict_reported.add(cid)
                self._log(
                    f"  ↪ {cid}: katı doğrulama sorunu ({reason}) cue bazında "
                    "yalıtılamadı; pahalı tüm-chunk tekrarı yapılmadı, "
                    "elle inceleme için raporlandı",
                    "warn",
                )
        repair_cids = [
            cid for cid in req_by_id
            if _needs_retry(cid)
            and cid not in report_only_cids
            and (_retry_reason(cid) not in strict_reasons
                 or cid in partial_only_cids)
        ]
        for cid in repair_cids:
            if self._stop_flag:
                break
            try:
                merged = self._resend_missing_blocks(
                    client,
                    req_by_id[cid],
                    raw_map.get(cid, ""),
                    max_sub=1,
                    file_path=_request_file_path(req_by_id[cid]),
                )
            except RequestCancelled:
                raise
            except Exception as e:
                self._log(f"  ↺ {cid}: alt-istek kurtarması hatası — {e}", "warn")
                merged = None
            if merged is not None:
                raw_map[cid] = merged

        for cid in req_by_id:
            if _retry_reason(cid) != "non_turkish_target":
                continue
            if cid in report_only_cids:
                continue
            try:
                items = json.loads(_extract_json_array(raw_map.get(cid, "")))
                req = req_by_id.get(cid)
                chunk_src_map = _chunk_src_map_from_request(req) if req else {}
                marked = 0
                example = None
                for item in items:
                    if isinstance(item, dict):
                        tok = ht.non_turkish_leak_token(
                            str(item.get("t", "")),
                            source_text=_chunk_leak_source_text(
                                chunk_src_map, item.get("i")),
                        )
                        if tok:
                            item["t"] = "[HATA_NON_TURKISH_TARGET]"
                            marked += 1
                            if example is None:
                                example = tok
                if marked:
                    raw_map[cid] = json.dumps(items, ensure_ascii=False)
                    tok_hint = f" (örn: '{example}')" if example else ""
                    self._log(f"  ↺ {cid}: {marked} hedef-dil kaçağı son çare için işaretlendi{tok_hint}", "warn")
            except Exception:
                pass

        if report_only_ids:
            ordered = sorted(
                report_only_ids,
                key=lambda value: (0, int(value))
                if str(value).isdigit() else (1, str(value)),
            )
            self._log(
                "  Cue sahipliği inceleme özeti: "
                f"{len(ordered)} cue API tekrarı yapılmadan rapora bırakıldı "
                f"({_fmt_align_ranges(ordered)})",
                "warn",
            )
        return {
            cid for cid in req_by_id
            if cid not in report_only_cids
            and _retry_reason(cid) not in {"", *report_only_reasons}
        }

    def _resend_missing_blocks(self, client, req: dict, current_raw: str,
                               max_sub: int = 1, file_path: str = ""):
        """Bir chunk'ta hâlâ eksik/[HATA] olan blokları, yalnızca o blokları içeren
        daha küçük isteklerle yeniden çevirir (kesilme kurtarması). Birleştirilmiş
        JSON dizisi (string) döner; her istek tek cue içerir, kurtarılacak bir şey
        yoksa None."""
        try:
            payload = json.loads(req["body"]["messages"][1]["content"])
        except Exception:
            return None
        all_items = payload.get("tr", [])
        if len(all_items) < 2:
            return None
        missing = _missing_block_items(all_items, current_raw)
        if not missing:
            return None
        repair_units, deferred_fragment_ids = _missing_repair_units(
            all_items, payload.get("sentence_groups") or [], missing)

        from response_integrity import parse_translation_payload
        expected_ids = {str(it.get("i")) for it in all_items if "i" in it}
        parsed_current = parse_translation_payload(current_raw, expected_ids)
        recovered = {
            cue_id: text
            for cue_id, text in parsed_current.translations.items()
            if str(text).strip() and not str(text).strip().startswith("[HATA")
        }

        sys_msg = req["body"]["messages"][0]
        model   = req["body"]["model"]
        _ml     = model.lower()
        _no_temp = _ml.startswith(("gpt-5", "o1", "o3", "o4", "codex-"))
        n_requests = len(repair_units)
        recovery_kind = "sağlayıcı kurtarması" if len(missing) == len(all_items) else "kesilme kurtarması"
        self._log(f"  ↺ {req['custom_id']}: {len(missing)} eksik blok "
                  f"{n_requests} küçük istekle tamamlanıyor ({recovery_kind})", "warn")
        if deferred_fragment_ids:
            self._log(
                f"  ↳ {req['custom_id']}: {_fmt_align_ranges(sorted(deferred_fragment_ids))} "
                "kısmi cümle grubu tek cue onarımına gönderilmedi; sağlam komşu "
                "çeviriyi bozmamak için teslim incelemesine bırakıldı",
                "warn")

        for sub in repair_units:
            if self._stop_flag:
                break
            sub = [dict(item) for item in sub]
            sub_payload = {"tr": sub}
            sub_ids = {str(item.get("i")) for item in sub}
            complete_groups = []
            partial_group_ids = set()
            for group in payload.get("sentence_groups") or []:
                if not isinstance(group, dict):
                    continue
                group_ids = {str(value) for value in group.get("items") or []}
                if group_ids and group_ids.issubset(sub_ids):
                    complete_groups.append(group)
                elif group_ids & sub_ids:
                    partial_group_ids.update(group_ids & sub_ids)
            for item in sub:
                if str(item.get("i")) in partial_group_ids:
                    item.pop("frag", None)
                    item.pop("frag_group", None)
            if complete_groups:
                sub_payload["sentence_groups"] = complete_groups
            for key in ("ctx", "next_ctx", "prev_scene", "scene",
                        "idioms", "prev_tr", "glossary"):
                if payload.get(key):
                    sub_payload[key] = payload[key]
            body = {
                "model": model,
                "messages": [sys_msg,
                             {"role": "user", "content": json.dumps(sub_payload, ensure_ascii=False)}],
                "max_completion_tokens": max(len(sub) * 200, 800),
            }
            if not _no_temp:
                body["temperature"] = 0.2
            try:
                resp = _safe_chat_create(
                    client,
                    cancel_context=self.__dict__.get("_helper_request_canceller"),
                    _checkpoint_label="translation_subgroup_recovery",
                    **body,
                )
                _report_response_usage(
                    _app_token_callback(
                        self, req.get("body", {}).get("model", ""),
                        "Eksik Cue Alt-Grup Onarımı",
                        base_url=(self.__dict__.get(
                            "_active_snapshot", {}) or {}).get(
                                "main_api_base_url", ""),
                        file_path=file_path),
                    resp, log_fn=self._log,
                    pass_name="Eksik Cue Alt-Grup Onarımı")
                txt = _validated_chat_content(resp)
                info = [(str(it.get("i")), "", "") for it in sub]
                tmap = parse_response(txt, info)
                for k, v in tmap.items():
                    if str(v).strip() and not str(v).strip().startswith("[HATA"):
                        recovered[k] = v
            except RequestCancelled:
                break
            except Exception as e:
                self._log(f"  ↺ alt-grup hatası: {e}", "warn")

        merged = [{"i": it.get("i"), "t": recovered.get(str(it.get("i")), "[HATA]")}
                  for it in all_items]
        return json.dumps(merged, ensure_ascii=False)

    def _update_active_model(self, source=None):
        if source == "2.5M":
            self.limit_class_var.set("2.5M")
            self.model_var.set(self.model_2_5m_var.get())
        elif source == "250K":
            self.limit_class_var.set("250K")
            self.model_var.set(self.model_250k_var.get())
        else:
            limit_class = self.limit_class_var.get()
            if limit_class == "2.5M":
                self.model_var.set(self.model_2_5m_var.get())
            else:
                self.model_var.set(self.model_250k_var.get())

        # Aktif seçimi mor çerçeve ile vurgula
        active_class = self.limit_class_var.get()
        if active_class == "2.5M":
            if hasattr(self, "model_2_5m_combo") and self.model_2_5m_combo:
                self.model_2_5m_combo.configure(border_color=ACCENT)
            if hasattr(self, "model_250k_combo") and self.model_250k_combo:
                self.model_250k_combo.configure(border_color=BORDER)
        else:
            if hasattr(self, "model_2_5m_combo") and self.model_2_5m_combo:
                self.model_2_5m_combo.configure(border_color=BORDER)
            if hasattr(self, "model_250k_combo") and self.model_250k_combo:
                self.model_250k_combo.configure(border_color=ACCENT)

        try:
            self._save_settings(save_credentials=False)
        except Exception:
            pass

    def _apply_workflow_profile(self, profile_name: str):
        profile = WORKFLOW_PROFILES.get(profile_name)
        if not profile:
            return
        for attr, value in profile.items():
            var = getattr(self, attr, None)
            if var is not None:
                var.set(value)
        self._apply_media_mode(self.media_mode_var.get(), notify=False)
        self._toggle_hybrid()
        self._log(f"Çalışma profili uygulandı: {profile_name}", "info")

    def _apply_media_mode(self, media_mode: str, *, notify=True):
        defaults = MEDIA_MODE_DEFAULTS.get(media_mode)
        if not defaults:
            return
        self.series_memory_var.set(defaults["series_memory"])
        self.season_canon_var.set(defaults["season_canon"])
        self._sync_media_mode_controls()
        if notify:
            self._log(
                f"İçerik modu: {media_mode} — "
                + ("dizi hafızası açık, sezon kanonu kapalı"
                   if media_mode == "Dizi" else "dizi özellikleri kapalı"),
                "info",
            )

    def _sync_media_mode_controls(self):
        is_series = (
            getattr(self, "media_mode_var", None) is not None
            and self.media_mode_var.get() == "Dizi"
        )
        switch = getattr(self, "season_canon_switch", None)
        if switch is not None:
            switch.configure(state="normal" if is_series else "disabled")

    def _on_mode_change(self):
        if self.mode_var.get() == "sync" and not self.hybrid_var.get():
            self.hybrid_var.set(True)
            self._toggle_hybrid()

    def _toggle_hybrid(self):
        if self.hybrid_var.get():
            self.hybrid_frame.grid()
            # Karşılıklı engelleme: Yardımcı Analiz açıkken Ön-Bağlam'ı kapat ve pasifleştir
            self.precontext_var.set(False)
            if hasattr(self, "precontext_switch") and self.precontext_switch:
                self.precontext_switch.configure(state="disabled")
        else:
            self.hybrid_frame.grid_remove()
            # Yardımcı Analiz kapandığında Ön-Bağlam switch'ini tekrar etkinleştir
            if hasattr(self, "precontext_switch") and self.precontext_switch:
                self.precontext_switch.configure(state="normal")
        self._sync_helper_role_controls()

    def _on_precontext_toggle(self):
        # Ön-Bağlam Analizi açıldığında Yardımcı Analiz'i kapat
        if self.precontext_var.get():
            self.hybrid_var.set(False)
            self._toggle_hybrid()

    def _on_input_entry_focus_in(self):
        """Kullanıcı girdi klasör kutusuna tıkladığında odak anındaki ilk değeri kaydeder."""
        if getattr(self, "_is_running", False):
            return
        self._input_entry_focus_val = self.input_var.get()

    def _on_input_entry_edited(self):
        """Kullanıcı odak kaybettiğinde veya Enter bastığında değer gerçekten değiştiyse açık seçim olarak işaretler."""
        if getattr(self, "_is_running", False):
            return
        cur_val = self.input_var.get()
        if getattr(self, "_input_entry_focus_val", None) is not None:
            if cur_val == self._input_entry_focus_val:
                return
        self._input_entry_focus_val = cur_val
        self._input_folder_explicitly_selected = True
        self._file_list_root = ""
        path = (cur_val or "").strip()
        if not self._selected_files and path and os.path.isdir(path):
            self._pm = None
            self._project_memories = {}
            self._queue_input_folder_scan(path)

    def _retarget_project_memory(self):
        current = getattr(self, "_pm", None)
        if current is None:
            return
        try:
            from project_memory import ProjectMemory
            self._pm = ProjectMemory(
                str(current.input_dir),
                _lang_iso639_1(self.tgt_var.get()),
                getattr(current, "source_language", "en"),
            )
            self._project_memories = {}
        except Exception:
            self._pm = None

    def _project_memory_for(self, filepath: str = "", source_language: str = ""):
        snapshot = getattr(self, "_active_snapshot", None) or {}
        selected = snapshot.get("selected_files") if snapshot else getattr(
            self, "_selected_files", ())
        if selected:
            return None
        input_dir = (
            snapshot.get("input_dir")
            if snapshot else getattr(getattr(self, "input_var", None), "get", lambda: "")()
        )
        if not input_dir and getattr(self, "_pm", None) is not None:
            input_dir = str(self._pm.input_dir)
        if not input_dir:
            return None
        if not source_language:
            fallback = snapshot.get("src_lang", "English") if snapshot else "English"
            source_language = (
                self._effective_file_source_language(filepath, fallback)
                if filepath else fallback
            )
        target_language = (
            snapshot.get("tgt_lang", "Turkish")
            if snapshot else App._run_setting(
                self, "tgt_lang", "tgt_var", "Turkish")
        )
        source_key = _lang_iso639_1(source_language)
        target_key = _lang_iso639_1(target_language)
        key = (
            os.path.normcase(os.path.abspath(input_dir)),
            source_key,
            target_key,
        )
        cache = getattr(self, "_project_memories", None)
        if not isinstance(cache, dict):
            cache = {}
            self._project_memories = cache
        if key not in cache:
            try:
                from project_memory import ProjectMemory
                cache[key] = ProjectMemory(
                    input_dir, target_key, source_key)
            except Exception:
                return None
        return cache[key]

    def _pick_folder(self, var, is_input):
        if getattr(self, "_is_running", False):
            self._log("Çeviri çalışırken klasör değiştirilemez.", "warn")
            return
        self.attributes("-topmost", True)
        path = filedialog.askdirectory(parent=self, title="Klasör Seç")
        self.attributes("-topmost", False)
        if not path:
            return
        var.set(path)
        if is_input:
            # Clear any manually selected files when a folder is chosen
            self._selected_files = []
            self._selected_folder_roots = [path]
            self._file_list_root = ""
            self._input_folder_explicitly_selected = True
            self._content_type_preflight_done = False
            self._language_preflight_done = False
            self.clear_files_btn.grid_remove()
            self.clear_info_btn.grid_remove()
            self._pm = None
            self._project_memories = {}
            self._queue_input_folder_scan(path)
        else:
            self._log(f"Çıkış klasörü: {path}", "info")

    def _set_folder_scan_busy(self, busy: bool):
        self._folder_scan_busy = bool(busy)
        button = getattr(self, "add_folders_btn", None)
        if button is not None:
            button.configure(
                state="disabled" if busy else "normal",
                text="⏳  Klasörler Taranıyor…" if busy else "📂  Klasörler Ekle",
            )
        start_button = getattr(self, "start_btn", None)
        if start_button is not None:
            start_button.configure(
                state="disabled" if busy or getattr(self, "_is_running", False) else "normal")
        if busy:
            self._set_status("Klasörler taranıyor…")
        elif not getattr(self, "_is_running", False):
            self._set_status("Hazır")

    def _run_folder_scan(self, work, finish):
        token = object()
        if getattr(self, "_folder_scan_busy", False):
            previous = getattr(self, "_folder_scan_cancel", None)
            if previous is not None:
                previous.set()
            self._folder_scan_pending = (token, work, finish)
            return
        App._start_folder_scan(self, token, work, finish)

    def _start_folder_scan(self, token, work, finish):
        cancel = threading.Event()
        self._folder_scan_token = token
        self._folder_scan_cancel = cancel
        self._set_folder_scan_busy(True)

        def _work():
            try:
                result = work(cancel.is_set)
                error = None
            except Exception as exc:
                result = None
                error = exc
            _post_ui(
                self, App._finish_folder_scan,
                self, token, finish, result, error, cancel.is_set())

        try:
            App._start_worker(self, _work)
        except Exception as exc:
            if token is getattr(self, "_folder_scan_token", None):
                self._folder_scan_token = None
                self._folder_scan_cancel = None
                self._set_folder_scan_busy(False)
                self._log(f"Klasör taraması başlatılamadı: {exc}", "err")

    def _finish_folder_scan(self, token, finish, result, error, cancelled=False):
        if token is not getattr(self, "_folder_scan_token", None):
            return
        pending = getattr(self, "_folder_scan_pending", None)
        if pending is not None:
            self._folder_scan_pending = None
            self._folder_scan_token = None
            self._folder_scan_cancel = None
            App._start_folder_scan(self, *pending)
            return
        self._folder_scan_token = None
        self._folder_scan_cancel = None
        self._set_folder_scan_busy(False)
        if cancelled:
            return
        if error is not None:
            self._log(f"Klasör taraması başarısız: {error}", "err")
            return
        finish(result)

    def _queue_input_folder_scan(self, path: str):
        target_key = _lang_iso639_1(self.tgt_var.get())
        source_key = _lang_iso639_1(self.src_var.get())
        output_var = getattr(self, "output_var", None)
        output_path = (output_var.get() if output_var is not None else "") or ""
        output_path = output_path.strip()
        same_folder_var = getattr(self, "same_folder_var", None)
        same_folder = bool(same_folder_var and same_folder_var.get())
        excluded_outputs = _nested_output_exclusions(
            [path], output_path, same_folder)

        def _work(cancel_check):
            files = get_subtitle_files(
                path, recursive=True, exclude_paths=excluded_outputs,
                cancel_check=cancel_check)
            if cancel_check():
                return None
            try:
                from project_memory import ProjectMemory
                memory = ProjectMemory(path, target_key, source_key)
                stats = memory.stats()
            except Exception:
                memory = None
                stats = None
            if cancel_check():
                return None
            return files, memory, stats

        def _finish(result):
            if result is None:
                return
            files, memory, stats = result
            if (self.input_var.get() != path
                    or not getattr(self, "_input_folder_explicitly_selected", True)
                    or getattr(self, "_selected_files", None)):
                return
            current_target = _lang_iso639_1(self.tgt_var.get())
            current_source = _lang_iso639_1(self.src_var.get())
            if current_target != target_key or current_source != source_key:
                self._pm = None
                self._queue_input_folder_scan(path)
                return
            self._pm = memory
            self._project_memories = {}
            if stats and (stats["glossary"] > 0 or stats["characters"] > 0):
                self._log(
                    f"Proje hafızası yüklendi: {stats['glossary']} terim, "
                    f"{stats['characters']} karakter", "ok")
            if files:
                self._file_list_root = path
                self._estimate_async(
                    files,
                    lambda tb, ek, n=len(files):
                    f"✓  {n} dosya  •  {tb} satır  •  ~{ek} token")
                self._log(f"Klasör: {path}  ({len(files)} dosya)", "ok")
                self._populate_file_list(files)
            else:
                self._file_list_root = path
                self.file_info_var.set("⚠  .srt bulunamadı!")
                self._log(f"'{path}' içinde .srt yok.", "warn")

        self._run_folder_scan(
            _work, _finish)

    def _pick_files(self):
        if getattr(self, "_is_running", False):
            self._log("Çeviri çalışırken dosya seçilemez.", "warn")
            return
        self.attributes("-topmost", True)
        paths = filedialog.askopenfilenames(
            parent=self, title="Altyazı Dosyaları Seç",
            filetypes=[
                ("Altyazı dosyaları", "*.srt *.vtt *.ass *.ssa"),
                ("SubRip (.srt)", "*.srt"),
                ("WebVTT (.vtt)", "*.vtt"),
                ("ASS/SSA (.ass *.ssa)", "*.ass *.ssa"),
                ("Tümü", "*.*"),
            ])
        self.attributes("-topmost", False)
        if not paths:
            return
        self._content_type_preflight_done = False
        self._input_folder_explicitly_selected = False
        self._selected_folder_roots = []
        self._selected_files = self._dedupe_paths(list(paths))
        self._pm = None
        n = len(self._selected_files)
        self._refresh_selected_files_ui(
            f"{n} dosya seçildi: "
            + ", ".join(Path(p).name for p in self._selected_files[:5])
            + ("…" if n > 5 else ""))

    def _pick_video_files(self):
        if getattr(self, "_is_running", False):
            self._log("Çeviri çalışırken video eklenemez.", "warn")
            return
        self.attributes("-topmost", True)
        paths = filedialog.askopenfilenames(
            parent=self,
            title="İçinden Altyazı Alınacak Videoları Seç",
            filetypes=[
                ("Video dosyaları", "*.mkv *.mp4 *.m4v *.mov *.avi *.webm *.m2ts"),
                ("Matroska (.mkv)", "*.mkv"),
                ("MP4 (.mp4 *.m4v)", "*.mp4 *.m4v"),
                ("Tümü", "*.*"),
            ],
        )
        self.attributes("-topmost", False)
        if paths:
            self._queue_video_probe(list(paths))

    def _queue_video_probe(self, video_paths):
        if getattr(self, "_is_running", False):
            self._log("Çeviri çalışırken video eklenemez.", "warn")
            return
        if getattr(self, "_video_import_busy", False):
            self._log("Video altyazıları zaten taranıyor veya çıkarılıyor.", "warn")
            return
        paths = [
            str(Path(path)) for path in self._dedupe_paths(video_paths)
            if video_tracks.is_video_path(path) and Path(path).is_file()
        ]
        if not paths:
            self._log("Geçerli video dosyası bulunamadı.", "warn")
            return
        self._video_import_busy = True
        self._set_status(f"Video altyazıları taranıyor… 0/{len(paths)}")

        def _probe():
            results = []
            errors = []
            for index, path in enumerate(paths, 1):
                try:
                    streams = video_tracks.probe_subtitle_streams(path)
                    results.append((path, streams))
                except Exception as exc:
                    errors.append(f"{Path(path).name}: {exc}")
                self._set_status(f"Video altyazıları taranıyor… {index}/{len(paths)}")
            _post_ui(self, self._show_video_stream_picker, results, errors)

        try:
            App._start_worker(self, _probe)
        except Exception as exc:
            self._video_import_busy = False
            self._set_status("Hazır.")
            self._log(f"Video altyazısı taraması başlatılamadı: {exc}", "err")

    def _show_video_stream_picker(self, results, errors):
        self._video_import_busy = False
        self._set_status("Hazır.")
        for error in errors:
            self._log(f"Video altyazısı: {error}", "warn")
        supported_count = sum(
            1 for _path, streams in results for stream in streams
            if stream.supported
        )
        if not supported_count:
            detail = "\n".join(errors[:4])
            if not detail:
                detail = (
                    "Seçilen videolarda metin tabanlı altyazı bulunamadı. "
                    "PGS/DVD gibi görüntü altyazıları OCR gerektirir ve otomatik eklenmez."
                )
            messagebox.showwarning("Video Altyazısı Bulunamadı", detail, parent=self)
            return

        dlg = ctk.CTkToplevel(self)
        dlg.title("Video Altyazı Akışlarını Seç")
        dlg.geometry("760x620")
        dlg.minsize(620, 420)
        dlg.configure(fg_color=BG)
        dlg.transient(self)
        dlg.grab_set()

        ctk.CTkLabel(
            dlg,
            text="Çıkarılacak altyazı akışlarını seç",
            font=ctk.CTkFont("Segoe UI", 17, "bold"),
            text_color=FG,
        ).pack(anchor="w", padx=18, pady=(18, 4))
        ctk.CTkLabel(
            dlg,
            text=(
                "Metin altyazıları SRT'ye çevrilip mevcut dosya sırasına eklenir. "
                "PGS/DVD görüntü altyazıları OCR gerektirdiği için seçilemez."
            ),
            font=ctk.CTkFont("Segoe UI", 11),
            text_color=FG2,
            wraplength=700,
            justify="left",
        ).pack(anchor="w", padx=18, pady=(0, 12))

        scroll = ctk.CTkScrollableFrame(
            dlg, fg_color=PANEL, corner_radius=10,
            scrollbar_button_color=BORDER,
            scrollbar_button_hover_color=ACCENT,
        )
        scroll.pack(fill="both", expand=True, padx=18, pady=(0, 12))
        selections = []
        for path, streams in results:
            ctk.CTkLabel(
                scroll,
                text=Path(path).name,
                font=ctk.CTkFont("Segoe UI", 12, "bold"),
                text_color=FG,
                anchor="w",
            ).pack(fill="x", padx=10, pady=(12, 4))
            supported = [stream for stream in streams if stream.supported]
            preferred = next(
                (stream for stream in supported
                 if stream.language.lower() in {"eng", "en", "english"}),
                supported[0] if supported else None,
            )
            if not streams:
                ctk.CTkLabel(
                    scroll, text="Altyazı akışı yok",
                    font=ctk.CTkFont("Segoe UI", 11),
                    text_color=FG_DIS,
                ).pack(anchor="w", padx=18, pady=(2, 6))
                continue
            for stream in streams:
                if stream.supported:
                    var = ctk.BooleanVar(value=(stream == preferred))
                    selections.append((path, stream, var))
                    ctk.CTkCheckBox(
                        scroll,
                        text=stream.label,
                        variable=var,
                        font=ctk.CTkFont("Segoe UI", 11),
                        text_color=FG,
                        fg_color=ACCENT,
                        hover_color=ACCENT_HOVER,
                        border_color=BORDER,
                    ).pack(anchor="w", fill="x", padx=18, pady=3)
                else:
                    ctk.CTkLabel(
                        scroll,
                        text=f"⚠ {stream.label} — görüntü tabanlı, OCR gerekli",
                        font=ctk.CTkFont("Segoe UI", 11),
                        text_color=FG_DIS,
                        anchor="w",
                    ).pack(fill="x", padx=18, pady=3)

        buttons = ctk.CTkFrame(dlg, fg_color="transparent")
        buttons.pack(fill="x", padx=18, pady=(0, 18))
        buttons.grid_columnconfigure((0, 1), weight=1)

        def _extract_selected():
            chosen = [
                (path, stream) for path, stream, var in selections if var.get()
            ]
            if not chosen:
                messagebox.showwarning(
                    "Seçim Yok", "En az bir metin altyazısı seçin.", parent=dlg)
                return
            dlg.destroy()
            self._video_import_busy = True
            self._set_status(f"Video altyazıları çıkarılıyor… 0/{len(chosen)}")

            def _extract():
                extracted = []
                extract_errors = []
                for index, (path, stream) in enumerate(chosen, 1):
                    try:
                        extracted.append(str(
                            video_tracks.extract_subtitle_stream(path, stream)))
                    except Exception as exc:
                        extract_errors.append(f"{Path(path).name} / {stream.label}: {exc}")
                    self._set_status(
                        f"Video altyazıları çıkarılıyor… {index}/{len(chosen)}")
                _post_ui(
                    self, self._finish_video_subtitle_import,
                    extracted, extract_errors)

            try:
                App._start_worker(self, _extract)
            except Exception as exc:
                self._video_import_busy = False
                self._set_status("Hazır.")
                self._log(f"Video altyazısı çıkarma işlemi başlatılamadı: {exc}", "err")
                messagebox.showerror(
                    "Video Altyazısı", f"Çıkarma işlemi başlatılamadı:\n{exc}", parent=self)

        ctk.CTkButton(
            buttons, text="İptal",
            fg_color=CARD, hover_color=BORDER,
            command=dlg.destroy,
        ).grid(row=0, column=0, padx=(0, 6), sticky="ew")
        ctk.CTkButton(
            buttons, text="Seçilenleri Çıkar ve Ekle",
            fg_color=ACCENT, hover_color=ACCENT_HOVER,
            command=_extract_selected,
        ).grid(row=0, column=1, padx=(6, 0), sticky="ew")

    def _finish_video_subtitle_import(self, extracted, errors):
        self._video_import_busy = False
        self._set_status("Hazır.")
        for error in errors:
            self._log(f"Video altyazısı çıkarılamadı: {error}", "warn")
        added = self._append_extracted_video_subtitles(extracted)
        if errors and not added:
            messagebox.showwarning(
                "Video Altyazısı Çıkarılamadı",
                "\n".join(errors[:5]),
                parent=self,
            )

    def _append_extracted_video_subtitles(self, paths):
        valid = [str(Path(path)) for path in paths if Path(path).is_file()]
        if not valid:
            return 0
        detected_languages = {
            path: _video_track_language(video_tracks.extracted_video_language(path))
            for path in valid
        }
        if (not self._selected_files
                and getattr(self, "_input_folder_explicitly_selected", False)
                and self.input_var.get()):
            self._selected_files = self._get_srt_files()
        before = len(self._selected_files)
        self._content_type_preflight_done = False
        self._language_preflight_done = False
        self._file_integrity_preflight_done = False
        self._file_integrity_preflight_signature = None
        self._selected_files = self._dedupe_paths(
            list(self._selected_files) + valid)
        self._pm = None
        added = len(self._selected_files) - before
        total = len(self._selected_files)
        self._refresh_selected_files_ui(
            f"Videodan +{added} altyazı eklendi, toplam {total} dosya")
        for path, language in detected_languages.items():
            var = getattr(self, "_file_language_vars", {}).get(path)
            if var is None:
                var = ctk.StringVar(value=language)
                self._file_language_vars[path] = var
            else:
                var.set(language)
        return added

    def _add_folder_files(self):
        if getattr(self, "_is_running", False):
            self._log("Çeviri çalışırken klasör eklenemez.", "warn")
            return
        try:
            paths = pick_multiple_folders(
                owner_hwnd=self.winfo_id(),
                title="Altyazı Klasörlerini Seç (Ctrl/Shift ile birden fazla klasör seçebilirsiniz)")
        except Exception:
            paths = None
        if paths is None:
            self._log("Native çoklu klasör seçici kullanılamadı, alternatif klasör seçimi açılıyor.", "warn")
            collected = []
            while True:
                self.attributes("-topmost", True)
                path = filedialog.askdirectory(parent=self, title="Altyazı Klasörü Ekle")
                self.attributes("-topmost", False)
                if not path:
                    break
                collected.append(path)
                try:
                    from tkinter import messagebox
                    ans = messagebox.askyesno(
                        "Klasör Ekle",
                        "Başka klasör eklemek ister misiniz?",
                        parent=self
                    )
                except Exception:
                    ans = False
                if not ans:
                    break
            paths = collected
        if not paths:
            return

        queue_scan = getattr(self, "_queue_append_folder_files", None)
        if callable(queue_scan):
            queue_scan(paths)
        else:
            self._append_folder_files(paths)

    def _queue_append_folder_files(self, paths: list[str]):
        paths = self._dedupe_paths(paths)
        selected_before = list(self._selected_files)
        base_input = (
            self.input_var.get()
            if not selected_before
            and getattr(self, "_input_folder_explicitly_selected", False)
            else ""
        )
        output_var = getattr(self, "output_var", None)
        output_path = (output_var.get() if output_var is not None else "") or ""
        same_folder_var = getattr(self, "same_folder_var", None)
        same_folder = bool(same_folder_var and same_folder_var.get())
        excluded_outputs = _nested_output_exclusions(
            ([base_input] if base_input else []) + list(paths),
            output_path.strip(), same_folder)

        def _work(cancel_check):
            base_files = (
                get_subtitle_files(
                    base_input, recursive=True, cancel_check=cancel_check,
                    exclude_paths=excluded_outputs)
                if base_input else []
            )
            if cancel_check():
                return None
            files, empty = _scan_subtitle_folders(
                paths, cancel_check=cancel_check,
                exclude_paths=excluded_outputs)
            if cancel_check():
                return None
            return base_files, files, empty

        def _finish(result):
            if result is None:
                return
            base_files, files, empty = result
            if (not self._selected_files and base_input
                    and self.input_var.get() == base_input):
                self._selected_files = base_files
            App._apply_scanned_folder_files(self, paths, files, empty)

        self._run_folder_scan(_work, _finish)

    def _append_folder_files(self, paths: list[str]):
        """Bir veya daha fazla klasörün altyazılarını mevcut seçime ekle."""
        if getattr(self, "_is_running", False):
            self._log("Çeviri çalışırken klasör eklenemez.", "warn")
            return 0
        if (not self._selected_files
                and getattr(self, "_input_folder_explicitly_selected", False)
                and self.input_var.get()):
            self._selected_files = self._get_srt_files()
        paths = self._dedupe_paths(paths)
        output_var = getattr(self, "output_var", None)
        output_path = (output_var.get() if output_var is not None else "") or ""
        same_folder_var = getattr(self, "same_folder_var", None)
        same_folder = bool(same_folder_var and same_folder_var.get())
        excluded_outputs = _nested_output_exclusions(
            paths, output_path.strip(), same_folder)
        files, empty = _scan_subtitle_folders(
            paths, exclude_paths=excluded_outputs)
        return App._apply_scanned_folder_files(self, paths, files, empty)

    def _apply_scanned_folder_files(self, paths, files, empty):
        if not files:
            for path in empty:
                self._log(f"'{path}' içinde altyazı yok.", "warn")
            return 0
        before = len(self._selected_files)
        self._content_type_preflight_done = False
        self._language_preflight_done = False
        self._selected_files = self._dedupe_paths(list(self._selected_files) + files)
        self._selected_folder_roots = self._dedupe_paths(
            list(getattr(self, "_selected_folder_roots", ()) or ()) + list(paths))
        self._pm = None
        added = len(self._selected_files) - before
        total = len(self._selected_files)
        for path in empty:
            self._log(f"'{path}' içinde altyazı yok.", "warn")
        self._refresh_selected_files_ui(
            f"{len(paths)} klasör eklendi: +{added} yeni, toplam {total} dosya")
        return added

    def _helper_model_config(self, role: str):
        assignments = self.__dict__.get("_api_key_assignments", {})
        profiles = self.__dict__.get("_api_key_profiles", {})
        assigned = assignments.get(role) if isinstance(assignments, dict) else None
        profile = profiles.get(assigned) if isinstance(profiles, dict) else None
        if profile:
            provider = "anthropic" if profile["provider"] == "anthropic" else "openai"
            base_url = profile.get("base_url", "").strip()
            if profile["provider"] == "openai_official":
                base_url = "https://api.openai.com/v1"
            from helper_models import HelperModelConfig
            return HelperModelConfig(
                label="Özel (Custom)", provider=provider,
                model=profile["model"], base_url=base_url)
        if role not in self.helper_model_vars:
            return resolve_helper_model("GPT-5.4 (Reseller)")
        lbl = self.helper_model_vars[role].get()
        if self._is_custom_helper_label(lbl):
            from helper_models import HelperModelConfig
            prov = self.helper_custom_provider_vars[role].get()
            model_name = self.helper_custom_model_vars[role].get().strip() or "custom-model"
            base_url = self.helper_custom_url_vars[role].get().strip() or "https://api.openai.com/v1"
            if prov == "openai" and "claude" in model_name.lower() and "/messages" in base_url.lower():
                prov = "anthropic"
            return HelperModelConfig(
                label="Özel (Custom)",
                provider=prov,
                model=model_name,
                base_url=base_url
            )
        return resolve_helper_model(lbl)

    def _helper_api_base_url(self, role: str):
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            urls = self._active_snapshot.get("helper_urls") or {}
            if role in urls:
                return urls[role]
        cfg = self._helper_model_config(role)
        url = cfg.base_url
        if url:
            if cfg.provider == "anthropic":
                url = url.rstrip("/")
                if not url.lower().endswith("/messages"):
                    url += "/messages"
            else:
                url = _normalize_api_base_url(url)
        return url

    def _helper_api_model(self, role: str):
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            models = self._active_snapshot.get("helper_models") or {}
            if role in models:
                return models[role]
        return self._helper_model_config(role).model

    def _helper_api_key(self, role: str):
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            keys = self._active_snapshot.get("helper_keys") or {}
            if role in keys:
                return keys[role]
        assigned = getattr(self, "_api_key_assignments", {}).get(role)
        if assigned in getattr(self, "_api_key_profiles", {}):
            return (credential_store.load_key(f"api_profile_{assigned}") or "").strip()
        custom_active = (
            role in getattr(self, "helper_model_vars", {})
            and self._is_custom_helper_label(self.helper_model_vars[role].get()))
        if custom_active:
            custom_key = (
                self.helper_custom_key_vars[role].get().strip()
                if role in self.helper_custom_key_vars else "")
            return custom_key
        k = ""
        if role in self.helper_role_key_vars:
            k = self.helper_role_key_vars[role].get().strip()
        provider = self._get_current_helper_provider(role)
        if not k and provider in {"openai", "openai_helper"}:
            from urllib.parse import urlparse
            helper_url_fn = getattr(self, "_helper_api_base_url", None)
            helper_url = helper_url_fn(role) if helper_url_fn else "https://api.openai.com/v1"
            helper_host = (urlparse(helper_url or "").hostname or "").casefold()
            official = helper_host in {"api.openai.com", "openai.com"}
            if not official:
                main_custom = bool(
                    getattr(self, "_main_custom_active", None)
                    and self._main_custom_active())
                main_host = (
                    urlparse(self._main_api_base_url() or "").hostname or ""
                ).casefold() if main_custom else ""
                if main_custom and main_host == helper_host:
                    return self._main_api_key()
                return ""
        if not k:
            cache_key = "openai_helper" if provider == "openai" else provider
            k = self._helper_keys_cache.get(cache_key, "").strip()
        if (not k and provider in {"openai", "openai_helper"}
                and hasattr(self, "helper_key_entry") and self.helper_key_entry):
            k = self.helper_key_entry.get().strip()
        if (not k and provider in {"openai", "openai_helper"}
                and hasattr(self, "api_key_entry") and self.api_key_entry):
            k = self.api_key_entry.get().strip()
        return k

    # ── Ana Model — Özel Sağlayıcı resolver'ları ────────────────────────────
    # "OpenAI API Key"/"OpenAI API Base URL"/model dropdown'ına ASLA yazmaz/okumaz
    # onların dışından — yalnızca AŞAĞIDAKİ ayrı alanları okur, açık VE doluysa
    # onu döner; kapalıysa gerçek OpenAI alanına döner. Özel alan boşsa güvenlik
    # için fail-closed davranır; OpenAI anahtarı özel URL'ye gönderilmez.
    def _main_custom_active(self) -> bool:
        return bool(getattr(self, "main_custom_var", None) and self.main_custom_var.get())

    def _main_api_key(self) -> str:
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            return self._active_snapshot.get("main_api_key", "")
        assigned = getattr(self, "_api_key_assignments", {}).get("main")
        if assigned in getattr(self, "_api_key_profiles", {}):
            return (credential_store.load_key(f"api_profile_{assigned}") or "").strip()
        if self._main_custom_active():
            return self.main_custom_key_entry.get().strip()
        return self.api_key_entry.get().strip()

    def _main_api_base_url(self):
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            return self._active_snapshot.get("main_api_base_url", None)
        assignments = self.__dict__.get("_api_key_assignments", {})
        profiles = self.__dict__.get("_api_key_profiles", {})
        assigned = assignments.get("main") if isinstance(assignments, dict) else None
        profile = profiles.get(assigned) if isinstance(profiles, dict) else None
        if profile:
            if profile["provider"] == "openai_official":
                return "https://api.openai.com/v1"
            return _normalize_api_base_url(profile.get("base_url", ""))
        if self._main_custom_active():
            u = self.main_custom_url_var.get().strip()
            return _normalize_api_base_url(u) if u else None
        return _normalize_api_base_url(self.api_url_var.get())

    def _main_model_name(self) -> str:
        if threading.current_thread() is not threading.main_thread() and hasattr(self, "_active_snapshot") and self._active_snapshot:
            return self._active_snapshot.get("main_model_name", "")
        assignments = self.__dict__.get("_api_key_assignments", {})
        profiles = self.__dict__.get("_api_key_profiles", {})
        assigned = assignments.get("main") if isinstance(assignments, dict) else None
        profile = profiles.get(assigned) if isinstance(profiles, dict) else None
        if profile:
            return profile["model"]
        if self._main_custom_active():
            return self.main_custom_model_var.get().strip()
        return self.model_var.get()

    def _sync_main_custom_visibility(self):
        """Özel sağlayıcı alanlarını switch durumuna göre göster/gizler.

        Özel sağlayıcı (reseller) açıkken Batch modu seçilemez — gerçek
        OpenAI Batch API'si resmi OpenAI dışında desteklenmiyor (kullanıcı
        2026-07-20: yanlışlıkla batch seçip nasıl çalıştığını sormuştu; aslında
        hiç batch çalışmamıştı, mode_var sadece açılışta yüklenen eski ayarı
        gösteriyordu). Açıkken zaten Anında'ya (sync) zorlanır ve Batch radio'su
        pasifleştirilir; kapanınca tekrar seçilebilir olur."""
        custom_active = bool(getattr(self, "main_custom_var", None) and self.main_custom_var.get())
        if custom_active:
            self.main_custom_frame.grid()
        else:
            self.main_custom_frame.grid_remove()
        batch_radio = getattr(self, "_mode_batch_radio", None)
        if batch_radio:
            if custom_active:
                if self.mode_var.get() == "batch":
                    self.mode_var.set("sync")
                    self._on_mode_change()
                batch_radio.configure(state="disabled")
            else:
                batch_radio.configure(state="normal")

    def _on_main_custom_changed(self):
        """Switch tıklanınca: görünürlüğü güncelle + AYARLARI HEMEN KAYDET.

        Diğer toggle'lardan farklı olarak burada anında kaydediyoruz — kullanıcı
        switch'i açıp alanları doldurduktan sonra çeviri hiç başlatmadan/uygulamayı
        düzgün kapatmadan ekranı değiştirebilir; _start()/_resume()/_on_close()'a
        kadar beklemek bu durumda dolduruşu sessizce kaybettirir."""
        self._sync_main_custom_visibility()
        try:
            self._save_settings(save_credentials=False)
        except Exception as exc:
            _log_persistence_failure(
                self, "Özel sağlayıcı ayarı kaydedilemedi", exc)

    def _on_main_custom_key_focus_out(self, _event=None):
        self._save_settings(save_credentials=False)
        key = self.main_custom_key_entry.get().strip()
        lock = getattr(self, "_credential_save_lock", None)
        if lock is None:
            lock = threading.Lock()
            self._credential_save_lock = lock
        generation = getattr(self, "_main_custom_key_save_generation", 0) + 1
        self._main_custom_key_save_generation = generation

        def _persist():
            with lock:
                if generation != getattr(
                        self, "_main_custom_key_save_generation", generation):
                    return
                if key:
                    if not credential_store.save_key("main_custom", key):
                        self._log(
                            "keyring kullanılamıyor, anahtar obfuscated fallback dosyada saklandı",
                            "warn")
                else:
                    credential_store.delete_key("main_custom")

        self._start_worker(_persist)

    def _on_helper_provider_change_role(self, role: str):
        pass

    def _helper_display_name(self, role: str):
        if threading.current_thread() is not threading.main_thread():
            models = (getattr(self, "_active_snapshot", None) or {}).get("helper_models") or {}
            if role in models:
                return models[role]
        return self._helper_model_config(role).label

