    def _restore_advanced_settings(self, snapshot):
        for key, value in snapshot.items():
            if value is not None:
                setattr(self, key, value)

    # ── Progress Tracking ─────────────────────────────────────────────────────
    def _start_elapsed_timer(self):
        """Start tracking elapsed time."""
        self._start_time = time.time()
        self._update_elapsed_display()

    def _stop_elapsed_timer(self):
        """Stop tracking elapsed time."""
        if self._elapsed_tick:
            self.after_cancel(self._elapsed_tick)
            self._elapsed_tick = None
        self._start_time = None

    def _update_elapsed_display(self):
        """Update elapsed time display every 1 second."""
        if self._start_time is None:
            return
        elapsed = time.time() - self._start_time
        mins, secs = divmod(int(elapsed), 60)
        hrs, mins = divmod(mins, 60)
        if hrs > 0:
            text = f"{hrs}h {mins}m"
        else:
            text = f"{mins}m {secs}s"

        def update():
            try:
                self.elapsed_lbl.configure(text=text)
            except Exception:
                pass

        _post_ui(self, update)

        self._elapsed_tick = self.after(1000, self._update_elapsed_display)

    def _update_progress_speed(self, total_processed: int, total_items: int):
        """Calculate and display processing speed (items/min)."""
        if self._start_time is None or total_processed == 0:
            return

        elapsed_secs = time.time() - self._start_time
        if elapsed_secs < 1:
            return

        # Calculate items per minute
        speed = (total_processed / elapsed_secs) * 60

        def update():
            try:
                if speed < 1:
                    self.speed_lbl.configure(text=f"{speed:.1f} item/m")
                else:
                    self.speed_lbl.configure(text=f"{speed:.0f} item/m")
            except Exception:
                pass

        _post_ui(self, update)

    def _calculate_eta(self, total_processed: int, total_items: int) -> str:
        """Calculate ETA based on current speed."""
        if self._start_time is None or total_processed == 0:
            return ""

        elapsed_secs = time.time() - self._start_time
        if elapsed_secs < 1:
            return ""

        remaining = total_items - total_processed
        if remaining <= 0:
            return "Tamamlanıyor..."

        avg_speed = total_processed / elapsed_secs  # items per second
        if avg_speed == 0:
            return ""

        eta_secs = remaining / avg_speed
        if eta_secs < 60:
            return f"ETA: {int(eta_secs)}s"
        elif eta_secs < 3600:
            mins = int(eta_secs / 60)
            secs = int(eta_secs % 60)
            return f"ETA: {mins}m {secs}s"
        else:
            hrs = int(eta_secs / 3600)
            mins = int((eta_secs % 3600) / 60)
            return f"ETA: {hrs}h {mins}m"

    # ── Stat Card Animations ──────────────────────────────────────────────────
    def _animate_stat(self, attr: str, target_value: int, duration_ms: int = 400):
        """Smoothly animate stat card number to target value."""
        lbl = getattr(self, f"{attr}_lbl", None)
        if not lbl:
            return

        start_value = 0
        try:
            current_text = getattr(self, f"{attr}_var").get()
            if current_text != "—":
                start_value = int(current_text)
        except (ValueError, AttributeError):
            pass

        if start_value == target_value:
            getattr(self, f"{attr}_var").set(str(target_value))
            return

        steps = max(10, int(duration_ms / 30))  # ~30ms per frame
        step_size = (target_value - start_value) / steps
        current_step = 0

        def animate_frame():
            nonlocal current_step
            if current_step >= steps:
                getattr(self, f"{attr}_var").set(str(target_value))
                return

            current_step += 1
            current_val = int(start_value + step_size * current_step)
            getattr(self, f"{attr}_var").set(str(current_val))
            self.after(30, animate_frame)

        animate_frame()

    def _update_token_sparkline(self):
        """Draw a mini sparkline graph in the token card canvas."""
        canvas = getattr(self, "stat_tokens_canvas", None)
        if not canvas:
            return

        canvas.delete("all")

        if not self._token_sparkline_points or len(self._token_sparkline_points) < 2:
            return

        # Get canvas dimensions
        w = canvas.winfo_width()
        h = canvas.winfo_height()
        if w <= 1 or h <= 1:
            return

        points = self._token_sparkline_points[-20:]  # Last 20 samples
        if not points:
            return

        min_val = min(points)
        max_val = max(points)
        val_range = max_val - min_val if max_val > min_val else 1

        # Scale points to canvas
        scaled = []
        for i, val in enumerate(points):
            x = (i / (len(points) - 1)) * (w - 20) + 10 if len(points) > 1 else w / 2
            y = h - 8 - ((val - min_val) / val_range) * (h - 16)
            scaled.append((x, y))

        # Draw line
        if len(scaled) > 1:
            for i in range(len(scaled) - 1):
                x1, y1 = scaled[i]
                x2, y2 = scaled[i + 1]
                canvas.create_line(x1, y1, x2, y2, fill=YELLOW, width=2)

        # Draw points
        for x, y in scaled:
            canvas.create_oval(x-2, y-2, x+2, y+2, fill=YELLOW, outline=YELLOW)

    # ── Kontrol ───────────────────────────────────────────────────────────────
    def _validate(self):
        key = self._main_api_key()
        if len(key) < 10:
            messagebox.showerror("Hata", "API anahtarını girin.")
            return None
        if self._main_custom_active():
            if not self._main_api_base_url():
                messagebox.showerror("Hata", "Özel sağlayıcı Base URL alanını girin.")
                return None
            if not self._main_model_name():
                messagebox.showerror("Hata", "Özel sağlayıcı model adını girin.")
                return None
        hybrid = self.mode_var.get() == "batch" and self.hybrid_var.get()
        if hybrid or any((self.critic_var.get(), self.polish_var.get(),
                          self.native_var.get(), self.qc_var.get())):
            roles = []
            if hybrid:                                  roles.append("analysis")
            if self.critic_var.get():                  roles.append("critic")
            if self.polish_var.get():                  roles.append("polish")
            if self.native_var.get():                  roles.append("critic")
            if self.qc_var.get():                      roles.append("qc")
            for role in roles:
                hkey = self._helper_api_key(role)
                if not hkey or len(hkey) < 10:
                    messagebox.showerror(
                        "Hata",
                        f"Yardımcı API anahtarı gerekli: {role} ({self._helper_display_name(role)})")
                    return None
        return key

    def _provider_model_preflight(self, targets: list) -> bool:
        shuai_targets = [
            target for target in targets if _is_shuai_api_route(target[2])
        ]
        if not shuai_targets:
            return True
        self._set_phase("API Ön Kontrolü", "model ve grup erişimi doğrulanıyor")
        self._set_status("SHUAI model/grup uygunluğu kontrol ediliyor")
        self._log(
            f"API ön kontrolü: {len(shuai_targets)} etkin SHUAI model rotası "
            "token harcamadan doğrulanıyor...", "info")
        grouped = {}
        for label, key, base_url, model in shuai_targets:
            grouped.setdefault((key, base_url.rstrip("/")), []).append((label, model))
        for (key, base_url), routes in grouped.items():
            try:
                client = OpenAI(api_key=key, base_url=base_url)
                client = client.with_options(max_retries=0, timeout=30.0)
                visible = _visible_model_ids(client.models.list())
            except Exception as exc:
                from provider_retry import _is_transient_provider_error
                if _is_transient_provider_error(exc):
                    self._log(
                        "API ön kontrolü geçici olarak tamamlanamadı; asıl isteklerin "
                        f"görünür yeniden deneme düzeni kullanılacak: {exc}", "warn")
                    continue
                self._log(
                    f"API ön kontrolü başarısız; ücretli çeviri başlatılmadı: {exc}",
                    "err")
                return False
            missing = [(label, model) for label, model in routes if model not in visible]
            if missing:
                detail = ", ".join(f"{label}: {model}" for label, model in missing)
                self._log(
                    "API ön kontrolü: seçili anahtar/grup şu modeli göstermiyor; "
                    f"ücretli çeviri başlatılmadı ({detail}).", "err")
                return False
        self._log("API ön kontrolü tamamlandı; etkin modeller grupta görünüyor.", "ok")
        return True


    def _show_cost_estimate(self):
        """Hesaplanan tokenlara ve seçili modellere göre yaklaşık maliyet dökümü göster."""
        paths = self._get_srt_files()
        if not paths:
            messagebox.showwarning("Uyarı", "Lütfen önce SRT dosyası ekleyin.")
            return

        total_chars = 0
        for p in paths:
            try:
                blocks = list(parse_subtitle(p))
                for b in blocks:
                    total_chars += len(b[2])
            except Exception as e:
                self._log(f"Maliyet tahmini atlandı: {p}: {e}", "warn")

        if total_chars == 0:
            messagebox.showwarning("Uyarı", "Seçili dosyalarda geçerli altyazı bulunamadı.")
            return

        # Çok kaba token tahmini (yaklaşık her 4 karakter 1 token)
        base_tokens = total_chars / 4.0

        def estimate(model_name, base_url, input_factor, output_factor):
            price = _verified_token_price(model_name, base_url)
            if price is None:
                return None
            return base_tokens * (input_factor + output_factor) / 1_000_000 * price

        def add_estimate(details, label, model_name, base_url,
                         input_factor, output_factor):
            cost = estimate(
                model_name, base_url, input_factor, output_factor)
            if cost is None:
                details.append(
                    f"└ {label} ({model_name}): sağlayıcı panelinden doğrulanmalı")
                return 0.0, True
            details.append(f"└ {label} ({model_name}): ~${cost:.4f}")
            return cost, False

        main_model = self._main_model_name()
        main_cost = estimate(
            main_model, self._main_api_base_url(), 1.5, 1.1)
        unknown_cost = main_cost is None

        details = [f"Tahmini Toplam Dosya: {len(paths)}",
                   f"Tahmini Toplam Karakter: {total_chars:,}",
                   f"Tahmini Baz Token: {int(base_tokens):,}\n",
                   (f"Ana Çeviri Modeli ({main_model}): ~${main_cost:.4f}"
                    if main_cost is not None else
                    f"Ana Çeviri Modeli ({main_model}): sağlayıcı panelinden doğrulanmalı")]

        total_cost = main_cost or 0.0

        # Helper passes
        hybrid = self.hybrid_var.get()
        
        if hybrid:
            # Analysis
            an_m = self._helper_api_model("analysis")
            an_cost, unknown = add_estimate(
                details, "Ön Analiz", an_m,
                self._helper_api_base_url("analysis"), 1.0,
                500 / max(base_tokens, 1))
            total_cost += an_cost
            unknown_cost |= unknown

        if self.critic_var.get():
            cr_m = self._helper_api_model("critic")
            cr_cost, unknown = add_estimate(
                details, "Critic Pass", cr_m,
                self._helper_api_base_url("critic"), 2.0, 0.1)
            total_cost += cr_cost
            unknown_cost |= unknown

        if self.polish_var.get():
            pl_m = self._helper_api_model("polish")
            pl_cost, unknown = add_estimate(
                details, "Polish Pass", pl_m,
                self._helper_api_base_url("polish"), 1.2, 1.0)
            total_cost += pl_cost
            unknown_cost |= unknown

        if self.native_var.get():
            nt_m = self._helper_api_model("critic")
            nt_cost, unknown = add_estimate(
                details, "Native Reader", nt_m,
                self._helper_api_base_url("critic"), 2.0, 0.1)
            total_cost += nt_cost
            unknown_cost |= unknown

        if self.qc_var.get():
            qc_m = self._helper_api_model("qc")
            qc_cost, unknown = add_estimate(
                details, "QC Pass", qc_m,
                self._helper_api_base_url("qc"), 2.0, 0.1)
            total_cost += qc_cost
            unknown_cost |= unknown

        total_label = "Doğrulanmış USD ara toplam" if unknown_cost else "Genel Toplam Maliyet"
        details.append(f"\n{total_label}: ~${total_cost:.4f}")
        if unknown_cost:
            details.append(
                "Reseller/custom rota oranı ve para birimi yerel fiyat tablosundan "
                "doğrulanamaz; kesin toplam için sağlayıcı panelini kullanın.")

        messagebox.showinfo("Tahmini Maliyet Hesabı", "\n".join(details))

    def _start(self):

        if getattr(self, "_folder_scan_busy", False):
            self._set_status("Klasör taraması tamamlanmadan çeviri başlatılamaz.")
            self._log("Klasör taraması sürerken çeviri başlatılamaz.", "warn")
            return
        if not self._is_running:
            with self._batch_lock:
                active_batches = bool(self._active_batches)
            pending_batches = _pending_recovery_batch_ids()
            if (active_batches or pending_batches or _pending_regular_batch_intents()
                    or _pending_hybrid_batch_intents()):
                messagebox.showwarning(
                    "Bekleyen Batch Var",
                    "Önce bekleyen batch'i 'Batch'i Devam Ettir' ile tamamlayın "
                    "veya iptal edin. Yeni ücretli batch başlatılmadı.",
                )
                return
            if not _claim_translation_run_owner():
                messagebox.showwarning(
                    "Başka Çeviri Çalışıyor",
                    "Başka bir uygulama penceresinde çeviri sürüyor. Çift istek "
                    "ve gereksiz token harcamasını önlemek için başlatılmadı.",
                )
                return
        if self._is_running:          # double-click guard — ikinci tık state'i bozmasın
            return
        self._is_running = True       # TOCTOU: hemen set et — _validate boyunca ikinci tık блокlanır
        try:
            key = self._validate()
        except Exception:
            self._is_running = False
            _release_translation_run_owner()
            raise
        if not key:
            self._is_running = False
            _release_translation_run_owner()
            return
        # NOT: Burada eskiden "çıkış klasörü girişle aynı olamaz — kaynakların üzerine
        # yazılır" diye sert bir engel vardı. Çıktı-klasörü kuralları (2026-07-10) bunu
        # GEÇERSİZ kıldı: girdi==çıktı artık kaynağın yanına DEĞİL, <girdi>/ÇIKTI/ içine
        # yazar (Kural 1, bkz. _resolve_output_path) — üzerine yazma riski yok. Engel
        # dururken Kural 1'e hiç ulaşılamıyordu (kullanıcı isteği ölü koda dönüşmüştü).
        # Ayrıca get_subtitle_files ÇIKTI alt-klasörünü girdiden dışlar, yani yeniden
        # çalıştırmada program kendi çıktısını kaynak sanmaz.
        self._save_settings()
        App._retarget_project_memory(self)
        self._stop_flag   = False
        from provider_retry import configure_provider_wait_hooks
        configure_provider_wait_hooks(
            cancel_check=lambda: self._stop_flag,
            wait_callback=self._provider_wait_callback,
        )
        self._pause_btw_files.set()  # start unpaused
        self._token_total = 0
        self._token_cached = 0
        self._cost_total  = 0.0
        self._unknown_cost_tokens = 0
        with self._batch_lock:
            self._active_batches.clear()   # onceki durdurulan kosudan kalanlari temizle
        self._tm.reset_session_hits()
        for attr in ("stat_tokens_var", "stat_done_var", "stat_fail_var", "stat_tm_var"):
            getattr(self, attr).set("0")
        self._set_eta("")
        self._set_running(True)

        hybrid = self.hybrid_var.get()
        mode   = self.mode_var.get()

        if hybrid:
            mm = self._helper_api_key("analysis")
            if not mm:
                messagebox.showerror("Hata", "Analiz / kalite veya OpenAI API key girin veya Hybrid modu kapatın.")
                self._set_running(False)
                return
            ext_path = self.ext_project_path_var.get().strip()
            try:
                import hybrid_translate as ht
                ext_path = ht.resolve_subtitle_project_path(ext_path)
                self.ext_project_path_var.set(ext_path)
            except Exception as e:
                messagebox.showerror("Hata", f"External Project Path geçersiz:\n{e}")
                self._set_running(False)
                return

        srt_files = self._get_srt_files()
        if not srt_files:
            messagebox.showwarning("Uyarı", "Çevrilecek altyazı dosyası kalmadı.", parent=self)
            self._set_running(False)
            return
        if srt_files and self._start_file_integrity_preflight(srt_files):
            return
        if (srt_files and _lang_iso639_1(self.tgt_var.get()) == "tr"
                and self._start_turkish_source_preflight(srt_files)):
            return
        if (
            srt_files
            and not self._language_preflight_done
            and self._auto_source_language_files(srt_files)
        ):
            if self._start_source_language_preflight(key, srt_files):
                return
        if (
            srt_files
            and not self._content_type_preflight_done
            and self._auto_content_type_files(srt_files)
        ):
            if self._start_content_type_preflight(key, srt_files):
                return
        self._language_preflight_done = False
        self._content_type_preflight_done = False
        self._file_integrity_preflight_done = False
        self._active_snapshot = _refresh_start_snapshot(
            getattr(self, "_active_snapshot", None),
            self._take_run_snapshot())
        provider_preflight_targets = _provider_preflight_targets(
            self._active_snapshot)
        begin_run = getattr(self, "_begin_run_record", None)
        if callable(begin_run):
            begin_run(srt_files)

        def _guarded_worker(target, *args):
            try:
                if not self._provider_model_preflight(provider_preflight_targets):
                    self._set_status("API modeli/grubu kullanılamıyor; çeviri başlatılmadı.")
                    self._set_running(False)
                    return
                target(*args)
            except Exception as e:
                self._log_exc("Arka plan is parcacigi hatasi", e)
                self._set_status(f"Hata: {e}")
                self._set_eta("")
                self._set_running(False)

        if hybrid and mode == "batch":
            App._start_worker(self,
                _guarded_worker, (self._run_hybrid, key, mm, ext_path))
        elif mode == "sync":
            App._start_worker(self, _guarded_worker, (self._run_sync, key))
        else:
            App._start_worker(self, _guarded_worker, (self._run_batch, key))

    def _resume(self):
        if getattr(self, "_is_running", False):
            return
        key = self._validate()
        if not key:
            return
        App._reconcile_regular_batch_intents(self, key)
        App._reconcile_hybrid_batch_intents(self, key)
        bid_path = _batch_id_path()
        if not bid_path.exists():
            messagebox.showerror("Hata", "batch_id.txt bulunamadı.")
            return
        self._save_settings()
        App._retarget_project_memory(self)
        self._stop_flag = False
        self._active_snapshot = self._take_run_snapshot()
        self._pause_btw_files.set()  # resume: start unpaused
        with self._batch_lock:
            self._active_batches.clear()
        raw = bid_path.read_text(encoding="utf-8")
        batch_ids = []
        for line in raw.splitlines():
            line = line.strip()
            if not line:
                continue
            parts = re.findall(r"batch_[A-Za-z0-9]+", line) or [line]
            batch_ids.extend(parts)
        batch_ids = list(dict.fromkeys(batch_ids))
        batch_ids = [bid for bid in batch_ids if is_safe_batch_id(bid)]
        if not batch_ids:
            messagebox.showerror("Hata", "batch_id.txt boş veya bozuk.")
            return

        from provider_retry import configure_provider_wait_hooks
        configure_provider_wait_hooks(
            cancel_check=lambda: self._stop_flag,
            wait_callback=self._provider_wait_callback,
        )
        self._token_total = 0
        self._token_cached = 0
        self._cost_total = 0.0
        self._unknown_cost_tokens = 0
        self._tm.reset_session_hits()
        for attr in ("stat_tokens_var", "stat_done_var", "stat_fail_var", "stat_tm_var"):
            getattr(self, attr).set("0")
        self._set_eta("")
        if not _claim_translation_run_owner():
            messagebox.showwarning(
                "Başka Çeviri Çalışıyor",
                "Başka bir uygulama penceresinde çeviri veya batch kurtarması "
                "sürüyor. Aynı batch'in iki kez işlenmesini önlemek için devam "
                "ettirilmedi.",
            )
            return
        self._set_running(True)
        begin_run = getattr(self, "_begin_run_record", None)
        if callable(begin_run):
            begin_run(self._get_srt_files(), resume=True)

        def _guarded_resume():
            try:
                self._resume_batches(key, batch_ids)
            except Exception as e:
                self._log(f"Resume hatası: {e}", "err")
                self._log_exc("Resume", e)
                try:
                    self._set_running(False)
                except Exception:
                    pass

        try:
            App._start_worker(self, _guarded_resume)
        except Exception:
            self._set_running(False)
            raise

    def _import_jsonl(self):
        """Manuel indirilen batch JSONL → SRT dönüştürücü."""
        self.attributes("-topmost", True)
        jsonl_path = filedialog.askopenfilename(
            parent=self, title="Batch Output JSONL seç",
            filetypes=[("JSONL", "*.jsonl"), ("Tümü", "*.*")])
        self.attributes("-topmost", False)
        if not jsonl_path:
            return

        self.attributes("-topmost", True)
        orig_path = filedialog.askopenfilename(
            parent=self, title="Orijinal SRT dosyasını seç (timestamps için)",
            filetypes=[("SRT", "*.srt"), ("Tümü", "*.*")])
        self.attributes("-topmost", False)
        if not orig_path:
            return

        self.attributes("-topmost", True)
        out_path = filedialog.asksaveasfilename(
            parent=self, title="Çevrilmiş SRT olarak kaydet",
            defaultextension=".srt",
            filetypes=[("SRT", "*.srt")],
            initialfile=Path(orig_path).stem + "_tr.srt")
        self.attributes("-topmost", False)
        if not out_path:
            return

        self._set_running(True)
        src = self.src_var.get()
        tgt = self.tgt_var.get()
        clean_sdh_on = self.clean_sdh_var.get()
        polish_on = self.polish_var.get()
        profanity = self.profanity_var.get()
        schema = self._get_schema()

        def _do():
            api_key = self._main_api_key()
            b_url = self._main_api_base_url()
            self._set_status("JSONL → SRT dönüştürülüyor...")
            try:
                # Timestamps from original SRT
                ts_map = {}
                cues = list(parse_srt(orig_path))
                for block in cues:
                    ts_map[block[0].strip()] = block[1].strip()

                # Translations from JSONL
                trans = {}
                rejected_ids = set()
                errors = 0
                total_tokens = 0
                with open(jsonl_path, encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        # Tek bozuk satır TÜM dönüştürmeyi kaybetmesin — atla, gerisi işlensin
                        try:
                            obj = json.loads(line)
                            if obj.get("error"):
                                errors += 1
                                continue
                            body = obj["response"]["body"]
                            if body.get("usage"):
                                total_tokens += body["usage"].get("total_tokens", 0)
                            choices = body.get("choices") or []
                            raw = ((choices[0].get("message") or {}).get("content") or "").strip() if choices else ""
                        except Exception as e:
                            errors += 1
                            self._log(f"JSONL satırı atlanıyor (parse hatası): {e}", "warn")
                            continue
                        cid_pp = obj.get("custom_id", "?")
                        parsed = _merge_jsonl_translation_payload(
                            trans, rejected_ids, raw, set(ts_map))
                        if parsed.parse_mode == "invalid":
                            self._log(f"Post-process {cid_pp}: JSON parse başarısız "
                                      f"(ham: {raw[:60]!r})", "err")
                        if parsed.unexpected_ids:
                            self._log(
                                f"Post-process {cid_pp}: kaynakta olmayan cue kimlikleri "
                                f"reddedildi ({', '.join(sorted(parsed.unexpected_ids)[:8])})",
                                "err")
                        if parsed.duplicate_ids:
                            self._log(
                                f"Post-process {cid_pp}: tekrarlı cue kimlikleri "
                                f"reddedildi ({', '.join(sorted(parsed.duplicate_ids)[:8])})",
                                "err")

                self._update_batch_tokens(total_tokens)
                self._log(f"JSONL: {len(trans)} satır çevrilmiş | {errors} hatalı chunk | "
                          f"{len(rejected_ids)} kimlik bütünlüğü reddi | "
                          f"{len(ts_map)} timestamp", "info")

                # Build blocks using original timestamps
                blocks = []
                for idx_str in sorted(ts_map, key=lambda x: int(x) if x.isdigit() else 0):
                    ts  = ts_map[idx_str]
                    txt = trans.get(idx_str, "[HATA]")
                    blocks.append((idx_str, ts, txt))
                _raw_map_pre = _raw_src_map_from_cues(cues)
                _repair_locked_terms = self._get_locked_terms_dict(orig_path, tgt)
                missing_ids = _partial_missing_translation_ids(
                    blocks, _raw_map_pre, cues,
                    locked_terms=_repair_locked_terms,
                    source_language=src)

                # Apply SDH cleaning if enabled
                if clean_sdh_on:
                    blocks = clean_sdh(
                        blocks, src_map=_src_map_from_cues(cues),
                        source_driven=True)

                # Apply Polish Pass if enabled
                if polish_on and blocks:
                    import hybrid_translate as ht
                    self._set_status("Doğallaştırma...")
                    self._log(f"Polish Pass başlıyor ({len(blocks)} satır)...", "info")
                    _mm_key = self._helper_api_key("polish")
                    _mm_url = self._helper_api_base_url("polish")
                    _mm_mdl = self._helper_api_model("polish")
                    _polish_status = {}
                    blocks = self._polish_pass(
                        blocks, tgt, _mm_key, _mm_url, _mm_mdl,
                        src_map=_src_map_from_cues(cues),
                        locked_terms=self._get_locked_terms_dict(orig_path, tgt),
                        status_out=_polish_status)
                    if _polish_status.get("status") == "completed":
                        self._log("Polish Pass tamamlandı", "ok")
                    blocks, _ = ht.final_consistency_sweep(
                        cues, blocks, log_fn=self._log,
                        locked_terms=self._get_locked_terms_dict(orig_path, tgt),
                        apply_changes=not bool(self._snap_get(
                            "quality_report_only", True)))

                # Çevrilemeyen satırları sync ile onarma denemesi
                if missing_ids:
                    try:
                        _repair_client = OpenAI(api_key=api_key, base_url=b_url if b_url else None)
                        blocks, _n_repaired = _repair_untranslated_sync(
                            blocks, _raw_map_pre, _repair_client,
                            src_lang=src, tgt_lang=tgt,
                            model=self._main_model_name(),
                            schema=schema, profanity=profanity,
                            log_fn=self._log,
                            token_cb=_app_token_callback(
                                self, self._main_model_name(),
                                "Eksik Cue API Onarımı", base_url=b_url,
                                file_path=orig_path),
                            source_cues=cues,
                            cancel_check=lambda: self._stop_flag,
                            cancel_context=self.__dict__.get(
                                "_helper_request_canceller"),
                            locked_terms=_repair_locked_terms,
                            enabled=bool(App._run_setting(
                                self, "repair_missing", "repair_missing_var", False)),
                            retry_wait_fn=lambda delay, cancelled: (
                                App._repair_retry_wait(self, delay, cancelled)))
                    except Exception as repair_error:
                        self._log(f"JSONL eksik cue onarımı başarısız: {repair_error}", "warn")

                if self._stop_flag:
                    self._log(
                        "JSONL dönüştürme durduruldu; eksik cue varken nihai dosya yazılmadı.",
                        "warn")
                    return

                if clean_sdh_on:
                    blocks = clean_sdh(
                        blocks, src_map=_src_map_from_cues(cues),
                        source_driven=True)

                blocks, _n_filled_save = _finalize_translation_blocks(
                    blocks, _raw_map_pre, source_cues=cues,
                    log_fn=self._log)
                remaining_missing_ids = _partial_missing_translation_ids(
                    blocks, _raw_map_pre, cues,
                    locked_terms=_repair_locked_terms,
                    source_language=src)

                _delivery_blocks = _prepare_upload_ready_blocks(
                    self._maybe_merge_cues(blocks, file_path=orig_path), tgt, self._log,
                    source_cues=cues)
                missing = len(remaining_missing_ids)
                _write_path = _partial_output_path(out_path) if missing else Path(out_path)
                write_srt(_write_path, _delivery_blocks, tgt)
                _quarantined = (
                    self._maybe_quarantine_incomplete_final(out_path) if missing else None)
                _delivery_failed = False
                if not missing:
                    _delivery_audit = _subtitle_delivery_audit(
                        orig_path, str(_write_path), tgt, src)
                    if _delivery_audit_has_hard_error(_delivery_audit):
                        _delivery_failed = True
                        _quarantined = self._maybe_quarantine_incomplete_final(_write_path)
                        if _quarantined:
                            _write_path = _quarantined
                        if self._delivery_report_only_enabled():
                            self._log(
                                "JSONL: yazılan SRT inceleme gerektiriyor; çıktı "
                                "yerinde bırakıldı (Yalnız Raporla).", "warn")
                        else:
                            self._log(
                                "JSONL: yazılan SRT teslim denetiminden geçmedi; "
                                f"çıktı karantinaya alındı{f': {Path(_quarantined).name}' if _quarantined else ''}.",
                                "err")
                if missing:
                    self._log(
                        f"JSONL: {missing} eksik çeviri kaldı; kısmi çıktı "
                        f"{_write_path.name} olarak ayrıldı ve tamamlandı sayılmadı.",
                        "err")
                    if _quarantined:
                        self._log(
                            f"Önceki eksik nihai çıktı karantinaya alındı: "
                            f"{_quarantined.name}", "warn")
                elif not _delivery_failed:
                    self._log(
                        f"Kaydedildi: {_write_path}  ({len(blocks)} satır)", "ok")
                if _delivery_failed:
                    _post_ui(self, messagebox.showerror, "Teslim Denetimi Başarısız",
                              f"Yazılan SRT doğrulanamadığı için teslim edilmedi.\n\n"
                              + (f"İnceleme konumu:\n{_write_path}"
                                 if self._delivery_report_only_enabled() else
                                 f"Karantina:\n{_write_path}"))
                elif missing:
                    _post_ui(self, messagebox.showwarning, "Kısmi Sonuç",
                                  f"{len(blocks)} satır SRT'ye dönüştürüldü ancak "
                                  f"{missing} satır eksik kaldı.\n\nKonum:\n{_write_path}")
                else:
                    _post_ui(self, messagebox.showinfo, "Tamamlandı",
                                  f"{len(blocks)} satır SRT'ye dönüştürüldü!\n\n"
                                  f"Konum:\n{_write_path}")
            except Exception as e:
                self._log(f"Dönüştürme hatası: {e}", "err")
                # 'e' except bloğu bitince silinir; after() lambda'yı SONRA çalıştırır —
                # mesajı default argümana bağla, yoksa lambda NameError verir
                _post_ui(self, messagebox.showerror, "Hata", str(e))
            finally:
                self._set_running(False)
                self._set_status("Hazır.")

        App._start_worker(self, _do)

    # ── Aktif batch muhasebesi (durdururken uzak iptal için) ──────────────────
    def _register_batch(self, batch_id: str, api_key: str, base_url: str = ""):
        if not is_safe_batch_id(batch_id):
            return
        with self._batch_lock:
            self._active_batches[batch_id] = (api_key, base_url or "")
            self._write_batch_owner()

    def _unregister_batch(self, batch_id: str):
        with self._batch_lock:
            self._active_batches.pop(batch_id, None)
            self._write_batch_owner()

    def _write_batch_owner(self):
        """Bu sürecin ÜZERİNDE ÇALIŞTIĞI batch'leri işaretler (batch_owner_<pid>.json).

        Başka bir uygulama örneği açılış kontrolünde bunu okur ve canlı sahibi olan
        batch'ler için 'Yarım Kalan Batch'ler' penceresini AÇMAZ — bkz.
        _live_owned_batch_ids. YALNIZCA kendi pid dosyamıza dokunulur; başka bir sürecin
        kilidi asla ezilmez/silinmez. Aktif batch kalmayınca kendi dosyamız silinir."""
        import os as _os
        with self._batch_lock:
            try:
                p = state_path(__file__, f"{_BATCH_OWNER_PREFIX}{_os.getpid()}.json")
                ids = sorted(self._active_batches.keys())
                if not ids:
                    p.unlink(missing_ok=True)
                    self._batch_owner_marker_failed = False
                    return True
                pid = _os.getpid()
                data = {"pid": pid, "ts": time.time(), "batch_ids": ids}
                marker = _process_start_marker(pid)
                if marker:
                    data["process_start"] = marker
                atomic_write_json(p, data)
                self._batch_owner_marker_failed = False
                return True
            except Exception as exc:
                self._batch_owner_marker_failed = bool(self._active_batches)
                self._log(
                    "Canlı batch sahiplik işareti yazılamadı; başka pencerenin "
                    f"kurtarma verisini silmemesi için açılış koruması devrede ({exc}).",
                    "err")
                return False

    def _clear_batch_recovery(self, batch_ids):
        """Verilen batch'lerin kurtarma dosyalarını (batch_fmap_<id>.json) siler ve
        bu id'leri batch_id.txt'den çıkarır (dosya boşalırsa siler).

        Tamamlanan işten sonra çağrılır — yoksa '↺ Batch'i Devam Ettir' zaten biten
        işi yeniden indirip (hybrid'de) işlenmiş çıktının üzerine yazardı."""
        base = state_dir(__file__)
        done = {str(b).strip() for b in (batch_ids or [])
                if is_safe_batch_id(b)}
        if not done:
            return
        try:
            mutate_batch_ids(_batch_id_path(), remove=done)
        except Exception:
            return
        for bid in done:
            try:
                (base / f"batch_fmap_{bid}.json").unlink(missing_ok=True)
            except Exception:
                pass

    def _record_batch_terminal_state(self, ht, session, filepath, status: str) -> bool:
        if status not in {"failed", "removed"}:
            raise ValueError("terminal batch status required")
        try:
            ht.update_batch_session(session, filepath, status)
            return True
        except Exception as exc:
            entry = session.setdefault("files", {}).setdefault(str(filepath), {})
            entry["status"] = status
            entry["state_persist_error"] = type(exc).__name__
            self._log(
                f"{Path(filepath).name}: batch kurtarma durumu diske "
                f"yazılamadı ({type(exc).__name__}); diğer dosyalar işlenmeye "
                "devam edecek, bu dosya tamamlandı sayılmayacak.",
                "err",
            )
            return False

    def _cancel_active_batches(self):
        """Açık OpenAI batch'lerini iptal eder + kurtarma dosyalarını temizler.
        UI'ı bloklamamak için arka plan thread'inde çağrılmalı."""
        with self._batch_lock:
            items = list(self._active_batches.items())
        cancelled = []
        for bid, auth in items:
            if isinstance(auth, (tuple, list)):
                key, base_url = auth[0], auth[1] if len(auth) > 1 else ""
            else:
                key, base_url = auth, ""
            try:
                OpenAI(api_key=key, base_url=base_url or None).batches.cancel(bid)
                self._log(f"Batch iptal edildi: {bid}", "ok")
                cancelled.append(bid)
            except Exception as e:
                self._log(f"Batch iptal edilemedi ({bid}): {e}", "warn")
        with self._batch_lock:
            for bid in cancelled:
                self._active_batches.pop(bid, None)
            self._write_batch_owner()
        if cancelled:
            import hybrid_translate as ht
            ht.mark_cancelled_batch_sessions(cancelled)
        self._clear_batch_recovery(cancelled)
    def _toggle_pause_between_files(self):
        if self._pause_btw_files.is_set():
            self._pause_btw_files.clear()
            self.pause_btn.configure(fg_color=PAUSE_BG, text="\u25b6  Devam", hover_color=PAUSE_HOVER)
            self._log("Duraklat\u0131ld\u0131 \u2014 mevcut dosya bitince duracak", "warn")
        else:
            self._pause_btw_files.set()
            self.pause_btn.configure(fg_color=CARD, text="\u23f8  Duraklat", hover_color=BORDER)
            self._log("Devam ediliyor...", "ok")


    def _capture_boundary_quality_settings(self) -> dict:
        if not isinstance(getattr(self, "_active_snapshot", None), dict):
            return {}
        App._unfreeze_run_variable_reads(self)
        try:
            values = {}
            for key, (attr, _label) in _BOUNDARY_QUALITY_VARS.items():
                var = getattr(self, attr, None)
                if var is not None:
                    values[key] = bool(var.get())
            changed = _apply_boundary_quality_values(
                self._active_snapshot, values)
        finally:
            App._freeze_run_variable_reads(self)
        if changed:
            details = ", ".join(
                f"{_BOUNDARY_QUALITY_VARS[key][1]}: "
                f"{'Açık' if new_value else 'Kapalı'}"
                for key, (_old_value, new_value) in changed.items()
            )
            self._log(
                f"Sonraki dosya kalite ayarları güncellendi — {details}", "ok")
        else:
            self._log("Sonraki dosya kalite ayarları değişmedi.", "info")
        return changed

    def _refresh_quality_settings_at_boundary(self) -> dict:
        if threading.current_thread() is threading.main_thread():
            return App._capture_boundary_quality_settings(self)
        if getattr(self, "_ui_queue", None) is None:
            return {}
        completed = threading.Event()
        result = {}

        def _capture():
            try:
                result.update(App._capture_boundary_quality_settings(self))
            finally:
                completed.set()

        _post_ui(self, _capture)
        while not completed.wait(timeout=0.1):
            if (getattr(self, "_stop_flag", False)
                    or getattr(self, "_is_shutting_down", False)):
                return {}
        return result


    def _wait_between_files(self, file_index: int, total_files: int, current_filename: str = "") -> str:
        """Dosya tamamlandıktan sonra, eğer sonraki dosya varsa ve 'Duraklat' düğmesine basılmışsa
        worker iş parçacığını duraklatır.

        Returns:
            "continue": Bir sonraki dosyaya geçilebilir (duraklatılmamış veya kullanıcı Devam'a bastı).
            "stopped":  Kullanıcı 'Durdur' düğmesine bastı (self._stop_flag True oldu).
        """
        import time
        if getattr(self, "_stop_flag", False) or file_index >= total_files - 1:
            return "stopped" if getattr(self, "_stop_flag", False) else "continue"

        was_paused = not self._pause_btw_files.is_set()
        if was_paused:
            fn_label = f" — '{current_filename}' tamamlandı." if current_filename else "."
            self._log(f"Duraklatıldı{fn_label} Devam bekleniyor...", "warn")
            self._set_status("Duraklatıldı — Devam bekleniyor...")

            while not self._pause_btw_files.is_set():
                if getattr(self, "_stop_flag", False):
                    return "stopped"
                self._pause_btw_files.wait(timeout=0.2)

            if getattr(self, "_stop_flag", False):
                return "stopped"

            self._log("Devam ediliyor...", "ok")
            self._set_status("Çeviriliyor...")
            App._refresh_quality_settings_at_boundary(self)

        return "continue"

    def _stop(self):
        self._stop_flag = True
        canceller = self.__dict__.get("_helper_request_canceller")
        if canceller is not None:
            canceller.cancel()
        self._pause_btw_files.set()
        self._log("Durduruluyor...", "warn")
        self._set_status("Durduruluyor...")
        with self._batch_lock:
            n_active = len(self._active_batches)
        if n_active:
            ans = messagebox.askyesno(
                "Durdur",
                f"OpenAI'da bekleyen {n_active} batch de iptal edilsin mi?\n\n"
                "Hayır derseniz batch'ler sunucuda tamamlanır; daha sonra "
                "'↺ Batch'i Devam Ettir' ile sonuçları alabilirsiniz.\n"
                "Evet derseniz iptal edilir (faturalanmayı durdurur).")
            if ans:
                App._start_worker(self, self._cancel_active_batches)

    def _get_srt_files(self):
        if self._selected_files:
            files = list(self._selected_files)
        elif getattr(self, "_input_folder_explicitly_selected", False):
            root = (self.input_var.get() or "").strip()
            if not root:
                return []
            cached_root = str(getattr(self, "_file_list_root", "") or "").strip()
            if (cached_root
                    and os.path.normcase(os.path.abspath(cached_root))
                    == os.path.normcase(os.path.abspath(root))):
                files = list(getattr(self, "_file_list_files", ()) or ())
                output_var = getattr(self, "output_var", None)
                output_path = (output_var.get() if output_var is not None else "") or ""
                same_folder_var = getattr(self, "same_folder_var", None)
                excluded_outputs = _nested_output_exclusions(
                    [root], output_path.strip(),
                    same_folder=bool(same_folder_var and same_folder_var.get()))
                excluded_keys = {
                    os.path.normcase(os.path.abspath(str(path)))
                    for path in excluded_outputs
                }
                if excluded_keys:
                    def _inside_excluded(path):
                        path_key = os.path.normcase(os.path.abspath(str(path)))
                        try:
                            return any(
                                os.path.commonpath([path_key, excluded]) == excluded
                                for excluded in excluded_keys)
                        except ValueError:
                            return False
                    files = [path for path in files if not _inside_excluded(path)]
            else:
                output_var = getattr(self, "output_var", None)
                output_path = (output_var.get() if output_var is not None else "") or ""
                output_path = output_path.strip()
                same_folder_var = getattr(self, "same_folder_var", None)
                same_folder = bool(same_folder_var and same_folder_var.get())
                excluded_outputs = _nested_output_exclusions(
                    [root], output_path, same_folder)
                files = get_subtitle_files(
                    root, recursive=True, exclude_paths=excluded_outputs)
        else:
            files = []
        dedupe = getattr(self, "_dedupe_paths", None)
        files = dedupe(files) if callable(dedupe) else list(dict.fromkeys(files))
        # Dizi hafızası açıkken bölüm sırasına diz (E01 kararları E02'ye aksın)
        if getattr(self, "series_memory_var", None) and self.series_memory_var.get():
            files = series_memory.sort_files_by_episode(files)
        return files

    def _output_selection_roots(self):
        snapshot = getattr(self, "_active_snapshot", None) or {}
        if "selected_folder_roots" in snapshot:
            return snapshot["selected_folder_roots"]
        return tuple(getattr(self, "_selected_folder_roots", ()) or ())

    def _series_mem_for(self, fp: str, *, persistent: bool = False):
        """Dosya için (SeriesMemory, sezon, bölüm) döner; dizi değilse/kapalıysa (None,None,None)."""
        snapshot = getattr(self, "_active_snapshot", None) or {}
        if (snapshot
                and threading.current_thread() is not threading.main_thread()):
            enabled = bool(snapshot.get("series_memory", True))
        else:
            enabled = bool(
                getattr(self, "series_memory_var", None)
                and self.series_memory_var.get())
        if not enabled:
            return None, None, None
        key = series_memory.parse_series_key(fp)
        if key is None:
            return None, None, None
        slug, season, ep = key
        selected = snapshot.get("selected_files") if snapshot else getattr(self, "_selected_files", ())
        input_dir = (str(series_memory.series_memory_root(fp)) if selected
                     else snapshot.get("input_dir") if snapshot
                     else self.input_var.get())
        input_dir = input_dir or str(Path(fp).parent)
        tgt_var = getattr(self, "tgt_var", None)
        target_language = (
            snapshot.get("tgt_lang")
            if snapshot
            else tgt_var.get() if tgt_var is not None
            else "Turkish"
        ) or "Turkish"
        target_key = _lang_iso639_1(target_language)
        source_fallback = snapshot.get("src_lang", "English") if snapshot else "English"
        effective_source = getattr(self, "_effective_file_source_language", None)
        source_language = (
            effective_source(fp, source_fallback)
            if callable(effective_source) else source_fallback
        )
        source_key = _lang_iso639_1(source_language)
        try:
            if not persistent:
                overlays = getattr(self, "_run_series_memory", None)
                if isinstance(overlays, dict):
                    overlay_key = (
                        str(Path(input_dir).resolve()).casefold(), slug,
                        source_key, target_key
                    )
                    if overlay_key not in overlays:
                        overlays[overlay_key] = series_memory.SeriesMemory.load(
                            input_dir, slug, target_language=target_key,
                            source_language=source_key)
                    return overlays[overlay_key], season, ep
            return series_memory.SeriesMemory.load(
                input_dir, slug, target_language=target_key,
                source_language=source_key), season, ep
        except Exception:
            return None, None, None

    def _series_hint_for(self, fp: str) -> str:
        sm_obj, season, ep = self._series_mem_for(fp)
        if not sm_obj:
            return ""
        import hybrid_translate as ht
        snap_get = getattr(self, "_snap_get", None)
        if callable(snap_get):
            target_language = snap_get("tgt_lang", "Turkish")
        else:
            target_language = (
                getattr(self, "_active_snapshot", {}) or {}
            ).get("tgt_lang", "Turkish")
        return sm_obj.build_hint(
            before_episode=(season, ep),
            term_filter=lambda terms: ht.sanitize_glossary_for_turkish(
                terms,
                target_language=target_language,
                log_fn=getattr(self, "_log", None),
            ),
        )

    def _estimate_async(self, files, label_fn):
        """estimate_tokens'i arka planda çalıştırır — klasör/dosya seçince UI donmaz.
        label_fn(total_blocks, est_k) → file_info_var'a yazılacak metni döner."""
        files = list(files)
        n = len(files)
        self._set_stat(self.stat_files_var, str(n))
        self.file_info_var.set(f"⏳  {n} dosya  •  token hesaplanıyor…")
        token = object()
        if getattr(self, "_estimate_busy", False):
            previous = getattr(self, "_estimate_cancel", None)
            if previous is not None:
                previous.set()
            self._estimate_pending = (token, files, label_fn, n)
            return
        App._start_token_estimate(self, token, files, label_fn, n)

    def _start_token_estimate(self, token, files, label_fn, n):
        cancel = threading.Event()
        self._estimate_busy = True
        self._estimate_token = token
        self._estimate_cancel = cancel
        _cs = self._chunk_size

        def _work():
            try:
                if cancel.is_set():
                    result = None
                    error = None
                else:
                    result = estimate_tokens(
                        files, chunk_size=_cs, cancel_check=cancel.is_set)
                    error = None
            except Exception as exc:
                result = None
                error = exc
            _post_ui(
                self, App._finish_token_estimate,
                self, token, label_fn, n, result, error, cancel.is_set())

        try:
            App._start_worker(self, _work)
        except Exception as exc:
            if token is getattr(self, "_estimate_token", None):
                self._estimate_busy = False
                self._estimate_token = None
                self._estimate_cancel = None
                self.file_info_var.set(
                    f"⚠  {n} dosya  •  token tahmini yapılamadı: {exc}")

    def _finish_token_estimate(self, token, label_fn, n, result, error, cancelled=False):
        if token is not getattr(self, "_estimate_token", None):
            return
        pending = getattr(self, "_estimate_pending", None)
        if pending is not None:
            self._estimate_pending = None
            self._estimate_token = None
            self._estimate_cancel = None
            App._start_token_estimate(self, *pending)
            return
        self._estimate_busy = False
        self._estimate_token = None
        self._estimate_cancel = None
        if cancelled or error is not None or not result or result[0] is None:
            try:
                self.file_info_var.set(
                    f"⚠  {n} dosya  •  token tahmini yapılamadı")
            except Exception:
                pass
            return
        est, total_blocks = result
        est_k = f"{est/1000:.0f}k"
        try:
            self.file_info_var.set(label_fn(total_blocks, est_k))
            self._set_stat(self.stat_blocks_var, str(total_blocks))
        except Exception:
            pass

    # ── Bağlam İncelemesi (Batch sonrası ikinci geçiş) ────────────────────────
    def _save_raw_backup(self, out_path, raw_blocks, raw_map, target_language="Turkish"):
        """Kalite geçişlerinden ÖNCEKİ ham çeviriyi <stem>.ham.srt olarak yedekler.

        critic/polish/native/geri-çeviri/QC ham çeviriyi değiştirebilir; bu yedek
        onlardan ETKİLENMEZ — kullanıcı 'orijinal çeviri dosyasına dokunulmasın' istedi.
        Geçerli/oynatılabilir olsun diye yalnız [HATA] işaretleme + etiket geri yükleme
        uygulanır (kalite geçişi değil, sonlandırma adımı). Cue birleştirme de YOK —
        orijinal satır sınırları korunur."""
        try:
            if not self.backup_raw_var.get():
                return
        except Exception:
            return
        try:
            blk = list(raw_blocks)
            if raw_map:
                try:
                    blk, _ = _fill_hata_with_source(blk, raw_map)
                    blk = _restore_tags_blocks(blk, raw_map)
                except Exception:
                    pass
            out_obj = Path(out_path)
            delivery_parent = out_obj.parent
            if (delivery_parent.name.casefold() == "kurtarma"
                    and delivery_parent.parent.name.casefold() == "raporlar"):
                delivery_parent = delivery_parent.parent.parent
            report_dir = delivery_parent / "Raporlar" / "Ham"
            report_dir.mkdir(parents=True, exist_ok=True)
            digest = hashlib.sha256(
                os.path.normcase(os.path.abspath(str(out_obj))).encode("utf-8")
            ).hexdigest()[:10]
            stem = out_obj.stem[:-8] if out_obj.stem.endswith(".partial") else out_obj.stem
            bpath = str(report_dir / f"{stem}.{digest}.ham.srt")
            # A ham backup is evidence, not a second delivery pass.  In
            # particular do not apply corpus local-fixes, SDH normalization or
            # Turkish-only homoglyph rewriting while preserving it.
            _write_srt_preserving_text(bpath, blk)
            self._log(f"Ham çeviri yedeği: {Path(bpath).name}", "info")
        except Exception as e:
            self._log(f"Ham yedek yazılamadı: {e}", "warn")

    def _maybe_backtranslation_check(self, out_path, src_clean_map, blocks,
                                     src_lang=None, source_path=None,
                                     status_out: dict | None = None) -> int:
        """Geri çeviri anlam kontrolü. Açıksa çalışır: Türkçeyi tekrar
        kaynağa çevirip anlamca sapan satırları bulur, <stem>.geri_ceviri.txt'e +
        log'a yazar. Şüpheli cue kimliklerini nihai anlam mutabakatına aktarır;
        çeviriyi doğrudan değiştirmez."""
        if status_out is not None:
            status_out.clear()
            status_out.update({
                "status": "not_started", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
            })
        rpath = (Path(out_path).parent / "Raporlar"
                 / f"{Path(out_path).stem}.geri_ceviri.txt")
        if threading.current_thread() is not threading.main_thread() and getattr(self, "_active_snapshot", None):
            enabled = bool(self._active_snapshot.get("backtrans"))
        else:
            try:
                enabled = bool(self.backtrans_var.get())
            except Exception:
                enabled = False
        if not enabled:
            rpath.unlink(missing_ok=True)
            if status_out is not None:
                status_out["status"] = "skipped"
            return 0
        if not src_clean_map or not blocks:
            rpath.unlink(missing_ok=True)
            if status_out is not None:
                status_out["status"] = "skipped"
            return 0
        try:
            import hybrid_translate as ht
            run_src_lang = src_lang
            run_tgt_lang = None
            if threading.current_thread() is not threading.main_thread() and getattr(self, "_active_snapshot", None):
                run_src_lang = run_src_lang or self._active_snapshot.get("src_lang")
                run_tgt_lang = self._active_snapshot.get("tgt_lang")
            else:
                run_src_lang = run_src_lang or self.src_var.get()
                run_tgt_lang = self.tgt_var.get()
            flags = ht.back_translation_check(
                src_map=src_clean_map, tr_blocks=blocks,
                api_key=self._helper_api_key("qc"),
                base_url=self._helper_api_base_url("qc"),
                model=self._helper_api_model("qc"),
                src_lang=run_src_lang or "English",
                tgt_lang=run_tgt_lang or "Turkish",
                log_fn=self._log,
                token_callback=App._token_callback_for_pass(
                    self, self._helper_api_model("qc"), "Geri Çeviri",
                    base_url=self._helper_api_base_url("qc"),
                    file_path=str(source_path or "")),
                cancel_context=self.__dict__.get("_helper_request_canceller"),
                status_out=status_out)
            if self.__dict__.get("_stop_flag", False):
                return 0
            if not flags:
                rpath.unlink(missing_ok=True)
                return 0
            if status_out is not None:
                status_out["changed"] = 0
                status_out["flagged"] = len(flags)
                status_out["flagged_ids"] = sorted({str(f["idx"]) for f in flags})
            # Rapor yaz
            try:
                rpath.parent.mkdir(parents=True, exist_ok=True)
                out = [f"# Geri Çeviri Anlam Kontrolü — {len(flags)} şüpheli satır",
                       "# Doğrudan değişiklik yapılmadı; şüpheli cue'lar Nihai Anlam Mutabakatına aktarıldı.", ""]
                for f in flags:
                    out.append(f"[{f['idx']}] sebep: {f['reason']}")
                    out.append(f"  kaynak     : {f['src']}")
                    out.append(f"  çeviri     : {f['tr']}")
                    out.append(f"  geri çeviri: {f['back']}")
                    out.append("")
                atomic_write_text(rpath, "\n".join(out), encoding="utf-8")
                self._log(f"Geri çeviri raporu: {Path(rpath).name} ({len(flags)} satır)", "info")
            except Exception as _re:
                self._log(f"Geri çeviri raporu yazılamadı: {_re}", "warn")
            return 0
        except Exception as e:
            if status_out is not None:
                status_out.update({"status": "failed", "error": str(e)})
            self._log(f"Geri çeviri kontrolü hatası: {e}", "warn")
            return 0

    def _semantic_reconcile_enabled(self) -> bool:
        if threading.current_thread() is not threading.main_thread() and getattr(self, "_active_snapshot", None):
            return bool(self._active_snapshot.get("semantic_reconcile", True))
        try:
            return bool(self.semantic_reconcile_var.get())
        except Exception:
            return True

    def _maybe_semantic_reconciliation(self, out_path, src_clean_map, blocks,
                                       src_lang=None, cues=None, changed_ids=None,
                                       source_path=None, canon_hint="",
                                       force=False, target_coverage=0.65,
                                       report_path=None, locked_terms=None,
                                       analysis_result=None,
                                       raise_errors=False,
                                       status_out: dict | None = None) -> int:
        if status_out is not None:
            status_out.clear()
            status_out.update({
                "status": "not_started", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
            })
        stale_report_path = Path(
            report_path
            or Path(out_path).parent / "Raporlar"
            / f"{Path(out_path).stem}.anlamsal_mutabakat.txt")
        if ((not force and not self._semantic_reconcile_enabled())
                or not src_clean_map or not blocks):
            stale_report_path.unlink(missing_ok=True)
            if status_out is not None:
                status_out["status"] = "skipped"
            return 0
        try:
            import hybrid_translate as ht
            if threading.current_thread() is not threading.main_thread() and getattr(self, "_active_snapshot", None):
                run_src_lang = src_lang or self._active_snapshot.get("src_lang") or "English"
                run_tgt_lang = self._active_snapshot.get("tgt_lang") or "Turkish"
            else:
                run_src_lang = src_lang or self.src_var.get() or "English"
                run_tgt_lang = self.tgt_var.get() or "Turkish"
            if locked_terms is None:
                locked_terms = self._get_locked_terms_dict(
                    source_path, run_tgt_lang)
            extra_suspect_reasons = {
                sid: {"MIXED_TERM_INCONSISTENCY"}
                for sid in _mixed_term_suspect_ids(blocks, src_clean_map)
            }
            for finding in detect_alignment_issues(blocks, src_clean_map):
                finding_ids = finding.get("ids") or [finding.get("idx")]
                reason = f"ALIGNMENT_{str(finding.get('type', 'issue')).upper()}"
                for sid in finding_ids:
                    if sid is not None:
                        extra_suspect_reasons.setdefault(str(sid), set()).add(reason)
            cancel_context = self.__dict__.get("_helper_request_canceller")
            cancel_kwargs = (
                {"cancel_context": cancel_context}
                if cancel_context is not None else {}
            )
            semantic_progress = App._pass_progress_callback(
                self, source_path, "Nihai Mutabakat", 96.0, 99.0)
            if "_phase_lbl" in self.__dict__:
                App._set_phase(
                    self,
                    "Nihai Mutabakat",
                    f"{Path(source_path).name if source_path else 'Geçerli dosya'}  —  hazırlanıyor",
                )
            result, stats = ht.semantic_reconciliation_pass(
                src_map=src_clean_map,
                tr_blocks=blocks,
                api_key=self._helper_api_key("critic"),
                base_url=self._helper_api_base_url("critic"),
                model=self._helper_api_model("critic"),
                src_lang=run_src_lang,
                tgt_lang=run_tgt_lang,
                cues=cues,
                changed_ids=changed_ids,
                extra_suspect_reasons=extra_suspect_reasons,
                locked_terms=locked_terms,
                target_coverage=target_coverage,
                canon_hint=canon_hint,
                analysis_context_hint=ht.build_polish_context_hint(
                    analysis_result, run_tgt_lang),
                scene_plan=(
                    analysis_result[4]
                    if analysis_result and len(analysis_result) > 4
                    else None
                ),
                scene_gap_sec=self._run_scene_gap(),
                log_fn=self._log,
                token_callback=App._token_callback_for_pass(
                    self, self._helper_api_model("critic"),
                    "Nihai Anlam Mutabakatı",
                    base_url=self._helper_api_base_url("critic"),
                    file_path=str(source_path or "")),
                progress_callback=semantic_progress,
                status_out=status_out,
                **cancel_kwargs,
            )
            if self.__dict__.get("_stop_flag", False) or (
                    cancel_context is not None and cancel_context.is_cancelled()):
                return 0
            blocks[:] = result
            rpath = stale_report_path
            if stats.get("clusters"):
                try:
                    lines = [
                        "# Nihai Anlam Mutabakatı",
                        f"# Küme: {stats['clusters']} | Şüpheli cue: {stats['suspects']} | "
                        f"Planlanan kapsam: {stats.get('covered_cues', 0)}/{len(blocks)} "
                        f"(%{stats.get('coverage_pct', 0.0):.1f}) | "
                        f"İşlenen kapsam: {stats.get('processed_cues', 0)}/{len(blocks)} "
                        f"(%{stats.get('processed_coverage_pct', 0.0):.1f}) | "
                        f"Tahmini API isteği: {stats.get('api_requests', 0)} | "
                        f"Öneri: {stats['proposed']} | Düzeltme: {stats['fixed']} | "
                        f"Satır sarma kurtarma: {stats.get('reflow_recovered', 0)} | "
                        f"Reddedilen küme: {stats['rejected']}",
                        "",
                    ]
                    for detail in stats.get("details", []):
                        cluster = detail.get("cluster") or ",".join(detail.get("clusters", []))
                        lines.append(
                            f"[{cluster or '?'}] {detail.get('status', '?')}: "
                            f"{detail.get('reason', '')}".rstrip()
                        )
                        if detail.get("ids"):
                            lines.append("  cue: " + ", ".join(detail["ids"]))
                        if detail.get("count"):
                            lines.append(f"  küme: {detail['count']}")
                        for sid, change in detail.get("changes", {}).items():
                            lines.append(f"  [{sid}] kaynak: {change.get('source', '')}")
                            lines.append(f"       önce : {change.get('before', '')}")
                            lines.append(f"       sonra: {change.get('after', '')}")
                    rpath.parent.mkdir(parents=True, exist_ok=True)
                    atomic_write_text(rpath, "\n".join(lines), encoding="utf-8")
                    if report_path and getattr(self, "_active_run_record", None):
                        with self._run_record_lock:
                            self._active_run_record.setdefault("reports", []).append(
                                str(rpath))
                    self._log(f"Anlamsal mutabakat raporu: {Path(rpath).name}", "info")
                except Exception as exc:
                    self._log(f"Anlamsal mutabakat raporu yazılamadı: {exc}", "warn")
            else:
                rpath.unlink(missing_ok=True)
            return int(stats.get("fixed", 0))
        except RequestCancelled:
            if status_out is not None:
                status_out["status"] = "cancelled"
            raise
        except Exception as e:
            if status_out is not None:
                status_out.update({"status": "failed", "error": str(e)})
            self._log(f"Nihai anlam mutabakatı hatası: {e}", "warn")
            if raise_errors:
                raise
            return 0

    def _run_final_semantic_checks(self, out_path, src_clean_map, blocks,
                                   src_lang=None, cues=None, changed_ids=None,
                                   source_path=None, locked_terms=None,
                                   analysis_result=None,
                                   status_out: dict | None = None,
                                   backtranslation_status_out: dict | None = None) -> int:
        progress_path = str(source_path or out_path)
        progress_name = Path(progress_path).name
        fixed = 0
        if App._run_setting(self, "backtrans", "backtrans_var", False):
            _record_file_stage_if_available(
                self, progress_path, "Geri Çeviri", "running")
            self._set_phase(
                "Geri Çeviri", f"{progress_name} — anlam kontrolü")
            self._update_file_progress(
                progress_path, "Geri Çeviri", 96)
        back_status = backtranslation_status_out if backtranslation_status_out is not None else {}
        fixed += self._maybe_backtranslation_check(
            out_path, src_clean_map, blocks, src_lang=src_lang,
            source_path=source_path,
            status_out=back_status)
        changed_ids = set(changed_ids or [])
        changed_ids.update(
            str(idx) for idx in back_status.get(
                "flagged_ids", ())
        )
        if App._run_setting(
                self, "semantic_reconcile", "semantic_reconcile_var", True):
            _record_file_stage_if_available(
                self,
                progress_path, "Nihai Anlam Mutabakatı", "running")
            self._set_phase(
                "Nihai Anlam Mutabakatı",
                f"{progress_name} — kaynakla son karşılaştırma")
            self._update_file_progress(
                progress_path, "Nihai Anlam Mutabakatı", 98)
        fixed += self._maybe_semantic_reconciliation(
            out_path, src_clean_map, blocks, src_lang=src_lang,
            cues=cues, changed_ids=changed_ids, source_path=source_path,
            locked_terms=locked_terms, analysis_result=analysis_result,
            status_out=status_out)
        return fixed

    def _get_locked_terms_dict(self, fp: str | None, tgt: str) -> dict:
        try:
            import hybrid_translate as ht
            schema_terms = {}
            file_terms = {}
            project_terms = {}
            series_terms = {}
            try:
                schema_dict = self._get_file_schema(fp) if fp else self._get_schema()
                schema_terms = (schema_dict or {}).get("glossary") or {}
            except Exception:
                pass
            try:
                file_terms = ht.load_glossary(
                    self._get_file_glossary(fp), strict=True) or {}
            except ht.GlossaryLoadError:
                raise
            except Exception:
                pass
            try:
                file_source = self._effective_file_source_language(
                    fp, self._snap_get("src_lang", "English"))
                file_pm = self._project_memory_for(fp, file_source)
            except Exception:
                file_pm = getattr(self, "_pm", None)
            if file_pm is None:
                file_pm = getattr(self, "_pm", None)
            if file_pm is not None:
                try:
                    project_terms = file_pm.get_glossary() or {}
                except RequestCancelled:
                    raise
                except Exception:
                    pass
            if fp:
                try:
                    if (threading.current_thread() is not threading.main_thread()
                            and getattr(self, "_active_snapshot", None)):
                        enabled = bool(self._active_snapshot.get("series_memory"))
                        selected = self._active_snapshot.get("selected_files") or ()
                        input_dir = (str(series_memory.series_memory_root(fp)) if selected
                                     else self._active_snapshot.get("input_dir") or str(Path(fp).parent))
                    else:
                        enabled = bool(
                            getattr(self, "series_memory_var", None)
                            and self.series_memory_var.get()
                        )
                        input_dir = (str(series_memory.series_memory_root(fp))
                                     if self.__dict__.get("_selected_files")
                                     else self.input_var.get() or str(Path(fp).parent))
                    key = series_memory.parse_series_key(fp) if enabled else None
                    if key:
                        slug, _season, _episode = key
                        try:
                            series_source = self._effective_file_source_language(
                                fp, self._snap_get("src_lang", "English"))
                        except Exception:
                            series_source = "English"
                        sm_obj = series_memory.SeriesMemory.load(
                            input_dir, slug,
                            target_language=_lang_iso639_1(tgt),
                            source_language=_lang_iso639_1(series_source))
                        series_terms = sm_obj.get_terms()
                except Exception:
                    pass
            # Şema genel varsayımdır; proje/dizi hafızası önceki kanondur; açıkça
            # seçilmiş dosya sözlüğü ise kullanıcı kararı olarak son sözü söyler.
            terms = _merge_locked_term_sources(
                schema_terms, project_terms, series_terms, file_terms)
            try:
                terms = ht.sanitize_glossary_for_turkish(
                    terms, target_language=tgt, log_fn=getattr(self, "_log", None)
                ) or {}
            except Exception as exc:
                # Doğrulanamayan otomatik terimler prompt'a sızmamalı; açık sözlüğü
                # de ham halde kullanmak yerine bu dosyada kilitleri kapat.
                log_fn = getattr(self, "_log", None)
                if callable(log_fn):
                    log_fn(
                        f"Sabit terimler güvenlik denetiminden geçemedi; bu dosyada "
                        f"sözlük devre dışı bırakıldı: {exc}", "warn")
                terms = {}
            return {
                str(source).strip(): str(target).strip()
                for source, target in terms.items()
                if source and target
                and (
                    str(source).strip().casefold() != str(target).strip().casefold()
                    or not str(source).strip().islower()
                )
            }
        except RequestCancelled:
            raise
        except Exception:
            return {}

    def _locked_terms_hint(self, fp: str, tgt: str) -> str:
        """Batch inceleme için kilitli terim + isim bloğu.

        Dosya sözlüğü + proje hafızası sözlüğünü birleştirir (kimlik 'x -> x'
        çiftlerini eler), karakter isimlerini ayrı 'değiştirme' listesine koyar.
        Böylece review pass terim/isim tutarsızlığını yalnız sezgiyle değil,
        sabit referansla düzeltebilir. Boşsa '' döner."""
        try:
            locked = list(self._get_locked_terms_dict(fp, tgt).items())
            names = []
            try:
                file_source = self._effective_file_source_language(
                    fp, self._snap_get("src_lang", "English"))
                file_pm = self._project_memory_for(fp, file_source)
            except Exception:
                file_pm = getattr(self, "_pm", None)
            if file_pm is None:
                file_pm = getattr(self, "_pm", None)
            if file_pm is not None:
                try:
                    names = [n for n in (file_pm.get_characters() or {}).keys() if n]
                except Exception:
                    names = []
            if not locked and not names:
                return ""
            parts = []
            if locked:
                rows = "; ".join(f"{s} -> {t}" for s, t in locked[:60])
                parts.append(
                    f"\n## LOCKED TERMS (source term -> required {tgt} rendering; if a reviewed "
                    f"line renders that term differently, fix it to this):\n" + rows)
            if names:
                parts.append(
                    "\n## LOCKED NAMES (character/proper names — must appear verbatim, do NOT "
                    "translate or alter):\n" + ", ".join(names[:40]))
            return "".join(parts)
        except Exception:
            return ""

    def _review_pass(self, fp: str, sorted_blocks: list, model: str, tgt: str,
                     status_out: dict | None = None) -> tuple:
        """Batch çevirisi sonrası ana modelle tam-bağlam incelemesi. (bloklar, düzeltme_sayısı) döner.

        Batch modunda chunk'lar birbirinin çevirisini göremez (istekler önceden
        paketlenir); bu geçiş bütün dosyayı kaynakla karşılaştırarak sırayla okur,
        terim/hitap tutarsızlıklarını ve çeviri hatalarını düzeltir."""
        REVIEW_CHUNK = 80
        REVIEW_CTX   = 8   # önceki chunk'tan taşınan bağlam çifti sayısı
        if status_out is not None:
            status_out.clear()
            status_out.update({
                "status": "not_started", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
            })
        try:
            b_url = self._main_api_base_url()
            client = OpenAI(api_key=self._main_api_key(), base_url=b_url if b_url else None)
        except Exception as e:
            if status_out is not None:
                status_out.update({"status": "failed", "error": str(e)})
            self._log_exc("Bağlam incelemesi başlatılamadı", e)
            return sorted_blocks, 0

        src_cues = self._cached_blocks_for(fp)
        if src_cues is None:
            try:
                src_cues = list(parse_subtitle(fp))
            except Exception:
                src_cues = []
        src_map = _src_map_from_cues(src_cues)
        if not src_map:
            if status_out is not None:
                status_out.update({
                    "status": "failed", "error": "source_text_missing"})
            self._log("Bağlam incelemesi: kaynak metin bulunamadı, atlandı", "warn")
            return sorted_blocks, 0
        import hybrid_translate as ht

        sys_prompt = (
            f"You are a senior {tgt} subtitle QA reviewer. You receive source+translation pairs "
            f"from ONE film, in chronological order, with full context.\n"
            "Fix ONLY lines that have a real problem:\n"
            "- mistranslation (meaning differs from source)\n"
            "- inconsistent terminology or character names vs earlier lines\n"
            "- sen/siz (T-V) register breaks between the same speakers\n"
            "- unnatural literal phrasing a native speaker would never say\n"
            "- word-for-word rendering that misses intent, implication, joke, threat, sarcasm, or documentary logic\n"
            "- choppy line flow or wording too long for the available subtitle duration\n"
            "- untranslated source-language words left in the text\n"
            "Use sense-for-sense Turkish only when supported by the visible source words and surrounding context: "
            "preserve what the line is doing, not the source wording; do not add unstated ideas, and keep fixes concise. "
            "Duration/CPS beats source length: prefer <=21 CPS and avoid >24 CPS when possible.\n"
            "Preserve polarity, questions, and numbers exactly: negative stays negative, questions stay questions, "
            "and digits/dates/amounts keep the same value.\n"
            "Rules: preserve \\n line breaks exactly; keep similar length (subtitle reading "
            "speed matters); do NOT touch lines that are already correct.\n"
            "Input JSON keys:\n"
            '  "ctx"    — earlier reviewed pairs (do NOT output these, reference only)\n'
            '  "review" — pairs to review: [{"i":N,"src":"...","tr":"..."}]\n'
            'Output: JSON array of ONLY the corrected items [{"i":N,"t":"fixed translation"}]. '
            "Return [] if nothing needs fixing. Return ONLY the JSON array."
        )
        locked_getter = getattr(self, "_get_locked_terms_dict", None)
        locked_terms = locked_getter(fp, tgt) if callable(locked_getter) else {}
        sys_prompt += self._locked_terms_hint(fp, tgt)   # kilitli sözlük/isim referansı (#7)

        # Fragment gruplarını hesapla (EARLY_VERB_CLOSURE tespiti için)
        review_cues = ht._semantic_validator_cues(src_map, sorted_blocks, src_cues)
        review_frag_tags = {}
        review_frag_group_ids = {}
        review_fragment_groups = []
        try:
            if review_cues:
                review_frag_tags = ht._tag_fragments(review_cues)
                review_frag_group_ids, review_fragment_groups = ht._fragment_groups(
                    review_cues, review_frag_tags)
        except Exception:
            pass

        result      = list(sorted_blocks)
        pos_by_idx  = {str(b[0]): k for k, b in enumerate(result)}
        review_ranges = []
        range_start = 0
        while range_start < len(result):
            range_end = min(len(result), range_start + REVIEW_CHUNK)
            if range_end < len(result):
                prev_idx = result[range_end - 1][0]
                next_idx = result[range_end][0]
                prev_gid = review_frag_group_ids.get(
                    prev_idx, review_frag_group_ids.get(str(prev_idx)))
                next_gid = review_frag_group_ids.get(
                    next_idx, review_frag_group_ids.get(str(next_idx)))
                if prev_gid is not None and prev_gid == next_gid:
                    while range_end < len(result):
                        idx = result[range_end][0]
                        gid = review_frag_group_ids.get(
                            idx, review_frag_group_ids.get(str(idx)))
                        if gid != prev_gid:
                            break
                        range_end += 1
            review_ranges.append((range_start, range_end))
            range_start = range_end
        total_chunks = len(review_ranges)
        fixed_total = 0
        review_rejected = 0
        review_rejected_reasons = {}
        successful_chunks = 0
        failed_chunks = 0
        attempted_chunks = 0
        cancelled = False
        for chunk_no, (cs, chunk_end) in enumerate(review_ranges, 1):
            if self._stop_flag:
                break
            chunk = result[cs:chunk_end]
            current_idxs = {str(idx) for idx, ts, text in chunk}   # yalnız bu chunk'ın id'leri
            items = [{"i": idx, "src": src_map.get(str(idx), ""), "tr": text}
                     for idx, ts, text in chunk
                     if not str(text).startswith("[HATA")]
            for it in items:
                tag = review_frag_tags.get(it["i"], "none")
                if tag != "none":
                    it["frag"] = tag
                    if it["i"] in review_frag_group_ids:
                        it["frag_group"] = review_frag_group_ids[it["i"]]
            if not items:
                continue
            attempted_chunks += 1
            payload = {"review": items}
            chunk_ids = {it["i"] for it in items}
            chunk_groups = [
                g for g in review_fragment_groups
                if any(str(g_item) in chunk_ids for g_item in g.get("items", []))
            ]
            if chunk_groups:
                payload["sentence_groups"] = chunk_groups
            if cs > 0:
                # Önceki chunk'ın (incelenmiş) son satırları — tutarlılık referansı
                ctx = [{"i": idx, "src": src_map.get(str(idx), ""), "tr": text}
                       for idx, ts, text in result[max(0, cs - REVIEW_CTX):cs]
                       if not str(text).startswith("[HATA")]
                if ctx:
                    payload["ctx"] = ctx
            try:
                resp = _safe_chat_create(
                    client, model=model,
                    _checkpoint_label="context_review",
                    cancel_context=self.__dict__.get(
                        "_helper_request_canceller"),
                    messages=[{"role": "system", "content": sys_prompt},
                              {"role": "user",
                               "content": json.dumps(payload, ensure_ascii=False)}],
                    max_tokens=REVIEW_CHUNK * 80,
                    temperature=0.2,
                )
                _report_response_usage(
                    _app_token_callback(
                        self, model, "Bağlam İncelemesi",
                        base_url=b_url, file_path=fp),
                    resp, log_fn=self._log,
                    pass_name="Bağlam İncelemesi", filepath=fp)
                content = (resp.choices[0].message.content or "").strip() if resp.choices else ""
                raw = _extract_json_array(content)
                if not raw.strip():
                    raise ValueError("empty review response")
                fixes = json.loads(raw)
                if not isinstance(fixes, list):
                    raise ValueError("review response is not a JSON array")
                fix_by_id = {}
                conflicting_ids = set()
                for it in fixes:
                    if not (isinstance(it, dict) and "i" in it and "t" in it):
                        continue
                    sid = str(it["i"])
                    if sid not in current_idxs:
                        continue   # model ctx satırının idx'ini döndürdü → önceki chunk'ı EZME
                    new_t = str(it["t"]).strip()
                    if not new_t:
                        continue
                    if sid in fix_by_id and fix_by_id[sid] != new_t:
                        conflicting_ids.add(sid)
                    else:
                        fix_by_id.setdefault(sid, new_t)
                for sid in conflicting_ids:
                    fix_by_id.pop(sid, None)
                if conflicting_ids:
                    review_rejected += len(conflicting_ids)
                    review_rejected_reasons["duplicate_fix_conflict"] = (
                        review_rejected_reasons.get("duplicate_fix_conflict", 0)
                        + len(conflicting_ids)
                    )

                active_group_ids = set()
                for sid in current_idxs:
                    pos = pos_by_idx.get(sid)
                    if pos is None:
                        continue
                    old_idx = result[pos][0]
                    gid = review_frag_group_ids.get(
                        old_idx, review_frag_group_ids.get(sid))
                    if gid is not None:
                        active_group_ids.add(gid)
                chunk_group_expected = {}
                original_by_id = {}
                for old_idx, _old_ts, old_t in result:
                    sid = str(old_idx)
                    original_by_id[sid] = old_t
                    gid = review_frag_group_ids.get(
                        old_idx, review_frag_group_ids.get(sid))
                    if gid in active_group_ids:
                        chunk_group_expected.setdefault(gid, []).append(sid)

                chunk_proposals = {}
                for sid, new_t in fix_by_id.items():
                    pos = pos_by_idx.get(sid)
                    if pos is None:
                        continue
                    old_idx, old_ts, old_t = result[pos]
                    if old_t.startswith("[HATA"):
                        continue
                    neighbor_start = max(0, pos - 2)
                    neighbor_end = min(len(result), pos + 3)
                    neighbor_texts = [
                        result[n][2] for n in range(neighbor_start, neighbor_end)
                        if n != pos
                    ]
                    fragment_tag = (
                        review_frag_tags.get(old_idx)
                        or review_frag_tags.get(str(old_idx))
                        or review_frag_tags.get(sid)
                        or "none"
                    )
                    ok, reason = ht.validate_polish_candidate(
                        old_t,
                        new_t,
                        source_text=src_map.get(str(old_idx), ""),
                        neighbor_texts=neighbor_texts,
                        fragment_tag=fragment_tag,
                        locked_terms=locked_terms,
                    )
                    group_id = review_frag_group_ids.get(
                        old_idx, review_frag_group_ids.get(sid))
                    chunk_proposals[sid] = (new_t, ok, reason, group_id)

                chunk_result, chunk_rejected, chunk_reasons = ht.apply_polish_group_atomic(
                    chunk_proposals,
                    original_by_id,
                    group_expected=chunk_group_expected,
                    src_map=src_map,
                    locked_terms=locked_terms,
                )
                review_rejected += chunk_rejected
                for reason, count in chunk_reasons.items():
                    review_rejected_reasons[reason] = (
                        review_rejected_reasons.get(reason, 0) + count)
                for sid, new_t in chunk_result.items():
                    pos = pos_by_idx.get(sid)
                    if pos is None:
                        continue
                    old_idx, old_ts, old_t = result[pos]
                    if new_t != old_t:
                        result[pos] = (old_idx, old_ts, new_t)
                        fixed_total += 1
                        self._log(f"  ✏ İnceleme #{old_idx}: {old_t!r}", "warn")
                        self._log(f"       → {new_t!r}", "ok")
                successful_chunks += 1
                self._set_status(f"Bağlam incelemesi {chunk_no}/{total_chunks} — {Path(fp).name}")
            except RequestCancelled:
                cancelled = True
                break
            except Exception as e:
                failed_chunks += 1
                self._log_exc(f"Bağlam incelemesi chunk {chunk_no}/{total_chunks} hatası", e)
        if status_out is not None:
            if self._stop_flag or cancelled:
                pass_status = "cancelled"
            elif failed_chunks:
                pass_status = "partial" if successful_chunks else "failed"
            else:
                pass_status = "completed"
            status_out.update({
                "status": pass_status,
                "successful_chunks": successful_chunks,
                "failed_chunks": failed_chunks,
                "total_chunks": attempted_chunks,
                "changed": fixed_total,
            })
        if review_rejected:
            reason_bits = ", ".join(
                f"{reason}:{count}" for reason, count in sorted(review_rejected_reasons.items())
            )
            self._log(
                f"Bağlam incelemesi: {review_rejected} öneri güvenlik filtresinden döndü ({reason_bits})",
                "warn",
            )
        self._log(f"Bağlam incelemesi: {fixed_total} satır düzeltildi / {len(result)} toplam",
                  "ok" if fixed_total else "info")
        return result, fixed_total

    def _cached_blocks_for(self, fp: str):
        cache = getattr(self, "_block_cache", None)
        if isinstance(cache, dict):
            return cache.get(fp)
        return None

    # ── Polish Pass ───────────────────────────────────────────────────────────
    def _polish_pass(self, sorted_blocks: list, tgt: str,
                     helper_key: str, helper_url: str, helper_model: str,
                     src_map: dict = None, analysis_result=None,
                     locked_terms: dict | None = None,
                     cancel_context=None, status_out: dict | None = None) -> list:
        """Second-pass naturalisation using the helper model gpt-5.4-mini (cost-efficient).

        src_map: {idx_str: kaynak metin} — verilirse her satıra 'en' alanı eklenir;
        editör anlamı kaynaktan doğrular, anlam kayması engellenir."""
        if status_out is not None:
            status_out.clear()
            status_out.update({
                "status": "not_started", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
            })
        if not sorted_blocks:
            if status_out is not None:
                status_out["status"] = "skipped"
            return sorted_blocks
        POLISH_CHUNK = 150  # Balanced: large enough to be fast, small enough to avoid API limits
        POLISH_CTX   = 6    # önceki chunk'ın son N cilalı satırı — üslup sürekliliği
        from openai import OpenAI as _OAI
        import hybrid_translate as ht
        try:
            client = _OAI(api_key=helper_key, base_url=helper_url)
        except Exception as exc:
            if status_out is not None:
                status_out.update({"status": "failed", "error": str(exc)})
            raise
        cancel_context = cancel_context or self.__dict__.get("_helper_request_canceller")
        src_map = src_map or {}
        
        # Reconstruct mock cues for fragment tagging
        frag_tags = {}
        frag_group_ids = {}
        fragment_groups = []
        if src_map:
            class MockCue:
                def __init__(self, index, text):
                    self.index = index
                    self.text = text
            mock_cues = []
            for idx, ts, text in sorted_blocks:
                src_t = src_map.get(str(idx), "")
                mock_cues.append(MockCue(idx, src_t))
            try:
                from hybrid_translate import _fragment_groups, _tag_fragments
                frag_tags = _tag_fragments(mock_cues)
                frag_group_ids, fragment_groups = _fragment_groups(mock_cues, frag_tags)
            except Exception:
                frag_tags = {}
                frag_group_ids = {}
                fragment_groups = []
                
        context_hint = ht.build_polish_context_hint(analysis_result, tgt_lang=tgt)
        sys_prompt = (
            f"Sen deneyimli bir {tgt} altyazı editörüsün. Sana makine tarafından çevrilmiş altyazılar gelecek.\n"
            f"Görevin: Anlam ve satır sayısını KORUYARAK dili insan çevirisi kalitesine yükselt.\n\n"
            f"{context_hint}"
            f"ANLAM ÖNCELİĞİ: Kaynak satırın sahnede ne demek istediğini, alt metnini ve konuşma eylemini yalnızca "
            f"görünen kaynak sözlerden ve çevre bağlamdan çıkar; keyfi yorum veya yeni bilgi ekleme. Türkçeyi buna "
            f"göre kur. Kelime kelime cilalama yapma. Anlam, bilgi ve ton değişmeyecekse Türkçe söz dizimini ve "
            f"ifadeyi doğallaştır. Süre/CPS kaynak uzunluğundan önceliklidir: hedef <=21 CPS, mümkünse 24 CPS'i "
            f"aşma; kısa ve okunabilir kal.\n\n"
            f"TEMEL KURALLAR:\n"
            f"1. Yeniden çevirme — orijinal anlamı değiştirme, sadece dil akışını düzelt. Emin değilsen satırı AYNEN döndür.\n"
            f"2. Satır sayısını ve \\n karakterlerini koru — ekstra satır ekleme, mevcut satırları birleştirme.\n"
            f"3. Orijinaldeki karakter sayısına yakın kal — Türkçe altyazı ekonomisi önemli, izleyici hızlı okur.\n\n"
            f"KORUMA RAYLARI:\n"
            f"- Sayıları, tarihleri, saatleri, ölçüleri, para birimlerini ve teknik kodları değiştirme.\n"
            f"- Olumsuzluğu, soru kipini ve sayısal değeri aynen koru: olumsuz olumluya dönmez, soru soru kalır, rakam/tarih/tutar değişmez.\n"
            f"- <i>, <b>, <u>, ASS biçim etiketleri ve konuşmacı tirelerini koru.\n"
            f"- [SFX]/[ACTION]/ekran yazısı etiketlerini silme; zaten Türkçeyse aynen bırak.\n"
            f"- Özel isim, marka, yer adı ve evren terimlerini bağlam/glossary gerektirmedikçe değiştirme.\n"
            f"- Kaynak anlamı ile mevcut çeviri çelişiyorsa yalnızca o çelişkiyi düzelt; yeni bilgi ekleme.\n"
            f"- MUHAFAZAKÂR CİLA: Yalnızca yazım hatası, noktalama, büyük-küçük harf, barok yapı (İngilizce söz dizimi → "
            f"doğal Türkçe SOV) ve doğallık sorunlarını düzelt. TÜMCE İÇERİĞİNİ YENİDEN YAZMA. Anlam, bilgi ve "
            f"içerik kelimeleri (isim, fiil, sıfat) aynı kalmalı. Emin değilsen satırı AYNEN bırak.\n"
            f"- AŞIRI DEĞİŞİM RİSKİ: Bir satırda tüm içerik kelimelerini değiştirme; bu anlam kaymasıdır. "
            f"Yüzey düzeltmeleri (imlâ/noktalama) yeterliyse, satırı olduğu gibi bırak.\n\n"
            f"DÜZELTİLECEKLER:\n"
            f"- Çoklu Satır Akışı & Söz Dizimi (Sondan Başa İlerleme): Eğer ardışık satırlarda 'frag' alanı varsa ('start', 'mid', 'end'), bu satırlar tek bir İngilizce cümlenin parçalarıdır. Türkçe çevirilerde İngilizce söz dizimi (SVO) sırası nedeniyle bilgi akışının 'sondan başa' gidiyor gibi durmasını (örn. erken yüklem kapanıp nesnelerin arkadan gelmesini) engelle. Bilgileri/kelimeleri bu satırlar arasında Türkçe kurallarına göre (SOV) yeniden dağıt. Cümle en son satırda ('end') yüklemle bitsin, önceki satırlar ('start', 'mid') Türkçe'de devam bekleyen yapıda olsun.\n"
            f"- Literalizm: 'benim için' → 'bence', 'sahip olmak' → 'var', 'gerçekleştirmek' → 'yapmak'\n"
            f"- Aşırı resmiyet: 'müzakere etmek' → 'konuşmak', 'istihdam' → 'iş', 'ikamet' → 'oturma'\n"
            f"- İngilizce kalıntılar: ass→göt, shit→bok, fuck→sik-, damn→kahretsin, bro→lan/abi\n"
            f"- Yapay Türkçe: 'Bu doğru değil mi?' → 'Değil mi?', 'Evet, biliyorum' → 'Biliyorum'\n"
            f"- Sen/Siz tutarsızlığı: Aynı karakterin bir cümlede 'sen' bir cümlede 'siz' demesi\n"
            f"- Okuma hızı: 42+ karakter satırlarında mümkünse kısalt, anlam kaybolmasın\n\n"
            f"DOKUNMA:\n"
            f"- Özel isimler, yer adları, marka adları\n"
            f"- Sayılar, tarihler, teknik terimler\n"
            f"- Zaten doğal olan satırlar\n\n"
            f"GİRDİ ALANLARI:\n"
            f"- 'en': satırın ORİJİNAL kaynak metni — anlam kontrolü için kullan; "
            f"düzeltmen kaynaktaki anlamdan SAPMAMALI. Çeviri kaynaktan zaten sapmışsa anlamı kaynağa göre düzelt.\n"
            f"- 'risk': bu satır için olası sorun ipuçlarıdır; yoksa satır muhtemelen daha az dokunulmalıdır.\n"
            f"- 'ctx': önceki bölümün son satırları (cilalanmış halleriyle) — üslup, terim ve sen/siz "
            f"tutarlılığı için referans; bunları ASLA çıktına ekleme.\n\n"
            f"- 'next_ctx': sonraki satırlar — devam eden cümle ve ton için referans; bunları ASLA çıktına ekleme.\n\n"
            f"- 'sentence_groups': start/mid/end satırlarının oluşturduğu tam kaynak cümlelerdir. "
            f"Önce bu bütün cümleyi anla, sonra Türkçeyi aynı id'lere doğal SOV akışla dağıt; "
            f"sentence_groups içeriğini ayrıca çıktılama.\n\n"
            f'Input: JSON {{"ctx": [...], "next_ctx": [...], "polish": [{{"id": N, "en": "source", "tr": "...", "risk": [...]}}]}}\n'
            f'Output: JSON array [{{"id": N, "tr": "polished"}}] — same IDs, same count.\n'
            f"Return ONLY the JSON array. No explanation, no preamble."
        )
        result_map = {}
        rejected = 0
        rejected_reasons = {}
        usage_callback = App._token_callback_for_pass(
            self,
            helper_model, "Polish Pass", base_url=helper_url)
        attempted_chunks = 0
        successful_chunks = 0
        partial_chunks = 0
        permanent_error = None
        polish_ranges = _polish_chunk_ranges(
            sorted_blocks, frag_group_ids, POLISH_CHUNK)
        global_group_expected = {}
        for idx, _ts, text in sorted_blocks:
            if str(text).startswith("[HATA"):
                continue
            gid = frag_group_ids.get(idx, frag_group_ids.get(str(idx)))
            if gid is not None:
                global_group_expected.setdefault(gid, []).append(str(idx))
        for chunk_num, (cs, chunk_end) in enumerate(polish_ranges, 1):
            if self.__dict__.get("_stop_flag", False) or (
                    cancel_context is not None and cancel_context.is_cancelled()):
                break
            chunk = sorted_blocks[cs:chunk_end]
            items = []
            original_by_id = {}
            neighbor_texts_by_id = {}
            for idx, ts, text in chunk:
                if str(text).startswith("[HATA"):
                    continue
                it = {"id": idx, "tr": text}
                src_t = src_map.get(str(idx))
                if src_t:
                    it["en"] = src_t
                tag = frag_tags.get(idx, "none")
                if tag != "none":
                    it["frag"] = tag
                    if idx in frag_group_ids:
                        it["frag_group"] = frag_group_ids[idx]
                risk = ht.polish_risk_hints(src_t or "", text)
                if risk:
                    it["risk"] = risk
                items.append(it)
                original_by_id[str(idx)] = text
            for pos, (idx, _ts, _text) in enumerate(chunk):
                start = max(0, pos - 2)
                end = min(len(chunk), pos + 3)
                neighbor_texts_by_id[str(idx)] = [chunk[i][2] for i in range(start, end) if i != pos]
            # Grubun BEKLENEN üyeleri (cue sırasında) — apply_polish_group_atomic'in
            # kısmi-yanıt ve birleşik-anlam kontrolleri için. [HATA] cue'ları original_by_id'de
            # olmadığından zaten dışarıda kalır.
            chunk_group_expected = {
                gid: list(expected_ids)
                for gid, expected_ids in global_group_expected.items()
                if any(sid in original_by_id for sid in expected_ids)
            }
            if not items:
                continue
            attempted_chunks += 1
            payload = {"polish": items}
            chunk_ids = {idx for idx, _ts, _text in chunk}
            chunk_groups = [
                group for group in fragment_groups
                if any(group_item in chunk_ids for group_item in group["items"])
            ]
            if chunk_groups:
                payload["sentence_groups"] = chunk_groups
            if cs > 0:
                # Önceki chunk'ın son satırları — cilalanmış halleri öncelikli
                ctx_lines = []
                for p_idx, p_ts, p_text in sorted_blocks[max(0, cs - POLISH_CTX):cs]:
                    ctx_lines.append(result_map.get(str(p_idx), p_text))
                if ctx_lines:
                    payload["ctx"] = ctx_lines
            next_lines = []
            for n_idx, n_ts, n_text in sorted_blocks[chunk_end:chunk_end + POLISH_CTX]:
                next_lines.append(n_text)
            if next_lines:
                payload["next_ctx"] = next_lines
            total_chunks = len(polish_ranges)

            for attempt in range(2):  # 1 retry on failure
                try:
                    resp = _safe_chat_create(
                        client,
                        cancel_context=cancel_context,
                        _checkpoint_label="polish",
                        model=helper_model,
                        messages=[
                            {"role": "system", "content": sys_prompt},
                            {"role": "user",   "content": json.dumps(payload, ensure_ascii=False)},
                        ],
                        max_tokens=max(1000, len(items) * 120),
                        temperature=0.4,
                    )
                    if self.__dict__.get("_stop_flag", False) or (
                            cancel_context is not None and cancel_context.is_cancelled()):
                        return list(sorted_blocks)
                    if not resp.choices:
                        raise RuntimeError("Polish: empty choices")
                    content = resp.choices[0].message.content or ""

                    if not content.strip():
                        raise RuntimeError("Polish: empty response from API")

                    raw = _extract_json_array(content)

                    if not raw.strip():
                        raise RuntimeError("Polish: invalid JSON response")

                    _report_response_usage(
                        usage_callback, resp, log_fn=self._log,
                        pass_name="Polish Pass")
                    polished = json.loads(raw)
                    if not isinstance(polished, list):
                        raise RuntimeError("Polish: expected JSON array")
                    returned_ids = []
                    malformed_items = False
                    for candidate in polished:
                        if not isinstance(candidate, dict) or "id" not in candidate or not isinstance(candidate.get("tr"), str):
                            malformed_items = True
                            continue
                        returned_ids.append(str(candidate["id"]))
                    expected_ids = set(original_by_id)
                    returned_set = set(returned_ids)
                    if (malformed_items or len(returned_ids) != len(returned_set)
                            or not returned_set <= expected_ids):
                        missing = sorted(expected_ids - returned_set)
                        extra = sorted(set(returned_ids) - expected_ids)
                        raise RuntimeError(
                            "Polish: incomplete/invalid JSON ids "
                            f"(missing={','.join(missing[:8]) or '-'}, "
                            f"extra={','.join(extra[:8]) or '-'})")
                    if returned_set != expected_ids:
                        partial_chunks += 1
                        self._log(
                            f"Polish chunk {chunk_num}/{total_chunks}: "
                            f"{len(expected_ids - returned_set)} cue aynen korundu; "
                            "dönen güvenli öneriler uygulanacak.", "warn")
                    chunk_proposals = {}
                    for item in polished:
                        if isinstance(item, dict) and "id" in item and "tr" in item:
                            sid = str(item["id"])
                            if sid not in original_by_id:
                                continue
                            new_text = str(item["tr"])
                            frag_key = int(sid) if sid.isdigit() else item["id"]
                            fragment_tag = frag_tags.get(item["id"], frag_tags.get(frag_key, "none"))
                            group_id = frag_group_ids.get(item["id"], frag_group_ids.get(frag_key))
                            ok, reason = ht.validate_polish_candidate(
                                original_by_id[sid],
                                new_text,
                                src_map.get(sid, ""),
                                neighbor_texts=neighbor_texts_by_id.get(sid, []),
                                fragment_tag=fragment_tag,
                                locked_terms=locked_terms,
                            )
                            chunk_proposals[sid] = (new_text, ok, reason, group_id)
                    # Bir fragment grubunda değişen üyelerden biri reddedildiyse, model grubun
                    # yalnız bir kısmını döndürdüyse, ya da birleşik cümle anlamı bozulduysa
                    # grubun tamamı geri alınır — cümle bütünlüğü tek-tek kabulle bozulmasın.
                    chunk_result, chunk_rejected, chunk_reasons = ht.apply_polish_group_atomic(
                        chunk_proposals, original_by_id,
                        group_expected=chunk_group_expected, src_map=src_map,
                        locked_terms=locked_terms)
                    result_map.update(chunk_result)
                    rejected += chunk_rejected
                    for _reason_key, _count in chunk_reasons.items():
                        rejected_reasons[_reason_key] = rejected_reasons.get(_reason_key, 0) + _count
                    successful_chunks += 1
                    break
                except RequestCancelled:
                    if status_out is not None:
                        status_out.update({
                            "status": "cancelled",
                            "successful_chunks": successful_chunks,
                            "failed_chunks": max(0, attempted_chunks - successful_chunks),
                            "total_chunks": attempted_chunks, "changed": 0,
                        })
                    return list(sorted_blocks)
                except Exception as e:
                    if _is_permanent_provider_error(e):
                        permanent_error = e
                        _log_exception_or_warning(
                            self,
                            f"Polish chunk {chunk_num}/{total_chunks} kalıcı API hatası", e)
                        break
                    if attempt == 0:
                        self._log(f"Polish chunk {chunk_num}/{total_chunks} — retry...", "warn")
                        time.sleep(2)
                    else:
                        _log_exception_or_warning(
                            self, f"Polish chunk {chunk_num}/{total_chunks} hatası", e)
            if permanent_error is not None:
                attempted_chunks = total_chunks
                break

        if self.__dict__.get("_stop_flag", False) or (
                cancel_context is not None and cancel_context.is_cancelled()):
            if status_out is not None:
                status_out.update({
                    "status": "cancelled",
                    "successful_chunks": successful_chunks,
                    "failed_chunks": max(0, attempted_chunks - successful_chunks),
                    "total_chunks": attempted_chunks, "changed": 0,
                })
            return list(sorted_blocks)
        final = []
        changed = 0
        orig_by_id = {str(idx): text for idx, ts, text in sorted_blocks}
        for idx, ts, text in sorted_blocks:
            new_text = result_map.get(str(idx), text)
            if new_text != text:
                changed += 1
                self._log(f"  ✏ #{idx}  {text!r}", "warn")
                self._log(f"       → {new_text!r}", "ok")
            final.append((idx, ts, new_text))
        total = len(sorted_blocks)
        ratio = changed / total if total > 0 else 0
        failed_chunks = max(0, attempted_chunks - successful_chunks)
        pass_status = (
            "completed" if successful_chunks == attempted_chunks and not partial_chunks
            else "partial" if successful_chunks
            else "failed"
        )
        if ratio > 0.25:
            revert_count = 0
            safe_final = []
            for idx, ts, text in sorted_blocks:
                sid = str(idx)
                new_text = result_map.get(sid, text)
                if new_text != text and not ht.is_safe_polish_edit(text, new_text):
                    safe_final.append((idx, ts, text))
                    revert_count += 1
                else:
                    safe_final.append((idx, ts, new_text))
            final = safe_final
            changed = sum(1 for idx, ts, text in final if text != orig_by_id.get(str(idx), text))
            self._log(f"Polish Pass: {changed} satır değişti / {total} toplam ({revert_count} riskli düzeltme geri alındı)", "warn")
        elif ratio > 0.15:
            self._log(f"Polish Pass: %{ratio*100:.0f} satır değişti — yüksek oran, gözden geçirilmeli", "warn")
        if status_out is not None:
            status_out.update({
                "status": pass_status,
                "successful_chunks": successful_chunks,
                "failed_chunks": failed_chunks,
                "partial_chunks": partial_chunks,
                "total_chunks": attempted_chunks, "changed": changed,
            })
            if permanent_error is not None:
                status_out["error"] = str(permanent_error)
        if rejected:
            reason_txt = ", ".join(f"{k}:{v}" for k, v in sorted(rejected_reasons.items()))
            self._log(f"Polish Pass: {rejected} öneri güvenlik filtresinden döndü ({reason_txt})", "warn")
        if failed_chunks:
            self._log(
                f"Polish Pass tamamlanamadı: {successful_chunks}/{attempted_chunks} paket başarılı, "
                f"{failed_chunks} paket başarısız",
                "warn" if successful_chunks else "err")
        if ratio <= 0.25 and pass_status == "completed":
            self._log(f"Polish Pass: {changed} satır değişti / {total} toplam", "info")
        return final

    # ── Mevcut SRT post-işleme ────────────────────────────────────────────────
    def _post_process_existing(self):
        """Kullanıcının seçtiği SRT'ye pass seçimi dialoguyla işler."""
        paths = filedialog.askopenfilenames(
            title="Post-işlenecek SRT dosyalarını seç",
            filetypes=[("SRT dosyası", "*.srt"), ("Tüm dosyalar", "*.*")])
        if not paths:
            return

        # ── Pass seçim dialogu ────────────────────────────────────────────────
        dlg = ctk.CTkToplevel(self)
        dlg.title("✦  SRT Post-İşle")
        dlg.geometry("420x420")
        dlg.configure(fg_color=BG)
        dlg.grab_set()
        dlg.lift()
        dlg.focus_force()
        dlg.resizable(False, False)

        # Başlık
        ctk.CTkLabel(dlg, text="Hangi passları uygulayalım?",
                     font=ctk.CTkFont("Segoe UI", 14, "bold"),
                     text_color=FG).pack(pady=(20, 4))
        ctk.CTkLabel(dlg,
                     text=f"{len(paths)} dosya seçildi  •  Dosyalar ÜZERİNE yazılacak",
                     font=ctk.CTkFont("Segoe UI", 11),
                     text_color=FG2).pack(pady=(0, 16))

        # Checkbox'lar
        checks_fr = ctk.CTkFrame(dlg, fg_color=PANEL, corner_radius=10)
        checks_fr.pack(fill="x", padx=20, pady=(0, 16))

        passes = [
            ("🔍  Critic Pass",        "critic",        "gpt-5.4-mini ile hata tespiti"),
            ("✨  Polish Pass",        "polish",        "gpt-5.4-mini ile doğallaştırma"),
            ("🇹🇷  Native Okuyucu",   "native_reader", "Türk izleyici gözüyle doğallık"),
            ("✅  QC Kontrolü",       "qc",            "gpt-5.4-mini ile kalite kontrolü"),
            ("🧹  SDH Temizle",       "clean_sdh",     "İşitme engelli etiketleri kaldır"),
            ("↵   Satır Kırma",       "linebreak",     "42+ karakter satırları böl"),
            ("🔗  Parçalı Cue Birleştir", "merge_cues", "Kelime kelime bölünmüş cue'ları topla (dengeli 2 satır, senkron korunur)"),
            ("🤖  AI Akıllı Segmentasyon", "ai_merge", "Birleştirmenin AI'lı sürümü: anlamsal gruplama + öğe-bilinçli kırma (gpt-5.4-mini)"),
        ]

        check_vars = {}
        for i, (label, key, hint) in enumerate(passes):
            row = ctk.CTkFrame(checks_fr, fg_color="transparent")
            row.pack(fill="x", padx=12, pady=(8 if i == 0 else 2, 8 if i == len(passes)-1 else 2))
            row.grid_columnconfigure(1, weight=1)

            var = ctk.BooleanVar(value=False)
            check_vars[key] = var

            ctk.CTkCheckBox(row, text="", variable=var,
                            width=24, height=24,
                            fg_color=ACCENT, hover_color=ACCENT_HOVER,
                            border_color=BORDER).grid(row=0, column=0, padx=(0, 10))
            ctk.CTkLabel(row, text=label,
                         font=ctk.CTkFont("Segoe UI", 12, "bold"),
                         text_color=FG, anchor="w").grid(row=0, column=1, sticky="w")
            ctk.CTkLabel(row, text=hint,
                         font=ctk.CTkFont("Segoe UI", 10),
                         text_color=FG2, anchor="w").grid(row=1, column=1, sticky="w")

        # Butonlar
        btn_fr = ctk.CTkFrame(dlg, fg_color="transparent")
        btn_fr.pack(fill="x", padx=20, pady=(0, 20))
        btn_fr.grid_columnconfigure((0, 1), weight=1)

        result = [None]

        def confirm():
            selected = [k for k, v in check_vars.items() if v.get()]
            if not selected:
                messagebox.showwarning("Seçim yok", "En az bir pass seçin.", parent=dlg)
                return
            result[0] = selected
            dlg.destroy()

        def cancel():
            dlg.destroy()

        ctk.CTkButton(btn_fr, text="▶  Başlat", height=40,
                      font=ctk.CTkFont("Segoe UI", 13, "bold"),
                      fg_color=ACCENT, hover_color=ACCENT_HOVER,
                      command=confirm).grid(row=0, column=0, sticky="ew", padx=(0, 6))
        ctk.CTkButton(btn_fr, text="✕  İptal", height=40,
                      font=ctk.CTkFont("Segoe UI", 12),
                      fg_color=CARD, hover_color=BORDER,
                      command=cancel).grid(row=0, column=1, sticky="ew")

        dlg.protocol("WM_DELETE_WINDOW", cancel)
        self.wait_window(dlg)

        if result[0] is None:
            return  # kullanıcı iptal etti

        selected_passes = result[0]
        job = self._take_run_snapshot()
        job["analysis_depth"] = self.analysis_depth_var.get()
        job["ext_project_path"] = self.ext_project_path_var.get().strip()
        job["merge_max_chars"] = self._merge_max_chars
        job["merge_max_gap_ms"] = self._merge_max_gap_ms
        self._active_snapshot = _refresh_start_snapshot(
            getattr(self, "_active_snapshot", None), job)
        self._set_running(True)
        begin_run = getattr(self, "_begin_run_record", None)
        if callable(begin_run):
            begin_run(list(paths))
        self._set_phase("Post-işlem", f"{len(paths)} dosya seçildi")
        App._start_worker(self,
            self._run_post_process, (list(paths), selected_passes, job))

    def _run_post_process(self, paths: list, selected_passes: list, job=None):
        import hybrid_translate as ht
        job = dict(job or {})
        helper_keys = job.get("helper_keys") or {}
        helper_urls = job.get("helper_urls") or {}
        helper_models = job.get("helper_models") or {}
        try:
            ht.set_project_path(job.get("ext_project_path", ""))
            tgt = job.get("tgt_lang", "Turkish")
        except Exception as e:
            # Kurulum hatası (ör. harici proje yolu) → thread sessizce ölmesin, UI'yi geri aç
            self._log_exc("Post-işlem başlatılamadı", e)
            self._set_running(False)
            self._set_eta("")
            return
        n        = len(paths)
        report_rows = []
        completed_files = []
        failed_files = []
        skipped_files = []

        def _postprocess_report_row(filepath, output_path="", total=0,
                                    *, error=False, audit_skip=False,
                                    delivery_source_path=""):
            return {
                "name": Path(filepath).name,
                "source_path": str(filepath),
                "output_path": str(output_path),
                "delivery_source_path": str(delivery_source_path),
                "total": int(total or 0), "hata": int(bool(error)),
                "cps": 0, "cps_avg": 0.0, "cps_max": 0.0,
                "cons": 0, "pass_fix": 0, "qc_auto": 0, "qc": 0,
                "warn": 0, "pass_trace": {}, "pass_status": {},
                "pass_history": {}, "pass_coverage": "manuel post-işlem",
                "run_status": "error" if error else "done",
                "delivery_audit_skip": bool(audit_skip),
            }

        do_critic   = "critic"        in selected_passes
        do_polish   = "polish"        in selected_passes
        do_native   = "native_reader" in selected_passes
        do_qc       = "qc"            in selected_passes
        do_sdh      = "clean_sdh"     in selected_passes
        do_linebrk  = "linebreak"     in selected_passes
        do_merge    = "merge_cues"    in selected_passes
        do_ai_merge = "ai_merge"      in selected_passes
        mm_key = mm_url = mm_model = ""
        if do_ai_merge:
            mm_key = helper_keys.get("analysis", "")
            mm_url = helper_urls.get("analysis", "")
            mm_model = helper_models.get("analysis", "gpt-5.4-mini")

        _post_ui(self, self._show_progress_board, paths)

        for i, fp in enumerate(paths):
            if self._stop_flag:
                break
            if self._is_queued_file_removed(fp):
                skipped_files.append(fp)
                continue
            fname = Path(fp).name
            self._log(f"\n── Post-işlem [{i+1}/{n}] {fname} ──", "info")
            self._update_file_progress(fp, "Yükleniyor", 5)

            try:
                try:
                    backup_path = _create_postprocess_backup(fp)
                    self._log(
                        f"Post-işlem yedeği: {backup_path.name}", "info")
                except Exception as backup_error:
                    self._log(
                        f"{fname}: geri alınabilir yedek oluşturulamadı; "
                        f"orijinal dosyaya dokunulmadı ({backup_error})", "err")
                    self._update_file_progress(fp, "Yedek hatası", 0, "error")
                    report_rows.append(_postprocess_report_row(
                        fp, error=True, audit_skip=True))
                    failed_files.append(fp)
                    continue
                blocks = list(parse_subtitle(fp))
                if not blocks:
                    self._log(f"{fname}: geçerli blok yok, atlandı", "warn")
                    self._update_file_progress(fp, "Atlandı", 0, "skip")
                    skipped_files.append(fp)
                    continue
                postprocess_failed = False

                def _pass_failed(status):
                    return str((status or {}).get("status", "")).lower() in {
                        "failed", "cancelled"
                    }

                source_path = _resolve_postprocess_source(fp)
                source_language = job.get("src_lang", "English")
                orig_cues = (
                    ht.load_subtitle(str(source_path), source_language)
                    if source_path else None)
                analysis_result = None
                if source_path and _postprocess_source_drifted(fp, source_path):
                    self._log(
                        f"{fname}: kaynak dosya son teslimden sonra değişti; "
                        "manuel post-işlem eski çeviriyi yazmayacak.", "err")
                    self._update_file_progress(fp, "Kaynak değişti", 100, "error")
                    report_rows.append(_postprocess_report_row(
                        fp, error=True, audit_skip=True,
                        delivery_source_path=str(source_path)))
                    failed_files.append(fp)
                    continue
                if do_critic or do_polish or do_native or do_qc:
                    if orig_cues:
                        self._log(
                            f"{fname}: kaynak rapordan bulundu: {source_path.name}",
                            "info")
                    else:
                        self._log(
                            f"{fname}: gerçek kaynak raporda bulunamadığı için Critic, Polish, "
                            "Native ve QC atlandı; kaynak doğrulaması olmadan çeviri değiştirilmeyecek.",
                            "warn")
                        postprocess_failed = True

                # Critic Pass
                if do_critic and orig_cues:
                    try:
                        self._update_file_progress(fp, "Critic Pass", 20)
                        self._set_phase("Critic Pass", f"{fname}  ({i+1}/{n})")
                        self._log(f"Critic Pass — {len(blocks)} satır...", "info")
                        _before_critic = list(blocks)
                        _critic_change_log = []
                        _critic_status = {}
                        blocks = ht.critic_pass_with_helper(
                            cues=orig_cues, tr_blocks=blocks,
                            helper_api_key=helper_keys.get("critic", ""),
                            helper_url=helper_urls.get("critic", ""),
                            helper_model=helper_models.get("critic", "gpt-5.4-mini"), tgt_lang=tgt,
                            log_fn=self._log,
                            glossary=None,
                            analysis_result=analysis_result,
                            change_log=_critic_change_log,
                            scene_gap_sec=float(self._snap_get(
                                "scene_gap_seconds", self._scene_gap_seconds)),
                            token_callback=App._token_callback_for_pass(
                                self,
                                helper_models.get("critic", "gpt-5.4-mini"),
                                "Critic Pass",
                                base_url=helper_urls.get("critic", ""),
                                file_path=fp),
                            cancel_context=self.__dict__.get(
                                "_helper_request_canceller"),
                            status_out=_critic_status,
                            apply_changes=not bool(self._snap_get(
                                "quality_report_only", True)))
                        if self._stop_flag:
                            break
                        self._write_critic_change_report(
                            fp, _critic_change_log,
                            _critic_status.get("rejected_candidates", []),
                            report_only=bool(self._snap_get(
                                "quality_report_only", True)),
                            source_cues=orig_cues,
                            translation_blocks=_before_critic)
                        if _pass_failed(_critic_status):
                            postprocess_failed = True
                    except Exception as e:
                        self._log(f"Critic Pass hatası: {e}", "warn")
                        postprocess_failed = True

                # Polish Pass
                if do_polish and orig_cues:
                    try:
                        self._update_file_progress(fp, "Polish Pass", 55)
                        self._set_phase("Polish Pass", f"{fname}  ({i+1}/{n})")
                        self._log(f"Polish Pass — {len(blocks)} satır...", "info")
                        _polish_status = {}
                        blocks = self._polish_pass(
                            blocks, tgt,
                            helper_keys.get("polish", ""),
                            helper_urls.get("polish", ""),
                            helper_models.get("polish", "gpt-5.4-mini"),
                            src_map=_src_map_from_cues(orig_cues) if orig_cues else None,
                            analysis_result=analysis_result,
                            status_out=_polish_status)
                        if self._stop_flag:
                            break
                        if _pass_failed(_polish_status):
                            postprocess_failed = True
                    except Exception as e:
                        self._log(f"Polish Pass hatası: {e}", "warn")
                        postprocess_failed = True

                # Native Okuyucu Pass
                if do_native and orig_cues:
                    try:
                        self._update_file_progress(fp, "Native Okuyucu", 65)
                        self._set_phase("Native Okuyucu", f"{fname}  ({i+1}/{n})")
                        self._log(f"Native Okuyucu Pass — {len(blocks)} satır...", "info")
                        _native_status = {}
                        blocks = ht.native_reader_pass(
                            tr_blocks=blocks,
                            helper_api_key=helper_keys.get("critic", ""),
                            helper_url=helper_urls.get("critic", ""),
                            helper_model=helper_models.get("critic", "gpt-5.4-mini"), tgt_lang=tgt,
                            log_fn=self._log, analysis_result=analysis_result,
                            scene_gap_sec=float(self._snap_get(
                                "scene_gap_seconds", self._scene_gap_seconds)),
                            token_callback=App._token_callback_for_pass(
                                self,
                                helper_models.get("critic", "gpt-5.4-mini"),
                                "Native Okuyucu",
                                base_url=helper_urls.get("critic", ""),
                                file_path=fp),
                            src_map=_src_map_from_cues(orig_cues) if orig_cues else None,
                            progress_callback=App._pass_progress_callback(
                            self, fp, "Native Okuyucu", 65.0, 82.0),
                            cancel_context=self.__dict__.get("_helper_request_canceller"),
                            status_out=_native_status)
                        if self._stop_flag:
                            break
                        if _pass_failed(_native_status):
                            postprocess_failed = True
                    except Exception as e:
                        self._log(f"Native Pass hatası: {e}", "warn")
                        postprocess_failed = True

                _manual_quality_guard = _pass_structure_guard_reason(
                    "QC", list(parse_subtitle(str(backup_path))), blocks)
                if _manual_quality_guard:
                    self._log(
                        f"{fname}: kalite geçişleri altyazı yapısını değiştirdi "
                        f"({_manual_quality_guard}); orijinal dosya korunacak.",
                        "err")
                    postprocess_failed = True

                # SDH temizle
                if do_sdh:
                    try:
                        self._update_file_progress(fp, "SDH Temizle", 85)
                        blocks = clean_sdh(blocks, src_map=None, source_driven=False)
                    except Exception as e:
                        self._log(f"SDH temizleme hatası: {e}", "warn")
                        postprocess_failed = True

                # Satır kırma
                if do_linebrk:
                    try:
                        self._update_file_progress(fp, "Satır Kırma", 92)
                        blocks = apply_line_breaks(blocks)
                    except Exception as e:
                        self._log(f"Satır kırma hatası: {e}", "warn")
                        postprocess_failed = True

                # QC Kontrolü
                if do_qc and orig_cues:
                    try:
                        self._update_file_progress(fp, "QC Kontrolü", 72)
                        self._set_phase("QC Kontrolü", f"{fname}  ({i+1}/{n})")
                        self._log(f"QC Kontrolü — {len(blocks)} satır...", "info")
                        _qc_status = {}
                        _before_manual_qc = list(blocks)
                        blocks = self._run_quality_check_inline(
                            fp, orig_cues, blocks, 
                            helper_keys.get("qc", ""),
                            helper_urls.get("qc", ""),
                            helper_models.get("qc", "gpt-5.4-mini"),
                            tgt, analysis_result=analysis_result,
                            use_passed_credentials=True,
                            status_out=_qc_status)
                        _manual_qc_guard = _pass_structure_guard_reason(
                            "QC", _before_manual_qc, blocks)
                        if _manual_qc_guard:
                            self._log(
                                f"{fname}: QC altyazı yapısını değiştirdi "
                                f"({_manual_qc_guard}); orijinal dosya korunacak.",
                                "err")
                            postprocess_failed = True
                        if _pass_failed(_qc_status):
                            postprocess_failed = True
                    except Exception as e:
                        self._log(f"QC hatası: {e}", "warn")
                        postprocess_failed = True
                elif do_qc:
                    self._log(
                        "QC atlandı: post-işlemde gerçek kaynak altyazı seçilmedi.",
                        "warn",
                    )

                # Parçalı cue birleştirme (en son — dengeli 2 satır, senkron korunur)
                # AI segmentasyon seçiliyse onun (anlamsal) sürümü, değilse hızlı algoritma.
                if do_ai_merge and mm_key:
                    try:
                        self._update_file_progress(fp, "AI Segmentasyon", 96)
                        _before = len(blocks)
                        blocks = ai_resegment_cues(
                            blocks, mm_key, mm_url, mm_model, log_fn=self._log,
                            max_chars=job.get("merge_max_chars", MERGE_MAX_CHARS),
                            max_gap_ms=job.get("merge_max_gap_ms", MERGE_MAX_GAP_MS),
                            token_callback=_app_token_callback(
                                self, mm_model, "AI Segmentasyon",
                                base_url=mm_url, file_path=fp),
                            cancel_context=self.__dict__.get(
                                "_helper_request_canceller"))
                        self._log(f"AI segmentasyon: {_before} → {len(blocks)} blok", "ok")
                    except RequestCancelled:
                        raise
                    except Exception as e:
                        self._log(f"AI segmentasyon hatası: {e}", "warn")
                        postprocess_failed = True
                elif do_merge or (do_ai_merge and not mm_key):
                    try:
                        if do_ai_merge and not mm_key:
                            self._log("AI segmentasyon: API anahtarı yok, hızlı birleştirmeye düşülüyor", "warn")
                        self._update_file_progress(fp, "Cue Birleştirme", 96)
                        _before = len(blocks)
                        blocks = merge_fragmented_cues(
                            blocks,
                            max_chars=job.get("merge_max_chars", MERGE_MAX_CHARS),
                            max_gap_ms=job.get("merge_max_gap_ms", MERGE_MAX_GAP_MS),
                            source_cues=orig_cues)
                        self._log(f"Parçalı cue birleştirme: {_before} → {len(blocks)} blok", "ok")
                    except Exception as e:
                        self._log(f"Cue birleştirme hatası: {e}", "warn")
                        postprocess_failed = True

                if postprocess_failed:
                    self._log(
                        f"{fname}: seçilen post-işlem geçişlerinden en az biri "
                        "tamamlanamadı; orijinal dosya değiştirilmedi.", "err")
                    self._update_file_progress(
                        fp, "Post-işlem tamamlanamadı", 100, "error")
                    report_rows.append(_postprocess_report_row(
                        fp, fp, len(blocks), error=True, audit_skip=True,
                        delivery_source_path=str(source_path or backup_path)))
                    failed_files.append(fp)
                    continue

                if orig_cues:
                    _raw_map = _raw_src_map_from_cues(orig_cues)
                    blocks, _ = _fill_hata_with_source(blocks, _raw_map, log_fn=self._log)
                    blocks = _restore_tags_blocks(blocks, _raw_map)

                _delivery_blocks = _prepare_upload_ready_blocks(
                    blocks, tgt, self._log, source_cues=orig_cues)
                if self._stop_flag:
                    self._log(
                        f"{fname}: durdurma istendi; post-işlem sonucu yazılmadı.",
                        "warn")
                    skipped_files.append(fp)
                    break
                ownership_guard = _postprocess_write_guard_reason(fp, backup_path)
                if ownership_guard:
                    self._log(
                        f"{fname}: post-işlem sürerken hedef dosya değişti; "
                        "kullanıcının daha yeni çıktısı korunuyor.", "err")
                    self._update_file_progress(fp, "Hedef değişti", 100, "error")
                    report_rows.append(_postprocess_report_row(
                        fp, error=True, audit_skip=True,
                        delivery_source_path=str(source_path or backup_path)))
                    failed_files.append(fp)
                    continue
                if source_path and _postprocess_source_drifted(fp, source_path):
                    self._log(
                        f"{fname}: kalite geçişleri sırasında kaynak değişti; "
                        "eski çeviri yazılmadı.", "err")
                    self._update_file_progress(fp, "Kaynak değişti", 100, "error")
                    report_rows.append(_postprocess_report_row(
                        fp, error=True, audit_skip=True,
                        delivery_source_path=str(source_path)))
                    failed_files.append(fp)
                    continue
                write_srt(fp, _delivery_blocks, tgt)
                audit_source = str(source_path or backup_path)
                delivery_audit = _subtitle_delivery_audit(
                    audit_source, fp, tgt, source_language)
                if _delivery_audit_has_hard_error(delivery_audit):
                    quarantined = self._maybe_quarantine_incomplete_final(fp)
                    if self._delivery_report_only_enabled():
                        self._log(
                            f"{fname}: post-işlem çıktısı inceleme gerektiriyor; "
                            "çıktı yerinde bırakıldı (Yalnız Raporla).", "warn")
                    else:
                        self._log(
                            f"{fname}: post-işlem çıktısı teslim denetiminden geçmedi; "
                            f"{Path(quarantined).name if quarantined else 'karantina başarısız'}",
                            "err")
                    self._update_file_progress(
                        fp, "Teslim denetimi başarısız", 100, "error")
                    report_rows.append(_postprocess_report_row(
                        fp, quarantined or fp, len(_delivery_blocks), error=True,
                        delivery_source_path=audit_source))
                    failed_files.append(fp)
                    continue
                self._log(f"Kaydedildi: {fp}  ({len(blocks)} satır)", "ok")
                self._update_file_progress(fp,
                    f"Tamamlandı  {len(blocks)} satır", 100, "done")
                report_rows.append(_postprocess_report_row(
                    fp, fp, len(_delivery_blocks),
                    delivery_source_path=audit_source))
                completed_files.append(fp)

            except Exception as e:
                self._log_exc(f"[{fname}] post-işlem hatası", e)
                self._update_file_progress(fp, "Hata", 0, "error")
                report_rows.append(_postprocess_report_row(
                    fp, fp, error=True, audit_skip=True))
                failed_files.append(fp)

        self._save_quality_report(report_rows, self.output_var.get())
        completed_files, failed_files = _reconcile_delivery_outcomes(
            report_rows, completed_files, failed_files)
        outcome = summarize_file_outcomes(
            completed_files, failed_files, skipped_files,
            total_files=n, stop_flag=self._stop_flag)
        self._set_running(False)
        self._set_eta("")
        if outcome["is_full_success"]:
            self._set_phase("Tamamlandı", outcome["summary_text"])
            self._set_progress(100)
        elif self._stop_flag:
            self._set_phase("Hazır", outcome["summary_text"])
        else:
            self._set_phase("Kısmen tamamlandı" if outcome["is_partial_success"] else "Hata",
                            outcome["summary_text"])

    def _run_quality_check_inline(self, fp, orig_cues, blocks, mm_key, mm_url,
                                   mm_model, tgt, analysis_result=None,
                                   stats=None, use_passed_credentials=False,
                                   status_out=None):
        """QC kontrolü yap, dialog göster, onaylanan düzeltmeleri uygula. Güncel blocks döner.

        Uygulanan TÜM düzeltmeler (otomatik + dialogdan onaylı) <dosya>.qc_degisiklikler.txt'e
        öncesi/sonrasıyla yazılır. Neden: log sadece "X/Y satır yeniden çevrildi" özeti
        veriyor, hangi satırın neye dönüştüğünü göstermiyor — üstelik gerçekten uygulanan
        metin dialogdaki "Öneri" ile AYNI OLMAYABİLİR: onaylanan her satır qc_auto_fix
        içinde kaynak+hata+öneri eşliğinde YENİDEN çevriliyor, öneri sadece bir ipucu;
        yalnızca o yeniden-çeviri başarısız/güvenlik-filtresinden dönerse öneri metni
        aynen uygulanıyor. Kullanıcı gerçek sonucu görmeden onaylamış oluyordu."""
        import hybrid_translate as ht
        locked_getter = getattr(self, "_get_locked_terms_dict", None)
        locked_terms = locked_getter(fp, tgt) if callable(locked_getter) else {}
        if use_passed_credentials or not hasattr(self, "_helper_api_key"):
            qc_key, qc_url, qc_model = mm_key, mm_url, mm_model
        else:
            qc_key = self._helper_api_key("qc")
            qc_url = self._helper_api_base_url("qc")
            qc_model = self._helper_api_model("qc")
        cancel_context = self.__dict__.get("_helper_request_canceller")
        try:
            issues = ht.quality_check_with_helper(
                cues=orig_cues,
                tr_blocks=blocks,
                helper_api_key=qc_key,
                helper_url=qc_url,
                helper_model=qc_model,
                tgt_lang=tgt,
                log_fn=self._log,
                analysis_result=analysis_result,
                cancel_context=cancel_context,
                token_callback=App._token_callback_for_pass(
                    self, qc_model, "QC", base_url=qc_url, file_path=fp),
                status_out=status_out,
            )
        except Exception as e:
            self._log_exc("QC hatası", e)
            if status_out is not None:
                status_out.update({"status": "failed", "error": str(e)})
            return blocks
        if self.__dict__.get("_stop_flag", False) or (
                cancel_context is not None and cancel_context.is_cancelled()):
            return blocks

        if not issues:
            self._log("QC: sorun bulunamadı ✓", "ok")
            return blocks

        applied_records = []  # [{id, source, before, after, problem}]

        def _record(applied_issues, before_map, after_blocks):
            after_map = {str(b[0]): b[2] for b in after_blocks}
            for iss in applied_issues:
                iid = str(iss.get("id", ""))
                before = before_map.get(iid, iss.get("current", ""))
                after = after_map.get(iid, before)
                if after != before:
                    applied_records.append({
                        "id": iid, "source": iss.get("original", ""),
                        "before": before, "after": after,
                        "problem": iss.get("problem", ""),
                    })

        auto_issues, review_issues = ht.split_qc_issues_for_review(issues)
        if auto_issues:
            self._log(f"QC auto: {len(auto_issues)} düşük/orta severity düzeltme uygulanıyor", "info")
            before_map = {str(b[0]): b[2] for b in blocks}
            blocks = ht.qc_auto_fix(
                issues=auto_issues,
                tr_blocks=blocks,
                helper_api_key=qc_key,
                model=qc_model,
                tgt_lang=tgt,
                base_url=qc_url,
                log_fn=self._log,
                locked_terms=locked_terms,
                cancel_context=cancel_context,
                token_callback=App._token_callback_for_pass(
                    self, qc_model, "QC", base_url=qc_url, file_path=fp),
            )
            if self.__dict__.get("_stop_flag", False) or (
                    cancel_context is not None and cancel_context.is_cancelled()):
                return [
                    (idx, ts, before_map.get(str(idx), text))
                    for idx, ts, text in blocks
                ]
            before_count = len(applied_records)
            _record(auto_issues, before_map, blocks)
            if stats is not None:
                stats["qc_auto"] = stats.get("qc_auto", 0) + (
                    len(applied_records) - before_count)

        if not review_issues:
            self._write_qc_change_report(fp, applied_records)
            return blocks

        self._log(f"QC: {len(review_issues)} sorun insan onayı bekliyor — dialog açılıyor...", "warn")
        qc_event       = threading.Event()
        approved_fixes = []
        _post_ui(self, self._show_qc_dialog, review_issues, approved_fixes, qc_event)
        status = self._wait_for_dialog_event(qc_event, timeout=300)
        if status == "stopped":
            self._write_qc_change_report(fp, applied_records)
            return blocks
        if status == "timeout":
            self._set_status("QC: süre aşımı")

        if approved_fixes and status == "completed":
            before_map = {str(b[0]): b[2] for b in blocks}
            blocks = ht.qc_auto_fix(
                issues=approved_fixes,
                tr_blocks=blocks,
                helper_api_key=qc_key,
                model=qc_model,
                tgt_lang=tgt,
                base_url=qc_url,
                log_fn=self._log,
                locked_terms=locked_terms,
                cancel_context=cancel_context,
                token_callback=App._token_callback_for_pass(
                    self, qc_model, "QC", base_url=qc_url, file_path=fp),
            )
            if self.__dict__.get("_stop_flag", False) or (
                    cancel_context is not None and cancel_context.is_cancelled()):
                return [
                    (idx, ts, before_map.get(str(idx), text))
                    for idx, ts, text in blocks
                ]
            before_count = len(applied_records)
            _record(approved_fixes, before_map, blocks)
            if stats is not None:
                stats["qc"] = stats.get("qc", 0) + (
                    len(applied_records) - before_count)

        self._write_qc_change_report(fp, applied_records)
        return blocks

    def _write_qc_change_report(self, fp, applied_records: list):
        """QC tarafından fiilen değiştirilen satırları TEK bir txt dosyasına
        (kaynak/öncesi/sonrası) yazar — kullanıcı bunu paylaşıp kontrol ettirebilsin
        diye. Değişen satır yoksa dosya hiç yazılmaz (eski bir rapor varsa da
        silinmez — çağıran her zaman yeni bir liste ile çağırır)."""
        report_path = (
            Path(fp).parent / "Raporlar"
            / f"{Path(fp).stem}.qc_degisiklikler.txt")
        if not applied_records:
            report_path.unlink(missing_ok=True)
            return
        try:
            report_path.parent.mkdir(parents=True, exist_ok=True)
            lines = [f"QC Değişiklikleri — {Path(fp).name}", f"Toplam: {len(applied_records)} satır", "=" * 60, ""]
            for rec in applied_records:
                lines.append(f"#{rec['id']}  [{rec['problem']}]")
                if rec["source"]:
                    lines.append(f"Kaynak : {rec['source']}")
                lines.append(f"Önce   : {rec['before']}")
                lines.append(f"Sonra  : {rec['after']}")
                lines.append("")
            atomic_write_text(report_path, "\n".join(lines), encoding="utf-8")
            self._log(f"QC değişiklik raporu: {report_path.name}  ({len(applied_records)} satır)", "ok")
        except Exception as e:
            self._log_exc("QC değişiklik raporu yazılamadı", e)

    def _write_critic_change_report(
            self, fp, applied_records: list, rejected_records: list | None = None,
            report_only: bool = False, source_cues=None,
            translation_blocks=None):
        """Critic Pass tarafından fiilen değiştirilen satırları TEK bir txt
        dosyasına (kaynak/öncesi/sonrası/sebep) yazar — QC değişiklik raporuyla
        aynı motivasyon (bkz. _write_qc_change_report yukarıda): Critic 150-200
        satır değiştirebiliyor ama hangi satırın NEDEN değiştiğini kimse
        göremiyordu."""
        report_path = (
            Path(fp).parent / "Raporlar"
            / f"{Path(fp).stem}.critic_degisiklikler.txt")
        applied_records = _candidate_records_with_context(
            applied_records, source_cues, translation_blocks)
        rejected_records = _candidate_records_with_context(
            rejected_records, source_cues, translation_blocks)
        if not applied_records and not rejected_records:
            report_path.unlink(missing_ok=True)
            return
        try:
            report_path.parent.mkdir(parents=True, exist_ok=True)
            lines = [
                f"Critic Denetimi — {Path(fp).name}",
                f"Toplam: {len(applied_records)} satır",
                (f"Yalnız raporlanan: {len(applied_records)} | "
                 f"Korunan/reddedilen: {len(rejected_records)}"
                 if report_only else
                 f"Uygulanan: {len(applied_records)} | Korunan/reddedilen: {len(rejected_records)}"),
                "=" * 60, "",
            ]
            if applied_records:
                lines.extend([
                    "YALNIZ RAPORLANAN ÖNERİLER" if report_only else "UYGULANAN DÜZELTMELER",
                    ("Bu öneriler altyazıya uygulanmadı; mevcut Türkçe aynen korundu."
                     if report_only else ""),
                    "-" * 60, "",
                ])
            for rec in applied_records:
                lines.append(f"#{rec['id']}  [{rec.get('reason', '')}]")
                if rec.get("source"):
                    lines.append(f"Kaynak : {rec['source']}")
                lines.append(f"Önce   : {rec['before']}")
                lines.append(f"Sonra  : {rec['after']}")
                _append_candidate_context(lines, rec)
                lines.append("")
            if rejected_records:
                lines.extend([
                    "KORUNAN / REDDEDİLEN ÖNERİLER",
                    "Bu öneriler altyazıya uygulanmadı; mevcut Türkçe aynen korundu.",
                    "-" * 60, "",
                ])
                for rec in rejected_records:
                    lines.append(f"#{rec.get('id', '')}  [{rec.get('reason', '')}]")
                    if rec.get("source"):
                        lines.append(f"Kaynak : {rec['source']}")
                    lines.append(f"Mevcut : {rec.get('before', '')}")
                    lines.append(f"Öneri  : {rec.get('candidate', '')}")
                    _append_candidate_context(lines, rec)
                    lines.append("")
            atomic_write_text(report_path, "\n".join(lines), encoding="utf-8")
            self._log(
                f"Critic değişiklik raporu/denetimi: {report_path.name}  "
                f"({len(applied_records)} "
                f"{'yalnız raporlandı' if report_only else 'uygulandı'}, "
                f"{len(rejected_records)} korundu)",
                "ok")
        except Exception as e:
            self._log_exc("Critic değişiklik raporu yazılamadı", e)

    def _write_term_normalize_report(
            self, fp, status: dict, source_cues=None,
            translation_blocks=None):
        report_path = (
            Path(fp).parent / "Raporlar"
            / f"{Path(fp).stem}.terim_normalizasyonu.txt")
        status = dict(status or {})
        safe = _candidate_records_with_context(
            status.get("safe_candidates"), source_cues, translation_blocks)
        rejected = _candidate_records_with_context(
            status.get("rejected_candidates"), source_cues,
            translation_blocks)
        response_issues = list(status.get("response_issues") or [])
        if not safe and not rejected and not response_issues:
            report_path.unlink(missing_ok=True)
            return
        try:
            report_path.parent.mkdir(parents=True, exist_ok=True)
            report_only = bool(status.get("report_only"))
            lines = [
                f"Terim Normalizasyonu — {Path(fp).name}",
                f"Durum: {status.get('status', 'unknown')}",
                (f"Güvenli öneri: {len(safe)} (altyazıya uygulanmadı)"
                 if report_only else f"Uygulanan: {len(safe)}"),
                f"Korunan/reddedilen: {len(rejected)}",
                f"JSON/kimlik sorunu: {len(response_issues)}",
                "=" * 60, "",
            ]
            if safe:
                lines.extend([
                    ("YALNIZ RAPORLANAN GÜVENLİ ÖNERİLER"
                     if report_only else "UYGULANAN TERİM DÜZELTMELERİ"),
                    "-" * 60, "",
                ])
                for record in safe:
                    fixes = ", ".join(
                        f"{wrong}->{correct}"
                        for wrong, correct in record.get("fixes") or [])
                    lines.append(f"#{record.get('id', '?')}  [{fixes or '-'}]")
                    lines.append(f"Kaynak : {record.get('source', '')}")
                    lines.append(f"Mevcut : {record.get('before', '')}")
                    lines.append(f"Öneri  : {record.get('candidate', '')}")
                    _append_candidate_context(lines, record)
                    lines.append("")
            if rejected:
                lines.extend([
                    "KORUNAN / REDDEDİLEN TERİM ÖNERİLERİ",
                    "-" * 60, "",
                ])
                for record in rejected:
                    lines.append(
                        f"#{record.get('id', '?')}  "
                        f"[{record.get('reason', 'unknown')}]")
                    lines.append(f"Kaynak : {record.get('source', '')}")
                    lines.append(f"Mevcut : {record.get('before', '')}")
                    lines.append(f"Öneri  : {record.get('candidate', '')}")
                    _append_candidate_context(lines, record)
                    lines.append("")
            if response_issues:
                lines.extend(["JSON / KİMLİK SORUNLARI", "-" * 60])
                for issue in response_issues:
                    lines.append(
                        f"- #{issue.get('id', '?')}: "
                        f"{issue.get('reason', 'unknown')}")
            atomic_write_text(report_path, "\n".join(lines), encoding="utf-8")
            self._log(
                f"Terim normalizasyonu tanı raporu: {report_path.name} "
                f"({len(safe)} güvenli, {len(rejected)} korundu, "
                f"{len(response_issues)} yanıt sorunu)", "ok")
        except Exception as e:
            self._log_exc("Terim normalizasyonu tanı raporu yazılamadı", e)

    def _dismiss_modal_dialog(self, target_dlg=None, target_event=None):
        """Worker timeout/stop durumunda hâlâ açık olan modal inceleme dialog'unu (QC/Glossary) kapatır.
        Hedef dialog/event aktif modal ile eşleşmiyorsa no-op. Ana thread'de çağrılır."""
        dlg = getattr(self, "_active_modal_dlg", None)
        active_event = getattr(self, "_active_modal_event", None)
        if target_dlg is not None and dlg is not target_dlg:
            return
        if target_event is not None and active_event is not target_event:
            return
        self._active_modal_dlg = None
        self._active_modal_event = None
        try:
            if dlg is not None and dlg.winfo_exists():
                dlg.destroy()
        except Exception:
            pass

    def _wait_for_dialog_event(self, event: threading.Event, timeout: float = 300.0, poll_interval: float = 0.5) -> str:
        """Modal inceleme dialog event'ini self._stop_flag kontrolü ile güvenli şekilde bekler.

        Returns:
            "completed": Kullanıcı dialogu onayladı/kapattı (event set edildi).
            "stopped":   Kullanıcı 'Durdur' düğmesine bastı (self._stop_flag True oldu).
            "timeout":   Belirtilen süre (timeout) doldu.
        """
        start = time.monotonic()
        while not event.is_set():
            if getattr(self, "_stop_flag", False):
                event._dialog_cancelled = True
                _post_ui(self, self._dismiss_modal_dialog, target_event=event)
                return "stopped"
            if time.monotonic() - start >= timeout:
                event._dialog_cancelled = True
                _post_ui(self, self._dismiss_modal_dialog, target_event=event)
                return "timeout"
            event.wait(timeout=poll_interval)
        return "completed"

    def _probe_main_provider_once(self, client, model: str, file_path: str = ""):
        body = {
            "model": model,
            "messages": [{
                "role": "user",
                "content": "API health check. Reply with exactly OK.",
            }],
            "max_completion_tokens": 128,
            "timeout": 45,
        }
        try:
            import hybrid_translate as ht
            body = ht._normalize_chat_create_kwargs(model, body)
        except Exception:
            pass
        request_client = client
        try:
            request_client = client.with_options(max_retries=0)
        except (AttributeError, TypeError):
            pass
        cancel_context = self.__dict__.get("_helper_request_canceller")
        if cancel_context is not None:
            cancel_context.raise_if_cancelled()
            cancel_context.register(request_client)
        try:
            from provider_retry import provider_call_with_retry
            response = provider_call_with_retry(
                lambda: request_client.chat.completions.create(**body),
                request_client,
                model,
                {"operation": "provider_health_probe"},
                cancel_check=(cancel_context.is_cancelled
                              if cancel_context is not None else None),
                retry_delays=(),
            )
            _validated_chat_content(response)
            _report_response_usage(
                _app_token_callback(
                    self, model, "Sağlayıcı Sağlık Testi",
                    base_url=self._main_api_base_url(), file_path=file_path),
                response, log_fn=self._log,
                pass_name="Sağlayıcı Sağlık Testi", filepath=file_path)
            return response
        finally:
            if cancel_context is not None:
                cancel_context.unregister(request_client)

    def _show_provider_recovery_dialog(self, client, model: str, error_text: str,
                                       file_path: str, result: dict,
                                       done_event: threading.Event):
        if getattr(done_event, "_dialog_cancelled", False):
            return
        try:
            dlg = ctk.CTkToplevel(self)
            dlg.title("Modelden yanıt alınamadı")
            dlg.geometry("620x390")
            dlg.resizable(False, False)
            dlg.transient(self)
            dlg.grab_set()
            dlg.configure(fg_color=BG)
            self._active_modal_dlg = dlg
            self._active_modal_event = done_event

            ctk.CTkLabel(
                dlg, text="⚠  Modelden yanıt alınamadı",
                font=ctk.CTkFont("Segoe UI", 18, "bold"),
                text_color=ORANGE_LIVE,
            ).pack(padx=24, pady=(24, 8))
            ctk.CTkLabel(
                dlg,
                text=(
                    "Otomatik bağlantı denemeleri tamamlandı. Çeviri şu anda "
                    "bekletiliyor; mevcut ve tamamlanmış chunk'lar korunuyor."
                ),
                font=ctk.CTkFont("Segoe UI", 12), text_color=FG,
                wraplength=560, justify="center",
            ).pack(padx=24, pady=(0, 12))
            ctk.CTkLabel(
                dlg, text=f"Model: {model}\nSon hata: {error_text[:360]}",
                font=ctk.CTkFont("Consolas", 10), text_color=FG2,
                wraplength=560, justify="left",
            ).pack(fill="x", padx=28, pady=(0, 14))
            status = ctk.CTkLabel(
                dlg,
                text="Bekleniyor. Hazır olduğunda modeli tek bir küçük istekle test et.",
                font=ctk.CTkFont("Segoe UI", 11, "bold"), text_color=FG2,
                wraplength=560,
            )
            status.pack(padx=24, pady=(0, 18))

            buttons = ctk.CTkFrame(dlg, fg_color="transparent")
            buttons.pack(fill="x", padx=24, pady=(0, 22))
            buttons.grid_columnconfigure((0, 1, 2), weight=1)
            continue_btn = ctk.CTkButton(
                buttons, text="Devam Et", state="disabled",
                fg_color=BORDER, hover_color=BORDER)
            test_in_progress = {"value": False}

            def _probe_finished(ok: bool, detail: str = ""):
                test_in_progress["value"] = False
                if getattr(done_event, "_dialog_cancelled", False):
                    return
                try:
                    if not dlg.winfo_exists():
                        return
                    if ok:
                        status.configure(
                            text="✓ Model yanıt verdi. Devam Et düğmesi hazır.",
                            text_color=GREEN)
                        test_btn.configure(text="Tekrar Test Et", state="normal")
                        continue_btn.configure(
                            state="normal", fg_color=GREEN,
                            hover_color=GREEN_HOVER)
                    else:
                        status.configure(
                            text=f"Model hâlâ yanıt vermiyor: {detail[:280]}",
                            text_color=RED)
                        test_btn.configure(text="Tekrar Dene", state="normal")
                        continue_btn.configure(
                            state="disabled", fg_color=BORDER,
                            hover_color=BORDER)
                except Exception:
                    pass

            def _test_model():
                if test_in_progress["value"]:
                    return
                test_in_progress["value"] = True
                test_btn.configure(text="Test ediliyor...", state="disabled")
                continue_btn.configure(
                    state="disabled", fg_color=BORDER, hover_color=BORDER)
                status.configure(
                    text="Modele tek bir küçük deneme isteği gönderiliyor...",
                    text_color=ACCENT)

                def _worker():
                    try:
                        self._probe_main_provider_once(
                            client, model, file_path=file_path)
                    except RequestCancelled:
                        _post_ui(self, _probe_finished, False, "çalışma durduruldu")
                    except Exception as exc:
                        safe = _sanitize_settings_backup_text(str(exc))
                        self._log(
                            f"Sağlayıcı sağlık testi başarısız: {safe[:360]}",
                            "warn")
                        _post_ui(self, _probe_finished, False, safe)
                    else:
                        self._log(
                            "Sağlayıcı sağlık testi başarılı: model yanıt verdi",
                            "ok")
                        _post_ui(self, _probe_finished, True, "")

                App._start_worker(self, _worker)

            def _continue():
                result["decision"] = "continue"
                done_event.set()
                self._active_modal_dlg = None
                self._active_modal_event = None
                dlg.destroy()

            def _wait():
                self._log(
                    "Kullanıcı sağlayıcı düzelene kadar beklemeyi seçti", "warn")
                status.configure(
                    text="Çeviri beklemede. Hazır olduğunda Tekrar Dene'ye bas.",
                    text_color=FG2)

            def _stop_run():
                result["decision"] = "stop"
                done_event.set()
                self._active_modal_dlg = None
                self._active_modal_event = None
                dlg.destroy()
                self._stop()

            test_btn = ctk.CTkButton(
                buttons, text="Modeli Test Et", command=_test_model,
                fg_color=ACCENT, hover_color=ACCENT_HOVER)
            test_btn.grid(row=0, column=0, padx=5, sticky="ew")
            ctk.CTkButton(
                buttons, text="Bekle", command=_wait,
                fg_color=CARD, hover_color=BORDER,
            ).grid(row=0, column=1, padx=5, sticky="ew")
            continue_btn.configure(command=_continue)
            continue_btn.grid(row=0, column=2, padx=5, sticky="ew")
            ctk.CTkButton(
                dlg, text="Çalışmayı Durdur", command=_stop_run,
                fg_color=RED, hover_color=RED_HOVER, width=180,
            ).pack(pady=(0, 20))
            dlg.protocol("WM_DELETE_WINDOW", _wait)
            dlg.lift()
            dlg.focus_force()
        except Exception as exc:
            self._log_exc("Sağlayıcı bekleme penceresi açılamadı", exc)
            result["decision"] = "stop"
            done_event.set()

    def _coordinate_provider_recovery(self, client, model: str, exc,
                                      observed_generation: int,
                                      file_path: str = "") -> bool:
        condition = self._provider_recovery_condition
        with condition:
            if self._provider_recovery_generation != observed_generation:
                return True
            if self._provider_recovery_active:
                while (self._provider_recovery_active
                       and not getattr(self, "_stop_flag", False)):
                    condition.wait(timeout=0.5)
                return (
                    not getattr(self, "_stop_flag", False)
                    and self._provider_recovery_generation != observed_generation
                )
            self._provider_recovery_active = True

        result = {"decision": ""}
        done_event = threading.Event()
        safe_error = _sanitize_settings_backup_text(str(exc))
        self._log(
            "API/model otomatik denemeleri tükendi; kullanıcı kararı için "
            "çeviri bekletiliyor", "warn")
        self._set_status("Model yanıt vermiyor — kullanıcı kararı bekleniyor...")
        _post_ui(
            self, self._show_provider_recovery_dialog,
            client, model, safe_error, file_path, result, done_event)
        while not done_event.wait(timeout=0.5):
            if getattr(self, "_stop_flag", False):
                done_event._dialog_cancelled = True
                _post_ui(self, self._dismiss_modal_dialog,
                         target_event=done_event)
                result["decision"] = "stop"
                break

        should_continue = result.get("decision") == "continue"
        with condition:
            if should_continue:
                self._provider_recovery_generation += 1
            self._provider_recovery_active = False
            condition.notify_all()
        if should_continue:
            self._log(
                "Sağlayıcı sağlık testi başarılı; bekleyen chunk yeniden deneniyor",
                "ok")
            self._set_status("Model yeniden erişilebilir — çeviri sürüyor...")
        return should_continue

    def _main_translation_chat_create(self, client, body: dict,
                                      file_path: str = "",
                                      checkpoint_label: str = "main_translation"):
        observed_generation = self._provider_recovery_generation
        while True:
            try:
                return _safe_chat_create(
                    client,
                    cancel_context=self.__dict__.get(
                        "_helper_request_canceller"),
                    _checkpoint_label=checkpoint_label,
                    **body,
                )
            except RequestCancelled:
                raise
            except Exception as exc:
                if not _should_offer_provider_recovery(exc):
                    raise
                if not self._coordinate_provider_recovery(
                        client, str(body.get("model") or ""), exc,
                        observed_generation, file_path=file_path):
                    if getattr(self, "_stop_flag", False):
                        raise RequestCancelled("request cancelled") from exc
                    raise
                observed_generation = self._provider_recovery_generation

    # ── QC Dialog ────────────────────────────────────────────────────────────
    def _show_qc_dialog(self, issues: list, result_holder: list, done_event: threading.Event):
        """Show QC review dialog. Must be called on main thread."""
        if getattr(done_event, "_dialog_cancelled", False):
            return
        if not issues:
            done_event.set()
            return
        try:
            self._build_qc_dialog(issues, result_holder, done_event)
        except Exception as e:
            # Dialog kurulamazsa worker'ı 5 dk (qc_event.wait timeout) bekletme —
            # event'i hemen set et, fix uygulanmadan devam etsin
            self._log_exc("QC dialog açılamadı", e)
            done_event.set()

    def _build_qc_dialog(self, issues: list, result_holder: list, done_event: threading.Event):
        dlg = ctk.CTkToplevel(self)
        dlg.title(f"Kalite Kontrolü — {len(issues)} sorun bulundu")
        dlg.geometry("880x580")
        dlg.grab_set()
        dlg.configure(fg_color=BG)
        dlg.lift()
        dlg.focus_force()
        self._active_modal_dlg = dlg   # worker timeout'unda kapatabilmek için referans tut
        self._active_modal_event = done_event

        ctk.CTkLabel(dlg,
                     text=f"{len(issues)} potansiyel çeviri sorunu tespit edildi. "
                          f"Onayladıklarınız uygulanır:",
                     font=ctk.CTkFont("Segoe UI", 12), text_color=YELLOW,
                     wraplength=820).pack(padx=16, pady=(14,4))

        sf = ctk.CTkScrollableFrame(dlg, fg_color=PANEL, corner_radius=8)
        sf.pack(fill="both", expand=True, padx=12, pady=8)

        check_vars = []
        for issue in issues:
            row_fr = ctk.CTkFrame(sf, fg_color=CARD, corner_radius=8)
            row_fr.pack(fill="x", padx=4, pady=(0,6))
            info_fr = ctk.CTkFrame(row_fr, fg_color="transparent")
            info_fr.pack(fill="x", padx=10, pady=8)

            var = ctk.BooleanVar(value=True)
            check_vars.append(var)

            header_txt = f"#{issue.get('id','?')}  {issue.get('problem','')}"
            ctk.CTkCheckBox(info_fr, text=header_txt, variable=var,
                            fg_color=ACCENT, hover_color=ACCENT_HOVER,
                            font=ctk.CTkFont("Segoe UI", 12, "bold"),
                            text_color=FG).pack(anchor="w")
            ctk.CTkLabel(info_fr,
                         text=f"Mevcut:  {issue.get('current', '')}",
                         font=ctk.CTkFont("Segoe UI", 11), text_color=FG2,
                         wraplength=800, justify="left").pack(anchor="w", pady=(3,0))
            ctk.CTkLabel(info_fr,
                         text=f"Öneri:    {issue.get('suggestion', '')}",
                         font=ctk.CTkFont("Segoe UI", 11), text_color=GREEN,
                         wraplength=800, justify="left").pack(anchor="w", pady=(2,0))

        btn_fr = ctk.CTkFrame(dlg, fg_color="transparent")
        btn_fr.pack(fill="x", padx=12, pady=(0,14))
        btn_fr.grid_columnconfigure((0,1,2), weight=1)

        def select_all():
            for v in check_vars:
                v.set(True)

        def apply_fixes():
            for i, v in enumerate(check_vars):
                if v.get():
                    result_holder.append(issues[i])
            self._active_modal_dlg = None
            self._active_modal_event = None
            dlg.destroy()
            done_event.set()

        def cancel():
            self._active_modal_dlg = None
            self._active_modal_event = None
            dlg.destroy()
            done_event.set()

        ctk.CTkButton(btn_fr, text="Tümünü Seç",
                      fg_color=BORDER, hover_color=ACCENT,
                      command=select_all).grid(row=0, column=0, padx=4, sticky="ew")
        ctk.CTkButton(btn_fr, text="✓ Uygula",
                      fg_color=ACCENT, hover_color=ACCENT_HOVER,
                      command=apply_fixes).grid(row=0, column=1, padx=4, sticky="ew")
        ctk.CTkButton(btn_fr, text="Atla",
                      fg_color=CARD, hover_color=BORDER,
                      command=cancel).grid(row=0, column=2, padx=4, sticky="ew")

        dlg.protocol("WM_DELETE_WINDOW", cancel)

    # ── Auto-Glossary ─────────────────────────────────────────────────────────
    def _run_auto_glossary(self, cues: list, tr_blocks: list, filepath: str,
                           status_out: dict | None = None):
        """Build glossary suggestions from a completed translation and show review dialog."""
        import hybrid_translate as ht
        mm_key = self._helper_api_key("analysis")
        mm_url = self._helper_api_base_url("analysis")
        mm_mdl = self._helper_api_model("analysis")
        src_default = App._run_setting(self, "src_lang", "src_var", "English")
        effective = getattr(self, "_effective_file_source_language", None)
        src = effective(filepath, src_default) if callable(effective) else src_default
        tgt = App._run_setting(self, "tgt_lang", "tgt_var", "Turkish")
        run_status = status_out if status_out is not None else {}

        if not mm_key:
            run_status.clear()
            run_status.update({
                "status": "failed", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
                "error": "missing_api_key",
            })
            self._log("Auto-Glossary: OpenAI API anahtarı gerekli", "warn")
            return

        glossary_path = str(App._run_setting(
            self,
            "global_glossary_path", "glossary_var", "") or "").strip()
        if not glossary_path:
            run_status.clear()
            run_status.update({
                "status": "failed", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
                "error": "missing_glossary_path",
            })
            self._log(
                "Auto-Glossary: hedef sözlük yolu seçilmedi; API çağrılmadı",
                "warn")
            return
        glossary_store = Path(glossary_path)
        if not _json_glossary_store_is_valid(glossary_store):
            run_status.clear()
            run_status.update({
                "status": "failed", "successful_chunks": 0,
                "failed_chunks": 0, "total_chunks": 0, "changed": 0,
                "error": "corrupt_glossary_store",
            })
            self._log(
                "Auto-Glossary: mevcut JSON sözlük bozuk; veri kaybını "
                "önlemek için API çağrılmadı ve dosya değiştirilmedi", "err")
            return
        existing = ht.load_glossary(glossary_path, strict=True)
        token_callback_factory = getattr(
            self, "_token_callback_for_model", None)
        token_callback = (
            token_callback_factory(mm_mdl)
            if callable(token_callback_factory) else None)

        self._log(f"Auto-Glossary: {Path(filepath).name} analiz ediliyor...", "info")
        suggestions = ht.build_glossary_suggestions(
            cues=cues,
            tr_blocks=tr_blocks,
            src_lang=src,
            tgt_lang=tgt,
            helper_api_key=mm_key,
            helper_url=mm_url,
            helper_model=mm_mdl,
            existing_glossary=existing,
            log_fn=self._log,
            token_callback=token_callback,
            cancel_context=self.__dict__.get("_helper_request_canceller"),
            status_out=run_status,
        )

        if not suggestions:
            state = run_status.get("status")
            if state == "completed":
                self._log("Auto-Glossary: yeni terim önerisi yok", "ok")
            elif state == "skipped":
                self._log("Auto-Glossary: incelenecek kaynak/çeviri çifti yok", "info")
            return

        done_event    = threading.Event()
        approved_list = []
        _post_ui(self, self._show_glossary_dialog, suggestions, approved_list, done_event, glossary_path)
        status = self._wait_for_dialog_event(done_event, timeout=300)

        if status == "completed" and approved_list and glossary_path:
            try:
                gp = Path(glossary_path)
                approved = {}
                for item in approved_list:
                    src_term = str(item.get("src", "")).strip()
                    tgt_term = str(item.get("tgt", "")).strip()
                    if (not src_term or not tgt_term
                            or any(ch in src_term + tgt_term for ch in "\r\n\t=")):
                        continue
                    approved[src_term] = tgt_term
                written = len(approved)
                if not approved:
                    self._log("Auto-Glossary: geçerli onaylı terim yok", "warn")
                    return
                if gp.suffix.casefold() == ".json":
                    merged = dict(existing)
                    merged.update(approved)
                    atomic_write_json(gp, merged)
                else:
                    existing_text = read_subtitle_text(gp) if gp.exists() else ""
                    rows = [existing_text.rstrip(), "",
                            f"# Auto-Glossary — {Path(filepath).name}"]
                    rows.extend(f"{src_term} = {tgt_term}"
                                for src_term, tgt_term in approved.items())
                    atomic_write_text(gp, "\n".join(rows).lstrip("\n") + "\n")
                self._log(f"Auto-Glossary: {written} terim sözlüğe eklendi", "ok")
                run_status["written"] = written
            except Exception as e:
                run_status.update({"status": "failed", "error": str(e)})
                self._log(f"Auto-Glossary yazma hatası: {e}", "err")
        elif status == "stopped":
            run_status["status"] = "cancelled"
        elif status == "timeout":
            run_status.update({
                "status": "failed", "error": "dialog_timeout"})

    def _show_glossary_dialog(self, suggestions: list, result_holder: list,
                               done_event: threading.Event, glossary_path: str):
        """Show glossary suggestion review dialog. Must be called on main thread."""
        if getattr(done_event, "_dialog_cancelled", False):
            return
        if not suggestions:
            done_event.set()
            return

        _CATEGORY_COLORS = {
            "proper_noun": ACCENT,
            "technical":   TEAL,
            "idiom":       YELLOW,
            "recurring":   INFO_BLUE,
        }

        dlg = ctk.CTkToplevel(self)
        dlg.title(f"Auto-Glossary — {len(suggestions)} yeni terim önerisi")
        dlg.geometry("900x600")
        dlg.grab_set()
        dlg.configure(fg_color=BG)
        dlg.lift()
        dlg.focus_force()
        self._active_modal_dlg = dlg   # worker timeout'unda kapatabilmek için referans tut
        self._active_modal_event = done_event

        dest_label = Path(glossary_path).name if glossary_path else "sözlük seçilmedi"
        ctk.CTkLabel(dlg,
                     text=f"Çeviriden tespit edilen {len(suggestions)} terim. "
                          f"Onayladıklarınız '{dest_label}' dosyasına eklenir:",
                     font=ctk.CTkFont("Segoe UI", 12), text_color=YELLOW,
                     wraplength=840).pack(padx=16, pady=(14, 4))

        sf = ctk.CTkScrollableFrame(dlg, fg_color=PANEL, corner_radius=8)
        sf.pack(fill="both", expand=True, padx=12, pady=8)

        check_vars = []
        for sg in suggestions:
            row_fr = ctk.CTkFrame(sf, fg_color=CARD, corner_radius=8)
            row_fr.pack(fill="x", padx=4, pady=(0, 5))
            inner  = ctk.CTkFrame(row_fr, fg_color="transparent")
            inner.pack(fill="x", padx=10, pady=7)

            var = ctk.BooleanVar(value=True)
            check_vars.append(var)

            cat   = sg.get("category", "")
            color = _CATEGORY_COLORS.get(cat, FG2)
            ctk.CTkCheckBox(inner,
                            text=f"{sg.get('src','')}  →  {sg.get('tgt','')}",
                            variable=var,
                            fg_color=ACCENT, hover_color=ACCENT_HOVER,
                            font=ctk.CTkFont("Segoe UI", 12, "bold"),
                            text_color=FG).pack(anchor="w")
            meta = f"[{cat}]  {sg.get('reason','')}"
            ctk.CTkLabel(inner, text=meta,
                         font=ctk.CTkFont("Segoe UI", 10), text_color=color,
                         wraplength=820, justify="left").pack(anchor="w", pady=(2, 0))

        btn_fr = ctk.CTkFrame(dlg, fg_color="transparent")
        btn_fr.pack(fill="x", padx=12, pady=(0, 14))
        btn_fr.grid_columnconfigure((0, 1, 2), weight=1)

        def select_all():
            for v in check_vars:
                v.set(True)

        def add_selected():
            for i, v in enumerate(check_vars):
                if v.get():
                    result_holder.append(suggestions[i])
            self._active_modal_dlg = None
            self._active_modal_event = None
            dlg.destroy()
            done_event.set()

        def cancel():
            self._active_modal_dlg = None
            self._active_modal_event = None
            dlg.destroy()
            done_event.set()

        ctk.CTkButton(btn_fr, text="Tümünü Seç",
                      fg_color=BORDER, hover_color=ACCENT,
                      command=select_all).grid(row=0, column=0, padx=4, sticky="ew")
        ctk.CTkButton(btn_fr, text="✓ Sözlüğe Ekle",
                      fg_color=ACCENT, hover_color=ACCENT_HOVER,
                      command=add_selected).grid(row=0, column=1, padx=4, sticky="ew")
        ctk.CTkButton(btn_fr, text="Atla",
                      fg_color=CARD, hover_color=BORDER,
                      command=cancel).grid(row=0, column=2, padx=4, sticky="ew")

        dlg.protocol("WM_DELETE_WINDOW", cancel)

    # ── Senkron mod ───────────────────────────────────────────────────────────
    def _save_quality_report(self, rows: list, output_dir: str):
        """Kalite raporunu çıktı klasörüne ceviri_raporu.txt olarak yazar."""
        if not rows:
            try:
                with self._run_record_lock:
                    active_record = self._active_run_record or {}
                    run_id = str(active_record.get("run_id") or "")
                rep_dir = _resolve_report_dir(self.input_var.get(), output_dir)
                rep_dir.mkdir(parents=True, exist_ok=True)
                text = "\n".join([
                    "ÇEVİRİ KALİTE RAPORU",
                    f"Çalıştırma kimliği: {run_id or '-'}",
                    "",
                    "Bu çalıştırmada raporlanabilir nihai çıktı üretilemedi.",
                    "Ayrıntı için oturum logunu ve çalıştırma özetini inceleyin.",
                    "",
                ])
                payload = {
                    "run_id": run_id,
                    "status": "no_reportable_outputs",
                    "files": [],
                }
                txt_path = rep_dir / "ceviri_raporu.txt"
                json_path = rep_dir / "ceviri_raporu.json"
                atomic_write_text(txt_path, text, encoding="utf-8")
                atomic_write_json(json_path, payload)
                report_paths = [txt_path, json_path]
                if run_id:
                    run_path = rep_dir / f"ceviri_raporu_{run_id}.txt"
                    run_json_path = rep_dir / f"ceviri_raporu_{run_id}.json"
                    atomic_write_text(run_path, text, encoding="utf-8")
                    atomic_write_json(run_json_path, payload)
                    report_paths.extend([run_path, run_json_path])
                self._record_quality_report([], report_paths)
                self._log(
                    f"Kalite raporu: {txt_path} (nihai çıktı yok)", "warn")
                return txt_path
            except Exception as report_error:
                self._log(f"Boş kalite raporu yazılamadı: {report_error}", "err")
                return None
        try:
            snapshot = dict(getattr(self, "_active_snapshot", {}) or {})
            report_rows = []
            for source_row in rows:
                row = dict(source_row)
                source_path = str(row.get("source_path") or "")
                if row.get("delivery_audit_skip"):
                    row["delivery_audit"] = {
                        "status": "unavailable",
                        "reason": "postprocess_not_written",
                    }
                else:
                    delivery_source_path = str(
                        row.get("delivery_source_path") or source_path)
                    row["delivery_audit"] = _subtitle_delivery_audit(
                        delivery_source_path, row.get("output_path", ""),
                        self.tgt_var.get(), self._effective_file_source_language(
                            delivery_source_path, self.src_var.get()))
                if (not row.get("delivery_audit_skip") and (
                        _delivery_audit_has_hard_error(row["delivery_audit"])
                        or row.get("delivery_scan_failed"))):
                    report_only = self._delivery_report_only_enabled()
                    quarantined = self._maybe_quarantine_incomplete_final(
                        row.get("output_path", ""))
                    row["run_status"] = "review" if report_only else "error"
                    row["delivery_quarantined_path"] = str(quarantined or "")
                    if report_only:
                        self._log(
                            f"Teslim koruması: {row.get('name', 'altyazı')} inceleme "
                            "gerektiriyor; çıktı yerinde bırakıldı (Yalnız Raporla).",
                            "warn",
                        )
                    else:
                        self._log(
                            f"Teslim koruması: {row.get('name', 'altyazı')} yüklemeye hazır değil; "
                            f"{Path(quarantined).name if quarantined else 'çıktı karantinaya alınamadı'}",
                            "err",
                        )
                if isinstance(source_row, dict):
                    source_row.update({
                        "delivery_audit": row["delivery_audit"],
                        "run_status": row.get("run_status"),
                        "delivery_quarantined_path": row.get(
                            "delivery_quarantined_path", ""),
                    })
                if source_path:
                    needs_review = row.get("run_status") == "review"
                    terminal_status = (
                        "review" if needs_review else
                        "error" if row.get("run_status") == "error" else "done")
                    terminal_phase = (
                        "İnceleme gerekli" if needs_review else
                        "Hata" if terminal_status == "error" else "Tamamlandı")
                    self._record_file_status(
                        source_path, terminal_phase, terminal_status)
                    row["timing"] = self._file_timing_snapshot(source_path)
                row["feature_audit"] = _quality_feature_audit(row, snapshot)
                report_rows.append(row)
            with self._token_lock:
                tok = self._token_total
                actual_cost = self._cost_total
                unknown_cost_tokens = self._unknown_cost_tokens
            with self._run_record_lock:
                active_record = self._active_run_record or {}
                run_id = str(active_record.get("run_id") or "")
            txt = build_quality_report_text(report_rows, self._main_model_name(),
                                            self.tgt_var.get(),
                                            self.mode_var.get(), tok,
                                            actual_cost=actual_cost,
                                            unknown_cost_tokens=unknown_cost_tokens,
                                            run_id=run_id)
            # Raporlar altyazı klasörlerini karıştırmamak için efektif çıktı
            # tabanındaki Raporlar alt-klasörüne gider.
            rep_dir = _resolve_report_dir(self.input_var.get(), output_dir)
            rep_dir.mkdir(parents=True, exist_ok=True)
            p = rep_dir / "ceviri_raporu.txt"
            atomic_write_text(p, txt, encoding="utf-8")
            report_paths = [p]
            json_payload = {
                "run_id": run_id,
                "model": self._main_model_name(),
                "target_language": self.tgt_var.get(),
                "mode": self.mode_var.get(),
                "total_tokens": tok,
                "actual_cost": actual_cost,
                "unknown_cost_tokens": unknown_cost_tokens,
                "files": report_rows,
            }
            json_path = rep_dir / "ceviri_raporu.json"
            atomic_write_json(json_path, json_payload)
            report_paths.append(json_path)
            if run_id:
                run_path = rep_dir / f"ceviri_raporu_{run_id}.txt"
                atomic_write_text(run_path, txt, encoding="utf-8")
                report_paths.append(run_path)
                run_json_path = rep_dir / f"ceviri_raporu_{run_id}.json"
                atomic_write_json(run_json_path, json_payload)
                report_paths.append(run_json_path)
            detail_dir = rep_dir / "İşlem Dökümleri"
            detail_dir.mkdir(parents=True, exist_ok=True)
            for row in report_rows:
                safe_name = re.sub(
                    r"[^\w.-]+", "_", Path(str(row.get("name") or "altyazi")).stem,
                    flags=re.UNICODE).strip("._") or "altyazi"
                digest = hashlib.sha256(
                    str(row.get("source_path") or row.get("name") or "").encode(
                        "utf-8", "replace")).hexdigest()[:8]
                detail_path = detail_dir / f"{safe_name}.{digest}.islem_dokumu.txt"
                atomic_write_text(
                    detail_path, _file_process_report_text(row, run_id),
                    encoding="utf-8")
                report_paths.append(detail_path)
            guard_rows = []
            for row in report_rows:
                events = (row.get("pass_trace") or {}).get("__guard_events__") or []
                if events:
                    guard_rows.append({
                        "name": row.get("name"),
                        "source_path": row.get("source_path"),
                        "output_path": row.get("output_path"),
                        "guard_events": events,
                        "pass_history": row.get("pass_history") or {},
                    })
            if guard_rows:
                guard_path = rep_dir / f"pass_guard_kanit_{run_id or 'son'}.json"
                atomic_write_json(guard_path, {
                    "run_id": run_id,
                    "created_at": _timing_iso(time.time()),
                    "files": guard_rows,
                })
                report_paths.append(guard_path)
                self._log(f"Pass guard kanıt paketi: {guard_path}", "warn")
            with self._run_record_lock:
                active = getattr(self, "_active_run_record", None)
                if active is not None:
                    active["_quality_report_rows"] = copy.deepcopy(report_rows)
                    active["_quality_report_output_dir"] = str(output_dir or "")
            self._record_quality_report(report_rows, report_paths)
            self._log(f"Kalite raporu: {p}", "ok")
            return p
        except Exception as report_error:
            self._log(f"Kalite raporu yazılamadı: {report_error}", "err")
            return None

    def _refresh_quality_report_after_season_canon(self, updates: dict) -> None:
        """Rebuild the run report from the files actually rewritten by canon QA."""
        if not updates:
            return
        with self._run_record_lock:
            active = getattr(self, "_active_run_record", None) or {}
            rows = copy.deepcopy(active.get("_quality_report_rows") or [])
            output_dir = str(active.get("_quality_report_output_dir") or "")
            by_source = {
                os.path.normcase(os.path.abspath(str(row.get("source_path") or ""))): row
                for row in rows if row.get("source_path")
            }
            for source_path, update in updates.items():
                row = by_source.get(os.path.normcase(os.path.abspath(str(source_path))))
                if row is None:
                    continue
                row.update(update)
                row.setdefault("pass_trace", {})["Season-Canon"] = int(
                    update.get("season_canon_changes", 0) or 0)
                row.setdefault("pass_status", {})["Season-Canon"] = dict(
                    update.get("season_canon_status") or {})
            active["_quality_report_rows"] = copy.deepcopy(rows)
        if rows and output_dir:
            self._save_quality_report(rows, output_dir)

    def _open_quality_report(self):
        """Çıktı klasöründeki ceviri_raporu.txt'yi uygulama içi pencerede gösterir."""
        p = _resolve_report_dir(self.input_var.get(), self.output_var.get()) / "ceviri_raporu.txt"
        if not p.exists():
            messagebox.showinfo("Kalite Raporu",
                                "Henüz rapor yok.\nBir çeviri tamamlandığında çıktı "
                                "klasöründeki Raporlar alt-klasörüne "
                                "'ceviri_raporu.txt' yazılır.")
            return
        try:
            self._show_report_dialog(p.read_text(encoding="utf-8"), str(p))
        except Exception as e:
            messagebox.showerror("Hata", f"Rapor açılamadı:\n{e}")

